window.LING406_MODULE3 = {"revision": "ling406-module3-1", "status": "ready", "modules": [{"id": "reading1", "number": "01", "title": "Reading 1 · Empirical studies", "source": "reading1", "week": 10, "sections": ["m3-reading1-p001", "m3-reading1-p002", "m3-reading1-p003", "m3-reading1-p004", "m3-reading1-p005", "m3-reading1-p006", "m3-reading1-p007", "m3-reading1-p008", "m3-reading1-p009", "m3-reading1-p010", "m3-reading1-p011", "m3-reading1-p012", "m3-reading1-p013", "m3-reading1-p014", "m3-reading1-p015", "m3-reading1-p016", "m3-reading1-p017", "m3-reading1-p018", "m3-reading1-p019", "m3-reading1-p020", "m3-reading1-p021", "m3-reading1-p022", "m3-reading1-p023", "m3-reading1-p024"]}, {"id": "reading2", "number": "02", "title": "Reading 2 · Computational models", "source": "reading2", "week": 10, "sections": ["m3-reading2-p001", "m3-reading2-p002", "m3-reading2-p003", "m3-reading2-p004", "m3-reading2-p005", "m3-reading2-p006", "m3-reading2-p007", "m3-reading2-p008", "m3-reading2-p009", "m3-reading2-p010", "m3-reading2-p011", "m3-reading2-p012", "m3-reading2-p013", "m3-reading2-p014", "m3-reading2-p015", "m3-reading2-p016", "m3-reading2-p017", "m3-reading2-p018", "m3-reading2-p019", "m3-reading2-p020", "m3-reading2-p021", "m3-reading2-p022", "m3-reading2-p023", "m3-reading2-p024", "m3-reading2-p025", "m3-reading2-p026", "m3-reading2-p027", "m3-reading2-p028", "m3-reading2-p029", "m3-reading2-p030", "m3-reading2-p031"]}, {"id": "morphology", "number": "03", "title": "Inflectional morphology", "source": "morphology", "week": 11, "sections": ["m3-morphology-p001", "m3-morphology-p002", "m3-morphology-p003", "m3-morphology-p004", "m3-morphology-p005", "m3-morphology-p006", "m3-morphology-p007", "m3-morphology-p008", "m3-morphology-p009", "m3-morphology-p010", "m3-morphology-p011", "m3-morphology-p012", "m3-morphology-p013", "m3-morphology-p014", "m3-morphology-p015", "m3-morphology-p016", "m3-morphology-p017", "m3-morphology-p018", "m3-morphology-p019", "m3-morphology-p020", "m3-morphology-p021", "m3-morphology-p022", "m3-morphology-p023", "m3-morphology-p024", "m3-morphology-p025", "m3-morphology-p026", "m3-morphology-p027", "m3-morphology-p028", "m3-morphology-p029", "m3-morphology-p030"]}, {"id": "thought", "number": "04", "title": "Language and thought", "source": "thought", "week": 11, "sections": ["m3-thought-p001", "m3-thought-p002", "m3-thought-p003", "m3-thought-p004", "m3-thought-p005", "m3-thought-p006", "m3-thought-p007", "m3-thought-p008", "m3-thought-p009", "m3-thought-p010", "m3-thought-p011", "m3-thought-p012", "m3-thought-p013", "m3-thought-p014", "m3-thought-p015", "m3-thought-p016", "m3-thought-p017", "m3-thought-p018", "m3-thought-p019", "m3-thought-p020", "m3-thought-p021", "m3-thought-p022", "m3-thought-p023", "m3-thought-p024", "m3-thought-p025", "m3-thought-p026", "m3-thought-p027"]}, {"id": "modalities", "number": "05", "title": "Language in different modalities · Sign and Braille", "source": "modalities", "week": 12, "sections": ["m3-modalities-p001", "m3-modalities-p002", "m3-modalities-p003", "m3-modalities-p004", "m3-modalities-p005", "m3-modalities-p006", "m3-modalities-p007", "m3-modalities-p008", "m3-modalities-p009", "m3-modalities-p010", "m3-modalities-p011", "m3-modalities-p012", "m3-modalities-p013", "m3-modalities-p014", "m3-modalities-p015", "m3-modalities-p016", "m3-modalities-p017", "m3-modalities-p018", "m3-modalities-p019", "m3-modalities-p020", "m3-modalities-p021"]}, {"id": "review", "number": "06", "title": "Final review · supplied 2025 deck", "source": "review", "week": null, "sections": ["m3-review-p001", "m3-review-p002", "m3-review-p003", "m3-review-p004", "m3-review-p005", "m3-review-p006", "m3-review-p007", "m3-review-p008", "m3-review-p009", "m3-review-p010", "m3-review-p011", "m3-review-p012", "m3-review-p013", "m3-review-p014", "m3-review-p015", "m3-review-p016", "m3-review-p017", "m3-review-p018", "m3-review-p019", "m3-review-p020", "m3-review-p021", "m3-review-p022", "m3-review-p023", "m3-review-p024", "m3-review-p025", "m3-review-p026", "m3-review-p027", "m3-review-p028", "m3-review-p029", "m3-review-p030", "m3-review-p031", "m3-review-p032", "m3-review-p033", "m3-review-p034", "m3-review-p035", "m3-review-p036", "m3-review-p037", "m3-review-p038", "m3-review-p039", "m3-review-p040", "m3-review-p041", "m3-review-p042", "m3-review-p043", "m3-review-p044", "m3-review-p045", "m3-review-p046", "m3-review-p047", "m3-review-p048", "m3-review-p049", "m3-review-p050", "m3-review-p051", "m3-review-p052"]}], "sections": [{"id": "m3-reading1-p001", "noteId": "m3-reading1-p001", "module": "reading1", "source": "reading1", "page": 1, "title": "Reading 1 · Empirical studies", "sourceText": "Reading 1: Empirical studies\n", "image": "assets/reading1/001.webp", "core": false, "reviewPages": [], "paragraphs": [], "analysis": {"status": "authored", "role": "noninstructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p002", "noteId": "m3-reading1-p002", "module": "reading1", "source": "reading1", "page": 2, "title": "Phonemes and letters", "sourceText": "Do you remember when we discussed \nphonemes at the beginning of the semester?\nWhat was the first thing I wanted you to \nremember about phonemes?\n", "image": "assets/reading1/002.webp", "core": false, "reviewPages": [], "paragraphs": ["**Phonemes are speech-sound categories, not letters.** A writing system represents language, but its symbols do not have to correspond one-to-one with those categories.", "A letter can contribute to different pronunciations, and a phoneme can be represented by different spellings."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p003", "noteId": "m3-reading1-p003", "module": "reading1", "source": "reading1", "page": 3, "title": "Orthographic depth", "sourceText": "We were able to demonstrate that \nphonemes are not letters, but also \nthat letters are not phonemes with \na “mispronouncing contest” in \nwhich people willfully \nmispronounced words like:\nCOLONEL\nPARADIGM\nWe also talked about how some \nscripts (like Pinyin for Mandarin \nand French) are relatively regular.\nThis difference between scripts is also referred to as orthographic depth. \nEnglish, due its irregularities is a relatively deep script. \nFinnish and Korean are very shallow scripts. \n", "image": "assets/reading1/003.webp", "core": true, "reviewPages": [2], "paragraphs": ["**Orthographic depth** describes how consistently spelling corresponds to pronunciation. English is relatively deep because many spellings do not transparently specify their sounds.", "COLONEL and PARADIGM make the problem concrete. Applying common letter–sound patterns can produce a plausible-looking pronunciation that is wrong for the actual word.", "In shallower writing systems, such as Finnish and Korean, spelling–sound correspondences are more predictable. The comparison concerns the writing system, not the intelligence or ability of its readers."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p004", "noteId": "m3-reading1-p004", "module": "reading1", "source": "reading1", "page": 4, "title": "Transparent spelling in Finnish", "sourceText": "Some writing systems, like Finnish, are \nvery “transparent” (or “shallow” \naccording to the Orthographic Depth \nHypothesis).\nLet’s listen to this beginning Finnish \nlesson and follow along with the text…\nAfter about a minute of this, you \nprobably get the idea?\nEach letter corresponds more or less \nunambiguously to one phoneme. \nDoubled letters actually correspond to \ngeminated consonants or long vowels.\nFinnish children learn to decode\npronunciations for written forms very \nvery quickly. \nhttp://tasteoffinnish.fi/lesson1-1/\n", "image": "assets/reading1/004.webp", "core": true, "reviewPages": [3], "paragraphs": ["**Finnish has a shallow orthography.** Letters correspond relatively unambiguously to phonemes, so learning a spelling–sound correspondence helps with many different words.", "Doubled letters represent a meaningful length distinction. A doubled consonant is geminated, and a doubled vowel is long.", "This regularity helps Finnish children learn decoding quickly. Decoding means generating a pronunciation from a written form, whether or not its meaning is familiar."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p005", "noteId": "m3-reading1-p005", "module": "reading1", "source": "reading1", "page": 5, "title": "Learning to decode across languages", "sourceText": "In fact, English is a bit of an outlier \namong languages that use the Roman \nalphabet. \nOne result is that kids learn to decode \nmore slowly in English.\nIn Grade 1, kids learning a wide variety \nof other languages are able to generate \nplausible pronunciations for \n“pseudowords,” (made up words that \nfollow the spelling and sound patterns \nof their language) at a much higher rate \nthan English learners.\n", "image": "assets/reading1/005.webp", "core": true, "reviewPages": [4], "paragraphs": ["**Pseudoword reading tests decoding.** Because a pseudoword is not a familiar stored word, the child must generalize from learned spelling–sound patterns.", "The comparison involves Grade 1 children learning different alphabetic writing systems. Children learning many other languages produce plausible pseudoword pronunciations more successfully than English learners.", "English's less predictable correspondences help explain why decoding develops more slowly. This task does not measure the child's entire language ability."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p006", "noteId": "m3-reading1-p006", "module": "reading1", "source": "reading1", "page": 6, "title": "Korean letter forms and sounds", "sourceText": "Korean is even more regular than \nFinnish!\nThe symbols for similar phonemes \nare represented as similar to one \nanother. \nWhat orthographic feature \ncorresponds roughly to velar place of \narticulation, for example?\n", "image": "assets/reading1/006.webp", "core": true, "reviewPages": [5], "paragraphs": ["**Korean writing represents sound structure systematically.** Related phonemes can have related written shapes, so the visual forms themselves reflect aspects of phonological organization.", "The letters are arranged into syllable blocks with initial, medial and sometimes final positions. Those positions are not three unrelated pictures of whole words.", "The velar consonant forms share the basic angular ㄱ shape. Additional strokes or doubling distinguish related consonants."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p007", "noteId": "m3-reading1-p007", "module": "reading1", "source": "reading1", "page": 7, "title": "Pseudoword decoding", "sourceText": "Decoding in action\nRead these “pseudowords” aloud:\nGLORP\nSPLING\nJONK\nFEESH\nQUISP\n", "image": "assets/reading1/007.webp", "core": false, "reviewPages": [], "paragraphs": ["**GLORP, SPLING, JONK, FEESH and QUISP can be pronounced without being familiar words.** Their forms follow enough English spelling patterns for a reader to construct a plausible pronunciation.", "Success cannot depend on retrieving a stored pronunciation for each particular item. The reader is using knowledge that generalizes across words.", "The demonstration establishes generalization. By itself, it does not decide whether that knowledge consists of categorical rules or learned statistical patterns."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p008", "noteId": "m3-reading1-p008", "module": "reading1", "source": "reading1", "page": 8, "title": "Speed of pseudoword naming", "sourceText": "Pseudowords (here called “nonwords”) \ncan be read nearly as quickly and \naccurately as real words.\n(In this example, pseudoword naming \ntimes are between 5 and 12% slower than \nreading times for low-frequency words.)\nThis suggests that we “do” decoding fairly \nnaturally, automatically and implicitly. \nDecoding in action\nThe questions we’ll consider when we discuss computational models of word reading \nhave to do with how decoding should be characterized.\nSpecifically, we’ll discuss whether this behavior is best captured by categorical rules or \nprobabilistic constraints. \nLupker, Brown, & Colombo (1997)\n", "image": "assets/reading1/008.webp", "core": true, "reviewPages": [], "paragraphs": ["**Pseudoword decoding is fast and largely automatic.** In the Lupker, Brown and Colombo example, naming pseudowords is only about 5–12% slower than naming low-frequency real words.", "Participants read the items aloud, and naming time measures how quickly a pronunciation becomes available. The small difference shows that unfamiliarity does not make pronunciation an entirely slow, deliberate process.", "Both rules and statistical generalization might produce efficient decoding. The speed result constrains a theory without selecting one architecture on its own."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p009", "noteId": "m3-reading1-p009", "module": "reading1", "source": "reading1", "page": 9, "title": "Ambiguous pseudowords", "sourceText": "Decoding with ambiguity\nRead these pseudowords aloud:\nVONTH\nPHANGE\nSTREAD\nSOUGH\n", "image": "assets/reading1/009.webp", "core": false, "reviewPages": [], "paragraphs": ["**An unfamiliar spelling can support more than one plausible pronunciation.** VONTH, PHANGE, STREAD and SOUGH contain patterns whose pronunciations are not all uniquely determined in English.", "A response reflects the spelling–sound patterns available from previously learned words. Different familiar patterns can favor different responses to the same novel form."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p010", "noteId": "m3-reading1-p010", "module": "reading1", "source": "reading1", "page": 10, "title": "Generalization and competing patterns", "sourceText": "Decoding with ambiguity\nVONTH\nPHANGE\nSTREAD\nSOUGH\nGeneralization is a good way to test what kinds of \nregularities people have learned about a system.\nRemember, e.g., The Wug Test…(or if you don’t remember, \nwe’ll get to it next week)\nIt’s hard to imagine a rule set that covers our intuition that \nboth /strɛd/ and /strid/ are acceptable for STREAD.\n", "image": "assets/reading1/010.webp", "core": true, "reviewPages": [], "paragraphs": ["**STREAD can plausibly be pronounced with either /ɛ/ or /i/.** The same written sequence can resemble more than one learned spelling–sound pattern.", "Testing novel items reveals what a reader has generalized, because the particular word cannot simply have been memorized.", "The challenge for a categorical rule account is to explain why multiple outputs seem acceptable. A statistical account can represent differing support for alternative pronunciations."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p011", "noteId": "m3-reading1-p011", "module": "reading1", "source": "reading1", "page": 11, "title": "Regularity and consistency", "sourceText": "Decoding effects for real words: \nthe “regularity effect”\nWe’ll examine arguments about the \nnature of decoding processes next \ntime.\nIt’s uncontroversial that some form \nof decoding is part of normal \nreading, and that words that are \n“irregular” (or “inconsistent”) are \nharder to recognize than words \nthat are regular.\nThis is straightforward for items like \nPINT, ACHE, CHOIR, etc.\nIt’s less clear-cut for \n“neighborhoods” of words like \nROLL/POLL/TOLL/DOLL or \nCOOK/TOOK/BOOK/SPOOK. \n", "image": "assets/reading1/011.webp", "core": false, "reviewPages": [], "paragraphs": ["**The regularity effect is the difficulty of reading words whose pronunciation conflicts with common spelling–sound patterns.** PINT, ACHE and CHOIR are examples of words for which straightforward decoding can mislead.", "A strict regular–irregular division is less clear when a spelling neighborhood contains several pronunciations. ROLL, POLL and TOLL support one pattern, while DOLL differs.", "COOK, TOOK and BOOK likewise contrast with SPOOK. These neighborhoods motivate asking how much support a pronunciation has from similar words."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p012", "noteId": "m3-reading1-p012", "module": "reading1", "source": "reading1", "page": 12, "title": "Sublexical and lexical information", "sourceText": "So, we have a lot of evidence for the use of sublexical information in \nreading, especially in the translation from spelling to sound\nPeople read nonwords quickly and accurately.\nWords that follow typical spelling-to-sound patterns are easier to read than ones that don’t.\nWhat about lexical processes? \n", "image": "assets/reading1/012.webp", "core": false, "reviewPages": [], "paragraphs": ["**Sublexical information concerns units smaller than a whole word.** Rapid nonword reading and the advantage for typical spelling–sound patterns show that readers use this information.", "**Lexical information** concerns knowledge of particular words. A complete account must explain how experience with a specific word contributes alongside general spelling patterns."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p013", "noteId": "m3-reading1-p013", "module": "reading1", "source": "reading1", "page": 13, "title": "Interactive activation and ambiguous letters", "sourceText": "Well, there’s this again.\n", "image": "assets/reading1/013.webp", "core": true, "reviewPages": [], "paragraphs": ["**Word knowledge can help identify an ambiguous letter.** In an interactive activation network, visual features activate letters and letters activate candidate words.", "Activated word candidates send feedback to their constituent letters. A letter supported by a plausible word receives additional activation even when its local visual evidence is unclear.", "Competing candidates do not remain equally active. Their activation changes as the network settles on an interpretation."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p014", "noteId": "m3-reading1-p014", "module": "reading1", "source": "reading1", "page": 14, "title": "Feedback in the Interactive Activation Model", "sourceText": "The Interactive Activation Model:\n- feedback from activation for known words \nincreases the activation for letters that occur in \nthose words\n", "image": "assets/reading1/014.webp", "core": true, "reviewPages": [], "paragraphs": ["**Feedback carries word-level activation back to letters.** A partially activated known word increases activation of the letters that belong to it.", "This makes recognition interactive. Information does not flow only from isolated features upward to a finished word.", "The mechanism helps explain why an ambiguous letter can become easier to recognize when it appears in a familiar word context."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p015", "noteId": "m3-reading1-p015", "module": "reading1", "source": "reading1", "page": 15, "title": "Lexicality and frequency", "sourceText": "Also note that we’ve already seen two lexical \neffects:\n- the overall effect of lexicality\n- the effect of word frequency.\nJust as with picture naming, the number of \ntimes you’ve encountered a word in the past \nhas an impact on how rapidly you can name it.\nThis effect is robust over a very very large \nnumber of observations \n(Balota et al. 2004, data from the English Lexicon Project)\n", "image": "assets/reading1/015.webp", "core": false, "reviewPages": [], "paragraphs": ["**Lexicality and word frequency reveal effects of word-specific experience.** Real words are generally named faster than pseudowords, and frequently encountered words are named faster than less frequent words.", "Lexicality compares whether the item is a word. Frequency compares how often a particular word has been encountered.", "The English Lexicon Project data show that the frequency effect occurs across many observations, rather than depending on a few unusually easy examples."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p016", "noteId": "m3-reading1-p016", "module": "reading1", "source": "reading1", "page": 16, "title": "Controlling confounds in frequency effects", "sourceText": "Remember we worried about whether \nfrequency effects might be confounds of \nlength and other variables.\nThis appears not to be the case in a multiple \nregression analysis of about 3000 words, read \nby 30 young and older adults.\n", "image": "assets/reading1/016.webp", "core": true, "reviewPages": [], "paragraphs": ["**Multiple regression tests whether frequency predicts reading time after accounting for other word properties.** Length and sound-related characteristics could otherwise be mistaken for effects of frequency.", "The analysis uses about 3,000 words read by young and older adults. Frequency still contributes when other predictors are considered.", "This makes a simple length-confound explanation less plausible. It does not turn an observational predictor into an experimentally isolated cause."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p017", "noteId": "m3-reading1-p017", "module": "reading1", "source": "reading1", "page": 17, "title": "Frequency by regularity interaction", "sourceText": "This is a landmark finding in psycholinguistics. \nWe’ll see how it has impacted a number of other areas \n(most immediately inflectional morphology).\nWhat does it mean?\nThe frequency effect is much \nlarger for exception words \nthan regular words. \nBehold: The Frequency by Regularity interaction.\n", "image": "assets/reading1/017.webp", "core": true, "reviewPages": [6], "paragraphs": ["**Frequency and regularity interact.** Low-frequency exception words are slowed much more than low-frequency regular words, whereas high-frequency words show a much smaller regularity difference.", "Naming latency is the time needed to begin saying the word. Higher values mean slower responses.", "An interaction means the effect of one factor depends on the other. The regularity cost is not a fixed amount added equally to high- and low-frequency words."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p018", "noteId": "m3-reading1-p018", "module": "reading1", "source": "reading1", "page": 18, "title": "Dual-route interpretation of the interaction", "sourceText": "One interpretation\nThere are two separate processes in word recognition: \n1. A sublexical process (decoding), and\n2. A lexical process (knowledge of a particular word)\nFor high frequency (HF) words, the lexical process is so fast and efficient that there is little \ninfluence of the sublexical process.\nThe sublexical process only shows up when we read nonwords, or low frequency (LF) words.\n", "image": "assets/reading1/018.webp", "core": true, "reviewPages": [7], "paragraphs": ["**A dual-route interpretation separates lexical retrieval from sublexical decoding.** The lexical process supplies the learned pronunciation of a particular word, while decoding computes pronunciation from spelling units.", "For a high-frequency word, lexical information becomes available quickly enough to reduce the influence of the decoding output.", "For a low-frequency exception, the lexical response is less efficient and the regularized decoding output can interfere. Nonwords depend on decoding because they lack a stored whole-word entry."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p019", "noteId": "m3-reading1-p019", "module": "reading1", "source": "reading1", "page": 19, "title": "Acquired phonological dyslexia", "sourceText": "Neuropsychological evidence for these “dual \nroutes”\nPatients with acquired phonological dyslexia:\n- present with reading difficulty as the result of brain injury (thus “acquired” as opposed \nto “developmental” dyslexia)\n- have difficulty specifically with pseudoword naming.\nCacciopo van Vliet et al. (2003)\n", "image": "assets/reading1/019.webp", "core": true, "reviewPages": [], "paragraphs": ["**Acquired phonological dyslexia involves disproportionate difficulty reading pseudowords after brain injury.** Familiar words can remain relatively well read even when novel forms are difficult.", "Cacciopo van Vliet and colleagues compare real-word reading with several nonword tasks. The patients can often recognize and pronounce known words while struggling to generate a plausible pronunciation for an unfamiliar spelling.", "The selective difficulty suggests that familiar-word success and novel-form decoding do not rely on every process to the same degree."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p020", "noteId": "m3-reading1-p020", "module": "reading1", "source": "reading1", "page": 20, "title": "Acquired surface dyslexia", "sourceText": "Neuropsychological evidence for these “dual \nroutes”\nPatients with “acquired surface dyslexia:”\n- also present with reading \ndifficulties after brain injury\n- difficulties are specifically with \nirregular words.\n- mispronunciations tend to be \n“regularizations.” \n", "image": "assets/reading1/020.webp", "core": true, "reviewPages": [], "paragraphs": ["**Acquired surface dyslexia involves disproportionate difficulty reading irregular words after brain injury.** Errors often regularize the word by applying a more common spelling–sound pattern.", "DEAF pronounced like “deef” and SHOE pronounced like “show” illustrate regularization. The response is related to the spelling, but it is not the target word's learned pronunciation.", "Relatively good regular-word and nonword reading shows that generating pronunciation from spelling can remain useful despite difficulty with exceptions."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p021", "noteId": "m3-reading1-p021", "module": "reading1", "source": "reading1", "page": 21, "title": "The reading double dissociation", "sourceText": "Neuropsychological evidence for these “dual \nroutes”\nPatients with “acquired surface dyslexia:”\n- also present with reading \ndifficulties after brain injury\n- difficulties are specifically with \nirregular words.\n- mispronunciations tend to be \n“regularizations.”\n- relatively spared pseudoword\nreading.\nPatients with acquired phonological dyslexia:\n- present with reading difficulty as the \nresult of brain injury (thus “acquired” as \nopposed to “developmental” dyslexia)\n- have difficulty specifically with \npseudoword naming.\n- relatively spared exception word reading\nThis is a classic double dissociation.\n", "image": "assets/reading1/021.webp", "core": true, "reviewPages": [], "paragraphs": ["**A double dissociation compares opposite relative impairments.** Phonological dyslexia particularly affects pseudowords, while surface dyslexia particularly affects exception words.", "The first pattern shows that unfamiliar decoding can be difficult despite relatively preserved familiar-word reading. The second shows that exception reading can be difficult despite relatively preserved pseudoword reading.", "Together, the patterns are harder to explain by saying that one task is simply harder for everyone."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p022", "noteId": "m3-reading1-p022", "module": "reading1", "source": "reading1", "page": 22, "title": "Why double dissociations matter", "sourceText": "Why are double dissociations so powerful?\n", "image": "assets/reading1/022.webp", "core": false, "reviewPages": [], "paragraphs": ["**A double dissociation challenges a single fixed difficulty ranking.** If task A were merely harder than task B, damage might consistently hurt A more, but it would not readily explain another patient showing the reverse pattern.", "The reversal suggests that the tasks depend differently on underlying processes. For reading, pseudowords and exception words place different demands on the system.", "The evidence still requires a theory of what those underlying processes are. It does not uniquely identify a particular set of boxes in a model."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p023", "noteId": "m3-reading1-p023", "module": "reading1", "source": "reading1", "page": 23, "title": "Locating deficits in a dual-route model", "sourceText": "Why are double dissociations so powerful?\nThey provide evidence that processes underlying \npseudoword and irregular word reading (for example) \nare separable.\nIn this model, we can imagine:\n- phonological dyslexia results from specific\ndamage to the grapheme-phoneme conversion \nmodule\n- surface dyslexia results from damage to input \nor output “logogens”, or the connections between \nthem\n", "image": "assets/reading1/023.webp", "core": true, "reviewPages": [], "paragraphs": ["**A dual-route model attributes phonological dyslexia to damage in grapheme–phoneme conversion and surface dyslexia to damage in lexical processing.** These proposed locations connect the task dissociation to specific mechanisms.", "Damage to conversion particularly affects nonwords because there is no familiar whole-word pronunciation to retrieve.", "Damage to input or output word representations, called logogens in this account, or their connections makes exceptions vulnerable because general decoding supplies the wrong pronunciation."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading1-p024", "noteId": "m3-reading1-p024", "module": "reading1", "source": "reading1", "page": 24, "title": "Complications for a strict two-route account", "sourceText": "Patterson (1981, British Journal of Psychology)\nEarly inklings that it is not so simple…\n", "image": "assets/reading1/024.webp", "core": true, "reviewPages": [], "paragraphs": ["**Patterson's discussion shows why reading errors can complicate a clean lexical–nonlexical division.** Errors attributed to a purely nonlexical route can still show lexical influences.", "The example “incense” read as “increase” is a real-word response. A simple letter–sound mistake could instead produce a nonword, so the actual response raises a question about whole-word influence.", "Possible responses are to allow a more complicated combination of routes or to revise the supposedly nonlexical process itself. The observation motivates refinement rather than settling the issue alone."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-reading2-p001", "noteId": "m3-reading2-p001", "module": "reading2", "source": "reading2", "page": 1, "title": "Reading 2 · Computational models", "sourceText": "Reading 2: Computational \nmodels\n", "image": "assets/reading2/001.webp", "core": false, "reviewPages": [], "paragraphs": [], "analysis": {"status": "authored", "role": "noninstructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p002", "noteId": "m3-reading2-p002", "module": "reading2", "source": "reading2", "page": 2, "title": "Why propose two reading routes?", "sourceText": "Dual route models of visual word recognition \nThis general form of model is motivated by the \nphenomena we reviewed in the last lecture:\n- pseudoword reading is fast and automatic\n- word reading is faster\n- reading is fastest for high-frequency words\n- accuracy and response time are also \nimpacted by “regularity”\n- frequency and regularity interact\n- pseudoword reading and irregular word \nreading are dissociable in acquired dyslexia\nThus, the model hypothesize \n- a sublexical route for grapheme-to-\nphoneme conversion (decoding)\n- a lexical route for recognizing real words \n", "image": "assets/reading2/002.webp", "core": false, "reviewPages": [], "paragraphs": ["**Dual-route models distinguish a lexical route from a sublexical route.** Lexical processing uses knowledge of particular words, while grapheme–phoneme conversion generates pronunciation from spelling units.", "A model must explain fast pseudoword reading, faster familiar-word reading, frequency effects, regularity effects and their interaction.", "It must also explain why pseudoword and exception-word reading can be differently impaired after brain injury. These observations motivate the architecture but do not uniquely prove it."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p003", "noteId": "m3-reading2-p003", "module": "reading2", "source": "reading2", "page": 3, "title": "The Dual Route Cascaded model", "sourceText": "(image credit: http://www.maccs.mq.edu.au/~ssaunder/DRC/)\nColtheart et al. (2001, Psych Review)\nThis is the “DRC -- Dual Route \nCascaded” model. \nSome key points:\nThe portion circled in red is \njust the Interactive Activation \nmodel.\nThere is no implementation \nof semantics, since both the \northographic and phonological \nlexicons are independent of \nsemantics.\nThe Grapheme-Phoneme \nRule System has completely \ndifferent processing assumptions \nfrom the interactive portion of the \nmodel. \n", "image": "assets/reading2/003.webp", "core": true, "reviewPages": [], "paragraphs": ["**The Dual Route Cascaded model, or DRC, combines interactive lexical processing with a separate grapheme–phoneme rule system.** The two routes can contribute activation toward a spoken response.", "The lexical portion includes orthographic and phonological lexicons, representing written and spoken word forms. These representations are distinguished from meanings.", "The implementation described here does not implement semantics. The GPC rule system also has processing assumptions different from those of the interactive lexical network."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p004", "noteId": "m3-reading2-p004", "module": "reading2", "source": "reading2", "page": 4, "title": "How GPC processing works", "sourceText": "Some important features of the \nGrapheme-Phoneme Rule System:\nIts rules are activated serially, \nletter by letter. \nIt is not affected by frequency \nof occurrence in any way.\nIt has no feedback. \nIt does not interact with the \nlexical route, except in the \nphoneme response buffer, where \nit is connected to the same output \nunits (and therefore can compete \nto activate different patterns).\n(image credit: http://www.maccs.mq.edu.au/~ssaunder/DRC/)\nColtheart et al. (2001, Psych Review)\n", "image": "assets/reading2/004.webp", "core": true, "reviewPages": [], "paragraphs": ["**The DRC's grapheme–phoneme conversion rules operate serially, letter by letter.** Their operation is not adjusted by word frequency and receives no lexical feedback.", "The GPC and lexical routes do not interact throughout their internal computations. They converge in the phoneme response buffer.", "If the routes favor different phonemes, they can compete at that shared output. An exception word can therefore receive a correct lexical pronunciation and an incompatible regularized pronunciation."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p005", "noteId": "m3-reading2-p005", "module": "reading2", "source": "reading2", "page": 5, "title": "Rules and rules for applying rules", "sourceText": "What are the GPC rules like?\n<...>\n(you also need some meta-rules for \nwhen to apply rules at different levels of \nanalysis, e.g., larger-unit rules \nsupersede smaller-unit rules)\n", "image": "assets/reading2/005.webp", "core": false, "reviewPages": [], "paragraphs": ["**GPC rules map written units onto phonemes.** Some rules concern individual letters, while others concern several letters or a particular letter context.", "A model also needs a way to decide which applicable rule takes priority. A larger-unit rule can supersede rules for its individual letters.", "Context-sensitive rules restrict a pronunciation to specified surrounding letters or positions. This makes the procedure more than a simple lookup of one sound per letter."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p006", "noteId": "m3-reading2-p006", "module": "reading2", "source": "reading2", "page": 6, "title": "Categorical rules and statistical support", "sourceText": "Actually, the rules aren’t totally independent of statistics.\nThey’re often based on the most frequent pronunciation for a letter or \ncombination of letters.\nBut they are fixed and categorical. So, even though the rule for -OUGH has \nweaker statistical support than the rule for -EIGH, they are both rules and \nbehave the same way during processing. \n{OUGH: (final != T)}\nOUGH\n{EIGH: (final != T)}\nEIGH\n-\n-\n1\n0.667\n/eI/\n-\n-\n-\n0.333\n/aI/\n0.27\n0.53\n-\n-\n/ɔ/\n0.27\n0.16\n-\n-\n/әf/\n0.18\n0.16\n-\n-\n/oʊ/\n0.18\n0.11\n-\n-\n/aʊ/\n0.09\n0.05\n-\n-\n/u/\n", "image": "assets/reading2/006.webp", "core": true, "reviewPages": [], "paragraphs": ["**A categorical rule does not express the strength of the evidence behind it.** The DRC can choose a mapping because it is frequent, yet treat that mapping as a fixed rule during processing.", "The possible pronunciations of OUGH have more divided statistical support than those of EIGH. A rule can still operate categorically for both spellings.", "A probabilistic account instead allows alternatives to receive different strengths of support. The distinction concerns processing, not whether the model designer ever consulted frequency information."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p007", "noteId": "m3-reading2-p007", "module": "reading2", "source": "reading2", "page": 7, "title": "Why imperfect rules were defended", "sourceText": "…by which I mean that they seem to miss a lot of cases.\nThis was seen as a feature, though, not a bug.\nWe could certainly come up with better rules if we took statistics into account more flexibly. \n(In fact the DRC’s rules went through several revisions to improve its nonword reading.)\nBut the argument from the DRC is that people don’t use such finely-tuned rules for the GPC \nroute. \nIf they did, you wouldn’t see the pattern of regularization errors that you see in surface \ndyslexia, or the slow-down in performance that you see for low-frequency exception words. \nThese rules are kind of silly\n", "image": "assets/reading2/007.webp", "core": false, "reviewPages": [], "paragraphs": ["**The DRC's simple rules are intended to explain systematic human errors as well as correct reading.** More finely tuned rules might pronounce more exceptions correctly but remove behavior the model is meant to explain.", "A regularizing route helps account for errors in surface dyslexia and for slow naming of low-frequency exception words.", "The theory therefore claims that people's sublexical computation is constrained, rather than assuming that the best possible spelling algorithm is the correct cognitive model."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p008", "noteId": "m3-reading2-p008", "module": "reading2", "source": "reading2", "page": 8, "title": "Informational encapsulation", "sourceText": "Remember when we talked about models of syntax?\nWe saw that parsing strategies like “late closure” and \n“minimal attachment” were motivated by \nconsideration of syntactic complexity only.\nThe idea was to explain syntactic processing as \ninformationally encapsulated from world knowledge, \nlexical co-occurrence statistics, etc.\nThe dual-route models are designed to be similarly \nmodular. \nThe GPC chugs along and produces correct \npronunciations for many words, incorrect responses \nto some “exceptions” to its rules. Occasionally, we can \nobserve its operation when:\n-people produce “regularization” errors\n- we force people to name pseudowords\nThese rules are kind of silly\n", "image": "assets/reading2/008.webp", "core": false, "reviewPages": [], "paragraphs": ["**Informational encapsulation means that a process does not freely use every source of relevant knowledge.** In the dual-route account, GPC conversion proceeds without consulting whole-word meaning or lexical feedback.", "This resembles a modular parsing proposal in which an early syntactic process follows structural principles without immediately using world knowledge.", "Pseudoword naming exposes the conversion procedure because a familiar lexical entry is unavailable. Regularization errors expose it when conversion favors the wrong pronunciation."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p009", "noteId": "m3-reading2-p009", "module": "reading2", "source": "reading2", "page": 9, "title": "Breadth of DRC simulations", "sourceText": "The DRC can simulate a lot of phenomena in visual \nword recognition. \nColtheart et al., 2001, Psych Review\n", "image": "assets/reading2/009.webp", "core": false, "reviewPages": [], "paragraphs": ["**The DRC is evaluated against many reading phenomena.** These include frequency, lexicality, regularity, interactions, lexical decision and patterns in acquired dyslexia.", "Accounting for several effects with one architecture is stronger than fitting a single result. It also requires examining which assumptions stay fixed and which are changed between tasks.", "The model's research strategy places strong weight on human behavioral evidence as a constraint on architecture."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p010", "noteId": "m3-reading2-p010", "module": "reading2", "source": "reading2", "page": 10, "title": "Modeling lexical decision", "sourceText": "This sometimes means going to extremes to make contact with data\nReduce letter-word inhibition. \n(This change makes the task harder, but \nwithout it, the results make no sense.) \nIf any single word has an activity above a \nthreshold of 0.69, answer “yes.”\nIf the activity over the orthographic \ninput lexicon exceeds threshold S, \nanswer “yes.”\n(where S = 10 from 0-20 cycles, and is \nthen reduced to 1.98 if activity in the \northographic lexicon exceeds 0.2 at 20 \ncycles).\nIf neither of these criteria is met by D \ncycles, answer “no.”\n(where D = 42 unless activity in the \nlexicon exceeds 0.112 after 20 cycles, in \nwhich case it is set to 48. Note that this \nnearly twice as fast as the model \nnormally reads aloud).\nHow the lexical decision task is \nmodeled in the DRC…\n", "image": "assets/reading2/010.webp", "core": true, "reviewPages": [], "paragraphs": ["**Lexical decision requires deciding whether a written item is a word.** The DRC simulation adds decision criteria to the activation produced by its recognition system.", "A “yes” response can depend on a strongly activated single word or on total activity across the orthographic lexicon. A “no” response occurs if the criteria are not met by a deadline.", "The implementation also changes inhibition and uses time-dependent thresholds. These choices help obtain a fit, but they add assumptions beyond the basic two-route diagram."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p011", "noteId": "m3-reading2-p011", "module": "reading2", "source": "reading2", "page": 11, "title": "Modularity in the DRC", "sourceText": "Key feature of the DRC: Modularity\nThe GPC route and lexical route:\n- each have their own processing assumptions\n- are informationally encapsulated from one another\n- are domain-specific, i.e., the GPC rules can only take letters as \ninputs and pass phoneme activations to the phoneme system\n", "image": "assets/reading2/011.webp", "core": true, "reviewPages": [], "paragraphs": ["**The DRC routes are modular in several related senses.** They use different processing assumptions, restrict information exchange and accept particular kinds of input.", "The GPC system takes letters as input and sends phoneme activation toward the response system. This is **domain specificity** in the account.", "The absence of lexical feedback into the GPC system is **informational encapsulation**. Having two pathways alone would not establish those stronger restrictions."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p012", "noteId": "m3-reading2-p012", "module": "reading2", "source": "reading2", "page": 12, "title": "An emergentist reading model", "sourceText": "An emergentist approach: PDP models of visual word \nrecognition\nSeidenberg & McClelland (1989)\nConceived of reading skill as emerging from mappings \namong spelling, pronunciation, and meaning.\nModeled the learning of these mappings by training a \nsimple associative network. \nStudied mappings from orthography to phonology (O \nP) in a single “route.”\n", "image": "assets/reading2/012.webp", "core": false, "reviewPages": [], "paragraphs": ["**PDP models treat reading as learned mappings among orthography, phonology and semantics.** Orthography is spelling, phonology is sound structure, and semantics is meaning.", "Seidenberg and McClelland trained an associative network to map spelling onto pronunciation. The modeled spelling-to-sound pathway used one learned mapping for different kinds of words.", "Reading skill emerges from learning rather than being specified entirely as a hand-built list of rules and lexical entries."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p013", "noteId": "m3-reading2-p013", "module": "reading2", "source": "reading2", "page": 13, "title": "Distributed knowledge and general learning", "sourceText": "PDP models of visual word recognition\nSeidenberg & McClelland (1989)\nDifferent assumptions from dual-route models:\n- “rules” are just generalizations from lots of \nwords, not a separate process\n- the “lexicon” is also distributed. Some \nwhole-word information is stored in O P \nmappings, some in  other parts of the system.\nDifferent research strategy from dual-route \nmodels:\nExplain reading in terms of domain-general \nlearning mechanisms, rather than reverse-\nengineer the system from adult/neuropsych data.\n", "image": "assets/reading2/013.webp", "core": true, "reviewPages": [8], "paragraphs": ["**In a PDP account, rules are generalizations learned across words.** Whole-word knowledge is distributed across learned mappings instead of being stored only in a distinct lexical route.", "The same learning mechanism can capture both patterns shared by many words and information specific to a familiar word.", "The research strategy asks whether domain-general learning can explain reading. This contrasts with choosing separate adult processing components primarily from neuropsychological dissociations."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p014", "noteId": "m3-reading2-p014", "module": "reading2", "source": "reading2", "page": 14, "title": "Learning the frequency–regularity interaction", "sourceText": "Frequency by regularity interaction\nThe model captured the interaction between \nfrequency and regularity without assuming \nthat these effects resulted from different \nprocesses.\nHow?\n- “regular” words are consistent with \nstatistical patterns from many other words.\n- “exception” words are inconsistent with \nthese statistics.\n- frequency also impacts how well words \nare learned. So, highly frequent words are \nless effected by inconsistency with other \nwords.\n", "image": "assets/reading2/014.webp", "core": true, "reviewPages": [9], "paragraphs": ["**A learned network can produce a frequency-by-regularity interaction without separate frequency and rule mechanisms.** Regular words receive support from patterns shared across many words.", "An exception conflicts with those patterns, so learning its particular mapping is especially important. Frequent exposure strengthens that word-specific mapping.", "A low-frequency exception has both weak item-specific learning and poor support from the dominant pattern. This combination creates a larger disadvantage than either factor alone."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p015", "noteId": "m3-reading2-p015", "module": "reading2", "source": "reading2", "page": 15, "title": "Consistency rather than a single rule boundary", "sourceText": "Redefining “regularity”\nRegular Consistent: Many friends and no \nenemies [LATE, DUST]\nRegular Inconsistent: Many friends but at \nleast one enemy [GAVE (cf.HAVE), MINT \n(cf.PINT)]\nAmbiguous: About equal numbers of \nfriends and enemies [DOWN, KNOWN; \nPOUR, SOUR] \nException: Few if any friends and many \nenemies [HAVE (cf. GAVE), PINT (cf. \nMINT)] \n", "image": "assets/reading2/015.webp", "core": true, "reviewPages": [], "paragraphs": ["**Consistency describes how many similar spellings support a pronunciation.** “Friends” have the relevant spelling pattern and a compatible pronunciation, while “enemies” support a competing pronunciation.", "LATE and DUST illustrate consistent patterns. GAVE and MINT have many friends but also enemies such as HAVE and PINT.", "DOWN versus KNOWN and POUR versus SOUR illustrate ambiguity. An exception such as PINT has relatively little support compared with its competing neighborhood."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p016", "noteId": "m3-reading2-p016", "module": "reading2", "source": "reading2", "page": 16, "title": "Using learned weights for nonwords", "sourceText": "Reading words and nonwords in the same \n“route”\nIn principle: \n- nonwords named via the same set of weights used \nfor words.\n- generalization takes advantage of the same statistical \npatterns that give rise to regularity effects.\n", "image": "assets/reading2/016.webp", "core": true, "reviewPages": [10], "paragraphs": ["**A PDP model can pronounce nonwords using the weights learned from real words.** A new spelling activates patterns that overlap with familiar spellings, allowing the network to generalize.", "No stored entry for the particular nonword is required. The same learned correspondences that support consistent words can support a new combination.", "This is a proposed mechanism for decoding without a separate GPC rule module."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p017", "noteId": "m3-reading2-p017", "module": "reading2", "source": "reading2", "page": 17, "title": "Theory versus implementation", "sourceText": "In practice, though, not so great…\nNonword accuracy was not very \ngood.\nWhy?\nThis is a classic case of ambiguity in \nmodel evaluation.\nWas the theoretical claim -- that \nnonwords and exceptions could \nbe read by the same, associative \nmechanism – wrong?\nOr, was the problem something \nspecific to the way the model was \nmade?\n", "image": "assets/reading2/017.webp", "core": true, "reviewPages": [11], "paragraphs": ["**Poor nonword performance can challenge either a theoretical proposal or a particular implementation.** The early model's nonword accuracy was weaker than desired.", "One possibility is that a single associative mechanism cannot explain the task. Another is that the chosen representations fail to capture the similarities needed for generalization.", "Improving the implementation while retaining the theoretical mechanism helps distinguish these possibilities."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p018", "noteId": "m3-reading2-p018", "module": "reading2", "source": "reading2", "page": 18, "title": "Phonological representation matters", "sourceText": "Nonword reading related to phonological representations\nMany studies demonstrate a \nrelationship between “decoding” \n(i.e., nonword reading) and \nphonological processing.\nThe phonological representations \nused in Seidenberg & McClelland \nwere sort of weird:  Wickelfeatures.\nIndeed, a model by Plaut et al. (1996, \nPsych Review) improved the \nphonological representations, and \nproduced better performance on \nnonwords.\n", "image": "assets/reading2/018.webp", "core": true, "reviewPages": [12], "paragraphs": ["**Generalization depends on how sound similarity is represented.** The early Seidenberg–McClelland model used Wickelfeatures, whose representation of phonology was problematic for nonword reading.", "Plaut and colleagues improved the phonological representations and obtained better nonword performance. This supports a representational explanation for at least part of the earlier failure.", "Behavioral relations between phonological processing and decoding also make phonology a relevant target for explanation."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p019", "noteId": "m3-reading2-p019", "module": "reading2", "source": "reading2", "page": 19, "title": "Why degraded phonology hurts generalization", "sourceText": "How are phonological representations and \nnonword generalization related?\nGeneralization depends on similarity. (In fact this principle is \ninherited from behaviorism.)\nPoor phonological representations (like Wickelfeatures) fail to \nadequately capture the similarity space of words in the language.\nWord-specific information is more robust to poor representations, \nbecause it doesn’t depend entirely on generalization.\n", "image": "assets/reading2/019.webp", "core": true, "reviewPages": [13], "paragraphs": ["**A network generalizes through similarity.** If its phonological representation poorly captures similarities among words, the learned mapping cannot transfer as effectively to new forms.", "A familiar word can retain support from its own training history. A nonword lacks that item-specific experience and depends more heavily on generalization.", "This produces a reason for unfamiliar forms to be especially vulnerable to poor representations without requiring a dedicated nonword mechanism."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p020", "noteId": "m3-reading2-p020", "module": "reading2", "source": "reading2", "page": 20, "title": "Harm and Seidenberg's noise manipulation", "sourceText": "How are phonological representations and \nnonword generalization related?\nHarm & Seidenberg (1999) investigated \nthis more systematically, by \nmanipulating the amount of “noise” in \nthe phonological representations.\nThey were able to replicate a number of \nkey findings in the literature on \ndevelopmental dyslexia:\n- relationship between degree of \nphonological deficit and phonological \ndyslexia\n- relative sparing of word recognition\n", "image": "assets/reading2/020.webp", "core": true, "reviewPages": [14], "paragraphs": ["**Harm and Seidenberg manipulated noise in phonological representations.** Increasing noise makes the sound representations less reliable while keeping the model's general learning framework.", "The manipulation produced poorer nonword decoding and relative sparing of word recognition. It also linked the severity of the phonological deficit to the degree of decoding difficulty.", "The model therefore connects a reading pattern to the quality of a more general phonological system."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p021", "noteId": "m3-reading2-p021", "module": "reading2", "source": "reading2", "page": 21, "title": "Semantics and surface dyslexia", "sourceText": "What about all of those double-dissociations?\nWe’ve already seen how nonword\nreading can be specifically impaired, \ndespite the model’s lack of a specific \n“nonword reading mechanism.”\nPlaut et al. (1996) explored the other \nend of this dissociation: surface \ndyslexia. \nTo do this, they implemented a \nsimplified semantic system, and \ndemonstrated that lesions to \nsemantics resulted in a specific \nimpairment on “exception” words. \n", "image": "assets/reading2/021.webp", "core": true, "reviewPages": [], "paragraphs": ["**Damaging semantic support in a triangle model can impair exception-word reading especially strongly.** Plaut and colleagues added a simplified semantic contribution and examined what happened when it was lesioned.", "An exception has weak support from typical spelling–sound regularities. Meaning-related support can help produce its learned pronunciation.", "Reducing that support creates a surface-dyslexia-like pattern without defining a separate exception-word list as the sole explanation."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p022", "noteId": "m3-reading2-p022", "module": "reading2", "source": "reading2", "page": 22, "title": "Why the triangle is not just DRC renamed", "sourceText": "Why is this not just the dual route model now?\nSemantic representations are directly involved, as opposed \nto a theoretical commitment to a lexicon independent \nof semantics.\n[A later model (Harm & Seidenberg, 2004) would \nimplement featural semantics, and simulate the \nmapping of spelling to meaning.]\nThe OP and SP mappings have the same processing \nassumptions and learning algorithm. Both are \nprobabilistic. \nA key point of these simulations is that these pathways interact over the course of \nlearning. So, the OP pathway develops differently in the context of an OSP \npathway than it would otherwise.\nThis interactivity and gradedness permits the models to capture the fact that double \ndissociations are never entirely “clean.”\n- Phonological dyslexics are not perfect on exception words. \n- Surface dyslexics are not perfect on nonwords.\n", "image": "assets/reading2/022.webp", "core": true, "reviewPages": [], "paragraphs": ["**The triangle model's pathways share graded learning assumptions and interact during learning.** Semantic representations are directly involved rather than replaced by a lexicon defined as independent of meaning.", "Spelling-to-sound learning develops in the presence of meaning-related support. The contribution of one pathway therefore affects what another pathway learns.", "This allows graded impairments. Phonological dyslexics can make some exception errors, and surface dyslexics can make some nonword errors."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p023", "noteId": "m3-reading2-p023", "module": "reading2", "source": "reading2", "page": 23, "title": "Semantics and exception reading in patients", "sourceText": "Model predicts a strong association between \nsemantic abilities and exception word reading \n(Woollams et al., 2007) \n", "image": "assets/reading2/023.webp", "core": true, "reviewPages": [], "paragraphs": ["**Woollams and colleagues tested the predicted association between semantic ability and exception-word reading.** Lower semantic scores were associated with poorer low-frequency exception reading in patients with semantic dementia.", "The model and patient panels show comparable overall relationships, although individual patients vary. This supports an association between meaning and exceptional pronunciation.", "The finding is informative because it links a reading weakness to a broader semantic measure rather than describing only a reading-task dissociation."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p024", "noteId": "m3-reading2-p024", "module": "reading2", "source": "reading2", "page": 24, "title": "Interpreting apparent exceptions", "sourceText": "…this means the model misses a few data \npoints\nWhat should we make of \nthis?\nPatients to the left of the \nvertical line, and above the \nhorizontal line are statistical \noutliers.\nWoollams et al. would argue \nthat these observations \nshould be treated the way \nwe normally treat outliers \nwhen evaluating the fit of a \nmodel to data…\n", "image": "assets/reading2/024.webp", "core": false, "reviewPages": [], "paragraphs": ["**Some patients have relatively good exception reading despite low semantic scores.** These cases challenge a perfect one-to-one relationship, but an account of graded association does not predict zero variability.", "Woollams and colleagues interpret such observations in relation to the full distribution rather than treating each outlier as an automatic refutation.", "The scientific issue is whether the unusual cases show a stable separate pattern or arise within a noisy overall association."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p025", "noteId": "m3-reading2-p025", "module": "reading2", "source": "reading2", "page": 25, "title": "Following semantic dementia over time", "sourceText": "Further, because they were studying \npatients with a progressive\ncondition (semantic dementia) they \ncould observe how exception word \nreading changed as semantic \nabilities declined.\nIn most cases, when a patient’s \nsemantic abilities declined over \ntime, her reading ability also \ndeclined.\nNote also the regression to the \nmean with multiple observations. If \nthe dissociation between semantics \nand exception word reading were \ndue to idiosyncratic outliers, it \nwould show just this pattern.\n", "image": "assets/reading2/025.webp", "core": true, "reviewPages": [], "paragraphs": ["**Longitudinal observations track whether semantic and reading abilities change together within a patient.** Because semantic dementia progresses, repeated testing can reveal a trajectory rather than a single unusual score.", "In most cases, declining semantic ability accompanies declining exception-word reading. Some initially unusual observations move closer to the broader relation on retesting.", "This strengthens the association while leaving room for variability between individuals."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p026", "noteId": "m3-reading2-p026", "module": "reading2", "source": "reading2", "page": 26, "title": "Fitting the same patients with DRC", "sourceText": "DRC simulation of the same data\nColtheart et al. (2009, Psych Review) \nsimulated surface dyslexia by \ngenerating a population of 40,000 \nmodel “patients” varying on two \nparameters:\n- integrity of lexical route\n- integrity of GPC rules\nFor each patient in the Woollams et al. \ndata, they then selected the run of the \nmodel that best fit that patient’s data.\nIn this way, they produce an excellent \nfit to the data. \n", "image": "assets/reading2/026.webp", "core": true, "reviewPages": [], "paragraphs": ["**Coltheart and colleagues generated 40,000 model patients with different lexical-route and GPC impairment levels.** For each real patient, they selected the model run that best matched the observed data.", "This produced an excellent fit to the patient scores. The selection procedure is part of how that fit was achieved.", "The fit should be distinguished from predicting each patient's pattern before choosing among many possible parameter combinations."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p027", "noteId": "m3-reading2-p027", "module": "reading2", "source": "reading2", "page": 27, "title": "Fit and explanatory constraint", "sourceText": "Why would anyone argue that a better fit to the data \nis actually a bad thing in this case?\n", "image": "assets/reading2/027.webp", "core": true, "reviewPages": [], "paragraphs": ["**A better fit can be less informative if it relies on much greater flexibility.** Selecting the best match from many parameter combinations can reproduce a dataset without strongly constraining the underlying explanation.", "The question is not whether close agreement is bad in itself. It is whether the account predicts the relation with principled assumptions or accommodates each case after seeing the outcome.", "Comparing theories therefore requires attention to both fit and how much freedom produced it."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p028", "noteId": "m3-reading2-p028", "module": "reading2", "source": "reading2", "page": 28, "title": "Shared targets for competing models", "sourceText": "Comparison of dual-route and “triangle” models.\nBoth models cover a range of data about reading, including some basic facts:\n- decoding is fast and automatic (e.g., pseudoword reading)\n- words that diverge from typical spelling-to-sound mappings are harder to read\n- this “regularity” or “consistency” effect interacts with word frequency\n- pseudoword reading and “exception” or “inconsistent” word reading are dissociable \nin neuropsych patients \n", "image": "assets/reading2/028.webp", "core": false, "reviewPages": [], "paragraphs": ["**Dual-route and triangle models address many of the same findings.** Both must explain rapid nonword decoding, exception difficulty, the frequency–regularity interaction and acquired reading dissociations.", "Agreement on the phenomena does not mean agreement on mechanisms. One account emphasizes specialized routes, while the other emphasizes learning across interacting representational systems."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p029", "noteId": "m3-reading2-p029", "module": "reading2", "source": "reading2", "page": 29, "title": "Comparing explanations across models", "sourceText": "Comparison of dual-route and “triangle” models.\nTriangle\nDual-Route\nPhenomenon\nStatistical regularities \nlearned over many words\nDedicated “grapheme-\nphoneme conversion” (GPC) \nrule system\nPseudoword reading and \nregularity effects\nMore exposure to a word = \nbetter learning for that \nword\nDistinct lexicons for input \nand output, separate from \nGPC rules\nFrequency effects\nDeficit/damage in \nphonological processing, \ngenerally\nDeficit/damage in the GPC \nroute\nPhonological dyslexia\nDeficit/damage in semantic \nprocesses, generally\nDeficit/damage in the lexical \nroute\nSurface dyslexia\n", "image": "assets/reading2/029.webp", "core": true, "reviewPages": [], "paragraphs": ["**DRC attributes nonword decoding and regularity effects to GPC rules, while the triangle account attributes them to statistical learning.** Word-specific exposure strengthens learned mappings in the triangle account and affects lexical processing in DRC.", "For phonological dyslexia, DRC emphasizes GPC damage and the triangle account emphasizes broader phonological impairment.", "For surface dyslexia, DRC emphasizes lexical-route damage and the triangle account emphasizes semantic impairment."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p030", "noteId": "m3-reading2-p030", "module": "reading2", "source": "reading2", "page": 30, "title": "Dissociations and associations", "sourceText": "Comparison of dual-route and “triangle” models.\nTriangle\nDual-Route\nPhenomenon\nDeficit/damage in \nphonological processing, \ngenerally\nDeficit/damage in the GPC \nroute\nPhonological dyslexia\nDeficit/damage in semantic \nprocesses, generally\nDeficit/damage in the lexical \nroute\nSurface dyslexia\nThis is a key contrast: \nDual route models (generally) are motivated by double-dissociations: \nPseudowords and exception words can be impaired independently, so they should be \nmodeled as independent processes.\nModels informed by statistical learning instead reveal associations: Phonology is \nimportant for learning/using OP generalizations; semantics is important for words \nwhere OP generalization is ambiguous. \n", "image": "assets/reading2/030.webp", "core": true, "reviewPages": [], "paragraphs": ["**A major contrast is whether the explanation begins with separate reading routes or broader language associations.** Dual-route models use different task impairments to motivate independent processes.", "The statistical-learning account links phonology to spelling–sound generalization and semantics to words whose pronunciation is poorly supported by that generalization.", "Both dissociations and associations matter. A theory should explain selective weaknesses and the related abilities that vary with them."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-reading2-p031", "noteId": "m3-reading2-p031", "module": "reading2", "source": "reading2", "page": 31, "title": "Reading assignment", "sourceText": "For next time:\nRead Joanisse (2004) “Specific Language Impairments in Children”\nhttp://publish.uwo.ca/~marcj/joanisse-cdps-2004.pdf\n", "image": "assets/reading2/031.webp", "core": false, "reviewPages": [], "paragraphs": [], "analysis": {"status": "authored", "role": "noninstructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-morphology-p001", "noteId": "m3-morphology-p001", "module": "morphology", "source": "morphology", "page": 1, "title": "Inflectional morphology and language impairment", "sourceText": "More modeling: The case of inflectional morphology and specific language impairment ", "image": "assets/morphology/001.webp", "core": false, "reviewPages": [], "paragraphs": [], "analysis": {"status": "authored", "role": "noninstructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p002", "noteId": "m3-morphology-p002", "module": "morphology", "source": "morphology", "page": 2, "title": "Generative morphology", "sourceText": "Quick review\nMorphology is “generative”\n\nFor example, at some point there was no noun “generative,” just the verb “to generate.” But English has a process for turning verbs into nouns. That’s derivational morphology.\n\nToday we’re going to focus on inflectional morphology. In English this pretty much means the plural and the past tense.\n\n", "image": "assets/morphology/002.webp", "core": false, "reviewPages": [], "paragraphs": ["**Morphology is generative because speakers can form words they have not memorized individually.** Derivational morphology creates a new lexical form, while inflection marks grammatical information such as plural or past tense.", "The central question is how a speaker extends a familiar pattern to a new item. English plural and past-tense formation provide tractable examples.", "Generalization can also produce playful or incorrect forms. This shows productive use of patterns, rather than a vocabulary containing only previously heard responses."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p003", "noteId": "m3-morphology-p003", "module": "morphology", "source": "morphology", "page": 3, "title": "The wug test", "sourceText": "Classic study by Jean Berko Gleason (1958).\n\nDemonstrates how readily people generalize the past tense to new words.\n\nChildren do this too (thus the cute drawings).\nThe “wug” test", "image": "assets/morphology/003.webp", "core": true, "reviewPages": [], "paragraphs": ["**Berko Gleason's wug test measures morphological generalization to a novel word.** A child learns a new label and then supplies an inflected form that has not been provided.", "The pictured task introduces one WUG and then asks about two. Producing WUGS applies plural knowledge to a new noun.", "The same logic can test past tense using novel verbs. Success shows productive knowledge, but does not by itself distinguish symbolic rules from statistical generalization."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p004", "noteId": "m3-morphology-p004", "module": "morphology", "source": "morphology", "page": 4, "title": "Regular and irregular past tense", "sourceText": "The English past tense has “regular” and “irregular” forms.\nRegulars\nshow-showed, bake-baked, wade-waded\nblick-blicked, trog-trogged, \u000bwumble-wumbled \n\nIrregulars\ngo-went, take-took, eat-ate, sleep-slept\n\nThis should remind you right away of the last few lectures… ", "image": "assets/morphology/004.webp", "core": false, "reviewPages": [], "paragraphs": ["**Regular past tense follows the productive -ed pattern.** SHOW becomes SHOWED, BAKE becomes BAKED, and a novel verb such as BLICK can become BLICKED.", "Irregular pairs such as GO–WENT, TAKE–TOOK and EAT–ATE do not follow that default form. Some irregulars share smaller patterns with other verbs.", "A theory must explain both familiar exceptions and productive extension to novel verbs."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p005", "noteId": "m3-morphology-p005", "module": "morphology", "source": "morphology", "page": 5, "title": "Words and Rules", "sourceText": "Words and Rules\nPinker & colleagues\n‘words and rules’ are separate processes, representational formats, etc.\n\nRegulars: \nsymbolic rules (e.g., “add –ed”)\n\nIrregulars: \nlexicalized within “associative network”\n", "image": "assets/morphology/005.webp", "core": true, "reviewPages": [], "paragraphs": ["**The Words and Rules account gives regular and irregular inflection different mechanisms.** A symbolic rule generates a regular past tense, while irregular forms are stored in an associative lexical system.", "The regular process can apply to a new verb because it does not require an entry for that particular past tense.", "The irregular system stores word-specific information and can be influenced by frequency and similarity. A successful explanation also needs to prevent an available irregular form from being replaced by a regularization."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p006", "noteId": "m3-morphology-p006", "module": "morphology", "source": "morphology", "page": 6, "title": "A dual-process past-tense architecture", "sourceText": "A “dual route” model for the past tense\nPinker & Ullman (2002, TICS)\nHow is this similar to the dual-route model we were just considering for reading?\n\n\nHow is it different?\n", "image": "assets/morphology/006.webp", "core": true, "reviewPages": [15], "paragraphs": ["**The lexicon and grammar offer different ways to produce a past tense.** Lexical retrieval supplies an irregular form such as HELD, while grammatical combination can produce WALK plus -ed.", "Pinker and Ullman's diagram associates lexical lookup with declarative memory and grammatical combination with procedural processing.", "Like dual-route reading, the account separates word-specific knowledge from a productive operation. Unlike reading aloud, its task is to transform a stem according to a grammatical feature, rather than convert spelling into sound."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p007", "noteId": "m3-morphology-p007", "module": "morphology", "source": "morphology", "page": 7, "title": "Why separate rules from exceptions?", "sourceText": "Similar architecture, different origins\nRemember the dual route model was developed based on neuropsychological double-dissociations.\n\nPinker et al. are motivated by other concerns.\n\nGenerative linguistics of the time was mostly about categorical, symbolic, rule-based grammars.\n\nThese rules often have exceptions.\n\n\n", "image": "assets/morphology/007.webp", "core": true, "reviewPages": [16], "paragraphs": ["**The Words and Rules proposal was motivated partly by a theory of grammar.** A categorical symbolic grammar describes productive patterns, but language also contains exceptions.", "Reading dual-route theories were strongly motivated by neuropsychological dissociations. The morphology proposal also reflects a commitment to keeping the grammatical rule system distinct from exceptional lexical information."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p008", "noteId": "m3-morphology-p008", "module": "morphology", "source": "morphology", "page": 8, "title": "Properties of the exception system", "sourceText": "Similar architecture, different origins\nRather than make the grammar inelegant by adding machinery to handle the exceptions, linguists would often just leave the exceptions out of the grammar.\n\nSo dual-process model proposes a way to “handle” the exceptions while keeping the grammar elegant, symbolic, categorical, etc.\n\nThis second process had all the properties the rule route did not. It was:\n\t  - word-specific (lexical)\n\t\t- sensitive to frequency of occurrence\n\t  - sensitive to phonological similarity (keep-kept, weep-wept, leap-leapt, etc.)  \n\t", "image": "assets/morphology/008.webp", "core": true, "reviewPages": [17], "paragraphs": ["**An associative lexicon handles information that does not fit a categorical rule.** Its representations are word-specific and sensitive to frequency and phonological similarity.", "KEEP–KEPT, WEEP–WEPT and LEAP–LEAPT illustrate similarity among irregular forms. An exception can belong to a small family rather than being wholly unrelated to other words.", "Assigning these properties to lexical memory lets the rule system remain categorical and general."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p009", "noteId": "m3-morphology-p009", "module": "morphology", "source": "morphology", "page": 9, "title": "An associative alternative", "sourceText": "An alternative approach: It’s all associative learning!\nRumelhart & McClelland (1987) available, along with lots of these other papers, here: http://psych.stanford.edu/~jlm/papers/", "image": "assets/morphology/009.webp", "core": true, "reviewPages": [18], "paragraphs": ["**Rumelhart and McClelland modeled past tense as a learned association between present and past sound patterns.** A single trainable network learns across verbs instead of applying a separately specified -ed rule.", "The model encodes a root's phonology, transforms that representation through modifiable connections, and decodes an output pattern.", "Regularity is a pattern learned from many examples. Irregular forms are also learned within the same system."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p010", "noteId": "m3-morphology-p010", "module": "morphology", "source": "morphology", "page": 10, "title": "U-shaped learning", "sourceText": "Target phenomena of Rumelhart & McClelland\nBecause this was one of the first learning models to address a language process, the focus was on capturing developmental phenomena.\n\nSpecifically: “U-shaped” learning:\n\n\t- some frequent irregular verbs are learned quite early, e.g., run-ran\n\n\t- then, spontaneously, children begin producing “regularizations:” runned.\n\n\t- eventually, they start producing correct forms again.\n\nLearning is “U-shaped” because children often get worse before they get better, so performance goes down before it goes back up.", "image": "assets/morphology/010.webp", "core": true, "reviewPages": [19], "paragraphs": ["**U-shaped learning describes an initial success, a decline, and later recovery.** A child may correctly say RAN, later produce RUNNED, and eventually return to RAN.", "The middle error is a **regularization**, because the child applies the common past-tense pattern to an irregular verb.", "The decline does not necessarily mean that the child has stopped learning. A changing system can generalize more broadly while temporarily disrupting an earlier correct response."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p011", "noteId": "m3-morphology-p011", "module": "morphology", "source": "morphology", "page": 11, "title": "Words and Rules interpretation of development", "sourceText": "Why is U-shaped learning important to the “words and rules” approach? \nIt’s understood in terms of distinct stages/processes:\n\n\t- early correct forms are just imitations, don’t depend on the same mechanisms as adult processing.\n\n\t- when the rule is initially learned, it is applied to all cases. We can think of the rule as the “best hypothesis” for all items generally.\n\n\t- over time, exceptions are learned associatively, one-by-one and incorporated into lexical knowledge. Further, the “blocking process” develops.", "image": "assets/morphology/011.webp", "core": true, "reviewPages": [20], "paragraphs": ["**The Words and Rules account explains U-shaped learning through changes in the use of rules and lexical exceptions.** Early correct forms can be imitated before a productive rule is available.", "When the rule is learned, it can be applied too broadly, yielding RUNNED. Later, learned irregulars and the blocking process prevent that regularization.", "This account treats the developmental stages as involving distinguishable processes rather than only gradual changes in one mapping."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p012", "noteId": "m3-morphology-p012", "module": "morphology", "source": "morphology", "page": 12, "title": "U-shaped learning in an associative model", "sourceText": "“U-shaped learning” in Rumelhart & McClellands’s model.\n\n - training set is based on data about input to children, which changes over time.\n\n Early on, irregular verbs predominate – in fact the highest-frequency verbs tend to have irregular past-tense forms: GIVE, TAKE, HAVE, GO, etc.\n\n As the vocabulary expands to include more regular forms, the model reorganizes to capture those regularities.\n\n- this interferes with some of the early-learned forms.    ", "image": "assets/morphology/012.webp", "core": true, "reviewPages": [21], "paragraphs": ["**Changing the training vocabulary can produce U-shaped learning in one network.** Early training emphasizes frequent irregular verbs, allowing those particular mappings to be learned.", "As more regular verbs enter training, their common pattern changes the network's responses. That generalization can interfere with previously learned irregulars.", "With further learning, the network can recover the irregular responses while retaining broad regularity. No new symbolic rule component is inserted at the point of decline."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p013", "noteId": "m3-morphology-p013", "module": "morphology", "source": "morphology", "page": 13, "title": "Testing model generalization", "sourceText": "Generalization testing:\n\nThe model was trained on a small number of verbs, so they could do a “wug” test with real words… ", "image": "assets/morphology/013.webp", "core": true, "reviewPages": [22], "paragraphs": ["**Testing untrained verbs asks whether the network learned transferable structure.** A real English verb can be novel to a model if it was excluded from that model's training set.", "The test therefore uses the logic of a wug task even when the items are real words to humans.", "The model can generate many appropriate past-tense features, but feature-level success must be distinguished from producing an entirely correct word."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p014", "noteId": "m3-morphology-p014", "module": "morphology", "source": "morphology", "page": 14, "title": "Unusual model outputs", "sourceText": "But…", "image": "assets/morphology/014.webp", "core": true, "reviewPages": [23], "paragraphs": ["**Some model outputs contain changes that are unlike ordinary human regularizations.** Examples include MADE(D)-like changes to MATE and the unusual outputs MEMBLED for MAIL and TOUREDER for TOUR.", "The model authors acknowledge that people are unlikely to make some of these errors. They suggest that additional output constraints could reduce bizarre responses.", "This separates capturing an overall learning pattern from matching the detailed form of human errors."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p015", "noteId": "m3-morphology-p015", "module": "morphology", "source": "morphology", "page": 15, "title": "The blending criticism", "sourceText": "\nPrince & Pinker (1988, BBS)\n", "image": "assets/morphology/015.webp", "core": true, "reviewPages": [], "paragraphs": ["**Prince and Pinker argued that feature representations can blend distinct alternatives.** A model may activate features belonging to several possible past-tense forms without keeping those candidates separate.", "For SING, partial support for different sound patterns can overlap. Decoding the combined activation can produce a hybrid rather than selecting a coherent word.", "The criticism targets the representation and its treatment of competing outputs, not merely the presence of learning."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p016", "noteId": "m3-morphology-p016", "module": "morphology", "source": "morphology", "page": 16, "title": "Phonology and semantics in inflection", "sourceText": "A new(er) model: Joanisse & Seidenberg (1999)\nTheoretical premise:\n\n\t- “rule-like” generalization is supported by phonological representations\n\n \t- “irregular” forms require greater support from semantics ", "image": "assets/morphology/016.webp", "core": true, "reviewPages": [24], "paragraphs": ["**Joanisse and Seidenberg propose that phonology supports rule-like generalization while semantics especially supports irregular forms.** The same system links speech input, meaning and speech output.", "Reliable sound representations support extension from familiar present–past pairs to new forms. Irregular mappings receive additional support from the particular word's semantic representation.", "The hypothesis concerns different degrees of dependence on shared systems, rather than a separate symbolic rule route for every regular response."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p017", "noteId": "m3-morphology-p017", "module": "morphology", "source": "morphology", "page": 17, "title": "Targeting a neuropsychological dissociation", "sourceText": "A new(er) model: Joanisse & Seidenberg (1999)\nTarget phenomenon:\n\n\t- dissociation between irregular and nonword past tense in neuropsychological data.  ", "image": "assets/morphology/017.webp", "core": true, "reviewPages": [25], "paragraphs": ["**The model aims to explain the dissociation between irregular and nonword past-tense performance.** These tasks differ in how much they depend on learned word-specific information and phonological generalization.", "A nonword has no familiar item-specific semantic history to support its inflection. A known irregular can require semantic support because its output is not well predicted by the dominant pattern.", "Manipulating phonological or semantic integrity tests whether these different dependencies can produce opposite impairment profiles."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p018", "noteId": "m3-morphology-p018", "module": "morphology", "source": "morphology", "page": 18, "title": "Broca's aphasia and novel past tense", "sourceText": "Neuropsychological data\nBroca’s Aphasia\nInjury to left anterior brain regions\n\nPoor speech production\n\nProblems with regular morphology, esp. nonwords\nwug  wugged, \nblick   blicked", "image": "assets/morphology/018.webp", "core": true, "reviewPages": [26], "paragraphs": ["**The patient pattern associated here with Broca's aphasia includes especially poor nonword past-tense production.** These patients have left anterior injury and difficulty producing speech.", "Regular forms are also vulnerable, while irregular forms are relatively better in the displayed comparison. A novel BLICK must be transformed without relying on a familiar stored past tense.", "This motivates investigating phonological contributions to the apparent morphological deficit."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p019", "noteId": "m3-morphology-p019", "module": "morphology", "source": "morphology", "page": 19, "title": "Phonological damage in the model", "sourceText": "Phonological Impairment in the Model\nReduced ability to compute past tense forms\n\nNonwords worse than regulars and irregulars\n\nRegulars numerically worse than irregulars\n", "image": "assets/morphology/019.webp", "core": true, "reviewPages": [], "paragraphs": ["**Phonological impairment reduces past-tense performance most strongly for nonwords in the model.** Regulars are numerically worse than irregulars, but the largest difference concerns novel forms.", "The model manipulation weakens sound-based computation. Familiar words retain support unavailable to an untrained nonword.", "The similarity to the patient pattern shows how a selective-looking morphological deficit can arise from a broader phonological impairment."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p020", "noteId": "m3-morphology-p020", "module": "morphology", "source": "morphology", "page": 20, "title": "Patients with irregular-form difficulties", "sourceText": "Neuropsychological data: Problems with irregulars\nWernicke’s and Alzheimer’s patients\nAnomic patients with injury to inferior/middle temporal brain regions\n\nPoor on irregulars (middle bar)\n", "image": "assets/morphology/020.webp", "core": true, "reviewPages": [27], "paragraphs": ["**Other patient groups show a larger problem with irregular past-tense forms.** The material discusses Wernicke's and Alzheimer's patients and anomic patients with inferior or middle temporal injury.", "Their irregular performance is lower than their regular and nonword performance in the displayed comparison.", "This creates the other side of the dissociation and motivates examining the information that especially supports known irregular forms."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p021", "noteId": "m3-morphology-p021", "module": "morphology", "source": "morphology", "page": 21, "title": "Semantic damage in the model", "sourceText": "Effects of Semantic Impairment\nIrregulars worse than regulars and nonwords\n\nNonwords a bit worse than regulars", "image": "assets/morphology/021.webp", "core": true, "reviewPages": [], "paragraphs": ["**Semantic impairment particularly disrupts irregular past-tense forms.** When the model loses meaning-related support, irregular accuracy falls below regular and nonword accuracy.", "Typical phonological patterns still support many regular and novel forms. Nonwords can nevertheless be somewhat worse than regular words because they lack item-specific training.", "This shows how unequal dependence on semantics can produce the reverse of the phonological-damage profile."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p022", "noteId": "m3-morphology-p022", "module": "morphology", "source": "morphology", "page": 22, "title": "Testing the double-dissociation interpretation", "sourceText": "Broca’s patients:\nDifferences between regulars and irregulars are reduced when items are adequately controlled for phonology\n(Bird, Patterson, Lambon-Ralph, McClelland & Seidenberg, 2003)\n\nSemantic dementia patients: \nDegree of impairment with irregulars correlates strongly with severity of semantic deficit\n(Patterson, Lambon-Ralph, Hodges & McClelland, 2001)\n\nOther issues with the double dissociation data:", "image": "assets/morphology/022.webp", "core": true, "reviewPages": [], "paragraphs": ["**Phonological controls can change the apparent regular–irregular difference.** Bird and colleagues found that the difference in Broca's patients was reduced when items were adequately matched for phonology.", "Patterson and colleagues found that irregular impairment in semantic dementia correlated with semantic deficit severity.", "These findings connect morphology to phonological and semantic abilities, making a pure rule-versus-word interpretation less straightforward."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p023", "noteId": "m3-morphology-p023", "module": "morphology", "source": "morphology", "page": 23, "title": "Generalization and item-specific support", "sourceText": "Compare this to the “triangle model” account of dyslexia:\nPhonological representations support generalization.\n\n\tgeneralization is a result of statistical learning about patterns in the mapping from present to past\n\n\timpaired phonological representations impact these generalizations\n\nSemantic representations support idiosyncratic forms.\n\n\tforms that deviate from the overwhelmingly regular “add –ed” pattern need support from semantics\n\n\tsome “irregular” forms can take advantage of the sub-patterns, and are likely to be “spared”  \n\t", "image": "assets/morphology/023.webp", "core": true, "reviewPages": [], "paragraphs": ["**Phonological representations support learning the common mapping from present to past.** A degraded representation makes that generalization less reliable, especially for new words.", "Semantic information supports forms that depart from the dominant -ed pattern. Some irregulars also benefit from smaller phonological families and can be relatively spared.", "Regularity and exception status therefore describe degrees of statistical support rather than perfectly isolated kinds of processing."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p024", "noteId": "m3-morphology-p024", "module": "morphology", "source": "morphology", "page": 24, "title": "Specific language impairment", "sourceText": "Specific Language Impairment\nImpaired language development\n“Normal” performance/nonverbal IQ\nAffected grammar\nmorphology\nsyntax\nBut also:\nphonology \nreading \nworking memory\nspeech perception", "image": "assets/morphology/024.webp", "core": false, "reviewPages": [], "paragraphs": ["**Specific language impairment, or SLI in the course terminology, involves impaired language development despite relatively typical nonverbal performance.** Difficulties can include morphology and syntax.", "The profile can also involve phonology, reading, working memory and speech perception. This broader range matters when evaluating a theory that locates the problem only in grammar.", "A relative language difficulty does not by itself identify a single damaged learning mechanism."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p025", "noteId": "m3-morphology-p025", "module": "morphology", "source": "morphology", "page": 25, "title": "A rule-deficit account of SLI", "sourceText": "Past Tense and SLI\nPast tense deficits: sine qua non of SLI\nEarlier claims suggested their deficit was specific to rules\nGopnik; van der Lely; Pinker; Ullman; Clahsen\nSLI could represent evidence that language acquisition requires domain-specific mechanisms\nA deficit in learning rules\na problem with regulars and nonwords, \u000bbut not irregulars", "image": "assets/morphology/025.webp", "core": false, "reviewPages": [], "paragraphs": ["**A rule-deficit account predicts particular difficulty with regular and novel inflections.** If a domain-specific rule-learning mechanism is impaired, irregular forms stored lexically should be relatively less affected.", "This proposal uses past-tense performance to argue for a mechanism specific to grammatical rules.", "The prediction must be tested against the complete pattern, including irregular performance and broader phonological difficulties."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p026", "noteId": "m3-morphology-p026", "module": "morphology", "source": "morphology", "page": 26, "title": "SLI behavioral comparison", "sourceText": "Behavioral Data\nvan der Lely & Ullman (2001)", "image": "assets/morphology/026.webp", "core": true, "reviewPages": [], "paragraphs": ["**The van der Lely and Ullman comparison shows low past-tense accuracy across all three item types in the SLI group.** Same-age controls perform much better.", "Nonwords are especially difficult for the SLI group, but regulars and irregulars are also impaired. The results therefore contain a broad deficit as well as unequal condition difficulty.", "An explanation should account for the entire profile rather than reporting only that productive forms are poor."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p027", "noteId": "m3-morphology-p027", "module": "morphology", "source": "morphology", "page": 27, "title": "Developmental model results", "sourceText": "Model Results", "image": "assets/morphology/027.webp", "core": true, "reviewPages": [], "paragraphs": ["**Weakening phonological processing produces impaired learning across forms, with nonwords especially vulnerable.** The severe and weaker impairment settings differ in the degree of difficulty.", "The intact model performs substantially better. Even intact learning shows different performance across regulars, irregulars and nonwords.", "The comparison tests whether a phonological learning weakness can reproduce important aspects of the behavioral profile without a missing grammatical rule."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p028", "noteId": "m3-morphology-p028", "module": "morphology", "source": "morphology", "page": 28, "title": "Why phonology affects all forms", "sourceText": "Summary\nThe model illustrates how phonology affects development of all forms\n\n…and why it’s especially important to  nonwords", "image": "assets/morphology/028.webp", "core": false, "reviewPages": [], "paragraphs": ["**Phonology contributes to every spoken past-tense response.** Weakening it can therefore reduce performance on regulars, irregulars and nonwords.", "Nonwords are particularly dependent on generalizing a sound pattern to a new form. Familiar words have additional item-specific learning that can partly support their responses."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p029", "noteId": "m3-morphology-p029", "module": "morphology", "source": "morphology", "page": 29, "title": "A unified learning account", "sourceText": "Note similarities to “triangle” model of reading.\nThere are no “special rules” for the past tense, just mappings between phonology and semantics.\n\nThere is no separate lexicon that stores the exceptions.\n\nIndeed, the concept of “rule” and “exception” only approximately describes the system.\n\nAssociation between “irregular” forms and semantic processing.\n\nAssociation between “wug test” performance and phonological processing.\n", "image": "assets/morphology/029.webp", "core": true, "reviewPages": [], "paragraphs": ["**The associative account learns mappings among phonology and semantics without a separate symbolic past-tense rule or an isolated exception lexicon.** Regular and irregular are useful descriptions of behavior, but only approximate descriptions of the system's internal organization.", "Irregular performance is associated with semantic processing. Wug-test performance is associated with phonological processing.", "These associations provide tests of the proposed underlying mechanisms, beyond simply assigning different item types to different boxes."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-morphology-p030", "noteId": "m3-morphology-p030", "module": "morphology", "source": "morphology", "page": 30, "title": "Reading assignment", "sourceText": "For next lecture:\n\nRead Borodisky (2003) on Linguistic Relativity", "image": "assets/morphology/030.webp", "core": false, "reviewPages": [], "paragraphs": [], "analysis": {"status": "authored", "role": "noninstructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-thought-p001", "noteId": "m3-thought-p001", "module": "thought", "source": "thought", "page": 1, "title": "Language and thought", "sourceText": "Language and Thought\n", "image": "assets/thought/001.webp", "core": false, "reviewPages": [], "paragraphs": [], "analysis": {"status": "authored", "role": "noninstructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p002", "noteId": "m3-thought-p002", "module": "thought", "source": "thought", "page": 2, "title": "Linguistic relativity", "sourceText": "“No two languages are ever sufficiently similar to be considered as representing the same \nsocial reality. The worlds in which different societies live are distinct worlds, not merely \nthe same world with different labels attached.”\nSapir (1929)\nLinguistic Relativity, a.k.a. The “Sapir-Whorf Hypothesis”\n“We dissect nature along lines laid down by our native language. The categories and \ntypes that we isolate from the world of phenomena we do not find there because they \nstare every observer in the face; on the contrary, the world is presented in a \nkaleidoscope flux of impressions which has to be organized by our minds—and this \nmeans largely by the linguistic systems of our minds. We cut nature up, organize it into \nconcepts, and ascribe significances as we do, largely because we are parties to an \nagreement to organize it in this way—an agreement that holds throughout our speech \ncommunity and is codified in the patterns of our language [...] all observers are not led \nby the same physical evidence to the same picture of the universe, unless their linguistic \nbackgrounds are similar, or can in some way be calibrated.”\nWhorf (1956)\n(The Wikipedia page on this is actually pretty useful, BTW) \n", "image": "assets/thought/002.webp", "core": false, "reviewPages": [], "paragraphs": ["**Linguistic relativity concerns whether differences in language influence how people organize or use concepts.** The Sapir and Whorf quotations suggest that linguistic categories can shape how experience is interpreted.", "The strongest reading would make language determine what a person can think. A weaker claim is that habitual language use biases attention, memory or preferred ways of representing a situation.", "These claims require different evidence. A preference associated with language does not establish that alternative thought is impossible."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p003", "noteId": "m3-thought-p003", "module": "thought", "source": "thought", "page": 3, "title": "Language, culture and the strength of the claim", "sourceText": "Linguistic Relativity\nKeep in mind:\nEven Sapir and Whorf did not necessarily hold the “strong” relativist position implied \nin those pull-quotes.\nIn the first half of the 20th Century, linguistics was really part of anthropology, so \ntreating language as a part of culture seemed more natural than it does to contemporary \nlinguists.\nWe’re going to be talking mainly about space and the relationship between space and \ntime.  \n", "image": "assets/thought/003.webp", "core": false, "reviewPages": [], "paragraphs": ["**Language is embedded in cultural practices and experience.** A difference between language communities may therefore covary with factors other than linguistic structure.", "Sapir and Whorf should not automatically be assigned the strongest deterministic interpretation of selected quotations.", "A precise study must identify which cognitive process is affected and what alternative explanations the comparison controls."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p004", "noteId": "m3-thought-p004", "module": "thought", "source": "thought", "page": 4, "title": "Locating the ball", "sourceText": "Thinking about space…\nWhere’s the ball?\n", "image": "assets/thought/004.webp", "core": false, "reviewPages": [], "paragraphs": ["**A location description needs a frame of reference.** Saying where the ball is requires choosing what counts as left, front or a stable direction.", "The ball can be located with respect to the viewer, the chair's own orientation or a direction independent of either.", "Different descriptions can identify the same physical position while organizing that position differently."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p005", "noteId": "m3-thought-p005", "module": "thought", "source": "thought", "page": 5, "title": "Intrinsic, relative and absolute frames", "sourceText": "Thinking about space…\n(Levinson et al., 2002, Cognition)\n", "image": "assets/thought/005.webp", "core": true, "reviewPages": [], "paragraphs": ["**An intrinsic frame uses an object's own orientation, a relative frame uses an observer's viewpoint, and an absolute frame uses a stable direction.** These are different ways to specify the same location.", "“At the chair's front” uses the chair's intrinsic front. “To the left of the chair from my viewpoint” depends on the observer.", "“North of the chair” uses an absolute direction that does not reverse when the observer turns around."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p006", "noteId": "m3-thought-p006", "module": "thought", "source": "thought", "page": 6, "title": "Egocentric and absolute spatial language", "sourceText": "Thinking about space…\nIt seems natural in most languages to talk \nabout space egocentrically when talking about \nthings that are nearby.\nWhat is to your left or to your right, in front of \nyou or behind you, etc.\nNot so in Tzeltal, a Western Mayan language \nspoken in Chiapas.\nIn this language (and a small number of others, \nmostly unrelated to one another, and broadly \ndistributed, e.g., in Bali and Queensland) \nabsolute directions are used.\nRaise your east hand if this seems intuitive to \nyou… \nSome native Tzeltal speakers defending their land \nfrom the vampire squid of neoliberalism.\n", "image": "assets/thought/006.webp", "core": true, "reviewPages": [32], "paragraphs": ["**Egocentric spatial descriptions use the speaker's position and orientation.** Left, right, in front and behind are familiar examples for nearby objects.", "Tzeltal commonly uses absolute directions in circumstances where English speakers might use these relative terms.", "The contrast motivates asking whether habitual language use relates to nonverbal spatial coding, rather than merely comparing two ways of giving spoken directions."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p007", "noteId": "m3-thought-p007", "module": "thought", "source": "thought", "page": 7, "title": "Tzeltal uphill and downhill", "sourceText": "Tzeltal has a historically landmark-\nbased system.\nThings are either “uphill” or \n“downhill” from one another, not to \nthe left or right of the speaker or \ninterlocutor.\nIn fact, “uphill” and “downhill” are \nused as cardinal directions, making \nthis an absolute system. \nBeautiful downtown Tenejapa.\n(Levinson et al., 2002, Cognition)\n", "image": "assets/thought/007.webp", "core": true, "reviewPages": [33], "paragraphs": ["**Tzeltal's uphill and downhill terms function as an absolute directional system.** Their historical connection to a slope does not mean that each use simply points to the nearest visible hill.", "A direction is retained as a stable spatial reference rather than being recalculated from the speaker's current left and right.", "This allows positions to be described consistently as the speaker changes orientation."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p008", "noteId": "m3-thought-p008", "module": "thought", "source": "thought", "page": 8, "title": "Landmark-based directions", "sourceText": "New Yorkers use “uptown” \nand “downtown” as if they \nwere cardinal directions all \nthe time, but these don’t \nwork outside of Manhattan. \nSo that is literally a landmark-\nbased system.\nAlso, the subway map really \nhas us messed up on “north” \nand “south,” because \nManhattan is on an angle \nw/r/t magnetic north.\nAn aside\n", "image": "assets/thought/008.webp", "core": false, "reviewPages": [], "paragraphs": ["**A landmark-based direction is tied to a particular environment.** Uptown and downtown organize movement within Manhattan but do not provide a universally usable compass system.", "A city's conventional map orientation can also differ from magnetic north. Familiar spatial language therefore reflects local practices as well as geometric directions."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p009", "noteId": "m3-thought-p009", "module": "thought", "source": "thought", "page": 9, "title": "The rotated spatial-memory task", "sourceText": "Majid et al. (2004, TiCS)\nA non-linguistic test for relative vs. absolute coding of space\n", "image": "assets/thought/009.webp", "core": true, "reviewPages": [34], "paragraphs": ["**The chips task separates relative from absolute spatial memory by rotating the participant 180 degrees.** A participant sees a configuration, waits, and then chooses its match at a second table.", "A relative response preserves the arrangement with respect to the person's viewpoint. An absolute response preserves its orientation in the environment, so the two responses diverge after rotation.", "Dutch speakers predominantly gave relative responses, while Tzeltal speakers gave more absolute responses. The association is consistent with their preferred linguistic frames but does not isolate language from all other experience."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p010", "noteId": "m3-thought-p010", "module": "thought", "source": "thought", "page": 10, "title": "Spatial inference across displays", "sourceText": "Majid et al. (2004, TiCS)\nYou can get really fancy with this.\n", "image": "assets/thought/010.webp", "core": true, "reviewPages": [35], "paragraphs": ["**Spatial inference can combine relations learned in different displays.** Participants learn the relation between two objects, rotate to another display, and learn a second relation involving a shared object.", "They then place an object relative to another using the combined information. Relative and absolute coding lead to different placements because the person's orientation has changed.", "Dutch and Tzeltal response patterns again differ in the direction associated with their preferred spatial frames."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p011", "noteId": "m3-thought-p011", "module": "thought", "source": "thought", "page": 11, "title": "A testing-environment alternative", "sourceText": "Li and Gleitman:\nInducing landmark-based similarity in English speakers \nConsider the conditions under which \nthe Tzeltal speakers were tested: \nOutside, with visible, familiar landmarks. \nTypical psychology lab studies are done \nin windowless rooms.\n", "image": "assets/thought/011.webp", "core": true, "reviewPages": [36], "paragraphs": ["**Testing conditions could contribute to the apparent language-group difference.** Li and Gleitman noted that Tzeltal participants had been tested with visible, familiar outdoor landmarks, unlike many laboratory participants.", "An environment with useful landmarks can encourage landmark-based coding. A windowless laboratory can make viewer-relative descriptions more convenient.", "Manipulating landmark availability within English speakers tests whether the behavior can change without changing native language."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p012", "noteId": "m3-thought-p012", "module": "thought", "source": "thought", "page": 12, "title": "Blinds down, blinds up and outdoors", "sourceText": "In the “blinds down” condition, English \nspeakers overwhelmingly use relative position \nin this task – like the Dutch speakers in prior \nstudies.\nWith the blinds up and a view of the street, or \noutdoors, their preference is less pronounced. \nLi and Gleitman:\nInducing landmark-based spatial reasoning in English \nspeakers \n", "image": "assets/thought/012.webp", "core": true, "reviewPages": [37], "paragraphs": ["**English speakers' preference for relative coding weakened when external landmarks were available.** They strongly preferred relative responses with the blinds down, but the preference was less pronounced with a street view or outdoors.", "The manipulation changes the spatial information available while keeping the language group the same.", "This demonstrates that task context can influence the response. It challenges an explanation in which language alone fixes the chosen frame."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p013", "noteId": "m3-thought-p013", "module": "thought", "source": "thought", "page": 13, "title": "Discussion pause", "sourceText": "What does it mean?\n", "image": "assets/thought/013.webp", "core": false, "reviewPages": [], "paragraphs": [], "analysis": {"status": "authored", "role": "noninstructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p014", "noteId": "m3-thought-p014", "module": "thought", "source": "thought", "page": 14, "title": "What the environmental confound means", "sourceText": "What does it mean?\nWhat if the differences between language groups are confounded with differences in \ntesting conditions?\nMaybe the bias toward relative spatial reasoning is an artifact of the way psychology \ntests are typically run in universities…\n", "image": "assets/thought/014.webp", "core": true, "reviewPages": [], "paragraphs": ["**If language groups are tested under different conditions, their response difference may partly reflect those conditions.** Visible landmarks and familiarity can covary with native language in a cross-community study.", "A controlled comparison must separate the effect of the environment from any contribution of habitual linguistic coding.", "Showing an environmental effect does not prove that language never matters. It limits what can be inferred from an uncontrolled comparison."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p015", "noteId": "m3-thought-p015", "module": "thought", "source": "thought", "page": 15, "title": "Levinson's methodological response", "sourceText": "Levinson and colleagues \nwere not impressed.\nThey claim that Li and \nGleitman made it too \ntransparent that they were \ntesting something to do \nwith rotation by reducing \nmemory load and \ntime/distance between \nstimulus and test.\nAlso Li and Gleitman’s\nparticipants were Ivy \nLeague students, who excel \nat figuring out what the \nprofessor wants and then \nmaking it happen.  \n", "image": "assets/thought/015.webp", "core": true, "reviewPages": [38], "paragraphs": ["**Levinson and colleagues argued that the simplified task could make the experimenter's purpose too obvious.** Low memory demands and short time or distance between displays may encourage a deliberate strategy about rotation.", "Participants who infer what is being tested can alter their response for reasons different from habitual spatial coding.", "The response therefore focuses on memory load and task transparency, rather than denying that landmarks can ever matter."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p016", "noteId": "m3-thought-p016", "module": "thought", "source": "thought", "page": 16, "title": "Increasing memory load and reducing transparency", "sourceText": "Levinson et al. (2002) re-ran the “animals in a row” experiment with Dutch college \nstudents, but including a fourth animal, a longer delay interval (both to increase memory \nload) and a larger distance between the stimulus and response tables (to reduce the \nsalience of the rotation).\nUnder these conditions, a bias to use relative framing remains.\n", "image": "assets/thought/016.webp", "core": true, "reviewPages": [], "paragraphs": ["**Levinson and colleagues retested Dutch students with four animals, a longer delay and greater distance between tables.** The extra item and delay increased memory demands, while the distance made the rotation manipulation less conspicuous.", "Under these conditions, the preference for relative coding remained.", "The result suggests that the environmental effect depends on how the task is arranged, including how much memory and strategic inference it encourages."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p017", "noteId": "m3-thought-p017", "module": "thought", "source": "thought", "page": 17, "title": "Memory as part of the explanation", "sourceText": "What does it mean?\nFor speakers of languages that use relative spatial frames of reference, the bias to use \nrelative vs. absolute frames is robust to the environment when:\n1. There’s a significant memory component, and\n2. The experimenter’s interest in rotation and frames of reference isn’t obvious\nCan you think of a way in which the importance of “memory” muddies the waters here?  \n", "image": "assets/thought/017.webp", "core": false, "reviewPages": [], "paragraphs": ["**A robust spatial-frame preference under memory demands does not automatically identify a purely spatial representation.** Remembering the task can recruit verbal strategies as well as spatial ones.", "The relative preference is reported when memory demands are substantial and the experimenter's interest is less obvious.", "That pattern makes it important to ask how the sequence is stored during the delay, not only which direction is chosen at the end."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p018", "noteId": "m3-thought-p018", "module": "thought", "source": "thought", "page": 18, "title": "Verbal recoding of a spatial sequence", "sourceText": "What does it mean?\nFor speakers of languages that use relative spatial frames of reference, the bias to use \nrelative vs. absolute frames is robust to the environment when:\n1. There’s a significant memory component, and\n2. The experimenter’s interest in rotation and frames of reference isn’t obvious\nCan you think of a way in which the importance of “memory” muddies the waters here? \nWhat if participants are just recoding the list in working memory as a sequence, e.g. “lion, \ntiger, bear,” and then naturally working from left to right?\nWhy does “left to right” seem like a natural translation of a temporal sequence?\n", "image": "assets/thought/018.webp", "core": true, "reviewPages": [], "paragraphs": ["**Participants might remember the animals as a verbal list such as “lion, tiger, bear.”** Reconstructing that sequence from left to right can produce a relative-looking response.", "This strategy would connect language to the task through working memory and ordering habits, rather than through an inability to represent absolute space.", "The interpretation changes because the same choice can arise from different internal codes."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p019", "noteId": "m3-thought-p019", "module": "thought", "source": "thought", "page": 19, "title": "Metaphor and abstract concepts", "sourceText": "“You’re like a dull knife.\nJust ain’t cuttin’.\nBecause you’re talkin’ loud,\nBut you ain’t sayin’ nothin’.\n(Brown & Byrd, 1970)\nMetaphorical language and “abstract” concepts.\nWhat’s going on here?\nHow is failing to make a compelling argument \nlike “not cutting?”\nDo you literally have to be speaking in a loud \nvoice to be “talking loud” but “saying \nnothing?”\nObviously, James Brown was a great artist, so we expect him to use evocative language. \nBut how much of language can we safely describe as non-metaphorical?\nWhat is the point here? \nIs the discussion of Language and Thought a knotty and convoluted argument that \ngenerates more heat than light. In the following section, we’ll pursue the problem of \nwhether language has an impact on how we think about time in terms of space.  \n", "image": "assets/thought/019.webp", "core": false, "reviewPages": [], "paragraphs": ["**Metaphorical language expresses one kind of experience using terms from another.** Saying that an argument is not “cutting” describes its effectiveness rather than a literal action with a blade.", "Physical and spatial terms can therefore help express abstract relations. Time is especially useful for studying whether such linguistic habits are associated with nonlinguistic representations.", "The question is empirical. Using a spatial phrase does not by itself prove that every thought about time has the same spatial format."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p020", "noteId": "m3-thought-p020", "module": "thought", "source": "thought", "page": 20, "title": "Spatial language for time", "sourceText": "Spatial metaphors for time in different languages\n(Boroditsky et al., 2010)\n", "image": "assets/thought/020.webp", "core": true, "reviewPages": [], "paragraphs": ["**English and Mandarin both use horizontal spatial language for time, but Mandarin also frequently uses vertical terms.** Earlier events can be described with an “up” term and later events with a “down” term.", "The linguistic contrast motivates testing whether speakers differ in the spatial organization they use during temporal tasks.", "The existence of the expressions is the starting observation. A behavioral task is needed to investigate whether the contrast extends beyond words."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p021", "noteId": "m3-thought-p021", "module": "thought", "source": "thought", "page": 21, "title": "Spatial priming and temporal judgments", "sourceText": "Boroditsky, 2001)\nA priming experiment\nPriming with a spatial task (horizontal or vertical) has different effects on temporal \nprocessing in the two languages.\nShort-term training on vertical metaphors for time (“Cars were invented above fax \nmachines”) also has an impact. \n", "image": "assets/thought/021.webp", "core": true, "reviewPages": [], "paragraphs": ["**Boroditsky's priming task tests whether spatial processing influences subsequent time judgments.** Participants first process horizontal or vertical relations, then respond to temporal earlier–later questions.", "English speakers respond faster after horizontal than vertical primes, while Mandarin speakers show the opposite pattern in the displayed comparison.", "Training English speakers on vertical metaphors changes the pattern toward a vertical-prime advantage. This suggests sensitivity to experience, rather than an unchangeable division between language groups."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p022", "noteId": "m3-thought-p022", "module": "thought", "source": "thought", "page": 22, "title": "Reading direction as an alternative", "sourceText": "Casasanto & Bottini (2005, Cognitive Science Proceedings)\nAn alternative explanation: direction of text…\n", "image": "assets/thought/022.webp", "core": true, "reviewPages": [], "paragraphs": ["**Reading and writing habits can also organize sequences spatially.** Differences attributed to temporal metaphors may covary with whether text is commonly read left-to-right, right-to-left or vertically.", "Casasanto and Bottini use differences in text orientation and arrangement preferences to motivate this alternative.", "The point is to identify another source of spatial experience, not to assume that a writing-system label perfectly predicts every individual's habits."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p023", "noteId": "m3-thought-p023", "module": "thought", "source": "thought", "page": 23, "title": "Controlling reported vertical reading", "sourceText": "Boroditsky et al. (2010, Cognition)\nExcluding Chinese readers who reported \nreading top-to-bottom. \n…so Boroditsky et al. controlled for that…\n", "image": "assets/thought/023.webp", "core": true, "reviewPages": [], "paragraphs": ["**Boroditsky and colleagues excluded Chinese readers who reported top-to-bottom reading.** This tests whether the vertical temporal effect can be explained entirely by that reported reading experience.", "English speakers show an advantage for a left-is-earlier horizontal mapping. Mandarin speakers also show an advantage for a top-is-earlier vertical mapping in the displayed comparison.", "Retaining a vertical effect under this restriction weakens that particular reading-direction explanation, without proving that every possible experiential confound is removed."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p024", "noteId": "m3-thought-p024", "module": "thought", "source": "thought", "page": 24, "title": "Past–future button mappings", "sourceText": "Casasanto & Bottini (2010, Spatial Cognition)\nTask: Push a blue button for events in the past, a red button for events in the future \n(or the reverse, in different blocks). \nThus, half the time, the “past” is on the left, and the other half it’s on the right. \n", "image": "assets/thought/024.webp", "core": true, "reviewPages": [], "paragraphs": ["**Participants classify events as past or future using colored buttons.** The color-to-category mapping is reversed across blocks, so the past response is sometimes on the left and sometimes on the right.", "With standard text reading, responses are faster when past maps left and future maps right.", "Because the response concerns time rather than an explicit judgment of spatial direction, the compatibility effect reveals an implicit spatial association in this task."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p025", "noteId": "m3-thought-p025", "module": "thought", "source": "thought", "page": 25, "title": "Mirror reading changes the mapping effect", "sourceText": "Casasanto & Bottini (2010, Spatial Cognition)\nTask: Push a blue button for events in the past, a red button for events in the future \n(or the reverse, in different blocks). \nThus, half the time, the “past” is on the left, and the other half it’s on the right. \nNow ask people to do a few minutes of \n“mirror reading:”\n", "image": "assets/thought/025.webp", "core": true, "reviewPages": [], "paragraphs": ["**Mirror reading tests whether short-term reading experience can alter spatial associations with time.** Participants read reversed text and perform the past–future button task.", "By the second mirror-reading block, the compatibility effect reverses. Responses are faster when earlier maps right and later maps left.", "The result supports a contribution of reading-direction experience and shows that the association can change over a short period."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p026", "noteId": "m3-thought-p026", "module": "thought", "source": "thought", "page": 26, "title": "Evaluating vocabulary anecdotes", "sourceText": "(for those of you who were straining your eyes to read this on the last slide, it’s from a classic rant by \nPullum (1989, Natural Language and Linguistic Theory) called “The Great *Eskimo Vocabulary Hoax.” \nSee if you can guess where he comes down on linguistic relativism…) \n*not an OK word for Inuktitut people whose language is the most likely source for the examples, but \nit’s the title of the book, sorry \n", "image": "assets/thought/026.webp", "core": false, "reviewPages": [], "paragraphs": ["**Claims about a language's vocabulary are not automatically evidence for cognitive limits.** Pullum's discussion criticizes how an account of different word roots became an exaggerated story about language and thought.", "Languages can express distinctions through separate roots, derived words or phrases. Counting one of these forms without considering the others can misrepresent expressive capacity.", "A reliable claim requires accurate linguistic description and an appropriate behavioral test, rather than repetition of a striking anecdote."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-thought-p027", "noteId": "m3-thought-p027", "module": "thought", "source": "thought", "page": 27, "title": "Reading assignment", "sourceText": "For next week: Bavelier et al. on cortical plasticity \nhttp://www.nature.com/nrn/journal/v3/n6/abs/nrn848.html\n", "image": "assets/thought/027.webp", "core": false, "reviewPages": [], "paragraphs": [], "analysis": {"status": "authored", "role": "noninstructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-modalities-p001", "noteId": "m3-modalities-p001", "module": "modalities", "source": "modalities", "page": 1, "title": "Language in different modalities", "sourceText": "Language in different modalities: \nSign and Braille\n", "image": "assets/modalities/001.webp", "core": false, "reviewPages": [], "paragraphs": [], "analysis": {"status": "authored", "role": "noninstructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p002", "noteId": "m3-modalities-p002", "module": "modalities", "source": "modalities", "page": 2, "title": "Signed languages and Braille", "sourceText": "Note\nSign language and Braille are really different cases.\nSign languages, as we’ll see, are natural languages that have their own linguistic \nstructure.\nBraille is a system that allows blind individuals to read a spoken language they share with \nsighted individuals.\nI’ve lumped them together because they reveal interesting things about the plasticity of \nsensory systems, and how the brain gets organized differently when language input \ncomes from different modalities.\n", "image": "assets/modalities/002.webp", "core": true, "reviewPages": [], "paragraphs": ["**A signed language is a natural language, while Braille is a writing system.** Signed languages have their own linguistic structure. Braille allows a language to be read through touch.", "The distinction matters because changing the modality of a language is not the same as changing how a written language is accessed.", "Both cases reveal how sensory experience shapes the organization of systems involved in language and reading."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p003", "noteId": "m3-modalities-p003", "module": "modalities", "source": "modalities", "page": 3, "title": "How signed languages differ from speech", "sourceText": "Sign Language\nEmmorey et al. (2004, Brain & Language)\nSign languages have some obvious differences \nfrom spoken languages:\n- modality\n- articulators\n- use of space\n- iconicity (though this is easy to exaggerate \nwhen you look at individual words with their \nglosses)  \n", "image": "assets/modalities/003.webp", "core": false, "reviewPages": [], "paragraphs": ["**Signed languages use a visual modality and manual and bodily articulators.** The hands, face and upper body contribute to a coordinated linguistic signal.", "Space can carry linguistic relations. Some signs are iconic, meaning that aspects of their form resemble aspects of their meaning.", "Iconicity is easy to overestimate when a familiar translation is supplied. A visible resemblance does not eliminate the need to learn a language's forms and structure."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p004", "noteId": "m3-modalities-p004", "module": "modalities", "source": "modalities", "page": 4, "title": "Coordinated signing", "sourceText": "https://www.youtube.com/watch?v=8J_UfLH8isU\nNote:\n- eye contact\n- coordination of hands, face, upper body\n- fluidity (can you segment words?)\n- speed \nTake a look at sign language in action.\n", "image": "assets/modalities/004.webp", "core": false, "reviewPages": [], "paragraphs": ["**Fluent signing coordinates hands, facial expression, gaze and upper-body movement.** The linguistic signal is distributed across these visible articulators rather than produced by one hand movement at a time.", "Like speech, a fluent stream is continuous enough that word boundaries are not always obvious to a learner.", "Eye contact and movement timing are therefore relevant to perceiving the interaction, alongside the form of individual signs."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p005", "noteId": "m3-modalities-p005", "module": "modalities", "source": "modalities", "page": 5, "title": "Contrastive features in sign", "sourceText": "As with speech, there are featural descriptions of sign. \nSigns can differ contrastively in:\n- hand configuration\n- gesture location\n- movement    \n(Emmorey et al., 2003, Language & Cognitive Processes)\nPhonology of sign language.\n“please”\n“sorry”\n“onion”\n“apple”\n", "image": "assets/modalities/005.webp", "core": true, "reviewPages": [], "paragraphs": ["**Signed-language phonology includes contrastive hand configuration, location and movement.** Changing one of these features can distinguish signs, just as changing a speech feature can distinguish spoken words.", "The PLEASE–SORRY and ONION–APPLE examples demonstrate that closely related visible forms can have different linguistic identities.", "Phonology therefore concerns the organization of contrastive form, not only acoustic sound."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p006", "noteId": "m3-modalities-p006", "module": "modalities", "source": "modalities", "page": 6, "title": "Testing categorical perception in sign", "sourceText": "Research question: Is there categorical perception for these dimensions?\n", "image": "assets/modalities/006.webp", "core": true, "reviewPages": [39], "paragraphs": ["**Categorical perception can be tested by varying a sign feature continuously.** The hand-configuration continuum moves between forms while the observer's identification and discrimination responses are measured.", "One continuum crosses a phonemic distinction between PLEASE and SORRY. The allophonic comparison varies hand configuration without the same change in sign identity.", "A sharp identification boundary accompanied by better discrimination near that boundary would indicate category-sensitive perception."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p007", "noteId": "m3-modalities-p007", "module": "modalities", "source": "modalities", "page": 7, "title": "Identification and discrimination results", "sourceText": "These curves should look \nfamiliar.\nThere is a fairly sharp\ncategorical boundary between \nstimuli 4 and 6 for the \nphonemic boundary. \nThis corresponds to the peak in \nthe discrimination function.\nFor the allophonic condition, \nthe identification function is \nmuch shallower – i.e., many \nmore ambiguous stimuli – and \nthere is no peak in the \ndiscrimination function. \n", "image": "assets/modalities/007.webp", "core": true, "reviewPages": [40], "paragraphs": ["**Deaf signers show a sharper categorical boundary for phonemic than allophonic hand-configuration changes.** In the phonemic condition, identification shifts steeply around stimuli 4–6.", "Discrimination is also strongest near the phonemic boundary. Comparable physical steps are easier to distinguish when they cross that category boundary.", "The allophonic identification function is shallower and lacks the same localized discrimination peak. This links the perceptual pattern to linguistic contrast rather than any visible hand change."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p008", "noteId": "m3-modalities-p008", "module": "modalities", "source": "modalities", "page": 8, "title": "Spatial information in grammar", "sourceText": "Use of spatial information in grammar.\nSign language uses space to indicate relationships between words in a sentence. \nThis is a very transparent example, where the relative position of two objects is given by \nwhere the classifier sign is made. \nConsider that understanding sentences of any complexity in sign language requires \nkeeping track of where signs were made. \n", "image": "assets/modalities/008.webp", "core": true, "reviewPages": [], "paragraphs": ["**Signed languages can use positions in signing space to represent relationships.** A classifier sign made at a particular location can indicate the relative position of an object.", "Understanding a sentence can require retaining where entities were introduced and how subsequent signs relate to those locations.", "Spatial processing therefore contributes to linguistic comprehension, rather than functioning only as background vision."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p009", "noteId": "m3-modalities-p009", "module": "modalities", "source": "modalities", "page": 9, "title": "Shared and modality-related brain activity", "sourceText": "Brain activity during sign language comprehension has both important \nsimilarities and differences with spoken language.\nSimilar: \n- left lateralization\n- classical language areas \n(Broca’s / inferior frontal; Wernicke’s\n/ posterior superior temporal)\nDifferent:\n- visual areas\n- superior parietal / classic \nspatial areas\nCampbell, MacSweeney, & Waters (2008)\nDeaf signers\nHearing signers\nAudio-visual \nSpeech (hearing participants)\n", "image": "assets/modalities/009.webp", "core": true, "reviewPages": [41], "paragraphs": ["**Signed-language comprehension recruits classical language regions and shows left lateralization, as spoken-language comprehension does.** Inferior frontal and posterior superior temporal regions are part of this overlap.", "Signing also engages visual and superior parietal regions relevant to its perceptual and spatial demands.", "The combination suggests both common language organization and modality-related contributions. Similarity does not require identical activation everywhere."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p010", "noteId": "m3-modalities-p010", "module": "modalities", "source": "modalities", "page": 10, "title": "Deafness, signing and peripheral attention", "sourceText": "Bavelier D et al. J. Neurosci. 2001;21:8931-8942\nResearch question: \nDoes deafness and/or experience with sign impact spatial attention?\nParticipants monitored for brief changes in either \nluminance or velocity of “dots” either in the center \nof the screen, or at the periphery.\nDeaf participants show an advantage in this task \nwhen attention is directed to the periphery.\n", "image": "assets/modalities/010.webp", "core": true, "reviewPages": [], "paragraphs": ["**Bavelier and colleagues compared hearing controls, deaf signers and hearing signers on visual attention.** Participants monitored dots for brief changes in luminance or velocity, with attention directed centrally or peripherally.", "Deaf participants showed an advantage when attention was directed to the periphery.", "Including hearing signers helps separate experience with signing from lack of auditory input. If all signers had the same advantage, signing alone would be a stronger explanation."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p011", "noteId": "m3-modalities-p011", "module": "modalities", "source": "modalities", "page": 11, "title": "Two different effects of experience", "sourceText": "Learning sign language changes the laterality of \nareas involved in motion perception from right to \nleft.\n(Perhaps because motion perception needs to \n“talk to” left-lateralized language networks in \npeople who learn sign.) \nEnhancements of peripheral visual attention, \nhowever, are only observed in deaf individuals.\n(Perhaps because hearing individuals are more \ndependent on auditory cues for spatial \nattention when things are at the far \nperiphery.) \n", "image": "assets/modalities/011.webp", "core": true, "reviewPages": [], "paragraphs": ["**Signing experience and deafness show different associations with visual processing.** Both deaf and hearing signers show a leftward shift in motion-processing lateralization relative to hearing nonsigners.", "Enhanced peripheral attention is found in deaf individuals, not hearing signers. Signing experience alone therefore does not explain that enhancement.", "The proposed interpretations involve links between motion and language systems for signing, and reduced reliance on auditory peripheral cues in deafness."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p012", "noteId": "m3-modalities-p012", "module": "modalities", "source": "modalities", "page": 12, "title": "Sign language versus tic-tac gestures", "sourceText": "Dissociating visual/spatial/motor processing of hand movements from language processing.\nDirect comparison of sign comprehension with “tic-tac,” a sophisticated (and \noutmoded) gestural system used to communicate about odds at horse races in the \nUK.\nhttps://www.youtube.com/watch?v=YsZu_wZa-j8\n", "image": "assets/modalities/012.webp", "core": true, "reviewPages": [], "paragraphs": ["**Comparing sign comprehension with another organized gesture system helps control visible movement demands.** Tic-tac uses sophisticated hand gestures to communicate horse-racing odds.", "Both tasks involve meaningful, sequenced hand movements. A difference between them is more informative about linguistic processing than a comparison between signing and no movement.", "The control is not identical to a natural language, which is precisely why the remaining difference is of interest."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p013", "noteId": "m3-modalities-p013", "module": "modalities", "source": "modalities", "page": 13, "title": "Neural difference between sign and gesture", "sourceText": "D\nCampbell, MacSweeney, & Waters (2008)\nStronger activity was observed around \nWernicke’s area for sign language vs. tic-tac.\n(The frontal activation is superior to Broca’s\narea; you can make up a “hand-wavy” story \nabout why tic-tac might activate Broca’s area.)\n(See what I did there? Hand-wavy? Ha ha.) \n", "image": "assets/modalities/013.webp", "core": true, "reviewPages": [], "paragraphs": ["**Sign language produces stronger activity around posterior superior temporal language regions than tic-tac gestures.** This supports a distinction between processing organized hand movements and processing a natural language.", "The comparison reduces a simple explanation based only on the presence of hands moving through space.", "The frontal activation shown is superior to classic Broca's area, so it should not be casually relabeled as a precise Broca's effect."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p014", "noteId": "m3-modalities-p014", "module": "modalities", "source": "modalities", "page": 14, "title": "Evidence about signed language", "sourceText": "So, sign language…\nSign language has phonological structure, and native speakers show categorical perception \nfor some contrastive features.\nLearning a signed language results in some brain reorganization, particularly the \nlateralization of motion processing.\nAlthough attention to the visual periphery is critical for both hearing and deaf signers, only \ndeaf signers show enhanced processing of visual attention in the periphery.\nCompared with non-language stimuli that also involve organized, sequenced hand \nmovements, signed sentences activate posterior STG (Wernicke’s area).\n", "image": "assets/modalities/014.webp", "core": true, "reviewPages": [42], "paragraphs": ["**Signed languages have linguistic form, grammar and language-related neural organization.** Contrastive sign features can produce categorical perception, and comprehension recruits posterior superior temporal language regions.", "Signing experience is associated with changes in motion lateralization. Deafness is associated with enhanced peripheral attention in the reported comparison.", "These findings jointly show that linguistic experience and sensory history contribute in different ways."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p015", "noteId": "m3-modalities-p015", "module": "modalities", "source": "modalities", "page": 15, "title": "Perspective in signed spatial descriptions", "sourceText": "", "image": "assets/modalities/015.webp", "core": true, "reviewPages": [], "paragraphs": ["**Comprehending a signed spatial description can require a perspective transformation.** A room can be described from the speaker's perspective or the addressee's perspective.", "The figure's caption reports better comprehension for descriptions from the speaker's perspective despite the mental transformation that this requires.", "This illustrates that the most linguistically natural representation is not necessarily the one that eliminates every spatial transformation."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p016", "noteId": "m3-modalities-p016", "module": "modalities", "source": "modalities", "page": 16, "title": "Braille as tactile reading", "sourceText": "Tactile reading: Braille\nBraille reading is in many ways equivalent to reading print, BUT:\n- symbols are optimized for tactile discrimination (reading Braille by sight is really hard)\n- fingers take in letters one at a time\n", "image": "assets/modalities/016.webp", "core": true, "reviewPages": [], "paragraphs": ["**Braille represents written language through tactilely distinguishable symbols.** It is a way to read a language, rather than a separate natural language with its own grammar.", "The symbols are optimized for touch. Fingers acquire letters sequentially, creating perceptual demands that differ from viewing printed text.", "The comparison asks how reading networks operate when the input arrives through touch instead of vision."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p017", "noteId": "m3-modalities-p017", "module": "modalities", "source": "modalities", "page": 17, "title": "Blindness onset and visual-cortex recruitment", "sourceText": "Reading Braille activates visual cortex \nin blind individuals.\nThe images on the left show three \nearly blind participants, with late blind \nparticipants on the right.\nThe earlier sight is lost, the more \nextensive visual activity is to tactile \nstimuli.\nWe haven’t talked about the “visual \nword form area,” but it’s strongly \nactivated in early blind participants, \nmore so than late blind.\n", "image": "assets/modalities/017.webp", "core": true, "reviewPages": [], "paragraphs": ["**Braille reading activates visual cortex in blind individuals, with more extensive recruitment after earlier sight loss.** Early- and late-blind groups therefore provide a comparison of developmental sensory history.", "Early-blind participants show stronger involvement of regions associated with visual word processing than late-blind participants.", "This indicates that a region's usual sensory label does not completely determine the information it can help process."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p018", "noteId": "m3-modalities-p018", "module": "modalities", "source": "modalities", "page": 18, "title": "Five days of blindfolding", "sourceText": "A question about competition\nRemember that we worried about \nwhether competition could be \npreventing hearing individuals from \ndeveloping awesome peripheral \nvisual attention?\nMerabet et al. asked sighted \nindividuals to wear blindfolds for five \ndays, and trained them to read \nBraille.\nRelative to a control group, the \nblindfolded group learned more \nquickly.  \nMerabet et al. (2008, PLoS ONE)\n", "image": "assets/modalities/018.webp", "core": true, "reviewPages": [], "paragraphs": ["**Merabet and colleagues tested rapid plasticity by blindfolding sighted adults for five days while training Braille.** A comparison group received training without the same continuous removal of visual input.", "The blindfolded group learned more quickly. This suggests that eliminating competing visual input can affect tactile learning over a short timescale.", "Because the participants were sighted adults, the experiment tests a different question from lifelong or early blindness."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p019", "noteId": "m3-modalities-p019", "module": "modalities", "source": "modalities", "page": 19, "title": "Rapid and reversible recruitment", "sourceText": "Merabet LB, Hamilton R, Schlaug G, Swisher JD, et al. (2008) Rapid and Reversible Recruitment of Early Visual Cortex for Touch. PLoS ONE 3(8): \ne3046. doi:10.1371/journal.pone.0003046\nhttp://www.plosone.org/article/info:doi/10.1371/journal.pone.0003046\nFurther, over the course of the experiment, \nsighted, blindfolded participants started to \nshow some activity in primary visual cortex \nwhen reading Braille.\nWhen the blindfold was removed on Day 6, \nthe effect was completely reversed.\n", "image": "assets/modalities/019.webp", "core": true, "reviewPages": [], "paragraphs": ["**Visual-cortex responses to Braille developed during blindfolding and reversed after the blindfold was removed on Day 6.** The time course shows that the change was rapid and reversible.", "Removing visual input can allow tactile-related activity to become more evident. Restoring vision changes that balance again.", "This pattern is consistent with unmasking existing inputs rather than requiring the creation of an entirely new pathway over a few days."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p020", "noteId": "m3-modalities-p020", "module": "modalities", "source": "modalities", "page": 20, "title": "TMS tests functional contribution", "sourceText": "When transcranial magnetic \nstimulation (TMS) was used to \ndisrupt activity in visual cortex, \nit disrupted reading in the \nblindfolded group only (solid \nsymbols).\nThis is evidence that the \nblindfolded participants are \nsomehow using visual cortex\nfor tactile processing. (Maybe?)\nOne way to think about this is that visual cortex is getting tactile \ninput all the time, even in sighted, unblindfolded people, but that \nthis input is too weak to compete with the much stronger, more \nconsistent visual input.\nEven short-term removal of visual input can “unmask” tactile \nresponses in visual cortex.\n", "image": "assets/modalities/020.webp", "core": true, "reviewPages": [], "paragraphs": ["**Disrupting visual cortex with TMS impaired Braille discrimination in the blindfolded group.** This goes beyond showing that the region becomes active during touch.", "On Day 5, the blindfolded group's error rate rises under 1 Hz TMS relative to its baseline and sham conditions. The nonblindfolded group does not show the same selective disruption.", "The effect is no longer present in the same way after blindfold removal. The result supports a temporary functional contribution of visual cortex to tactile performance."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-modalities-p021", "noteId": "m3-modalities-p021", "module": "modalities", "source": "modalities", "page": 21, "title": "Cross-modal plasticity and language", "sourceText": "Cross-modal plasticity and language\nAn important point is the resilience of language circuitry despite differences in modality. \n- Classical language areas are activated by sign language, although the input is \ndramatically different in its surface form.\n- Braille reading seems to engage networks that are important for processing text.\nWe can think of cross-modal plasticity as demonstrating that brain organization is shaped \nover the course of development by competition.\nFor example, when auditory input is unavailable, putative auditory areas are used to \nprocess sign, and visual attention is enhanced at the periphery.\nRecall that the competing cognitive/perceptual processes shaping language processing \nwere also important when we considered the Competition Model as relevant to second \nlanguage learning.\n", "image": "assets/modalities/021.webp", "core": true, "reviewPages": [], "paragraphs": ["**Language-related organization is resilient across sensory modalities while remaining shaped by experience.** Signed language recruits classical language regions, and Braille engages networks associated with text processing.", "Competition among available inputs offers a way to understand reorganization. When an input is absent or reduced, other information can make a larger contribution.", "The evidence does not imply that all regions are interchangeable. It shows both stable functional relationships and experience-sensitive recruitment."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-review-p001", "noteId": "m3-review-p001", "module": "review", "source": "review", "page": 1, "title": "Final review", "sourceText": "Review Session\n", "image": "assets/review/001.webp", "core": false, "reviewPages": [], "paragraphs": [], "analysis": {"status": "authored", "role": "noninstructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p002", "noteId": "m3-review-p002", "module": "review", "source": "review", "page": 2, "title": "Orthographic depth", "sourceText": "We were able to demonstrate that \nphonemes are not letters, but also \nthat letters are not phonemes with \na “mispronouncing contest” in \nwhich people willfully \nmispronounced words like:\nCOLONEL\nPARADIGM\nWe also talked about how some \nscripts (like Pinyin for Mandarin \nand French) are relatively regular.\nThis difference between scripts is also referred to as orthographic depth. \nEnglish, due its irregularities is a relatively deep script. \nFinnish and Korean are very shallow scripts. \n", "image": "assets/review/002.webp", "core": false, "reviewPages": [], "paragraphs": ["**Orthographic depth** describes how consistently spelling corresponds to pronunciation. English is relatively deep because many spellings do not transparently specify their sounds.", "COLONEL and PARADIGM make the problem concrete. Applying common letter–sound patterns can produce a plausible-looking pronunciation that is wrong for the actual word.", "In shallower writing systems, such as Finnish and Korean, spelling–sound correspondences are more predictable. The comparison concerns the writing system, not the intelligence or ability of its readers."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-review-p003", "noteId": "m3-review-p003", "module": "review", "source": "review", "page": 3, "title": "Transparent spelling in Finnish", "sourceText": "Some writing systems, like Finnish, are \nvery “transparent” (or “shallow” \naccording to the Orthographic Depth \nHypothesis).\nLet’s listen to this beginning Finnish \nlesson and follow along with the text…\nAfter about a minute of this, you \nprobably get the idea?\nEach letter corresponds more or less \nunambiguously to one phoneme. \nDoubled letters actually correspond to \ngeminated consonants or long vowels.\nFinnish children learn to decode\npronunciations for written forms very \nvery quickly. \nhttp://tasteoffinnish.fi/lesson1-1/\n", "image": "assets/review/003.webp", "core": false, "reviewPages": [], "paragraphs": ["**Finnish has a shallow orthography.** Letters correspond relatively unambiguously to phonemes, so learning a spelling–sound correspondence helps with many different words.", "Doubled letters represent a meaningful length distinction. A doubled consonant is geminated, and a doubled vowel is long.", "This regularity helps Finnish children learn decoding quickly. Decoding means generating a pronunciation from a written form, whether or not its meaning is familiar."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-review-p004", "noteId": "m3-review-p004", "module": "review", "source": "review", "page": 4, "title": "Learning to decode across languages", "sourceText": "In fact, English is a bit of an outlier \namong languages that use the Roman \nalphabet. \nOne result is that kids learn to decode \nmore slowly in English.\nIn Grade 1, kids learning a wide variety \nof other languages are able to generate \nplausible pronunciations for \n“pseudowords,” (made up words that \nfollow the spelling and sound patterns \nof their language) at a much higher rate \nthan English learners.\n", "image": "assets/review/004.webp", "core": false, "reviewPages": [], "paragraphs": ["**Pseudoword reading tests decoding.** Because a pseudoword is not a familiar stored word, the child must generalize from learned spelling–sound patterns.", "The comparison involves Grade 1 children learning different alphabetic writing systems. Children learning many other languages produce plausible pseudoword pronunciations more successfully than English learners.", "English's less predictable correspondences help explain why decoding develops more slowly. This task does not measure the child's entire language ability."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-review-p005", "noteId": "m3-review-p005", "module": "review", "source": "review", "page": 5, "title": "Korean letter forms and sounds", "sourceText": "Korean is even more regular than \nFinnish!\nThe symbols for similar phonemes \nare represented as similar to one \nanother. \nWhat orthographic feature \ncorresponds roughly to velar place of \narticulation, for example?\n", "image": "assets/review/005.webp", "core": false, "reviewPages": [], "paragraphs": ["**Korean writing represents sound structure systematically.** Related phonemes can have related written shapes, so the visual forms themselves reflect aspects of phonological organization.", "The letters are arranged into syllable blocks with initial, medial and sometimes final positions. Those positions are not three unrelated pictures of whole words.", "The velar consonant forms share the basic angular ㄱ shape. Additional strokes or doubling distinguish related consonants."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-review-p006", "noteId": "m3-review-p006", "module": "review", "source": "review", "page": 6, "title": "Frequency by regularity interaction", "sourceText": "This is a landmark finding in psycholinguistics. \nWe’ll see how it has impacted a number of other areas \n(most immediately inflectional morphology).\nWhat does it mean?\nThe frequency effect is much \nlarger for exception words \nthan regular words. \nBehold: The Frequency by Regularity interaction.\n", "image": "assets/review/006.webp", "core": false, "reviewPages": [], "paragraphs": ["**Frequency and regularity interact.** Low-frequency exception words are slowed much more than low-frequency regular words, whereas high-frequency words show a much smaller regularity difference.", "Naming latency is the time needed to begin saying the word. Higher values mean slower responses.", "An interaction means the effect of one factor depends on the other. The regularity cost is not a fixed amount added equally to high- and low-frequency words."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-review-p007", "noteId": "m3-review-p007", "module": "review", "source": "review", "page": 7, "title": "Dual-route interpretation of the interaction", "sourceText": "One interpretation\nThere are two separate processes in word recognition: \n1. A sublexical process (decoding), and\n2. A lexical process (knowledge of a particular word)\nFor high frequency (HF) words, the lexical process is so fast and efficient that there is little \ninfluence of the sublexical process.\nThe sublexical process only shows up when we read nonwords, or low frequency (LF) words.\n", "image": "assets/review/007.webp", "core": false, "reviewPages": [], "paragraphs": ["**A dual-route interpretation separates lexical retrieval from sublexical decoding.** The lexical process supplies the learned pronunciation of a particular word, while decoding computes pronunciation from spelling units.", "For a high-frequency word, lexical information becomes available quickly enough to reduce the influence of the decoding output.", "For a low-frequency exception, the lexical response is less efficient and the regularized decoding output can interfere. Nonwords depend on decoding because they lack a stored whole-word entry."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading1.txt"}}, {"id": "m3-review-p008", "noteId": "m3-review-p008", "module": "review", "source": "review", "page": 8, "title": "Distributed knowledge and general learning", "sourceText": "PDP models of visual word recognition\nSeidenberg & McClelland (1989)\nDifferent assumptions from dual-route models:\n- “rules” are just generalizations from lots of \nwords, not a separate process\n- the “lexicon” is also distributed. Some \nwhole-word information is stored in O P \nmappings, some in  other parts of the system.\nDifferent research strategy from dual-route \nmodels:\nExplain reading in terms of domain-general \nlearning mechanisms, rather than reverse-\nengineer the system from adult/neuropsych data.\n", "image": "assets/review/008.webp", "core": false, "reviewPages": [], "paragraphs": ["**In a PDP account, rules are generalizations learned across words.** Whole-word knowledge is distributed across learned mappings instead of being stored only in a distinct lexical route.", "The same learning mechanism can capture both patterns shared by many words and information specific to a familiar word.", "The research strategy asks whether domain-general learning can explain reading. This contrasts with choosing separate adult processing components primarily from neuropsychological dissociations."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-review-p009", "noteId": "m3-review-p009", "module": "review", "source": "review", "page": 9, "title": "Learning the frequency–regularity interaction", "sourceText": "Frequency by regularity interaction\nThe model captured the interaction between \nfrequency and regularity without assuming \nthat these effects resulted from different \nprocesses.\nHow?\n- “regular” words are consistent with \nstatistical patterns from many other words.\n- “exception” words are inconsistent with \nthese statistics.\n- frequency also impacts how well words \nare learned. So, highly frequent words are \nless effected by inconsistency with other \nwords.\n", "image": "assets/review/009.webp", "core": false, "reviewPages": [], "paragraphs": ["**A learned network can produce a frequency-by-regularity interaction without separate frequency and rule mechanisms.** Regular words receive support from patterns shared across many words.", "An exception conflicts with those patterns, so learning its particular mapping is especially important. Frequent exposure strengthens that word-specific mapping.", "A low-frequency exception has both weak item-specific learning and poor support from the dominant pattern. This combination creates a larger disadvantage than either factor alone."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-review-p010", "noteId": "m3-review-p010", "module": "review", "source": "review", "page": 10, "title": "Using learned weights for nonwords", "sourceText": "Reading words and nonwords in the same \n“route”\nIn principle: \n- nonwords named via the same set of weights used \nfor words.\n- generalization takes advantage of the same statistical \npatterns that give rise to regularity effects.\n", "image": "assets/review/010.webp", "core": false, "reviewPages": [], "paragraphs": ["**A PDP model can pronounce nonwords using the weights learned from real words.** A new spelling activates patterns that overlap with familiar spellings, allowing the network to generalize.", "No stored entry for the particular nonword is required. The same learned correspondences that support consistent words can support a new combination.", "This is a proposed mechanism for decoding without a separate GPC rule module."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-review-p011", "noteId": "m3-review-p011", "module": "review", "source": "review", "page": 11, "title": "Theory versus implementation", "sourceText": "In practice, though, not so great…\nNonword accuracy was not very \ngood.\nWhy?\nThis is a classic case of ambiguity in \nmodel evaluation.\nWas the theoretical claim -- that \nnonwords and exceptions could \nbe read by the same, associative \nmechanism – wrong?\nOr, was the problem something \nspecific to the way the model was \nmade?\n", "image": "assets/review/011.webp", "core": false, "reviewPages": [], "paragraphs": ["**Poor nonword performance can challenge either a theoretical proposal or a particular implementation.** The early model's nonword accuracy was weaker than desired.", "One possibility is that a single associative mechanism cannot explain the task. Another is that the chosen representations fail to capture the similarities needed for generalization.", "Improving the implementation while retaining the theoretical mechanism helps distinguish these possibilities."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-review-p012", "noteId": "m3-review-p012", "module": "review", "source": "review", "page": 12, "title": "Phonological representation matters", "sourceText": "Nonword reading related to phonological representations\nMany studies demonstrate a \nrelationship between “decoding” \n(i.e., nonword reading) and \nphonological processing.\nThe phonological representations \nused in Seidenberg & McClelland \nwere sort of weird:  Wickelfeatures.\nIndeed, a model by Plaut et al. (1996, \nPsych Review) improved the \nphonological representations, and \nproduced better performance on \nnonwords.\n", "image": "assets/review/012.webp", "core": false, "reviewPages": [], "paragraphs": ["**Generalization depends on how sound similarity is represented.** The early Seidenberg–McClelland model used Wickelfeatures, whose representation of phonology was problematic for nonword reading.", "Plaut and colleagues improved the phonological representations and obtained better nonword performance. This supports a representational explanation for at least part of the earlier failure.", "Behavioral relations between phonological processing and decoding also make phonology a relevant target for explanation."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-review-p013", "noteId": "m3-review-p013", "module": "review", "source": "review", "page": 13, "title": "Why degraded phonology hurts generalization", "sourceText": "How are phonological representations and \nnonword generalization related?\nGeneralization depends on similarity. (In fact this principle is \ninherited from behaviorism.)\nPoor phonological representations (like Wickelfeatures) fail to \nadequately capture the similarity space of words in the language.\nWord-specific information is more robust to poor representations, \nbecause it doesn’t depend entirely on generalization.\n", "image": "assets/review/013.webp", "core": false, "reviewPages": [], "paragraphs": ["**A network generalizes through similarity.** If its phonological representation poorly captures similarities among words, the learned mapping cannot transfer as effectively to new forms.", "A familiar word can retain support from its own training history. A nonword lacks that item-specific experience and depends more heavily on generalization.", "This produces a reason for unfamiliar forms to be especially vulnerable to poor representations without requiring a dedicated nonword mechanism."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-review-p014", "noteId": "m3-review-p014", "module": "review", "source": "review", "page": 14, "title": "Harm and Seidenberg's noise manipulation", "sourceText": "How are phonological representations and \nnonword generalization related?\nHarm & Seidenberg (1999) investigated \nthis more systematically, by \nmanipulating the amount of “noise” in \nthe phonological representations.\nThey were able to replicate a number of \nkey findings in the literature on \ndevelopmental dyslexia:\n- relationship between degree of \nphonological deficit and phonological \ndyslexia\n- relative sparing of word recognition\n", "image": "assets/review/014.webp", "core": false, "reviewPages": [], "paragraphs": ["**Harm and Seidenberg manipulated noise in phonological representations.** Increasing noise makes the sound representations less reliable while keeping the model's general learning framework.", "The manipulation produced poorer nonword decoding and relative sparing of word recognition. It also linked the severity of the phonological deficit to the degree of decoding difficulty.", "The model therefore connects a reading pattern to the quality of a more general phonological system."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/reading2.txt"}}, {"id": "m3-review-p015", "noteId": "m3-review-p015", "module": "review", "source": "review", "page": 15, "title": "A dual-process past-tense architecture", "sourceText": "A “dual route” model for the past tense\nPinker & Ullman (2002, TICS)\nHow is this similar to the dual-route model we \nwere just considering for reading?\nHow is it different?\n", "image": "assets/review/015.webp", "core": false, "reviewPages": [], "paragraphs": ["**The lexicon and grammar offer different ways to produce a past tense.** Lexical retrieval supplies an irregular form such as HELD, while grammatical combination can produce WALK plus -ed.", "Pinker and Ullman's diagram associates lexical lookup with declarative memory and grammatical combination with procedural processing.", "Like dual-route reading, the account separates word-specific knowledge from a productive operation. Unlike reading aloud, its task is to transform a stem according to a grammatical feature, rather than convert spelling into sound."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-review-p016", "noteId": "m3-review-p016", "module": "review", "source": "review", "page": 16, "title": "Why separate rules from exceptions?", "sourceText": "Similar architecture, different origins\nRemember the dual route model was \ndeveloped based on \nneuropsychological double-\ndissociations.\nPinker et al. are motivated by other \nconcerns.\nGenerative linguistics of the time was \nmostly about categorical, symbolic, \nrule-based grammars.\nThese rules often have exceptions.\n", "image": "assets/review/016.webp", "core": false, "reviewPages": [], "paragraphs": ["**The Words and Rules proposal was motivated partly by a theory of grammar.** A categorical symbolic grammar describes productive patterns, but language also contains exceptions.", "Reading dual-route theories were strongly motivated by neuropsychological dissociations. The morphology proposal also reflects a commitment to keeping the grammatical rule system distinct from exceptional lexical information."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-review-p017", "noteId": "m3-review-p017", "module": "review", "source": "review", "page": 17, "title": "Properties of the exception system", "sourceText": "Similar architecture, different origins\nRather than make the grammar inelegant by \nadding machinery to handle the \nexceptions, linguists would often just \nleave the exceptions out of the grammar.\nSo dual-process model proposes a way to \n“handle” the exceptions while keeping \nthe grammar elegant, symbolic, \ncategorical, etc.\nThis second process had all the properties \nthe rule route did not. It was:\n- word-specific (lexical)\n- sensitive to frequency of occurrence\n- sensitive to phonological similarity \n(keep-kept, weep-wept, leap-leapt, etc.)  \n", "image": "assets/review/017.webp", "core": false, "reviewPages": [], "paragraphs": ["**An associative lexicon handles information that does not fit a categorical rule.** Its representations are word-specific and sensitive to frequency and phonological similarity.", "KEEP–KEPT, WEEP–WEPT and LEAP–LEAPT illustrate similarity among irregular forms. An exception can belong to a small family rather than being wholly unrelated to other words.", "Assigning these properties to lexical memory lets the rule system remain categorical and general."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-review-p018", "noteId": "m3-review-p018", "module": "review", "source": "review", "page": 18, "title": "An associative alternative", "sourceText": "An alternative approach: It’s all \nassociative learning!\nRumelhart & McClelland (1987) available, along with lots of these other papers, here: \nhttp://psych.stanford.edu/~jlm/papers/\n", "image": "assets/review/018.webp", "core": false, "reviewPages": [], "paragraphs": ["**Rumelhart and McClelland modeled past tense as a learned association between present and past sound patterns.** A single trainable network learns across verbs instead of applying a separately specified -ed rule.", "The model encodes a root's phonology, transforms that representation through modifiable connections, and decodes an output pattern.", "Regularity is a pattern learned from many examples. Irregular forms are also learned within the same system."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-review-p019", "noteId": "m3-review-p019", "module": "review", "source": "review", "page": 19, "title": "U-shaped learning", "sourceText": "Target phenomena of Rumelhart & McClelland\nBecause this was one of the first learning models to address a language process, the \nfocus was on capturing developmental phenomena.\nSpecifically: “U-shaped” learning:\n- some frequent irregular verbs are learned quite early, e.g., run-ran\n- then, spontaneously, children begin producing “regularizations:” runned.\n- eventually, they start producing correct forms again.\nLearning is “U-shaped” because children often get worse before they get better, so \nperformance goes down before it goes back up.\n", "image": "assets/review/019.webp", "core": false, "reviewPages": [], "paragraphs": ["**U-shaped learning describes an initial success, a decline, and later recovery.** A child may correctly say RAN, later produce RUNNED, and eventually return to RAN.", "The middle error is a **regularization**, because the child applies the common past-tense pattern to an irregular verb.", "The decline does not necessarily mean that the child has stopped learning. A changing system can generalize more broadly while temporarily disrupting an earlier correct response."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-review-p020", "noteId": "m3-review-p020", "module": "review", "source": "review", "page": 20, "title": "Words and Rules interpretation of development", "sourceText": "Why is U-shaped learning important to the \n“words and rules” approach? \nIt’s understood in terms of distinct stages/processes:\n- early correct forms are just imitations, don’t depend on the same \nmechanisms as adult processing.\n- when the rule is initially learned, it is applied to all cases. We can \nthink of the rule as the “best hypothesis” for all items generally.\n- over time, exceptions are learned associatively, one-by-one and \nincorporated into lexical knowledge. Further, the “blocking process” \ndevelops.\n", "image": "assets/review/020.webp", "core": false, "reviewPages": [], "paragraphs": ["**The Words and Rules account explains U-shaped learning through changes in the use of rules and lexical exceptions.** Early correct forms can be imitated before a productive rule is available.", "When the rule is learned, it can be applied too broadly, yielding RUNNED. Later, learned irregulars and the blocking process prevent that regularization.", "This account treats the developmental stages as involving distinguishable processes rather than only gradual changes in one mapping."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-review-p021", "noteId": "m3-review-p021", "module": "review", "source": "review", "page": 21, "title": "U-shaped learning in an associative model", "sourceText": "“U-shaped learning” in \nRumelhart & McClellands’s\nmodel.\n- training set is based on data \nabout input to children, which \nchanges over time.\n- Early on, irregular verbs \npredominate – in fact the highest-\nfrequency verbs tend to have \nirregular past-tense forms: GIVE, \nTAKE, HAVE, GO, etc.\n- As the vocabulary expands to \ninclude more regular forms, the \nmodel reorganizes to capture those \nregularities.\n-- this interferes with some of the \nearly-learned forms.    \n", "image": "assets/review/021.webp", "core": false, "reviewPages": [], "paragraphs": ["**Changing the training vocabulary can produce U-shaped learning in one network.** Early training emphasizes frequent irregular verbs, allowing those particular mappings to be learned.", "As more regular verbs enter training, their common pattern changes the network's responses. That generalization can interfere with previously learned irregulars.", "With further learning, the network can recover the irregular responses while retaining broad regularity. No new symbolic rule component is inserted at the point of decline."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-review-p022", "noteId": "m3-review-p022", "module": "review", "source": "review", "page": 22, "title": "Testing model generalization", "sourceText": "Generalization testing:\nThe model was trained \non a small number of \nverbs, so they could \ndo a “wug” test with \nreal words… \n", "image": "assets/review/022.webp", "core": false, "reviewPages": [], "paragraphs": ["**Testing untrained verbs asks whether the network learned transferable structure.** A real English verb can be novel to a model if it was excluded from that model's training set.", "The test therefore uses the logic of a wug task even when the items are real words to humans.", "The model can generate many appropriate past-tense features, but feature-level success must be distinguished from producing an entirely correct word."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-review-p023", "noteId": "m3-review-p023", "module": "review", "source": "review", "page": 23, "title": "Unusual model outputs", "sourceText": "But…\n", "image": "assets/review/023.webp", "core": false, "reviewPages": [], "paragraphs": ["**Some model outputs contain changes that are unlike ordinary human regularizations.** Examples include MADE(D)-like changes to MATE and the unusual outputs MEMBLED for MAIL and TOUREDER for TOUR.", "The model authors acknowledge that people are unlikely to make some of these errors. They suggest that additional output constraints could reduce bizarre responses.", "This separates capturing an overall learning pattern from matching the detailed form of human errors."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-review-p024", "noteId": "m3-review-p024", "module": "review", "source": "review", "page": 24, "title": "Phonology and semantics in inflection", "sourceText": "A new(er) model: Joanisse & \nSeidenberg (1999)\nTheoretical premise:\n- “rule-like” generalization is \nsupported by phonological \nrepresentations\n- “irregular” forms require \ngreater support from \nsemantics \nSemantics\nSpeech\nInput\nSpeech\nOutput\n", "image": "assets/review/024.webp", "core": false, "reviewPages": [], "paragraphs": ["**Joanisse and Seidenberg propose that phonology supports rule-like generalization while semantics especially supports irregular forms.** The same system links speech input, meaning and speech output.", "Reliable sound representations support extension from familiar present–past pairs to new forms. Irregular mappings receive additional support from the particular word's semantic representation.", "The hypothesis concerns different degrees of dependence on shared systems, rather than a separate symbolic rule route for every regular response."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-review-p025", "noteId": "m3-review-p025", "module": "review", "source": "review", "page": 25, "title": "Targeting a neuropsychological dissociation", "sourceText": "A new(er) model: Joanisse & \nSeidenberg (1999)\nTarget phenomenon:\n- dissociation between \nirregular and nonword past \ntense in neuropsychological \ndata.  \nSemantics\nSpeech\nInput\nSpeech\nOutput\n", "image": "assets/review/025.webp", "core": false, "reviewPages": [], "paragraphs": ["**The model aims to explain the dissociation between irregular and nonword past-tense performance.** These tasks differ in how much they depend on learned word-specific information and phonological generalization.", "A nonword has no familiar item-specific semantic history to support its inflection. A known irregular can require semantic support because its output is not well predicted by the dominant pattern.", "Manipulating phonological or semantic integrity tests whether these different dependencies can produce opposite impairment profiles."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-review-p026", "noteId": "m3-review-p026", "module": "review", "source": "review", "page": 26, "title": "Broca's aphasia and novel past tense", "sourceText": "Neuropsychological data\nBroca’s Aphasia\nInjury to left anterior brain \nregions\nPoor speech production\nProblems with regular \nmorphology, esp. nonwords\nwug wugged, \nblick blicked\n", "image": "assets/review/026.webp", "core": false, "reviewPages": [], "paragraphs": ["**The patient pattern associated here with Broca's aphasia includes especially poor nonword past-tense production.** These patients have left anterior injury and difficulty producing speech.", "Regular forms are also vulnerable, while irregular forms are relatively better in the displayed comparison. A novel BLICK must be transformed without relying on a familiar stored past tense.", "This motivates investigating phonological contributions to the apparent morphological deficit."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-review-p027", "noteId": "m3-review-p027", "module": "review", "source": "review", "page": 27, "title": "Patients with irregular-form difficulties", "sourceText": "Neuropsychological data: Problems with \nirregulars\nWernicke’s and Alzheimer’s patients\nAnomic patients with injury \nto inferior/middle temporal \nbrain regions\nPoor on irregulars (middle \nbar)\n50\n60\n70\n80\n90\n100\nregular\nnonword\nPercent Correct\n", "image": "assets/review/027.webp", "core": false, "reviewPages": [], "paragraphs": ["**Other patient groups show a larger problem with irregular past-tense forms.** The material discusses Wernicke's and Alzheimer's patients and anomic patients with inferior or middle temporal injury.", "Their irregular performance is lower than their regular and nonword performance in the displayed comparison.", "This creates the other side of the dissociation and motivates examining the information that especially supports known irregular forms."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/morphology.txt"}}, {"id": "m3-review-p028", "noteId": "m3-review-p028", "module": "review", "source": "review", "page": 28, "title": "The classical aphasia contrast", "sourceText": "An attractive dichotomy:\nWernicke’s aphasia = “Word salad” or “Jabberwocky,” often with neologisms. Syntax \nroughly intact:\nBroca’s aphasia =  “Telegraphic” speech, difficulty with word order and grammatical \nparticles (relative sparing of important content words):\n", "image": "assets/review/028.webp", "core": true, "reviewPages": [], "paragraphs": ["**The classical contrast associates Wernicke's aphasia with fluent but often poorly interpretable speech and Broca's aphasia with effortful, telegraphic speech.** The former can include neologisms, while the latter can omit grammatical particles and show word-order difficulty.", "This makes a lexical-versus-grammatical interpretation attractive. However, a descriptive syndrome is not itself a demonstration of an isolated processing module.", "Content words may be relatively preserved in telegraphic speech, while fluent speech can retain sentence-like structure without conveying a clear message."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p029", "noteId": "m3-review-p029", "module": "review", "source": "review", "page": 29, "title": "Historical Broca cases and modern classification", "sourceText": "An attractive dichotomy:\nWernicke’s aphasia = problems with activation (inhibition?) in the lexicon.\nBroca’s aphasia =  problems with grammar\nNote that this is fairly distant from \nhow Broca described his original \ncases.\nRemember this slide from a few \nweeks ago?\nThis is confusing: Broca’s actual \npatients would not necessarily be \nclassified as Broca’s aphasics. They \nwere arguably unable to produce \nspeech at all, apparently due to \nmotor control issues, and would be \nclassified as suffering from apraxia of \nspeech.\n", "image": "assets/review/029.webp", "core": true, "reviewPages": [], "paragraphs": ["**Broca's original patients are not necessarily straightforward examples of what is now called Broca's aphasia.** Profound inability to articulate speech can reflect motor-planning impairment rather than a selective grammatical deficit.", "**Apraxia of speech** concerns planning or coordinating speech movements. That differs from explaining an omission of grammatical structure in otherwise producible speech.", "The historical label therefore should not substitute for a precise description of the impaired behavior."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p030", "noteId": "m3-review-p030", "module": "review", "source": "review", "page": 30, "title": "Grammar, lexicon and aphasia", "sourceText": "An attractive dichotomy:\nWernicke’s aphasia = problems with activation (inhibition?) in the lexicon.\nBroca’s aphasia =  problems with grammar\nThis dichotomy is interesting in part \nbecause it seems well aligned with a \nsharp distinction drawn late 20th\nCentury formal linguistics between \nthe grammar and the lexicon.\nThis starts with Chomsky’s \nformulation of the computational \nproblem of language learning, and \ncompelling demonstrations of the \nindependence of syntax and \nsemantics.\n", "image": "assets/review/030.webp", "core": true, "reviewPages": [], "paragraphs": ["**A grammar–lexicon distinction makes the classical aphasia contrast theoretically appealing.** A grammatical system combines forms, while lexical knowledge concerns words and their properties.", "Chomsky's example of a grammatical but semantically unusual sentence shows that syntactic well-formedness cannot be reduced to whether a sentence describes a sensible event.", "That conceptual distinction does not establish a simple one-to-one mapping from each syndrome to one isolated component."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p031", "noteId": "m3-review-p031", "module": "review", "source": "review", "page": 31, "title": "Levels of speech production", "sourceText": "An attractive dichotomy:\nWernicke’s aphasia = problems with activation (inhibition?) in the lexicon.\nBroca’s aphasia =  problems with grammar\nConsider, too, the difference between \nthe Functional and Positional levels in \nour speech production model.\nLemmas have an arbitrary relationship \nto their referents. \nBut the syntactic trees, affixes, etc. at \nthe positional level are the product of \nabstract syntactic processes.\n“But,” you might object “what about \nwords like HOUSEBOAT and DOGHOUSE, \nwhere the meaning is clearly not \narbitrary,” and I would remind you of \nspeech error evidence that derivational \nmorphology is done at the positional \nlevel, e.g., easy enoughly.\n", "image": "assets/review/031.webp", "core": true, "reviewPages": [], "paragraphs": ["**The functional level selects word meanings and semantic roles, while the positional level organizes word forms into a grammatical sequence.** Phonological encoding and articulation concern later aspects of producing the utterance.", "A **lemma** is a representation involved in lexical selection, distinct from simply executing its sound pattern. Positional processing contributes ordering and morphological structure.", "Combinations such as HOUSEBOAT show that complex-word meaning can be partly compositional. Errors such as “easy enoughly” provide evidence about the organization of morphological operations."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p032", "noteId": "m3-review-p032", "module": "review", "source": "review", "page": 32, "title": "Egocentric and absolute spatial language", "sourceText": "Thinking about space…\nIt seems natural in most languages to talk \nabout space egocentrically when talking about \nthings that are nearby.\nWhat is to your left or to your right, in front of \nyou or behind you, etc.\nNot so in Tzeltal, a Western Mayan language \nspoken in Chiapas.\nIn this language (and a small number of others, \nmostly unrelated to one another, and broadly \ndistributed, e.g., in Bali and Queensland) \nabsolute directions are used.\nRaise your east hand if this seems intuitive to \nyou… \nSome native Tzeltal speakers defending their land \nfrom the vampire squid of neoliberalism.\n", "image": "assets/review/032.webp", "core": false, "reviewPages": [], "paragraphs": ["**Egocentric spatial descriptions use the speaker's position and orientation.** Left, right, in front and behind are familiar examples for nearby objects.", "Tzeltal commonly uses absolute directions in circumstances where English speakers might use these relative terms.", "The contrast motivates asking whether habitual language use relates to nonverbal spatial coding, rather than merely comparing two ways of giving spoken directions."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-review-p033", "noteId": "m3-review-p033", "module": "review", "source": "review", "page": 33, "title": "Tzeltal uphill and downhill", "sourceText": "Tzeltal has a historically landmark-\nbased system.\nThings are either “uphill” or \n“downhill” from one another, not to \nthe left or right of the speaker or \ninterlocutor.\nIn fact, “uphill” and “downhill” are \nused as cardinal directions, making \nthis an absolute system. \nBeautiful downtown Tenejapa.\n(Levinson et al., 2002, Cognition)\n", "image": "assets/review/033.webp", "core": false, "reviewPages": [], "paragraphs": ["**Tzeltal's uphill and downhill terms function as an absolute directional system.** Their historical connection to a slope does not mean that each use simply points to the nearest visible hill.", "A direction is retained as a stable spatial reference rather than being recalculated from the speaker's current left and right.", "This allows positions to be described consistently as the speaker changes orientation."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-review-p034", "noteId": "m3-review-p034", "module": "review", "source": "review", "page": 34, "title": "The rotated spatial-memory task", "sourceText": "Majid et al. (2004, TiCS)\nA non-linguistic test for relative vs. absolute coding of space\n", "image": "assets/review/034.webp", "core": false, "reviewPages": [], "paragraphs": ["**The chips task separates relative from absolute spatial memory by rotating the participant 180 degrees.** A participant sees a configuration, waits, and then chooses its match at a second table.", "A relative response preserves the arrangement with respect to the person's viewpoint. An absolute response preserves its orientation in the environment, so the two responses diverge after rotation.", "Dutch speakers predominantly gave relative responses, while Tzeltal speakers gave more absolute responses. The association is consistent with their preferred linguistic frames but does not isolate language from all other experience."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-review-p035", "noteId": "m3-review-p035", "module": "review", "source": "review", "page": 35, "title": "Spatial inference across displays", "sourceText": "Majid et al. (2004, TiCS)\nYou can get really fancy with this.\n", "image": "assets/review/035.webp", "core": false, "reviewPages": [], "paragraphs": ["**Spatial inference can combine relations learned in different displays.** Participants learn the relation between two objects, rotate to another display, and learn a second relation involving a shared object.", "They then place an object relative to another using the combined information. Relative and absolute coding lead to different placements because the person's orientation has changed.", "Dutch and Tzeltal response patterns again differ in the direction associated with their preferred spatial frames."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-review-p036", "noteId": "m3-review-p036", "module": "review", "source": "review", "page": 36, "title": "A testing-environment alternative", "sourceText": "Li and Gleitman:\nInducing landmark-based similarity in English speakers \nConsider the conditions under which \nthe Tzeltal speakers were tested: \nOutside, with visible, familiar landmarks. \nTypical psychology lab studies are done \nin windowless rooms.\n", "image": "assets/review/036.webp", "core": false, "reviewPages": [], "paragraphs": ["**Testing conditions could contribute to the apparent language-group difference.** Li and Gleitman noted that Tzeltal participants had been tested with visible, familiar outdoor landmarks, unlike many laboratory participants.", "An environment with useful landmarks can encourage landmark-based coding. A windowless laboratory can make viewer-relative descriptions more convenient.", "Manipulating landmark availability within English speakers tests whether the behavior can change without changing native language."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-review-p037", "noteId": "m3-review-p037", "module": "review", "source": "review", "page": 37, "title": "Blinds down, blinds up and outdoors", "sourceText": "In the “blinds down” condition, English \nspeakers overwhelmingly use relative position \nin this task – like the Dutch speakers in prior \nstudies.\nWith the blinds up and a view of the street, or \noutdoors, their preference is less pronounced. \nLi and Gleitman:\nInducing landmark-based spatial reasoning in English \nspeakers \n", "image": "assets/review/037.webp", "core": false, "reviewPages": [], "paragraphs": ["**English speakers' preference for relative coding weakened when external landmarks were available.** They strongly preferred relative responses with the blinds down, but the preference was less pronounced with a street view or outdoors.", "The manipulation changes the spatial information available while keeping the language group the same.", "This demonstrates that task context can influence the response. It challenges an explanation in which language alone fixes the chosen frame."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-review-p038", "noteId": "m3-review-p038", "module": "review", "source": "review", "page": 38, "title": "Levinson's methodological response", "sourceText": "Levinson and colleagues \nwere not impressed.\nThey claim that Li and \nGleitman made it too \ntransparent that they were \ntesting something to do \nwith rotation by reducing \nmemory load and \ntime/distance between \nstimulus and test.\nAlso Li and Gleitman’s\nparticipants were Ivy \nLeague students, who excel \nat figuring out what the \nprofessor wants and then \nmaking it happen.  \n", "image": "assets/review/038.webp", "core": false, "reviewPages": [], "paragraphs": ["**Levinson and colleagues argued that the simplified task could make the experimenter's purpose too obvious.** Low memory demands and short time or distance between displays may encourage a deliberate strategy about rotation.", "Participants who infer what is being tested can alter their response for reasons different from habitual spatial coding.", "The response therefore focuses on memory load and task transparency, rather than denying that landmarks can ever matter."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/thought.txt"}}, {"id": "m3-review-p039", "noteId": "m3-review-p039", "module": "review", "source": "review", "page": 39, "title": "Testing categorical perception in sign", "sourceText": "Research question: Is there categorical perception for these dimensions?\n", "image": "assets/review/039.webp", "core": false, "reviewPages": [], "paragraphs": ["**Categorical perception can be tested by varying a sign feature continuously.** The hand-configuration continuum moves between forms while the observer's identification and discrimination responses are measured.", "One continuum crosses a phonemic distinction between PLEASE and SORRY. The allophonic comparison varies hand configuration without the same change in sign identity.", "A sharp identification boundary accompanied by better discrimination near that boundary would indicate category-sensitive perception."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-review-p040", "noteId": "m3-review-p040", "module": "review", "source": "review", "page": 40, "title": "Identification and discrimination results", "sourceText": "These curves should look \nfamiliar.\nThere is a fairly sharp \ncategorical boundary between \nstimuli 4 and 6 for the \nphonemic boundary. \nThis corresponds to the peak in \nthe discrimination function.\nFor the allophonic condition, \nthe identification function is \nmuch shallower – i.e., many \nmore ambiguous stimuli – and \nthere is no peak in the \ndiscrimination function. \n", "image": "assets/review/040.webp", "core": false, "reviewPages": [], "paragraphs": ["**Deaf signers show a sharper categorical boundary for phonemic than allophonic hand-configuration changes.** In the phonemic condition, identification shifts steeply around stimuli 4–6.", "Discrimination is also strongest near the phonemic boundary. Comparable physical steps are easier to distinguish when they cross that category boundary.", "The allophonic identification function is shallower and lacks the same localized discrimination peak. This links the perceptual pattern to linguistic contrast rather than any visible hand change."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-review-p041", "noteId": "m3-review-p041", "module": "review", "source": "review", "page": 41, "title": "Shared and modality-related brain activity", "sourceText": "Brain activity during sign language comprehension has both important \nsimilarities and differences with spoken language.\nSimilar: \n- left lateralization\n- classical language areas \n(Broca’s / inferior frontal; Wernicke’s\n/ posterior superior temporal)\nDifferent:\n- +visual areas (-auditory areas)\n- superior parietal / classic \nspatial areas\nCampbell, MacSweeney, & Waters (2008)\nDeaf signers\nHearing signers\nAudio-visual \nSpeech (hearing participants)\n", "image": "assets/review/041.webp", "core": false, "reviewPages": [], "paragraphs": ["**Signed-language comprehension recruits classical language regions and shows left lateralization, as spoken-language comprehension does.** Inferior frontal and posterior superior temporal regions are part of this overlap.", "Signing also engages visual and superior parietal regions relevant to its perceptual and spatial demands.", "The combination suggests both common language organization and modality-related contributions. Similarity does not require identical activation everywhere."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-review-p042", "noteId": "m3-review-p042", "module": "review", "source": "review", "page": 42, "title": "Evidence about signed language", "sourceText": "So, sign language…\nSign language has phonological structure, and native speakers show categorical perception \nfor some contrastive features.\nLearning a signed language results in some brain reorganization, particularly the \nlateralization of motion processing.\nAlthough attention to the visual periphery is critical for both hearing and deaf signers, only \ndeaf signers show enhanced processing of visual attention in the periphery.\nCompared with non-language stimuli that also involve organized, sequenced hand \nmovements, signed sentences activate posterior STG (Wernicke’s area).\n", "image": "assets/review/042.webp", "core": false, "reviewPages": [], "paragraphs": ["**Signed languages have linguistic form, grammar and language-related neural organization.** Contrastive sign features can produce categorical perception, and comprehension recruits posterior superior temporal language regions.", "Signing experience is associated with changes in motion lateralization. Deafness is associated with enhanced peripheral attention in the reported comparison.", "These findings jointly show that linguistic experience and sensory history contribute in different ways."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/modalities.txt"}}, {"id": "m3-review-p043", "noteId": "m3-review-p043", "module": "review", "source": "review", "page": 43, "title": "Exercise and maturational-state hypotheses", "sourceText": "Two versions of the “critical period” hypothesis\nWhich of these do you think JN89 see as more consistent with their data?\nDoes this change our interpretation of the L1 critical period data?\n", "image": "assets/review/043.webp", "core": true, "reviewPages": [], "paragraphs": ["**The exercise hypothesis proposes that early language use preserves language-learning capacity, while the maturational-state hypothesis allows capacity to decline despite early use.** Both assume an early advantage, but they differ in what early successful experience protects.", "Later second-language difficulty in people who already acquired a first language is more directly compatible with maturation than with complete preservation through exercise.", "This does not make early first-language experience unimportant. Early access and age-related change address related but distinct questions."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p044", "noteId": "m3-review-p044", "module": "review", "source": "review", "page": 44, "title": "Early language access and later learning", "sourceText": "Mayberry, Lock, & Kazmi (2002, Nature)\nMany deaf children do not get sign language input, \nbut have an otherwise typical upbringing.\nChildren (ages 9-15) have difficulty learning \nAmerican Sign Language (ASL) if this is their first time \nlearning a language.\nA comparison group of children who went deaf after \ninitially learning a spoken language do much better.\nThese differences persist into adulthood.\n", "image": "assets/review/044.webp", "core": true, "reviewPages": [], "paragraphs": ["**Mayberry, Lock and Kazmi compared later language learning after different early-language histories.** Deaf individuals without accessible early language performed worse than those who had acquired an early spoken or signed language.", "Children first exposed to ASL at ages 9–15 had particular difficulty when it was also their first language. Those who had first learned a spoken language did much better, and the differences persisted.", "The comparison distinguishes late first-language learning from late acquisition of an additional language."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p045", "noteId": "m3-review-p045", "module": "review", "source": "review", "page": 45, "title": "Controlling visual similarity in blocking", "sourceText": "Dealing with potential confounds 101\nWhat if the blocking effect arises at the level of \nvisual object recognition?\nTwo responses:\n1. Stimuli were normed so that objects in \nthe same category were not more visually \nsimilar to one another than objects in different \ncategories, on average.\n2.  A control experiment was run in which \nvisual similarity was blocked along, and \ndifferent results were found.\nSpecifically, the blocking effect was \nobserved in the first block of trials. \nThus, the effects in Experiment 1 aren’t likely \nto be due to visual similarity.\n", "image": "assets/review/045.webp", "core": true, "reviewPages": [], "paragraphs": ["**Semantic blocking effects must be separated from visual-recognition difficulty.** Objects from one semantic category could resemble one another visually, creating a potential confound in naming.", "The materials were normed so that same-category items were not more visually similar on average. A separate visual-similarity manipulation also produced a different time course.", "Visual blocking affected the first block, whereas the semantic pattern of interest developed differently. This weakens a purely visual explanation."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p046", "noteId": "m3-review-p046", "module": "review", "source": "review", "page": 46, "title": "Simultaneous displays and serial naming", "sourceText": "Yeah, but what about that Hermens et al., study, where people saw multiple \nobjects simultaneously, and they didn’t find an effect?\nMaybe there’s just something weird about seeing objects in serial?\nBelke et al. address this by asking participants to view displays of four items \nsimultaneously and produce their names in serial.\n", "image": "assets/review/046.webp", "core": true, "reviewPages": [], "paragraphs": ["**Belke and colleagues presented four objects simultaneously but required their names in sequence.** This tests whether the absence of an effect in another simultaneous-display study depended on presentation format.", "Displaying all objects at once reduces dependence on a succession of isolated pictures. Serial naming still requires selecting and producing one label after another.", "Eye tracking provides additional timing information about the processing of each object."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p047", "noteId": "m3-review-p047", "module": "review", "source": "review", "page": 47, "title": "Gaze duration and eye–speech lag", "sourceText": "They measure eye-movements while they do this.\n", "image": "assets/review/047.webp", "core": true, "reviewPages": [], "paragraphs": ["**Eye movements and speech onsets provide different timing measures during serial naming.** Gaze duration records how long the eyes remain on an object, while eye–speech lag concerns the interval between leaving it and beginning its spoken name.", "A participant can move the eyes toward the next object before articulating the current one. The measures therefore separate overlapping parts of preparation.", "Different blocking effects on these measures can help constrain the processing stage affected."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p048", "noteId": "m3-review-p048", "module": "review", "source": "review", "page": 48, "title": "Where the blocking effect appears", "sourceText": "Overall duration of speech \ndecreases over the course of \nthe experiment, but doesn’t \nshow a blocking effect.\ngesture level\nGaze duration shows a \nblocking effect, but only after \nthe first cycle.\nlemma selection\nThere’s no effect on lag. \nNumerically, the blocking \neffect seems to go in the \nopposite direction, but this is \nnot significant.\nphonological encoding\n", "image": "assets/review/048.webp", "core": true, "reviewPages": [], "paragraphs": ["**Semantic blocking increases gaze duration after the first presentation cycle, but not overall speech duration or eye–speech lag.** The measures therefore do not show a uniform slowdown.", "Speech duration decreases with repetition without a blocking difference. Gaze duration shows the condition difference after the first cycle.", "The nonsignificant lag difference should not be reported as evidence for a reversed effect. The reported pattern is interpreted as supporting a contribution at lemma selection rather than articulation or phonological encoding."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p049", "noteId": "m3-review-p049", "module": "review", "source": "review", "page": 49, "title": "Thresholded or cascaded speech processing?", "sourceText": "So, we want to know, is phoneme identification for word recognition more like thresholded\n(lumber mill) or cascaded (food web) processing?\nMcMurray, B., Tanenhaus, M., Aslin, R. and Spivey, M. (2003). \nProbabilistic constraint satisfaction at the lexical/phonetic interface: \nEvidence for gradient effects of within-category VOT on lexical \naccess. Journal of Psycholinguistic Research, 32, 77-97.\nhttp://www2.psychology.uiowa.edu/faculty/mcmurray/publications/\nmcmurray-jpr.pdf \nMcMurray et al. tested identification of a /b/-/p/ \ncontinuum in a “visual world” display for eye-\ntracking.\n", "image": "assets/review/049.webp", "core": true, "reviewPages": [], "paragraphs": ["**McMurray and colleagues tested whether fine phonetic information affects lexical competition.** Participants heard a /b/–/p/ continuum while viewing pictures including BEAR and PEAR, with eye movements recorded.", "**Voice onset time**, or VOT, varies the timing between release and voicing. It can change how strongly the sound supports /b/ or /p/.", "A thresholded account would pass a completed categorical decision onward. A cascaded account allows graded information to influence word candidates before uncertainty is fully resolved."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p050", "noteId": "m3-review-p050", "module": "review", "source": "review", "page": 50, "title": "Categorical mouse choices", "sourceText": "So, we want to know, is phoneme identification for word recognition more like thresholded\n(lumber mill) or cascaded (food web) processing?\nParticipants used the mouse to select the \npicture most consistent with what they \nheard, e.g., a “bear” or a “pear,” just like \nin the experiment you did at home.\nA typical, step-like, identification function \nwas observed. \n", "image": "assets/review/050.webp", "core": true, "reviewPages": [], "paragraphs": ["**Participants selected the picture that best matched the spoken item.** Their BEAR–PEAR choices produced a typical step-like identification function across VOT.", "Shorter VOTs favored the /b/ response and longer VOTs the /p/ response. Near the boundary, the preferred category changed rapidly.", "A categorical-looking final response does not establish that all earlier lexical activation was categorical."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p051", "noteId": "m3-review-p051", "module": "review", "source": "review", "page": 51, "title": "Graded lexical competition", "sourceText": "Eye-movements reveal that ambiguity is gradient, i.e., there are more looks to the competitor \nclose to the boundary.\n", "image": "assets/review/051.webp", "core": true, "reviewPages": [], "paragraphs": ["**Competitor looks vary with phonetic ambiguity even within a chosen category.** Tokens closer to the /b/–/p/ boundary produce more competition than clear tokens farther from it.", "A participant can ultimately select BEAR while spending more time looking at PEAR when the sound is close to the boundary.", "This supports the claim that fine phonetic information remains relevant to lexical activation, rather than disappearing completely after a categorical phoneme decision."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}, {"id": "m3-review-p052", "noteId": "m3-review-p052", "module": "review", "source": "review", "page": 52, "title": "Distance from the boundary and time", "sourceText": "The effect is a lot clearer viewed this way…\n", "image": "assets/review/052.webp", "core": true, "reviewPages": [], "paragraphs": ["**Competitor fixation increases as a token approaches the category boundary from either side.** For BEAR responses, more /p/-like VOT increases looks to PEAR. For PEAR responses, more /b/-like VOT increases looks to BEAR.", "The graph separates early and late observation windows. The gradient remains visible in the later competition measure, supporting continued sensitivity to within-category phonetic detail.", "The result favors cascaded use of graded evidence over a model that transmits only a completed phoneme label with all within-category detail discarded."], "analysis": {"status": "authored", "role": "instructional", "authorFile": "authoring/content/review.txt"}}], "sources": {"reading1": {"original": "reading1.pdf", "file": "sources/reading1.pdf", "pages": 24, "sha256": "d422b43524220c959a75e1afeccc28faff3b3b6f04c418651271759001af17f0", "format": "pdf", "previewStatus": "ready", "pdf": "sources/reading1.pdf"}, "reading2": {"original": "reading2.pdf", "file": "sources/reading2.pdf", "pages": 31, "sha256": "822e15f9224cb6af9e444102ef8e9156cdff53fb862b033fe514697f06796e08", "format": "pdf", "previewStatus": "ready", "pdf": "sources/reading2.pdf"}, "morphology": {"original": "inflectional_morphology.pptx", "file": "sources/morphology.pptx", "pages": 30, "sha256": "751204fed8617dffa27011e6540436c75af6a9017f39ee66cb14bf93b38cb89b", "format": "pptx", "previewStatus": "ready", "pdf": "sources/morphology.pdf"}, "thought": {"original": "language_and_thought_2025.pdf", "file": "sources/thought.pdf", "pages": 27, "sha256": "8e4c9cc473f2645d2e4ed6162e0b0ce5c3ddd39a45eb60868e791d403a93e0a1", "format": "pdf", "previewStatus": "ready", "pdf": "sources/thought.pdf"}, "modalities": {"original": "sign_and_braille_2025.pdf", "file": "sources/modalities.pdf", "pages": 21, "sha256": "bd6977a268b46c6dd274a6c936a5c4cd33b6dd1cbb99baa35318563f87fa53ed", "format": "pdf", "previewStatus": "ready", "pdf": "sources/modalities.pdf"}, "review": {"original": "final_review_session_2025 (in class 12-2).pdf", "file": "sources/review.pdf", "pages": 52, "sha256": "6701fb01d9dc9929cf11a18ae966acd908aa6823c4ac97aedb4a8a30807186e3", "format": "pdf", "previewStatus": "ready", "pdf": "sources/review.pdf"}}, "editions": [{"id": "psyc20", "label": "PSYC301 v20-style teaching", "scripts": {"m3-reading1-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 1}, "m3-reading1-p002": {"status": "ready", "blocks": [{"text": "**Phonemes are speech-sound categories, not letters.** A writing system represents language, but its symbols do not have to correspond one-to-one with those categories. A letter can contribute to different pronunciations, and a phoneme can be represented by different spellings.", "children": []}, {"text": "**Keep spoken categories separate from written symbols.** Identifying a letter is not the same task as identifying a phoneme.", "children": ["The question concerns the relation between sound and writing, rather than how many letters a word contains."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 2}, "m3-reading1-p003": {"status": "ready", "blocks": [{"text": "**Orthographic depth** describes how consistently spelling corresponds to pronunciation. English is relatively deep because many spellings do not transparently specify their sounds. COLONEL and PARADIGM make the problem concrete. Applying common letter–sound patterns can produce a plausible-looking pronunciation that is wrong for the actual word.", "children": ["In shallower writing systems, such as Finnish and Korean, spelling–sound correspondences are more predictable. The comparison concerns the writing system, not the intelligence or ability of its readers."]}, {"text": "**An unfamiliar spelling cannot always be decoded correctly from its letters alone.** Deep orthographies create more exceptions that readers must learn through experience.", "children": ["The English examples contrast ordinary expectations from the letters with the word's learned pronunciation. A deep script is less predictable, not completely random."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 3}, "m3-reading1-p004": {"status": "ready", "blocks": [{"text": "**Finnish has a shallow orthography.** Letters correspond relatively unambiguously to phonemes, so learning a spelling–sound correspondence helps with many different words. Doubled letters represent a meaningful length distinction. A doubled consonant is geminated, and a doubled vowel is long.", "children": ["This regularity helps Finnish children learn decoding quickly. Decoding means generating a pronunciation from a written form, whether or not its meaning is familiar."]}, {"text": "**Consistent correspondences make decoding easier to generalize.** Finnish readers can apply what they learn about letters to unfamiliar written forms.", "children": ["The linked Finnish lesson is a source demonstration. Its sound is not embedded in the PDF, so the written claims establish the correspondence and length distinctions without supplying a recovered recording."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 4}, "m3-reading1-p005": {"status": "ready", "blocks": [{"text": "**Pseudoword reading tests decoding.** Because a pseudoword is not a familiar stored word, the child must generalize from learned spelling–sound patterns. The comparison involves Grade 1 children learning different alphabetic writing systems. Children learning many other languages produce plausible pseudoword pronunciations more successfully than English learners.", "children": ["English's less predictable correspondences help explain why decoding develops more slowly. This task does not measure the child's entire language ability."]}, {"text": "**A made-up word separates decoding from remembering a familiar word.** The lower English performance is consistent with greater orthographic depth.", "children": ["Compare accuracy across languages for the same type of task. The important outcome is the relative difficulty of English pseudoword decoding, not a claim that English children cannot decode."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 5}, "m3-reading1-p006": {"status": "ready", "blocks": [{"text": "**Korean writing represents sound structure systematically.** Related phonemes can have related written shapes, so the visual forms themselves reflect aspects of phonological organization. The letters are arranged into syllable blocks with initial, medial and sometimes final positions. Those positions are not three unrelated pictures of whole words.", "children": ["The velar consonant forms share the basic angular ㄱ shape. Additional strokes or doubling distinguish related consonants."]}, {"text": "**The organization of Hangul supports more than consistent pronunciation.** Similar sound categories can also be visibly related in their written symbols.", "children": ["The diagrams label initial, medial and final positions. The g, kk and k examples share a shape family, illustrating how a place-of-articulation relation can be reflected in the script."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 6}, "m3-reading1-p007": {"status": "ready", "blocks": [{"text": "**GLORP, SPLING, JONK, FEESH and QUISP can be pronounced without being familiar words.** Their forms follow enough English spelling patterns for a reader to construct a plausible pronunciation. Success cannot depend on retrieving a stored pronunciation for each particular item. The reader is using knowledge that generalizes across words.", "children": ["The demonstration establishes generalization. By itself, it does not decide whether that knowledge consists of categorical rules or learned statistical patterns."]}, {"text": "**Reading a novel letter sequence reveals knowledge beyond memorized words.** Familiar spelling patterns support pronunciation of new combinations.", "children": ["The items are instructional stimuli. Their role is to test decoding, not vocabulary knowledge or knowledge of a definition."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 7}, "m3-reading1-p008": {"status": "ready", "blocks": [{"text": "**Pseudoword decoding is fast and largely automatic.** In the Lupker, Brown and Colombo example, naming pseudowords is only about 5–12% slower than naming low-frequency real words. Participants read the items aloud, and naming time measures how quickly a pronunciation becomes available. The small difference shows that unfamiliarity does not make pronunciation an entirely slow, deliberate process.", "children": ["Both rules and statistical generalization might produce efficient decoding. The speed result constrains a theory without selecting one architecture on its own."]}, {"text": "**Fast nonword naming is evidence that decoding is a normal part of skilled reading.** It does not by itself prove that a separate rule system performs the task.", "children": ["Compare pseudowords with low-frequency words rather than treating every real word as an equally familiar baseline. A percentage slowdown describes relative naming time, not an error rate."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 8}, "m3-reading1-p009": {"status": "ready", "blocks": [{"text": "**An unfamiliar spelling can support more than one plausible pronunciation.** VONTH, PHANGE, STREAD and SOUGH contain patterns whose pronunciations are not all uniquely determined in English. A response reflects the spelling–sound patterns available from previously learned words. Different familiar patterns can favor different responses to the same novel form.", "children": []}, {"text": "**Generalization can be graded rather than all-or-none.** Ambiguous pseudowords reveal competing pronunciation possibilities.", "children": ["These items probe how readers resolve uncertainty in spelling-to-sound mappings. There is no requirement that every unfamiliar form have one universally agreed pronunciation."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 9}, "m3-reading1-p010": {"status": "ready", "blocks": [{"text": "**STREAD can plausibly be pronounced with either /ɛ/ or /i/.** The same written sequence can resemble more than one learned spelling–sound pattern. Testing novel items reveals what a reader has generalized, because the particular word cannot simply have been memorized.", "children": ["The challenge for a categorical rule account is to explain why multiple outputs seem acceptable. A statistical account can represent differing support for alternative pronunciations."]}, {"text": "**Accepting both /strɛd/ and /strid/ is information about the knowledge being generalized.** A model must explain the alternatives, not merely choose one output and ignore the other.", "children": ["The contrast changes the vowel while keeping the rest of STREAD constant. This isolates ambiguity in the spelling–sound relation."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 10}, "m3-reading1-p011": {"status": "ready", "blocks": [{"text": "**The regularity effect is the difficulty of reading words whose pronunciation conflicts with common spelling–sound patterns.** PINT, ACHE and CHOIR are examples of words for which straightforward decoding can mislead. A strict regular–irregular division is less clear when a spelling neighborhood contains several pronunciations. ROLL, POLL and TOLL support one pattern, while DOLL differs.", "children": ["COOK, TOOK and BOOK likewise contrast with SPOOK. These neighborhoods motivate asking how much support a pronunciation has from similar words."]}, {"text": "**A word's difficulty depends partly on how its spelling neighbors are pronounced.** The issue is not simply whether the reader knows the letters.", "children": ["A neighborhood is a set of words sharing relevant spelling patterns. The comparison concerns their pronunciations, not similarities in their meanings."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 11}, "m3-reading1-p012": {"status": "ready", "blocks": [{"text": "**Sublexical information concerns units smaller than a whole word.** Rapid nonword reading and the advantage for typical spelling–sound patterns show that readers use this information. **Lexical information** concerns knowledge of particular words. A complete account must explain how experience with a specific word contributes alongside general spelling patterns.", "children": []}, {"text": "**General decoding explains part of reading, but familiar-word knowledge also needs an account.** The two sources of information are conceptually distinguishable even before deciding how they are implemented.", "children": ["Nonwords test generalization, while differences among familiar words can reveal word-specific knowledge. These are evidence types, not proof that two independent modules must exist."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 12}, "m3-reading1-p013": {"status": "ready", "blocks": [{"text": "**Word knowledge can help identify an ambiguous letter.** In an interactive activation network, visual features activate letters and letters activate candidate words. Activated word candidates send feedback to their constituent letters. A letter supported by a plausible word receives additional activation even when its local visual evidence is unclear.", "children": ["Competing candidates do not remain equally active. Their activation changes as the network settles on an interpretation."]}, {"text": "**Letter recognition can depend on the word surrounding the letter.** Feedback supplies a mechanism by which whole-word knowledge influences perception.", "children": ["The network links features, letters and words. The letter-output graph shows one candidate increasing while competing candidates remain low, illustrating a developing preference rather than instantaneous recognition."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 13}, "m3-reading1-p014": {"status": "ready", "blocks": [{"text": "**Feedback carries word-level activation back to letters.** A partially activated known word increases activation of the letters that belong to it. This makes recognition interactive. Information does not flow only from isolated features upward to a finished word.", "children": ["The mechanism helps explain why an ambiguous letter can become easier to recognize when it appears in a familiar word context."]}, {"text": "**Recognizing a word and recognizing its letters can support one another.** Top-down feedback is the word-to-letter part of that interaction.", "children": ["The direction of a connection matters. Letter-to-word activation provides evidence for a candidate, while word-to-letter feedback supports the candidate's components."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 14}, "m3-reading1-p015": {"status": "ready", "blocks": [{"text": "**Lexicality and word frequency reveal effects of word-specific experience.** Real words are generally named faster than pseudowords, and frequently encountered words are named faster than less frequent words. Lexicality compares whether the item is a word. Frequency compares how often a particular word has been encountered.", "children": ["The English Lexicon Project data show that the frequency effect occurs across many observations, rather than depending on a few unusually easy examples."]}, {"text": "**Familiarity with a particular word contributes to reading speed.** Knowing general spelling patterns does not remove the benefit of repeated encounters with that word.", "children": ["A frequency effect is a relation between prior exposure and naming performance. It is not the claim that all high-frequency words have the same length or pronunciation pattern."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 15}, "m3-reading1-p016": {"status": "ready", "blocks": [{"text": "**Multiple regression tests whether frequency predicts reading time after accounting for other word properties.** Length and sound-related characteristics could otherwise be mistaken for effects of frequency. The analysis uses about 3,000 words read by young and older adults. Frequency still contributes when other predictors are considered.", "children": ["This makes a simple length-confound explanation less plausible. It does not turn an observational predictor into an experimentally isolated cause."]}, {"text": "**The frequency effect is not adequately explained by saying that frequent words are merely shorter.** Its contribution survives statistical control of other properties.", "children": ["The highlighted objective- and subjective-frequency coefficients are negative. Higher frequency is associated with shorter reaction times, with separate columns for lexical decision and naming in the two age groups."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 16}, "m3-reading1-p017": {"status": "ready", "blocks": [{"text": "**Frequency and regularity interact.** Low-frequency exception words are slowed much more than low-frequency regular words, whereas high-frequency words show a much smaller regularity difference. Naming latency is the time needed to begin saying the word. Higher values mean slower responses.", "children": ["An interaction means the effect of one factor depends on the other. The regularity cost is not a fixed amount added equally to high- and low-frequency words."]}, {"text": "**Experience matters especially when pronunciation conflicts with the usual spelling pattern.** Frequent exposure reduces the disadvantage of exception words.", "children": ["The lines are close at high frequency and separate at low frequency. Exception words rise to roughly 580 ms, while regular words rise only to roughly 555 ms in this figure."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 17}, "m3-reading1-p018": {"status": "ready", "blocks": [{"text": "**A dual-route interpretation separates lexical retrieval from sublexical decoding.** The lexical process supplies the learned pronunciation of a particular word, while decoding computes pronunciation from spelling units. For a high-frequency word, lexical information becomes available quickly enough to reduce the influence of the decoding output.", "children": ["For a low-frequency exception, the lexical response is less efficient and the regularized decoding output can interfere. Nonwords depend on decoding because they lack a stored whole-word entry."]}, {"text": "**Two routes can explain why regularity matters most for unfamiliar words.** Fast lexical processing protects familiar exceptions from competing sublexical output.", "children": ["This is an interpretation of the interaction, not the interaction itself. Other architectures must be evaluated against the same observed pattern."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 18}, "m3-reading1-p019": {"status": "ready", "blocks": [{"text": "**Acquired phonological dyslexia involves disproportionate difficulty reading pseudowords after brain injury.** Familiar words can remain relatively well read even when novel forms are difficult. Cacciopo van Vliet and colleagues compare real-word reading with several nonword tasks. The patients can often recognize and pronounce known words while struggling to generate a plausible pronunciation for an unfamiliar spelling.", "children": ["The selective difficulty suggests that familiar-word success and novel-form decoding do not rely on every process to the same degree."]}, {"text": "**Preserved word reading does not guarantee preserved decoding.** A patient can draw on learned word information while performing poorly on novel letter sequences.", "children": ["The real-word table contains many high accuracy values, while several nonword lists have much lower scores. The deficit is relative, not a claim that every nonword response is wrong."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 19}, "m3-reading1-p020": {"status": "ready", "blocks": [{"text": "**Acquired surface dyslexia involves disproportionate difficulty reading irregular words after brain injury.** Errors often regularize the word by applying a more common spelling–sound pattern. DEAF pronounced like “deef” and SHOE pronounced like “show” illustrate regularization. The response is related to the spelling, but it is not the target word's learned pronunciation.", "children": ["Relatively good regular-word and nonword reading shows that generating pronunciation from spelling can remain useful despite difficulty with exceptions."]}, {"text": "**Surface dyslexia exposes the cost of relying on typical correspondences when a word is exceptional.** The errors are systematic rather than arbitrary failures to see the letters.", "children": ["HFR and LFR refer to high- and low-frequency regular words. HFE and LFE refer to exceptions. The highlighted exception columns are lower, especially for low-frequency exceptions."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 20}, "m3-reading1-p021": {"status": "ready", "blocks": [{"text": "**A double dissociation compares opposite relative impairments.** Phonological dyslexia particularly affects pseudowords, while surface dyslexia particularly affects exception words. The first pattern shows that unfamiliar decoding can be difficult despite relatively preserved familiar-word reading. The second shows that exception reading can be difficult despite relatively preserved pseudoword reading.", "children": ["Together, the patterns are harder to explain by saying that one task is simply harder for everyone."]}, {"text": "**Opposite patient patterns support separable contributions to reading.** They are stronger evidence than a single group doing worse on one difficult task.", "children": ["“Relatively spared” does not mean perfect. The inference concerns the difference between task profiles, not an absence of every error in the better-performing condition."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 21}, "m3-reading1-p022": {"status": "ready", "blocks": [{"text": "**A double dissociation challenges a single fixed difficulty ranking.** If task A were merely harder than task B, damage might consistently hurt A more, but it would not readily explain another patient showing the reverse pattern. The reversal suggests that the tasks depend differently on underlying processes. For reading, pseudowords and exception words place different demands on the system.", "children": ["The evidence still requires a theory of what those underlying processes are. It does not uniquely identify a particular set of boxes in a model."]}, {"text": "**The strength of a double dissociation comes from the reversal across cases.** The interpretation must explain both directions of impairment.", "children": ["Compare the relative task costs within each patient or group, then compare those profiles. Two low scores without an opposite pattern are not a double dissociation."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 22}, "m3-reading1-p023": {"status": "ready", "blocks": [{"text": "**A dual-route model attributes phonological dyslexia to damage in grapheme–phoneme conversion and surface dyslexia to damage in lexical processing.** These proposed locations connect the task dissociation to specific mechanisms. Damage to conversion particularly affects nonwords because there is no familiar whole-word pronunciation to retrieve.", "children": ["Damage to input or output word representations, called logogens in this account, or their connections makes exceptions vulnerable because general decoding supplies the wrong pronunciation."]}, {"text": "**The model turns an observed dissociation into a claim about damaged processing components.** Each proposed lesion must produce the corresponding pattern of spared and impaired performance.", "children": ["The lexical and conversion paths are theoretical components. Their labels should not be confused with a direct anatomical map of two single brain regions."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 23}, "m3-reading1-p024": {"status": "ready", "blocks": [{"text": "**Patterson's discussion shows why reading errors can complicate a clean lexical–nonlexical division.** Errors attributed to a purely nonlexical route can still show lexical influences. The example “incense” read as “increase” is a real-word response. A simple letter–sound mistake could instead produce a nonword, so the actual response raises a question about whole-word influence.", "children": ["Possible responses are to allow a more complicated combination of routes or to revise the supposedly nonlexical process itself. The observation motivates refinement rather than settling the issue alone."]}, {"text": "**A patient's error type matters as well as overall accuracy.** Lexical-looking errors challenge the idea that the remaining reading process is wholly independent of word knowledge.", "children": ["The highlighted passage presents two alternatives for interpreting lexical influence in surface dyslexia. It does not simply declare that the patient evidence is irrelevant."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 24}, "m3-reading2-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 1}, "m3-reading2-p002": {"status": "ready", "blocks": [{"text": "**Dual-route models distinguish a lexical route from a sublexical route.** Lexical processing uses knowledge of particular words, while grapheme–phoneme conversion generates pronunciation from spelling units. A model must explain fast pseudoword reading, faster familiar-word reading, frequency effects, regularity effects and their interaction.", "children": ["It must also explain why pseudoword and exception-word reading can be differently impaired after brain injury. These observations motivate the architecture but do not uniquely prove it."]}, {"text": "**The two-route proposal connects several reading findings to a common processing account.** Its success depends on explaining the full pattern, not only nonword reading.", "children": ["A grapheme is a written unit associated with a sound. The route labels specify kinds of information used during reading."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 2}, "m3-reading2-p003": {"status": "ready", "blocks": [{"text": "**The Dual Route Cascaded model, or DRC, combines interactive lexical processing with a separate grapheme–phoneme rule system.** The two routes can contribute activation toward a spoken response. The lexical portion includes orthographic and phonological lexicons, representing written and spoken word forms. These representations are distinguished from meanings.", "children": ["The implementation described here does not implement semantics. The GPC rule system also has processing assumptions different from those of the interactive lexical network."]}, {"text": "**The DRC does not treat every connection as the same kind of computation.** Word-form activation and rule-based conversion are separate mechanisms.", "children": ["The circled part of the diagram corresponds to interactive activation. The separate GPC path joins the output system rather than becoming another interactive lexical layer."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 3}, "m3-reading2-p004": {"status": "ready", "blocks": [{"text": "**The DRC's grapheme–phoneme conversion rules operate serially, letter by letter.** Their operation is not adjusted by word frequency and receives no lexical feedback. The GPC and lexical routes do not interact throughout their internal computations. They converge in the phoneme response buffer.", "children": ["If the routes favor different phonemes, they can compete at that shared output. An exception word can therefore receive a correct lexical pronunciation and an incompatible regularized pronunciation."]}, {"text": "**Encapsulation does not mean that the routes never affect the same response.** They remain separate internally but meet at the phoneme output.", "children": ["Follow the route to the response buffer. Shared output units explain how competing pronunciations can influence naming even without feedback into the GPC rules."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 4}, "m3-reading2-p005": {"status": "ready", "blocks": [{"text": "**GPC rules map written units onto phonemes.** Some rules concern individual letters, while others concern several letters or a particular letter context. A model also needs a way to decide which applicable rule takes priority. A larger-unit rule can supersede rules for its individual letters.", "children": ["Context-sensitive rules restrict a pronunciation to specified surrounding letters or positions. This makes the procedure more than a simple lookup of one sound per letter."]}, {"text": "**A rule list is incomplete without a procedure for resolving overlapping rules.** Both the mapping and its conditions of application matter.", "children": ["The table distinguishes multiletter rules from context-sensitive rules. Position labels specify whether a mapping applies at the beginning, middle, end or all positions."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 5}, "m3-reading2-p006": {"status": "ready", "blocks": [{"text": "**A categorical rule does not express the strength of the evidence behind it.** The DRC can choose a mapping because it is frequent, yet treat that mapping as a fixed rule during processing. The possible pronunciations of OUGH have more divided statistical support than those of EIGH. A rule can still operate categorically for both spellings.", "children": ["A probabilistic account instead allows alternatives to receive different strengths of support. The distinction concerns processing, not whether the model designer ever consulted frequency information."]}, {"text": "**Using statistics to select a rule differs from representing graded statistics while reading.** The two approaches can make different predictions for ambiguous spellings.", "children": ["The table distributes pronunciation frequencies across alternatives. A spread across many rows indicates greater uncertainty than a distribution concentrated on one pronunciation."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 6}, "m3-reading2-p007": {"status": "ready", "blocks": [{"text": "**The DRC's simple rules are intended to explain systematic human errors as well as correct reading.** More finely tuned rules might pronounce more exceptions correctly but remove behavior the model is meant to explain. A regularizing route helps account for errors in surface dyslexia and for slow naming of low-frequency exception words.", "children": ["The theory therefore claims that people's sublexical computation is constrained, rather than assuming that the best possible spelling algorithm is the correct cognitive model."]}, {"text": "**A cognitively useful model should reproduce the relevant failures.** Maximizing pronunciation accuracy is not the only goal.", "children": ["The crucial test is whether the same processing assumptions produce the observed pattern of success, interference and regularization, rather than an isolated incorrect response."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 7}, "m3-reading2-p008": {"status": "ready", "blocks": [{"text": "**Informational encapsulation means that a process does not freely use every source of relevant knowledge.** In the dual-route account, GPC conversion proceeds without consulting whole-word meaning or lexical feedback. This resembles a modular parsing proposal in which an early syntactic process follows structural principles without immediately using world knowledge.", "children": ["Pseudoword naming exposes the conversion procedure because a familiar lexical entry is unavailable. Regularization errors expose it when conversion favors the wrong pronunciation."]}, {"text": "**A modular account predicts restricted access to information.** The GPC route may produce an inappropriate response even when another part of the system has word-specific knowledge.", "children": ["The comparison with parsing concerns processing restrictions. It does not mean that syntactic parsing and letter–sound conversion use the same representations."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 8}, "m3-reading2-p009": {"status": "ready", "blocks": [{"text": "**The DRC is evaluated against many reading phenomena.** These include frequency, lexicality, regularity, interactions, lexical decision and patterns in acquired dyslexia. Accounting for several effects with one architecture is stronger than fitting a single result. It also requires examining which assumptions stay fixed and which are changed between tasks.", "children": ["The model's research strategy places strong weight on human behavioral evidence as a constraint on architecture."]}, {"text": "**A broad list of successful simulations is informative, but the conditions of each success also matter.** Model evaluation includes both coverage and the assumptions used to obtain it.", "children": ["The listed effects span reading aloud, lexical decision and patient performance. These are related but distinct tasks, so a task-specific adjustment must be identified as such."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 9}, "m3-reading2-p010": {"status": "ready", "blocks": [{"text": "**Lexical decision requires deciding whether a written item is a word.** The DRC simulation adds decision criteria to the activation produced by its recognition system. A “yes” response can depend on a strongly activated single word or on total activity across the orthographic lexicon. A “no” response occurs if the criteria are not met by a deadline.", "children": ["The implementation also changes inhibition and uses time-dependent thresholds. These choices help obtain a fit, but they add assumptions beyond the basic two-route diagram."]}, {"text": "**Fitting lexical decision requires an account of the decision itself.** Recognition activity does not automatically specify when to say yes or no.", "children": ["The thresholds and cycle deadlines implement response rules. Their conceptual role is more important here than memorizing each numerical cutoff."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 10}, "m3-reading2-p011": {"status": "ready", "blocks": [{"text": "**The DRC routes are modular in several related senses.** They use different processing assumptions, restrict information exchange and accept particular kinds of input. The GPC system takes letters as input and sends phoneme activation toward the response system. This is **domain specificity** in the account.", "children": ["The absence of lexical feedback into the GPC system is **informational encapsulation**. Having two pathways alone would not establish those stronger restrictions."]}, {"text": "**Modularity is a claim about how components operate and communicate.** It is more specific than drawing two arrows in a model.", "children": ["Distinguish the restrictions on inputs, the rules of computation and the restrictions on communication. These are separate properties of the proposed architecture."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 11}, "m3-reading2-p012": {"status": "ready", "blocks": [{"text": "**PDP models treat reading as learned mappings among orthography, phonology and semantics.** Orthography is spelling, phonology is sound structure, and semantics is meaning. Seidenberg and McClelland trained an associative network to map spelling onto pronunciation. The modeled spelling-to-sound pathway used one learned mapping for different kinds of words.", "children": ["Reading skill emerges from learning rather than being specified entirely as a hand-built list of rules and lexical entries."]}, {"text": "**An emergentist account asks how experience creates useful reading behavior.** Regularity can arise from learning across words rather than from a separate rule mechanism.", "children": ["The triangle's labels identify representational domains. A connection between domains represents a learned mapping, not an additional stored dictionary for every item."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 12}, "m3-reading2-p013": {"status": "ready", "blocks": [{"text": "**In a PDP account, rules are generalizations learned across words.** Whole-word knowledge is distributed across learned mappings instead of being stored only in a distinct lexical route. The same learning mechanism can capture both patterns shared by many words and information specific to a familiar word.", "children": ["The research strategy asks whether domain-general learning can explain reading. This contrasts with choosing separate adult processing components primarily from neuropsychological dissociations."]}, {"text": "**Word-specific knowledge and generalization can coexist in the same learned system.** They do not have to be implemented as a dictionary and a separate symbolic rule list.", "children": ["“Distributed” refers to how knowledge is represented across the network. It does not mean that the model has no memory of individual words."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 13}, "m3-reading2-p014": {"status": "ready", "blocks": [{"text": "**A learned network can produce a frequency-by-regularity interaction without separate frequency and rule mechanisms.** Regular words receive support from patterns shared across many words. An exception conflicts with those patterns, so learning its particular mapping is especially important. Frequent exposure strengthens that word-specific mapping.", "children": ["A low-frequency exception has both weak item-specific learning and poor support from the dominant pattern. This combination creates a larger disadvantage than either factor alone."]}, {"text": "**Consistency supplies support from other words, while frequency strengthens experience with the particular word.** Their joint influence explains why infrequent exceptions are especially difficult.", "children": ["The interaction is shared evidence that both architectures must explain. Producing it does not by itself establish whether the implementation contains symbolic rules."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 14}, "m3-reading2-p015": {"status": "ready", "blocks": [{"text": "**Consistency describes how many similar spellings support a pronunciation.** “Friends” have the relevant spelling pattern and a compatible pronunciation, while “enemies” support a competing pronunciation. LATE and DUST illustrate consistent patterns. GAVE and MINT have many friends but also enemies such as HAVE and PINT.", "children": ["DOWN versus KNOWN and POUR versus SOUR illustrate ambiguity. An exception such as PINT has relatively little support compared with its competing neighborhood."]}, {"text": "**Spelling–sound support varies in degree.** A statistical description captures differences that a simple regular-versus-irregular label can hide.", "children": ["Friend and enemy are labels for pronunciation relations among similar spellings. They do not refer to semantic relationships between the words."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 15}, "m3-reading2-p016": {"status": "ready", "blocks": [{"text": "**A PDP model can pronounce nonwords using the weights learned from real words.** A new spelling activates patterns that overlap with familiar spellings, allowing the network to generalize. No stored entry for the particular nonword is required. The same learned correspondences that support consistent words can support a new combination.", "children": ["This is a proposed mechanism for decoding without a separate GPC rule module."]}, {"text": "**Novel pronunciation can result from applying learned statistical structure.** Nonword reading therefore does not automatically establish a separate symbolic route.", "children": ["The relevant comparison is whether one learned mapping can handle both familiar words and new items. The claim must still be checked against the model's actual performance."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 16}, "m3-reading2-p017": {"status": "ready", "blocks": [{"text": "**Poor nonword performance can challenge either a theoretical proposal or a particular implementation.** The early model's nonword accuracy was weaker than desired. One possibility is that a single associative mechanism cannot explain the task. Another is that the chosen representations fail to capture the similarities needed for generalization.", "children": ["Improving the implementation while retaining the theoretical mechanism helps distinguish these possibilities."]}, {"text": "**A failed simulation does not identify its own cause.** The failure must be traced to the architecture, learning assumptions, representations or other implementation choices.", "children": ["The important question is what changes when the model is repaired. A representational improvement is a different theoretical move from adding a separate nonword route."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 17}, "m3-reading2-p018": {"status": "ready", "blocks": [{"text": "**Generalization depends on how sound similarity is represented.** The early Seidenberg–McClelland model used Wickelfeatures, whose representation of phonology was problematic for nonword reading. Plaut and colleagues improved the phonological representations and obtained better nonword performance. This supports a representational explanation for at least part of the earlier failure.", "children": ["Behavioral relations between phonological processing and decoding also make phonology a relevant target for explanation."]}, {"text": "**Changing the representation can improve decoding without adding a symbolic rule system.** That distinction matters when evaluating the original theoretical claim.", "children": ["The comparison concerns models with different representations. Better performance after that change is evidence about implementation, not proof that every associative model will succeed."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 18}, "m3-reading2-p019": {"status": "ready", "blocks": [{"text": "**A network generalizes through similarity.** If its phonological representation poorly captures similarities among words, the learned mapping cannot transfer as effectively to new forms. A familiar word can retain support from its own training history. A nonword lacks that item-specific experience and depends more heavily on generalization.", "children": ["This produces a reason for unfamiliar forms to be especially vulnerable to poor representations without requiring a dedicated nonword mechanism."]}, {"text": "**The same representational weakness can have unequal effects on words and nonwords.** Familiarity can partly compensate where new-item generalization cannot.", "children": ["Distinguish a weaker shared representation from damage to a separate route. Both can create a task difference, but they locate the explanation differently."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 19}, "m3-reading2-p020": {"status": "ready", "blocks": [{"text": "**Harm and Seidenberg manipulated noise in phonological representations.** Increasing noise makes the sound representations less reliable while keeping the model's general learning framework. The manipulation produced poorer nonword decoding and relative sparing of word recognition. It also linked the severity of the phonological deficit to the degree of decoding difficulty.", "children": ["The model therefore connects a reading pattern to the quality of a more general phonological system."]}, {"text": "**A selective-looking reading deficit can emerge from degraded shared representations.** Nonwords are especially dependent on reliable generalization.", "children": ["Noise is the manipulated model property. Word and nonword performance are outcomes, so the simulation tests a directional mechanistic proposal rather than merely observing a correlation."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 20}, "m3-reading2-p021": {"status": "ready", "blocks": [{"text": "**Damaging semantic support in a triangle model can impair exception-word reading especially strongly.** Plaut and colleagues added a simplified semantic contribution and examined what happened when it was lesioned. An exception has weak support from typical spelling–sound regularities. Meaning-related support can help produce its learned pronunciation.", "children": ["Reducing that support creates a surface-dyslexia-like pattern without defining a separate exception-word list as the sole explanation."]}, {"text": "**The model links exception reading to semantic processing.** A reading dissociation can reflect unequal dependence on broader language systems.", "children": ["“Lesion” here means a controlled change to the computational model. It is distinct from directly observing where a particular patient's brain injury occurred."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 21}, "m3-reading2-p022": {"status": "ready", "blocks": [{"text": "**The triangle model's pathways share graded learning assumptions and interact during learning.** Semantic representations are directly involved rather than replaced by a lexicon defined as independent of meaning. Spelling-to-sound learning develops in the presence of meaning-related support. The contribution of one pathway therefore affects what another pathway learns.", "children": ["This allows graded impairments. Phonological dyslexics can make some exception errors, and surface dyslexics can make some nonword errors."]}, {"text": "**Multiple pathways do not necessarily imply modular routes.** Their learning rules, information types and interactions distinguish the accounts.", "children": ["O denotes orthography, P phonology and S semantics. O-to-P and S-to-P mappings use the same general probabilistic assumptions, unlike DRC's distinct GPC and lexical procedures."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 22}, "m3-reading2-p023": {"status": "ready", "blocks": [{"text": "**Woollams and colleagues tested the predicted association between semantic ability and exception-word reading.** Lower semantic scores were associated with poorer low-frequency exception reading in patients with semantic dementia. The model and patient panels show comparable overall relationships, although individual patients vary. This supports an association between meaning and exceptional pronunciation.", "children": ["The finding is informative because it links a reading weakness to a broader semantic measure rather than describing only a reading-task dissociation."]}, {"text": "**The triangle account predicts that exception reading should vary with semantic ability.** The patient data broadly follow that relationship.", "children": ["The semantic score decreases from left to right on the patient plot. The downward slope therefore means that poorer semantics goes with poorer reading, not that better semantics harms reading."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 23}, "m3-reading2-p024": {"status": "ready", "blocks": [{"text": "**Some patients have relatively good exception reading despite low semantic scores.** These cases challenge a perfect one-to-one relationship, but an account of graded association does not predict zero variability. Woollams and colleagues interpret such observations in relation to the full distribution rather than treating each outlier as an automatic refutation.", "children": ["The scientific issue is whether the unusual cases show a stable separate pattern or arise within a noisy overall association."]}, {"text": "**An outlier and a clean dissociation are not automatically the same thing.** The strength and reliability of the apparent exception matter.", "children": ["Points above the horizontal reference line and left of the specified vertical boundary are singled out as unusual. Evaluate their location relative to the broader patient cloud and repeated measurements."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 24}, "m3-reading2-p025": {"status": "ready", "blocks": [{"text": "**Longitudinal observations track whether semantic and reading abilities change together within a patient.** Because semantic dementia progresses, repeated testing can reveal a trajectory rather than a single unusual score. In most cases, declining semantic ability accompanies declining exception-word reading. Some initially unusual observations move closer to the broader relation on retesting.", "children": ["This strengthens the association while leaving room for variability between individuals."]}, {"text": "**Repeated observations help test whether an apparent dissociation persists.** A one-time exceptional score is less compelling if the patient's later trajectory follows the general relation.", "children": ["Lines connect observations from the same person. Movement toward lower semantic scores and lower reading accuracy shows coupled decline rather than a comparison of unrelated people only."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 25}, "m3-reading2-p026": {"status": "ready", "blocks": [{"text": "**Coltheart and colleagues generated 40,000 model patients with different lexical-route and GPC impairment levels.** For each real patient, they selected the model run that best matched the observed data. This produced an excellent fit to the patient scores. The selection procedure is part of how that fit was achieved.", "children": ["The fit should be distinguished from predicting each patient's pattern before choosing among many possible parameter combinations."]}, {"text": "**A flexible model can closely reproduce observed data.** Evaluating the explanation also requires asking how the matching simulation was selected.", "children": ["The plotted patient and model lines lie close together. That visual agreement describes goodness of fit, while the large search over simulated patients describes flexibility."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 26}, "m3-reading2-p027": {"status": "ready", "blocks": [{"text": "**A better fit can be less informative if it relies on much greater flexibility.** Selecting the best match from many parameter combinations can reproduce a dataset without strongly constraining the underlying explanation. The question is not whether close agreement is bad in itself. It is whether the account predicts the relation with principled assumptions or accommodates each case after seeing the outcome.", "children": ["Comparing theories therefore requires attention to both fit and how much freedom produced it."]}, {"text": "**Goodness of fit is only one part of model evaluation.** A model should explain why the pattern occurs, not only contain a setting that resembles it.", "children": ["The contrast is between constrained prediction and flexible post hoc matching. It does not justify rejecting a model merely because its numerical fit is strong."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 27}, "m3-reading2-p028": {"status": "ready", "blocks": [{"text": "**Dual-route and triangle models address many of the same findings.** Both must explain rapid nonword decoding, exception difficulty, the frequency–regularity interaction and acquired reading dissociations. Agreement on the phenomena does not mean agreement on mechanisms. One account emphasizes specialized routes, while the other emphasizes learning across interacting representational systems.", "children": []}, {"text": "**The models compete over explanation, not over whether these basic reading patterns exist.** Shared behavioral success makes their differing assumptions especially important.", "children": ["A useful comparison holds the phenomenon constant and asks what each model changes or computes to produce it."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 28}, "m3-reading2-p029": {"status": "ready", "blocks": [{"text": "**DRC attributes nonword decoding and regularity effects to GPC rules, while the triangle account attributes them to statistical learning.** Word-specific exposure strengthens learned mappings in the triangle account and affects lexical processing in DRC. For phonological dyslexia, DRC emphasizes GPC damage and the triangle account emphasizes broader phonological impairment.", "children": ["For surface dyslexia, DRC emphasizes lexical-route damage and the triangle account emphasizes semantic impairment."]}, {"text": "**The same task pattern receives a different mechanistic explanation in each model.** Keep the observed phenomenon separate from the proposed locus of impairment.", "children": ["Read each table row across the two model columns. The row identifies the finding, while the columns specify competing explanations rather than two names for identical components."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 29}, "m3-reading2-p030": {"status": "ready", "blocks": [{"text": "**A major contrast is whether the explanation begins with separate reading routes or broader language associations.** Dual-route models use different task impairments to motivate independent processes. The statistical-learning account links phonology to spelling–sound generalization and semantics to words whose pronunciation is poorly supported by that generalization.", "children": ["Both dissociations and associations matter. A theory should explain selective weaknesses and the related abilities that vary with them."]}, {"text": "**Phonological and semantic measures can help identify what lies behind a reading dissociation.** They extend the evidence beyond the reading scores alone.", "children": ["The table's dyslexia rows contrast GPC versus phonological damage and lexical-route versus semantic damage. These are the key theoretical alternatives, not just different diagnostic labels."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 30}, "m3-reading2-p031": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 31}, "m3-morphology-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 1}, "m3-morphology-p002": {"status": "ready", "blocks": [{"text": "**Morphology is generative because speakers can form words they have not memorized individually.** Derivational morphology creates a new lexical form, while inflection marks grammatical information such as plural or past tense. The central question is how a speaker extends a familiar pattern to a new item. English plural and past-tense formation provide tractable examples.", "children": ["Generalization can also produce playful or incorrect forms. This shows productive use of patterns, rather than a vocabulary containing only previously heard responses."]}, {"text": "**Productive word formation goes beyond retrieving a stored list.** The theoretical issue is whether that productivity requires symbolic rules or can emerge from learning.", "children": ["The playful “crew” and “crode” examples extend irregular-sounding patterns to CRY. They demonstrate creative generalization, not correct standard English past-tense forms."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 2}, "m3-morphology-p003": {"status": "ready", "blocks": [{"text": "**Berko Gleason's wug test measures morphological generalization to a novel word.** A child learns a new label and then supplies an inflected form that has not been provided. The pictured task introduces one WUG and then asks about two. Producing WUGS applies plural knowledge to a new noun.", "children": ["The same logic can test past tense using novel verbs. Success shows productive knowledge, but does not by itself distinguish symbolic rules from statistical generalization."]}, {"text": "**A novel item prevents success from being explained as retrieval of that item's memorized inflection.** The child must extend a learned pattern.", "children": ["The drawing depicts plural formation, even though the accompanying discussion also mentions past tense. Keep the displayed plural task separate from the broader application of the method."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 3}, "m3-morphology-p004": {"status": "ready", "blocks": [{"text": "**Regular past tense follows the productive -ed pattern.** SHOW becomes SHOWED, BAKE becomes BAKED, and a novel verb such as BLICK can become BLICKED. Irregular pairs such as GO–WENT, TAKE–TOOK and EAT–ATE do not follow that default form. Some irregulars share smaller patterns with other verbs.", "children": ["A theory must explain both familiar exceptions and productive extension to novel verbs."]}, {"text": "**Past-tense knowledge includes generalization and item-specific variation.** The contrast creates a test for different theories of morphology.", "children": ["Compare regular real verbs with regularized nonwords, then with learned irregular pairs. The nonwords test extension, while the irregulars test successful handling of exceptions."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 4}, "m3-morphology-p005": {"status": "ready", "blocks": [{"text": "**The Words and Rules account gives regular and irregular inflection different mechanisms.** A symbolic rule generates a regular past tense, while irregular forms are stored in an associative lexical system. The regular process can apply to a new verb because it does not require an entry for that particular past tense.", "children": ["The irregular system stores word-specific information and can be influenced by frequency and similarity. A successful explanation also needs to prevent an available irregular form from being replaced by a regularization."]}, {"text": "**In this account, productive rule application and remembered exceptions are separate kinds of knowledge.** That is stronger than simply observing that regular and irregular forms look different.", "children": ["“Add -ed” summarizes the symbolic operation. The associative system is not proposed as another copy of the same rule."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 5}, "m3-morphology-p006": {"status": "ready", "blocks": [{"text": "**The lexicon and grammar offer different ways to produce a past tense.** Lexical retrieval supplies an irregular form such as HELD, while grammatical combination can produce WALK plus -ed. Pinker and Ullman's diagram associates lexical lookup with declarative memory and grammatical combination with procedural processing.", "children": ["Like dual-route reading, the account separates word-specific knowledge from a productive operation. Unlike reading aloud, its task is to transform a stem according to a grammatical feature, rather than convert spelling into sound."]}, {"text": "**Similar-looking architectures can solve different computational problems.** Keep morphological inflection separate from grapheme–phoneme conversion.", "children": ["The input includes a stem and a past-tense feature. The diagram distinguishes lexical association from combination, and its blocking connection prevents a retrieved irregular from competing unchecked with a regular form."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 6}, "m3-morphology-p007": {"status": "ready", "blocks": [{"text": "**The Words and Rules proposal was motivated partly by a theory of grammar.** A categorical symbolic grammar describes productive patterns, but language also contains exceptions. Reading dual-route theories were strongly motivated by neuropsychological dissociations. The morphology proposal also reflects a commitment to keeping the grammatical rule system distinct from exceptional lexical information.", "children": []}, {"text": "**The motivation for an architecture matters when evaluating its evidence.** Similar diagrams do not mean that the theories were derived from the same observations.", "children": ["The contrast is between a dissociation-driven reading account and a grammatical argument for separating productive rules from exceptions."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 7}, "m3-morphology-p008": {"status": "ready", "blocks": [{"text": "**An associative lexicon handles information that does not fit a categorical rule.** Its representations are word-specific and sensitive to frequency and phonological similarity. KEEP–KEPT, WEEP–WEPT and LEAP–LEAPT illustrate similarity among irregular forms. An exception can belong to a small family rather than being wholly unrelated to other words.", "children": ["Assigning these properties to lexical memory lets the rule system remain categorical and general."]}, {"text": "**Separating exceptions protects a simple rule, but creates a second mechanism that must also be explained.** The associative system carries graded and item-specific influences.", "children": ["The shared sound pattern in the listed verbs motivates associative similarity. It is not evidence that every irregular verb uses exactly the same transformation."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 8}, "m3-morphology-p009": {"status": "ready", "blocks": [{"text": "**Rumelhart and McClelland modeled past tense as a learned association between present and past sound patterns.** A single trainable network learns across verbs instead of applying a separately specified -ed rule. The model encodes a root's phonology, transforms that representation through modifiable connections, and decodes an output pattern.", "children": ["Regularity is a pattern learned from many examples. Irregular forms are also learned within the same system."]}, {"text": "**One learning mechanism is proposed for both regularities and exceptions.** The challenge is to explain accurate generalization as well as familiar forms.", "children": ["The fixed encoding and decoding stages surround a modifiable pattern associator. Wickelfeatures represent sound patterns, while the trainable connections store the learned mapping."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 9}, "m3-morphology-p010": {"status": "ready", "blocks": [{"text": "**U-shaped learning describes an initial success, a decline, and later recovery.** A child may correctly say RAN, later produce RUNNED, and eventually return to RAN. The middle error is a **regularization**, because the child applies the common past-tense pattern to an irregular verb.", "children": ["The decline does not necessarily mean that the child has stopped learning. A changing system can generalize more broadly while temporarily disrupting an earlier correct response."]}, {"text": "**Development can involve temporary errors as knowledge changes.** A theory must explain the entire trajectory, not just the final adult response.", "children": ["The vertical dimension is successful performance and the horizontal dimension is development or training. A U shape concerns accuracy over time, not the shape of a word."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 10}, "m3-morphology-p011": {"status": "ready", "blocks": [{"text": "**The Words and Rules account explains U-shaped learning through changes in the use of rules and lexical exceptions.** Early correct forms can be imitated before a productive rule is available. When the rule is learned, it can be applied too broadly, yielding RUNNED. Later, learned irregulars and the blocking process prevent that regularization.", "children": ["This account treats the developmental stages as involving distinguishable processes rather than only gradual changes in one mapping."]}, {"text": "**Overregularization is interpreted as productive rule use that is not yet sufficiently constrained by exceptions.** Recovery depends on the irregular form winning over the rule output.", "children": ["Blocking means that retrieval of the appropriate irregular prevents the otherwise available regular form. It is a proposed mechanism, not merely another name for correct performance."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 11}, "m3-morphology-p012": {"status": "ready", "blocks": [{"text": "**Changing the training vocabulary can produce U-shaped learning in one network.** Early training emphasizes frequent irregular verbs, allowing those particular mappings to be learned. As more regular verbs enter training, their common pattern changes the network's responses. That generalization can interfere with previously learned irregulars.", "children": ["With further learning, the network can recover the irregular responses while retaining broad regularity. No new symbolic rule component is inserted at the point of decline."]}, {"text": "**A shift in the distribution of experience can temporarily disrupt familiar responses.** The learning account explains the developmental pattern through changing weights and input.", "children": ["The lower plot contrasts correct irregular responses with regularized alternatives. Their changing strengths illustrate competition during training, rather than the sudden appearance of a separate rule box."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 12}, "m3-morphology-p013": {"status": "ready", "blocks": [{"text": "**Testing untrained verbs asks whether the network learned transferable structure.** A real English verb can be novel to a model if it was excluded from that model's training set. The test therefore uses the logic of a wug task even when the items are real words to humans.", "children": ["The model can generate many appropriate past-tense features, but feature-level success must be distinguished from producing an entirely correct word."]}, {"text": "**Generalization is defined relative to the learner's experience.** A familiar human word is still a valid novel-model test when it was withheld from training.", "children": ["The summary reports proportions of Wickelfeatures generated correctly. A high proportion of correct features does not imply that the same proportion of whole words was pronounced perfectly."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 13}, "m3-morphology-p014": {"status": "ready", "blocks": [{"text": "**Some model outputs contain changes that are unlike ordinary human regularizations.** Examples include MADE(D)-like changes to MATE and the unusual outputs MEMBLED for MAIL and TOUREDER for TOUR. The model authors acknowledge that people are unlikely to make some of these errors. They suggest that additional output constraints could reduce bizarre responses.", "children": ["This separates capturing an overall learning pattern from matching the detailed form of human errors."]}, {"text": "**A plausible learning curve is not enough if the model produces implausible words.** Error structure provides another test of the representation and decoding process.", "children": ["The quotation discusses outputs near threshold and a possible cleanup mechanism. That proposed mechanism is an explanation to be tested, not a repair already demonstrated by the quoted result."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 14}, "m3-morphology-p015": {"status": "ready", "blocks": [{"text": "**Prince and Pinker argued that feature representations can blend distinct alternatives.** A model may activate features belonging to several possible past-tense forms without keeping those candidates separate. For SING, partial support for different sound patterns can overlap. Decoding the combined activation can produce a hybrid rather than selecting a coherent word.", "children": ["The criticism targets the representation and its treatment of competing outputs, not merely the presence of learning."]}, {"text": "**Combining evidence for alternatives is different from blending the alternatives into a new malformed output.** A model must preserve the distinctions needed to produce a coherent response.", "children": ["The highlighted MEMBLED example makes the criticism concrete. It is presented as an unwanted hybrid, not as a normal past tense that children commonly produce."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 15}, "m3-morphology-p016": {"status": "ready", "blocks": [{"text": "**Joanisse and Seidenberg propose that phonology supports rule-like generalization while semantics especially supports irregular forms.** The same system links speech input, meaning and speech output. Reliable sound representations support extension from familiar present–past pairs to new forms. Irregular mappings receive additional support from the particular word's semantic representation.", "children": ["The hypothesis concerns different degrees of dependence on shared systems, rather than a separate symbolic rule route for every regular response."]}, {"text": "**The regular–irregular contrast can arise from how phonological and semantic information contribute.** A graded system can produce systematic differences between item types.", "children": ["The diagram connects speech input and semantics through learned mappings to speech output. Its components represent domains of information, not a list of regular and irregular words in separate boxes."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 16}, "m3-morphology-p017": {"status": "ready", "blocks": [{"text": "**The model aims to explain the dissociation between irregular and nonword past-tense performance.** These tasks differ in how much they depend on learned word-specific information and phonological generalization. A nonword has no familiar item-specific semantic history to support its inflection. A known irregular can require semantic support because its output is not well predicted by the dominant pattern.", "children": ["Manipulating phonological or semantic integrity tests whether these different dependencies can produce opposite impairment profiles."]}, {"text": "**The same architecture should explain both sides of the patient pattern.** Selectivity must arise from the manipulated representations and their contribution to the task.", "children": ["The target is a pattern of performance across item types. Drawing phonology and semantics in a diagram is not enough unless damaging them produces the relevant outcomes."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 17}, "m3-morphology-p018": {"status": "ready", "blocks": [{"text": "**The patient pattern associated here with Broca's aphasia includes especially poor nonword past-tense production.** These patients have left anterior injury and difficulty producing speech. Regular forms are also vulnerable, while irregular forms are relatively better in the displayed comparison. A novel BLICK must be transformed without relying on a familiar stored past tense.", "children": ["This motivates investigating phonological contributions to the apparent morphological deficit."]}, {"text": "**Difficulty with productive inflection may be connected to sound processing.** The nonword condition is particularly demanding because it relies on generalization.", "children": ["The graph places nonword accuracy below regular and irregular accuracy. The irregular advantage over regulars is smaller than the nonword disadvantage, so these differences should not be treated as equally large."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 18}, "m3-morphology-p019": {"status": "ready", "blocks": [{"text": "**Phonological impairment reduces past-tense performance most strongly for nonwords in the model.** Regulars are numerically worse than irregulars, but the largest difference concerns novel forms. The model manipulation weakens sound-based computation. Familiar words retain support unavailable to an untrained nonword.", "children": ["The similarity to the patient pattern shows how a selective-looking morphological deficit can arise from a broader phonological impairment."]}, {"text": "**Damaging phonology can imitate a failure of productive morphology without removing a symbolic rule.** The mechanism being tested is the quality of sound representations.", "children": ["Model and patient bars are paired within regular, irregular and nonword conditions. Compare the profile across conditions rather than expecting exact equality of every bar."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 19}, "m3-morphology-p020": {"status": "ready", "blocks": [{"text": "**Other patient groups show a larger problem with irregular past-tense forms.** The material discusses Wernicke's and Alzheimer's patients and anomic patients with inferior or middle temporal injury. Their irregular performance is lower than their regular and nonword performance in the displayed comparison.", "children": ["This creates the other side of the dissociation and motivates examining the information that especially supports known irregular forms."]}, {"text": "**Relatively preserved nonword inflection can coexist with poor irregular inflection.** The theory must explain this reverse pattern as well as phonological impairment.", "children": ["The middle bar is the irregular condition, at roughly 60% correct, compared with higher regular and nonword scores. The diagnostic labels do not make every individual's performance identical."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 20}, "m3-morphology-p021": {"status": "ready", "blocks": [{"text": "**Semantic impairment particularly disrupts irregular past-tense forms.** When the model loses meaning-related support, irregular accuracy falls below regular and nonword accuracy. Typical phonological patterns still support many regular and novel forms. Nonwords can nevertheless be somewhat worse than regular words because they lack item-specific training.", "children": ["This shows how unequal dependence on semantics can produce the reverse of the phonological-damage profile."]}, {"text": "**Irregular vulnerability is predicted from its greater dependence on semantic support.** The model does not have to delete an isolated exception list to produce that pattern.", "children": ["The irregular bars are the lowest for both the model and the comparison patients. The figure compares profiles, not a claim that model lesions reproduce every aspect of Alzheimer's disease."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 21}, "m3-morphology-p022": {"status": "ready", "blocks": [{"text": "**Phonological controls can change the apparent regular–irregular difference.** Bird and colleagues found that the difference in Broca's patients was reduced when items were adequately matched for phonology. Patterson and colleagues found that irregular impairment in semantic dementia correlated with semantic deficit severity.", "children": ["These findings connect morphology to phonological and semantic abilities, making a pure rule-versus-word interpretation less straightforward."]}, {"text": "**A task dissociation should be checked for differences in the demands of its items.** Related abilities can explain why one condition is more vulnerable.", "children": ["Matching phonology addresses a potential confound in the regular–irregular comparison. Correlating semantic severity with irregular performance tests an association predicted by the alternative account."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 22}, "m3-morphology-p023": {"status": "ready", "blocks": [{"text": "**Phonological representations support learning the common mapping from present to past.** A degraded representation makes that generalization less reliable, especially for new words. Semantic information supports forms that depart from the dominant -ed pattern. Some irregulars also benefit from smaller phonological families and can be relatively spared.", "children": ["Regularity and exception status therefore describe degrees of statistical support rather than perfectly isolated kinds of processing."]}, {"text": "**Different forms draw on the same systems to different degrees.** General patterns and word-specific support can jointly determine an output.", "children": ["The comparison with triangle reading concerns the division of support between phonology and semantics. Spelling-to-sound reading and present-to-past inflection remain different tasks."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 23}, "m3-morphology-p024": {"status": "ready", "blocks": [{"text": "**Specific language impairment, or SLI in the course terminology, involves impaired language development despite relatively typical nonverbal performance.** Difficulties can include morphology and syntax. The profile can also involve phonology, reading, working memory and speech perception. This broader range matters when evaluating a theory that locates the problem only in grammar.", "children": ["A relative language difficulty does not by itself identify a single damaged learning mechanism."]}, {"text": "**The diagnostic description and the causal explanation are separate.** A grammatical difficulty can coexist with weaknesses in other processes that support language.", "children": ["The list extends beyond grammatical categories. Those additional domains are relevant evidence, not automatically irrelevant symptoms because the condition is called language impairment."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 24}, "m3-morphology-p025": {"status": "ready", "blocks": [{"text": "**A rule-deficit account predicts particular difficulty with regular and novel inflections.** If a domain-specific rule-learning mechanism is impaired, irregular forms stored lexically should be relatively less affected. This proposal uses past-tense performance to argue for a mechanism specific to grammatical rules.", "children": ["The prediction must be tested against the complete pattern, including irregular performance and broader phonological difficulties."]}, {"text": "**The crucial issue is whether the deficit is selective enough to support the proposed rule mechanism.** Merely finding poor past tense does not establish its cause.", "children": ["Regular real words, irregular real words and nonwords are separate conditions. A theory should state how each condition is expected to change."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 25}, "m3-morphology-p026": {"status": "ready", "blocks": [{"text": "**The van der Lely and Ullman comparison shows low past-tense accuracy across all three item types in the SLI group.** Same-age controls perform much better. Nonwords are especially difficult for the SLI group, but regulars and irregulars are also impaired. The results therefore contain a broad deficit as well as unequal condition difficulty.", "children": ["An explanation should account for the entire profile rather than reporting only that productive forms are poor."]}, {"text": "**The observed pattern is broader than a simple intact-irregulars versus damaged-rules contrast.** Novel forms are most vulnerable, while familiar forms are not unaffected.", "children": ["The SLI bars are approximately 20% for regulars, somewhat lower for irregulars and below 10% for nonwords. The controls' bars are much higher in all three categories."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 26}, "m3-morphology-p027": {"status": "ready", "blocks": [{"text": "**Weakening phonological processing produces impaired learning across forms, with nonwords especially vulnerable.** The severe and weaker impairment settings differ in the degree of difficulty. The intact model performs substantially better. Even intact learning shows different performance across regulars, irregulars and nonwords.", "children": ["The comparison tests whether a phonological learning weakness can reproduce important aspects of the behavioral profile without a missing grammatical rule."]}, {"text": "**A graded phonological manipulation creates graded developmental impairment.** Novel generalization is most fragile because it cannot rely on a word's own training history.", "children": ["Compare severe phonology, weaker phonology and intact settings. The bars report percent correct, and the intact model is shown at two training points, so training amount and impairment should not be conflated."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 27}, "m3-morphology-p028": {"status": "ready", "blocks": [{"text": "**Phonology contributes to every spoken past-tense response.** Weakening it can therefore reduce performance on regulars, irregulars and nonwords. Nonwords are particularly dependent on generalizing a sound pattern to a new form. Familiar words have additional item-specific learning that can partly support their responses.", "children": []}, {"text": "**An especially large nonword deficit does not imply that other forms avoid phonology.** It reflects different degrees of dependence on generalization.", "children": ["The pattern to explain is broad impairment with a disproportionate nonword cost. A theory that predicts only one affected category misses part of that pattern."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 28}, "m3-morphology-p029": {"status": "ready", "blocks": [{"text": "**The associative account learns mappings among phonology and semantics without a separate symbolic past-tense rule or an isolated exception lexicon.** Regular and irregular are useful descriptions of behavior, but only approximate descriptions of the system's internal organization. Irregular performance is associated with semantic processing. Wug-test performance is associated with phonological processing.", "children": ["These associations provide tests of the proposed underlying mechanisms, beyond simply assigning different item types to different boxes."]}, {"text": "**Past-tense behavior can be explained through learned structure and unequal support from shared representations.** The proposal must still explain developmental, patient and generalization data together.", "children": ["The contrast with Words and Rules concerns representation and computation, not whether the English language contains recognizable regular and irregular patterns."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 29}, "m3-morphology-p030": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 30}, "m3-thought-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 1}, "m3-thought-p002": {"status": "ready", "blocks": [{"text": "**Linguistic relativity concerns whether differences in language influence how people organize or use concepts.** The Sapir and Whorf quotations suggest that linguistic categories can shape how experience is interpreted. The strongest reading would make language determine what a person can think. A weaker claim is that habitual language use biases attention, memory or preferred ways of representing a situation.", "children": ["These claims require different evidence. A preference associated with language does not establish that alternative thought is impossible."]}, {"text": "**Influencing thought is different from completely determining thought.** Keep that distinction explicit when interpreting a language-group difference.", "children": ["The quotations express broad theoretical ideas. They are not experimental demonstrations that two speakers are unable to understand the same physical event."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 2}, "m3-thought-p003": {"status": "ready", "blocks": [{"text": "**Language is embedded in cultural practices and experience.** A difference between language communities may therefore covary with factors other than linguistic structure. Sapir and Whorf should not automatically be assigned the strongest deterministic interpretation of selected quotations.", "children": ["A precise study must identify which cognitive process is affected and what alternative explanations the comparison controls."]}, {"text": "**Testing linguistic relativity requires a narrower claim than saying that every language creates a completely separate world.** Space and time provide specific domains in which to test representational preferences.", "children": ["Historical framing explains why language and culture were often discussed together. It also highlights the need to distinguish their contributions in an experiment."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 3}, "m3-thought-p004": {"status": "ready", "blocks": [{"text": "**A location description needs a frame of reference.** Saying where the ball is requires choosing what counts as left, front or a stable direction. The ball can be located with respect to the viewer, the chair's own orientation or a direction independent of either.", "children": ["Different descriptions can identify the same physical position while organizing that position differently."]}, {"text": "**The object does not have to move for its verbal description to change.** Changing the reference frame changes the relation being described.", "children": ["The chair and ball are the meaningful stimuli. The question is which reference determines the ball's location, not a judgment about the objects' appearance."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 4}, "m3-thought-p005": {"status": "ready", "blocks": [{"text": "**An intrinsic frame uses an object's own orientation, a relative frame uses an observer's viewpoint, and an absolute frame uses a stable direction.** These are different ways to specify the same location. “At the chair's front” uses the chair's intrinsic front. “To the left of the chair from my viewpoint” depends on the observer.", "children": ["“North of the chair” uses an absolute direction that does not reverse when the observer turns around."]}, {"text": "**Ask what fixes the direction in each description.** The object's orientation, the observer's body and a stable external direction are not interchangeable.", "children": ["The ball–chair example holds the scene constant while changing the reference. Rotating the observer changes relative left and right but does not change north."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 5}, "m3-thought-p006": {"status": "ready", "blocks": [{"text": "**Egocentric spatial descriptions use the speaker's position and orientation.** Left, right, in front and behind are familiar examples for nearby objects. Tzeltal commonly uses absolute directions in circumstances where English speakers might use these relative terms.", "children": ["The contrast motivates asking whether habitual language use relates to nonverbal spatial coding, rather than merely comparing two ways of giving spoken directions."]}, {"text": "**A direction can stay fixed when a person turns.** Absolute coding differs from coding an object as being on the viewer's left.", "children": ["The language comparison concerns preferred spatial descriptions. It does not imply that speakers of either language are incapable of learning another frame."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 6}, "m3-thought-p007": {"status": "ready", "blocks": [{"text": "**Tzeltal's uphill and downhill terms function as an absolute directional system.** Their historical connection to a slope does not mean that each use simply points to the nearest visible hill. A direction is retained as a stable spatial reference rather than being recalculated from the speaker's current left and right.", "children": ["This allows positions to be described consistently as the speaker changes orientation."]}, {"text": "**A landmark origin and an absolute use are different properties.** A historically landscape-based term can become a stable directional reference.", "children": ["The contrast is with a description that depends entirely on the current viewpoint. The relevant feature is how the reference behaves across changes in location and orientation."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 7}, "m3-thought-p008": {"status": "ready", "blocks": [{"text": "**A landmark-based direction is tied to a particular environment.** Uptown and downtown organize movement within Manhattan but do not provide a universally usable compass system. A city's conventional map orientation can also differ from magnetic north. Familiar spatial language therefore reflects local practices as well as geometric directions.", "children": []}, {"text": "**A stable local convention is not automatically an absolute frame that transfers everywhere.** Its usefulness depends on the landmark system being available.", "children": ["The Manhattan example distinguishes local orientation from cardinal direction. It is a contrast about reference systems rather than an experiment demonstrating linguistic causation."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 8}, "m3-thought-p009": {"status": "ready", "blocks": [{"text": "**The chips task separates relative from absolute spatial memory by rotating the participant 180 degrees.** A participant sees a configuration, waits, and then chooses its match at a second table. A relative response preserves the arrangement with respect to the person's viewpoint. An absolute response preserves its orientation in the environment, so the two responses diverge after rotation.", "children": ["Dutch speakers predominantly gave relative responses, while Tzeltal speakers gave more absolute responses. The association is consistent with their preferred linguistic frames but does not isolate language from all other experience."]}, {"text": "**The rotation makes two otherwise similar descriptions predict different choices.** The nonverbal response reveals a preferred spatial coding strategy.", "children": ["The north arrow stays fixed while the person changes orientation. Red bars represent relative choices and blue bars absolute choices, showing different response distributions across the two language groups."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 9}, "m3-thought-p010": {"status": "ready", "blocks": [{"text": "**Spatial inference can combine relations learned in different displays.** Participants learn the relation between two objects, rotate to another display, and learn a second relation involving a shared object. They then place an object relative to another using the combined information. Relative and absolute coding lead to different placements because the person's orientation has changed.", "children": ["Dutch and Tzeltal response patterns again differ in the direction associated with their preferred spatial frames."]}, {"text": "**The task goes beyond reproducing one remembered arrangement.** It asks whether a frame is used when combining spatial relations to make an inference.", "children": ["The cube appears in both learning displays, linking the cone and cylinder relations. The final placement distinguishes a viewer-relative inference from one preserving environmental direction."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 10}, "m3-thought-p011": {"status": "ready", "blocks": [{"text": "**Testing conditions could contribute to the apparent language-group difference.** Li and Gleitman noted that Tzeltal participants had been tested with visible, familiar outdoor landmarks, unlike many laboratory participants. An environment with useful landmarks can encourage landmark-based coding. A windowless laboratory can make viewer-relative descriptions more convenient.", "children": ["Manipulating landmark availability within English speakers tests whether the behavior can change without changing native language."]}, {"text": "**A language comparison can be confounded with a setting comparison.** The environment must be considered before assigning the entire difference to linguistic structure.", "children": ["The critical contrast is access to spatial cues, not simply the label “laboratory.” Windows, outdoor views and familiar surroundings can alter which references are useful."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 11}, "m3-thought-p012": {"status": "ready", "blocks": [{"text": "**English speakers' preference for relative coding weakened when external landmarks were available.** They strongly preferred relative responses with the blinds down, but the preference was less pronounced with a street view or outdoors. The manipulation changes the spatial information available while keeping the language group the same.", "children": ["This demonstrates that task context can influence the response. It challenges an explanation in which language alone fixes the chosen frame."]}, {"text": "**Spatial strategy is sensitive to the testing environment.** A within-language change helps reveal a potential confound in a between-language comparison.", "children": ["A reduced relative preference is not necessarily a complete switch to absolute coding. Describe the observed change in preference without exaggerating it into an all-or-none reversal."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 12}, "m3-thought-p013": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 13}, "m3-thought-p014": {"status": "ready", "blocks": [{"text": "**If language groups are tested under different conditions, their response difference may partly reflect those conditions.** Visible landmarks and familiarity can covary with native language in a cross-community study. A controlled comparison must separate the effect of the environment from any contribution of habitual linguistic coding.", "children": ["Showing an environmental effect does not prove that language never matters. It limits what can be inferred from an uncontrolled comparison."]}, {"text": "**The relevant question is what the study actually isolates.** A language-group effect can be real while its causal interpretation remains unsettled.", "children": ["A confound is a factor that changes with the variable of interest and offers another explanation for the result. It is not merely any feature present in the experiment."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 14}, "m3-thought-p015": {"status": "ready", "blocks": [{"text": "**Levinson and colleagues argued that the simplified task could make the experimenter's purpose too obvious.** Low memory demands and short time or distance between displays may encourage a deliberate strategy about rotation. Participants who infer what is being tested can alter their response for reasons different from habitual spatial coding.", "children": ["The response therefore focuses on memory load and task transparency, rather than denying that landmarks can ever matter."]}, {"text": "**Changing a task can change the process it measures.** A landmark effect in an easy, transparent task may not settle how people habitually remember spatial relations.", "children": ["The proposed alternative is a demand-characteristic explanation. Participants' interpretation of the experiment may influence the response independently of their normal coding preference."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 15}, "m3-thought-p016": {"status": "ready", "blocks": [{"text": "**Levinson and colleagues retested Dutch students with four animals, a longer delay and greater distance between tables.** The extra item and delay increased memory demands, while the distance made the rotation manipulation less conspicuous. Under these conditions, the preference for relative coding remained.", "children": ["The result suggests that the environmental effect depends on how the task is arranged, including how much memory and strategic inference it encourages."]}, {"text": "**A relative preference can persist despite changes in the environment when the memory task is more demanding.** This narrows the conditions under which the landmark alternative explains behavior.", "children": ["Each procedural change has a purpose. More animals and a longer delay tax memory, while separation of the tables reduces the salience of the rotation."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 16}, "m3-thought-p017": {"status": "ready", "blocks": [{"text": "**A robust spatial-frame preference under memory demands does not automatically identify a purely spatial representation.** Remembering the task can recruit verbal strategies as well as spatial ones. The relative preference is reported when memory demands are substantial and the experimenter's interest is less obvious.", "children": ["That pattern makes it important to ask how the sequence is stored during the delay, not only which direction is chosen at the end."]}, {"text": "**The involvement of memory creates another mechanism to examine.** A task can be nonverbal in its response while still allowing verbal recoding internally.", "children": ["The two conditions concern memory load and task transparency. They specify when the effect is robust, rather than proving that all other explanations have been eliminated."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 17}, "m3-thought-p018": {"status": "ready", "blocks": [{"text": "**Participants might remember the animals as a verbal list such as “lion, tiger, bear.”** Reconstructing that sequence from left to right can produce a relative-looking response. This strategy would connect language to the task through working memory and ordering habits, rather than through an inability to represent absolute space.", "children": ["The interpretation changes because the same choice can arise from different internal codes."]}, {"text": "**A nonverbal task does not guarantee nonverbal processing.** Verbal recoding is a concrete alternative mechanism for the spatial-memory result.", "children": ["The proposed list preserves order but does not explicitly preserve compass direction. Translating that order into a left-to-right display can mimic a spatial-frame preference."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 18}, "m3-thought-p019": {"status": "ready", "blocks": [{"text": "**Metaphorical language expresses one kind of experience using terms from another.** Saying that an argument is not “cutting” describes its effectiveness rather than a literal action with a blade. Physical and spatial terms can therefore help express abstract relations. Time is especially useful for studying whether such linguistic habits are associated with nonlinguistic representations.", "children": ["The question is empirical. Using a spatial phrase does not by itself prove that every thought about time has the same spatial format."]}, {"text": "**An expression can be meaningful without being literal.** The study of time asks whether familiar spatial expressions also relate to cognitive processing.", "children": ["The lyric is an example of metaphorical expression. It is not experimental evidence for a particular direction of causation between language and thought."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 19}, "m3-thought-p020": {"status": "ready", "blocks": [{"text": "**English and Mandarin both use horizontal spatial language for time, but Mandarin also frequently uses vertical terms.** Earlier events can be described with an “up” term and later events with a “down” term. The linguistic contrast motivates testing whether speakers differ in the spatial organization they use during temporal tasks.", "children": ["The existence of the expressions is the starting observation. A behavioral task is needed to investigate whether the contrast extends beyond words."]}, {"text": "**Habitual ways of talking about time can suggest testable predictions about processing.** Mandarin's vertical terms make a vertical temporal organization a relevant possibility.", "children": ["The examples contrast spatial and temporal uses of the same terms. “Up” in an expression for an earlier month is a temporal use, not a claim that the month occupies a physical location."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 20}, "m3-thought-p021": {"status": "ready", "blocks": [{"text": "**Boroditsky's priming task tests whether spatial processing influences subsequent time judgments.** Participants first process horizontal or vertical relations, then respond to temporal earlier–later questions. English speakers respond faster after horizontal than vertical primes, while Mandarin speakers show the opposite pattern in the displayed comparison.", "children": ["Training English speakers on vertical metaphors changes the pattern toward a vertical-prime advantage. This suggests sensitivity to experience, rather than an unchangeable division between language groups."]}, {"text": "**The prime changes what representation is active before the temporal judgment.** Response-time differences reveal compatibility between the prime and the later task.", "children": ["The vertical axis is reaction time, so a lower bar means faster processing. Compare horizontal and vertical bars within each group rather than interpreting the tallest bar as the best performance."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 21}, "m3-thought-p022": {"status": "ready", "blocks": [{"text": "**Reading and writing habits can also organize sequences spatially.** Differences attributed to temporal metaphors may covary with whether text is commonly read left-to-right, right-to-left or vertically. Casasanto and Bottini use differences in text orientation and arrangement preferences to motivate this alternative.", "children": ["The point is to identify another source of spatial experience, not to assume that a writing-system label perfectly predicts every individual's habits."]}, {"text": "**Language-group differences can bundle linguistic and literacy experiences together.** Reading direction therefore needs to be measured or controlled.", "children": ["The diagrams distinguish starting side and line direction. The table shows several arrangement patterns within the sampled groups, making individual experience relevant."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 22}, "m3-thought-p023": {"status": "ready", "blocks": [{"text": "**Boroditsky and colleagues excluded Chinese readers who reported top-to-bottom reading.** This tests whether the vertical temporal effect can be explained entirely by that reported reading experience. English speakers show an advantage for a left-is-earlier horizontal mapping. Mandarin speakers also show an advantage for a top-is-earlier vertical mapping in the displayed comparison.", "children": ["Retaining a vertical effect under this restriction weakens that particular reading-direction explanation, without proving that every possible experiential confound is removed."]}, {"text": "**A targeted control tests a specific alternative explanation.** Its conclusion should be limited to the experience that was actually controlled.", "children": ["White bars are canonical mappings and black bars noncanonical mappings. For vertical trials, canonical means top-is-earlier. Lower reaction times indicate a mapping advantage."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 23}, "m3-thought-p024": {"status": "ready", "blocks": [{"text": "**Participants classify events as past or future using colored buttons.** The color-to-category mapping is reversed across blocks, so the past response is sometimes on the left and sometimes on the right. With standard text reading, responses are faster when past maps left and future maps right.", "children": ["Because the response concerns time rather than an explicit judgment of spatial direction, the compatibility effect reveals an implicit spatial association in this task."]}, {"text": "**Changing which side corresponds to past allows a direct test of spatial–temporal compatibility.** Color alone cannot explain the pattern because the mappings are counterbalanced.", "children": ["The lower black bars represent the left-to-right temporal mapping. The effect concerns response time across mappings, not a change in which events count as past or future."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 24}, "m3-thought-p025": {"status": "ready", "blocks": [{"text": "**Mirror reading tests whether short-term reading experience can alter spatial associations with time.** Participants read reversed text and perform the past–future button task. By the second mirror-reading block, the compatibility effect reverses. Responses are faster when earlier maps right and later maps left.", "children": ["The result supports a contribution of reading-direction experience and shows that the association can change over a short period."]}, {"text": "**A flexible temporal mapping is difficult to explain as a fixed consequence of native-language grammar alone.** Recent perceptual and reading experience contributes to performance.", "children": ["The first block retains the usual advantage, while the second favors the opposite mapping. Compare the two colors within each block before comparing overall reaction times between blocks."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 25}, "m3-thought-p026": {"status": "ready", "blocks": [{"text": "**Claims about a language's vocabulary are not automatically evidence for cognitive limits.** Pullum's discussion criticizes how an account of different word roots became an exaggerated story about language and thought. Languages can express distinctions through separate roots, derived words or phrases. Counting one of these forms without considering the others can misrepresent expressive capacity.", "children": ["A reliable claim requires accurate linguistic description and an appropriate behavioral test, rather than repetition of a striking anecdote."]}, {"text": "**Different lexical packaging does not show that one group cannot understand another group's distinctions.** The linguistic facts and the cognitive inference both need scrutiny.", "children": ["The excerpt distinguishes roots from derivationally related forms and phrases. That distinction is central to why simple vocabulary counts can be misleading."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 26}, "m3-thought-p027": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 27}, "m3-modalities-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 1}, "m3-modalities-p002": {"status": "ready", "blocks": [{"text": "**A signed language is a natural language, while Braille is a writing system.** Signed languages have their own linguistic structure. Braille allows a language to be read through touch. The distinction matters because changing the modality of a language is not the same as changing how a written language is accessed.", "children": ["Both cases reveal how sensory experience shapes the organization of systems involved in language and reading."]}, {"text": "**Do not treat Braille as a signed language or signing as a tactile alphabet.** They provide different tests of language and neural plasticity.", "children": ["The shared theme is modality, but the linguistic status of the two cases differs. A comparison should preserve that distinction before discussing their brain responses."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 2}, "m3-modalities-p003": {"status": "ready", "blocks": [{"text": "**Signed languages use a visual modality and manual and bodily articulators.** The hands, face and upper body contribute to a coordinated linguistic signal. Space can carry linguistic relations. Some signs are iconic, meaning that aspects of their form resemble aspects of their meaning.", "children": ["Iconicity is easy to overestimate when a familiar translation is supplied. A visible resemblance does not eliminate the need to learn a language's forms and structure."]}, {"text": "**Changing the articulators does not remove linguistic organization.** Signed languages remain structured systems rather than collections of transparent gestures.", "children": ["The pictured signs include actions, objects and less directly depictable concepts. A gloss names the translation but does not make every feature of a sign self-explanatory."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 3}, "m3-modalities-p004": {"status": "ready", "blocks": [{"text": "**Fluent signing coordinates hands, facial expression, gaze and upper-body movement.** The linguistic signal is distributed across these visible articulators rather than produced by one hand movement at a time. Like speech, a fluent stream is continuous enough that word boundaries are not always obvious to a learner.", "children": ["Eye contact and movement timing are therefore relevant to perceiving the interaction, alongside the form of individual signs."]}, {"text": "**The unit of analysis is coordinated language production, not an isolated hand pose.** Fluency depends on how the articulators work together.", "children": ["The linked demonstration invites attention to coordination and segmentation. The original video link is retained separately from the static slide."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 4}, "m3-modalities-p005": {"status": "ready", "blocks": [{"text": "**Signed-language phonology includes contrastive hand configuration, location and movement.** Changing one of these features can distinguish signs, just as changing a speech feature can distinguish spoken words. The PLEASE–SORRY and ONION–APPLE examples demonstrate that closely related visible forms can have different linguistic identities.", "children": ["Phonology therefore concerns the organization of contrastive form, not only acoustic sound."]}, {"text": "**A feature is linguistically contrastive when changing it changes the sign identity.** Visual similarity alone does not determine whether two forms belong to the same category.", "children": ["The paired images hold some properties similar while contrasting others. Handshape, where the gesture is made and how it moves are separate dimensions to inspect."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 5}, "m3-modalities-p006": {"status": "ready", "blocks": [{"text": "**Categorical perception can be tested by varying a sign feature continuously.** The hand-configuration continuum moves between forms while the observer's identification and discrimination responses are measured. One continuum crosses a phonemic distinction between PLEASE and SORRY. The allophonic comparison varies hand configuration without the same change in sign identity.", "children": ["A sharp identification boundary accompanied by better discrimination near that boundary would indicate category-sensitive perception."]}, {"text": "**The test distinguishes a physical change from a linguistically meaningful category change.** Both continua vary visually, but only one crosses the relevant contrast.", "children": ["The stimulus sequences progress through intermediate hand configurations. Comparing equal-sized changes within and across a linguistic boundary is more informative than comparing only the two endpoints."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 6}, "m3-modalities-p007": {"status": "ready", "blocks": [{"text": "**Deaf signers show a sharper categorical boundary for phonemic than allophonic hand-configuration changes.** In the phonemic condition, identification shifts steeply around stimuli 4–6. Discrimination is also strongest near the phonemic boundary. Comparable physical steps are easier to distinguish when they cross that category boundary.", "children": ["The allophonic identification function is shallower and lacks the same localized discrimination peak. This links the perceptual pattern to linguistic contrast rather than any visible hand change."]}, {"text": "**The combination of a sharp identification shift and a boundary-related discrimination peak supports categorical perception.** Identification alone would provide a less complete test.", "children": ["The top plots show categorization and the lower plots discrimination. Compare the position of the steep change with the discrimination peak in the phonemic column."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 7}, "m3-modalities-p008": {"status": "ready", "blocks": [{"text": "**Signed languages can use positions in signing space to represent relationships.** A classifier sign made at a particular location can indicate the relative position of an object. Understanding a sentence can require retaining where entities were introduced and how subsequent signs relate to those locations.", "children": ["Spatial processing therefore contributes to linguistic comprehension, rather than functioning only as background vision."]}, {"text": "**Where a sign is made can be part of the sentence's meaning.** The listener must track linguistic relations across space as well as over time.", "children": ["The classifier example uses relative placement to express a relation between objects. The signing location is instructional information, not a decorative feature of the display."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 8}, "m3-modalities-p009": {"status": "ready", "blocks": [{"text": "**Signed-language comprehension recruits classical language regions and shows left lateralization, as spoken-language comprehension does.** Inferior frontal and posterior superior temporal regions are part of this overlap. Signing also engages visual and superior parietal regions relevant to its perceptual and spatial demands.", "children": ["The combination suggests both common language organization and modality-related contributions. Similarity does not require identical activation everywhere."]}, {"text": "**Different sensory inputs can engage overlapping language networks.** The additional visual and spatial activity reflects the demands of processing a signed signal.", "children": ["The figure compares deaf signers, hearing signers and hearing audiovisual-speech participants. Hearing signers are particularly useful because signing experience is not restricted to people who are deaf."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 9}, "m3-modalities-p010": {"status": "ready", "blocks": [{"text": "**Bavelier and colleagues compared hearing controls, deaf signers and hearing signers on visual attention.** Participants monitored dots for brief changes in luminance or velocity, with attention directed centrally or peripherally. Deaf participants showed an advantage when attention was directed to the periphery.", "children": ["Including hearing signers helps separate experience with signing from lack of auditory input. If all signers had the same advantage, signing alone would be a stronger explanation."]}, {"text": "**The comparison groups are essential to the causal question.** A deaf-versus-hearing contrast alone would bundle deafness and signing experience together.", "children": ["The display distinguishes center and peripheral monitoring. Luminance concerns brightness and velocity concerns motion, so the task measures attention to brief visual changes rather than sign comprehension itself."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 10}, "m3-modalities-p011": {"status": "ready", "blocks": [{"text": "**Signing experience and deafness show different associations with visual processing.** Both deaf and hearing signers show a leftward shift in motion-processing lateralization relative to hearing nonsigners. Enhanced peripheral attention is found in deaf individuals, not hearing signers. Signing experience alone therefore does not explain that enhancement.", "children": ["The proposed interpretations involve links between motion and language systems for signing, and reduced reliance on auditory peripheral cues in deafness."]}, {"text": "**Do not combine lateralization and peripheral attention into one undifferentiated advantage.** They track different aspects of experience.", "children": ["The upper comparison concerns hemispheric bias in motion-related areas. The lower comparison concerns center-versus-periphery attention. The sign and size of a bar must be read using its own axis."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 11}, "m3-modalities-p012": {"status": "ready", "blocks": [{"text": "**Comparing sign comprehension with another organized gesture system helps control visible movement demands.** Tic-tac uses sophisticated hand gestures to communicate horse-racing odds. Both tasks involve meaningful, sequenced hand movements. A difference between them is more informative about linguistic processing than a comparison between signing and no movement.", "children": ["The control is not identical to a natural language, which is precisely why the remaining difference is of interest."]}, {"text": "**A useful control shares some demands while differing in the process being tested.** Tic-tac helps separate language comprehension from hand-motion processing.", "children": ["The original demonstration link concerns the control gesture system. The comparison does not assume that every meaningful gesture is a natural language."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 12}, "m3-modalities-p013": {"status": "ready", "blocks": [{"text": "**Sign language produces stronger activity around posterior superior temporal language regions than tic-tac gestures.** This supports a distinction between processing organized hand movements and processing a natural language. The comparison reduces a simple explanation based only on the presence of hands moving through space.", "children": ["The frontal activation shown is superior to classic Broca's area, so it should not be casually relabeled as a precise Broca's effect."]}, {"text": "**Shared visual movement does not explain the entire neural response to signed language.** The temporal-region difference is the central language-related result.", "children": ["The highlighted posterior temporal activation is near Wernicke's region. The figure supports a regional comparison, not the claim that one highlighted spot is solely responsible for all signing."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 13}, "m3-modalities-p014": {"status": "ready", "blocks": [{"text": "**Signed languages have linguistic form, grammar and language-related neural organization.** Contrastive sign features can produce categorical perception, and comprehension recruits posterior superior temporal language regions. Signing experience is associated with changes in motion lateralization. Deafness is associated with enhanced peripheral attention in the reported comparison.", "children": ["These findings jointly show that linguistic experience and sensory history contribute in different ways."]}, {"text": "**A coherent account must separate shared language organization from sensory adaptations.** Neither “sign is just gesture” nor “modality makes no difference” captures the evidence.", "children": ["The summary combines behavioral category evidence, group comparisons and neural contrasts. Each addresses a different question, so one result should not be used as if it established all the others."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 14}, "m3-modalities-p015": {"status": "ready", "blocks": [{"text": "**Comprehending a signed spatial description can require a perspective transformation.** A room can be described from the speaker's perspective or the addressee's perspective. The figure's caption reports better comprehension for descriptions from the speaker's perspective despite the mental transformation that this requires.", "children": ["This illustrates that the most linguistically natural representation is not necessarily the one that eliminates every spatial transformation."]}, {"text": "**Spatial comprehension depends on conventions as well as geometric convenience.** The observer may transform a speaker-centered description rather than prefer an already reversed one.", "children": ["The two signing sequences describe the same table location in the room diagram. The difference is whose perspective organizes the description, not a change in the table's actual location."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 15}, "m3-modalities-p016": {"status": "ready", "blocks": [{"text": "**Braille represents written language through tactilely distinguishable symbols.** It is a way to read a language, rather than a separate natural language with its own grammar. The symbols are optimized for touch. Fingers acquire letters sequentially, creating perceptual demands that differ from viewing printed text.", "children": ["The comparison asks how reading networks operate when the input arrives through touch instead of vision."]}, {"text": "**The linguistic task can remain reading while the sensory input changes.** This makes Braille useful for studying cross-modal organization.", "children": ["Sequential tactile sampling is a processing constraint. It does not imply that Braille readers must consciously name every individual dot before understanding a word."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 16}, "m3-modalities-p017": {"status": "ready", "blocks": [{"text": "**Braille reading activates visual cortex in blind individuals, with more extensive recruitment after earlier sight loss.** Early- and late-blind groups therefore provide a comparison of developmental sensory history. Early-blind participants show stronger involvement of regions associated with visual word processing than late-blind participants.", "children": ["This indicates that a region's usual sensory label does not completely determine the information it can help process."]}, {"text": "**The timing of sensory experience relates to later functional organization.** Visual cortex can participate in tactile reading even when the stimulus is not visual.", "children": ["The early-blind examples are on the left and late-blind examples on the right. Compare the extent of activation rather than assuming that every displayed colored voxel has the same function."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 17}, "m3-modalities-p018": {"status": "ready", "blocks": [{"text": "**Merabet and colleagues tested rapid plasticity by blindfolding sighted adults for five days while training Braille.** A comparison group received training without the same continuous removal of visual input. The blindfolded group learned more quickly. This suggests that eliminating competing visual input can affect tactile learning over a short timescale.", "children": ["Because the participants were sighted adults, the experiment tests a different question from lifelong or early blindness."]}, {"text": "**Cross-modal changes do not have to be limited to early development.** A short-term manipulation can reveal latent contributions to tactile processing.", "children": ["The procedure includes baseline testing, training, repeated imaging and blindfold removal. The group comparison distinguishes training effects from the additional effect of continuous blindfolding."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 18}, "m3-modalities-p019": {"status": "ready", "blocks": [{"text": "**Visual-cortex responses to Braille developed during blindfolding and reversed after the blindfold was removed on Day 6.** The time course shows that the change was rapid and reversible. Removing visual input can allow tactile-related activity to become more evident. Restoring vision changes that balance again.", "children": ["This pattern is consistent with unmasking existing inputs rather than requiring the creation of an entirely new pathway over a few days."]}, {"text": "**Reversibility helps constrain the mechanism.** A rapid response that disappears after vision returns suggests a change in functional contribution or competition.", "children": ["The images and signal plot compare Days 1, 3, 5 and 6. Day 6 is specifically the post-blindfold condition, not simply another day under unchanged deprivation."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 19}, "m3-modalities-p020": {"status": "ready", "blocks": [{"text": "**Disrupting visual cortex with TMS impaired Braille discrimination in the blindfolded group.** This goes beyond showing that the region becomes active during touch. On Day 5, the blindfolded group's error rate rises under 1 Hz TMS relative to its baseline and sham conditions. The nonblindfolded group does not show the same selective disruption.", "children": ["The effect is no longer present in the same way after blindfold removal. The result supports a temporary functional contribution of visual cortex to tactile performance."]}, {"text": "**Activation and necessity are different kinds of evidence.** Interfering with a region and changing behavior provides stronger evidence that its activity contributes to the task.", "children": ["The solid symbols identify blindfolded participants. The vertical axis is error rate, so the upward TMS change means worse performance, not improved reading."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 20}, "m3-modalities-p021": {"status": "ready", "blocks": [{"text": "**Language-related organization is resilient across sensory modalities while remaining shaped by experience.** Signed language recruits classical language regions, and Braille engages networks associated with text processing. Competition among available inputs offers a way to understand reorganization. When an input is absent or reduced, other information can make a larger contribution.", "children": ["The evidence does not imply that all regions are interchangeable. It shows both stable functional relationships and experience-sensitive recruitment."]}, {"text": "**A brain region's contribution reflects development and competition as well as its usual sensory input.** Common language functions can coexist with modality-specific adaptations.", "children": ["Distinguish the language-network overlap from the visual-attention and tactile-recruitment findings. They support a related account of plasticity through different experimental comparisons."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 21}, "m3-review-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/review.txt", "source": "review", "page": 1}, "m3-review-p002": {"status": "ready", "blocks": [{"text": "**Orthographic depth** describes how consistently spelling corresponds to pronunciation. English is relatively deep because many spellings do not transparently specify their sounds. COLONEL and PARADIGM make the problem concrete. Applying common letter–sound patterns can produce a plausible-looking pronunciation that is wrong for the actual word.", "children": ["In shallower writing systems, such as Finnish and Korean, spelling–sound correspondences are more predictable. The comparison concerns the writing system, not the intelligence or ability of its readers."]}, {"text": "**An unfamiliar spelling cannot always be decoded correctly from its letters alone.** Deep orthographies create more exceptions that readers must learn through experience.", "children": ["The English examples contrast ordinary expectations from the letters with the word's learned pronunciation. A deep script is less predictable, not completely random."]}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 2}, "m3-review-p003": {"status": "ready", "blocks": [{"text": "**Finnish has a shallow orthography.** Letters correspond relatively unambiguously to phonemes, so learning a spelling–sound correspondence helps with many different words. Doubled letters represent a meaningful length distinction. A doubled consonant is geminated, and a doubled vowel is long.", "children": ["This regularity helps Finnish children learn decoding quickly. Decoding means generating a pronunciation from a written form, whether or not its meaning is familiar."]}, {"text": "**Consistent correspondences make decoding easier to generalize.** Finnish readers can apply what they learn about letters to unfamiliar written forms.", "children": ["The linked Finnish lesson is a source demonstration. Its sound is not embedded in the PDF, so the written claims establish the correspondence and length distinctions without supplying a recovered recording."]}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 3}, "m3-review-p004": {"status": "ready", "blocks": [{"text": "**Pseudoword reading tests decoding.** Because a pseudoword is not a familiar stored word, the child must generalize from learned spelling–sound patterns. The comparison involves Grade 1 children learning different alphabetic writing systems. Children learning many other languages produce plausible pseudoword pronunciations more successfully than English learners.", "children": ["English's less predictable correspondences help explain why decoding develops more slowly. This task does not measure the child's entire language ability."]}, {"text": "**A made-up word separates decoding from remembering a familiar word.** The lower English performance is consistent with greater orthographic depth.", "children": ["Compare accuracy across languages for the same type of task. The important outcome is the relative difficulty of English pseudoword decoding, not a claim that English children cannot decode."]}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 4}, "m3-review-p005": {"status": "ready", "blocks": [{"text": "**Korean writing represents sound structure systematically.** Related phonemes can have related written shapes, so the visual forms themselves reflect aspects of phonological organization. The letters are arranged into syllable blocks with initial, medial and sometimes final positions. Those positions are not three unrelated pictures of whole words.", "children": ["The velar consonant forms share the basic angular ㄱ shape. Additional strokes or doubling distinguish related consonants."]}, {"text": "**The organization of Hangul supports more than consistent pronunciation.** Similar sound categories can also be visibly related in their written symbols.", "children": ["The diagrams label initial, medial and final positions. The g, kk and k examples share a shape family, illustrating how a place-of-articulation relation can be reflected in the script."]}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 5}, "m3-review-p006": {"status": "ready", "blocks": [{"text": "**Frequency and regularity interact.** Low-frequency exception words are slowed much more than low-frequency regular words, whereas high-frequency words show a much smaller regularity difference. Naming latency is the time needed to begin saying the word. Higher values mean slower responses.", "children": ["An interaction means the effect of one factor depends on the other. The regularity cost is not a fixed amount added equally to high- and low-frequency words."]}, {"text": "**Experience matters especially when pronunciation conflicts with the usual spelling pattern.** Frequent exposure reduces the disadvantage of exception words.", "children": ["The lines are close at high frequency and separate at low frequency. Exception words rise to roughly 580 ms, while regular words rise only to roughly 555 ms in this figure."]}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 6}, "m3-review-p007": {"status": "ready", "blocks": [{"text": "**A dual-route interpretation separates lexical retrieval from sublexical decoding.** The lexical process supplies the learned pronunciation of a particular word, while decoding computes pronunciation from spelling units. For a high-frequency word, lexical information becomes available quickly enough to reduce the influence of the decoding output.", "children": ["For a low-frequency exception, the lexical response is less efficient and the regularized decoding output can interfere. Nonwords depend on decoding because they lack a stored whole-word entry."]}, {"text": "**Two routes can explain why regularity matters most for unfamiliar words.** Fast lexical processing protects familiar exceptions from competing sublexical output.", "children": ["This is an interpretation of the interaction, not the interaction itself. Other architectures must be evaluated against the same observed pattern."]}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 7}, "m3-review-p008": {"status": "ready", "blocks": [{"text": "**In a PDP account, rules are generalizations learned across words.** Whole-word knowledge is distributed across learned mappings instead of being stored only in a distinct lexical route. The same learning mechanism can capture both patterns shared by many words and information specific to a familiar word.", "children": ["The research strategy asks whether domain-general learning can explain reading. This contrasts with choosing separate adult processing components primarily from neuropsychological dissociations."]}, {"text": "**Word-specific knowledge and generalization can coexist in the same learned system.** They do not have to be implemented as a dictionary and a separate symbolic rule list.", "children": ["“Distributed” refers to how knowledge is represented across the network. It does not mean that the model has no memory of individual words."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 8}, "m3-review-p009": {"status": "ready", "blocks": [{"text": "**A learned network can produce a frequency-by-regularity interaction without separate frequency and rule mechanisms.** Regular words receive support from patterns shared across many words. An exception conflicts with those patterns, so learning its particular mapping is especially important. Frequent exposure strengthens that word-specific mapping.", "children": ["A low-frequency exception has both weak item-specific learning and poor support from the dominant pattern. This combination creates a larger disadvantage than either factor alone."]}, {"text": "**Consistency supplies support from other words, while frequency strengthens experience with the particular word.** Their joint influence explains why infrequent exceptions are especially difficult.", "children": ["The interaction is shared evidence that both architectures must explain. Producing it does not by itself establish whether the implementation contains symbolic rules."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 9}, "m3-review-p010": {"status": "ready", "blocks": [{"text": "**A PDP model can pronounce nonwords using the weights learned from real words.** A new spelling activates patterns that overlap with familiar spellings, allowing the network to generalize. No stored entry for the particular nonword is required. The same learned correspondences that support consistent words can support a new combination.", "children": ["This is a proposed mechanism for decoding without a separate GPC rule module."]}, {"text": "**Novel pronunciation can result from applying learned statistical structure.** Nonword reading therefore does not automatically establish a separate symbolic route.", "children": ["The relevant comparison is whether one learned mapping can handle both familiar words and new items. The claim must still be checked against the model's actual performance."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 10}, "m3-review-p011": {"status": "ready", "blocks": [{"text": "**Poor nonword performance can challenge either a theoretical proposal or a particular implementation.** The early model's nonword accuracy was weaker than desired. One possibility is that a single associative mechanism cannot explain the task. Another is that the chosen representations fail to capture the similarities needed for generalization.", "children": ["Improving the implementation while retaining the theoretical mechanism helps distinguish these possibilities."]}, {"text": "**A failed simulation does not identify its own cause.** The failure must be traced to the architecture, learning assumptions, representations or other implementation choices.", "children": ["The important question is what changes when the model is repaired. A representational improvement is a different theoretical move from adding a separate nonword route."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 11}, "m3-review-p012": {"status": "ready", "blocks": [{"text": "**Generalization depends on how sound similarity is represented.** The early Seidenberg–McClelland model used Wickelfeatures, whose representation of phonology was problematic for nonword reading. Plaut and colleagues improved the phonological representations and obtained better nonword performance. This supports a representational explanation for at least part of the earlier failure.", "children": ["Behavioral relations between phonological processing and decoding also make phonology a relevant target for explanation."]}, {"text": "**Changing the representation can improve decoding without adding a symbolic rule system.** That distinction matters when evaluating the original theoretical claim.", "children": ["The comparison concerns models with different representations. Better performance after that change is evidence about implementation, not proof that every associative model will succeed."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 12}, "m3-review-p013": {"status": "ready", "blocks": [{"text": "**A network generalizes through similarity.** If its phonological representation poorly captures similarities among words, the learned mapping cannot transfer as effectively to new forms. A familiar word can retain support from its own training history. A nonword lacks that item-specific experience and depends more heavily on generalization.", "children": ["This produces a reason for unfamiliar forms to be especially vulnerable to poor representations without requiring a dedicated nonword mechanism."]}, {"text": "**The same representational weakness can have unequal effects on words and nonwords.** Familiarity can partly compensate where new-item generalization cannot.", "children": ["Distinguish a weaker shared representation from damage to a separate route. Both can create a task difference, but they locate the explanation differently."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 13}, "m3-review-p014": {"status": "ready", "blocks": [{"text": "**Harm and Seidenberg manipulated noise in phonological representations.** Increasing noise makes the sound representations less reliable while keeping the model's general learning framework. The manipulation produced poorer nonword decoding and relative sparing of word recognition. It also linked the severity of the phonological deficit to the degree of decoding difficulty.", "children": ["The model therefore connects a reading pattern to the quality of a more general phonological system."]}, {"text": "**A selective-looking reading deficit can emerge from degraded shared representations.** Nonwords are especially dependent on reliable generalization.", "children": ["Noise is the manipulated model property. Word and nonword performance are outcomes, so the simulation tests a directional mechanistic proposal rather than merely observing a correlation."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 14}, "m3-review-p015": {"status": "ready", "blocks": [{"text": "**The lexicon and grammar offer different ways to produce a past tense.** Lexical retrieval supplies an irregular form such as HELD, while grammatical combination can produce WALK plus -ed. Pinker and Ullman's diagram associates lexical lookup with declarative memory and grammatical combination with procedural processing.", "children": ["Like dual-route reading, the account separates word-specific knowledge from a productive operation. Unlike reading aloud, its task is to transform a stem according to a grammatical feature, rather than convert spelling into sound."]}, {"text": "**Similar-looking architectures can solve different computational problems.** Keep morphological inflection separate from grapheme–phoneme conversion.", "children": ["The input includes a stem and a past-tense feature. The diagram distinguishes lexical association from combination, and its blocking connection prevents a retrieved irregular from competing unchecked with a regular form."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 15}, "m3-review-p016": {"status": "ready", "blocks": [{"text": "**The Words and Rules proposal was motivated partly by a theory of grammar.** A categorical symbolic grammar describes productive patterns, but language also contains exceptions. Reading dual-route theories were strongly motivated by neuropsychological dissociations. The morphology proposal also reflects a commitment to keeping the grammatical rule system distinct from exceptional lexical information.", "children": []}, {"text": "**The motivation for an architecture matters when evaluating its evidence.** Similar diagrams do not mean that the theories were derived from the same observations.", "children": ["The contrast is between a dissociation-driven reading account and a grammatical argument for separating productive rules from exceptions."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 16}, "m3-review-p017": {"status": "ready", "blocks": [{"text": "**An associative lexicon handles information that does not fit a categorical rule.** Its representations are word-specific and sensitive to frequency and phonological similarity. KEEP–KEPT, WEEP–WEPT and LEAP–LEAPT illustrate similarity among irregular forms. An exception can belong to a small family rather than being wholly unrelated to other words.", "children": ["Assigning these properties to lexical memory lets the rule system remain categorical and general."]}, {"text": "**Separating exceptions protects a simple rule, but creates a second mechanism that must also be explained.** The associative system carries graded and item-specific influences.", "children": ["The shared sound pattern in the listed verbs motivates associative similarity. It is not evidence that every irregular verb uses exactly the same transformation."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 17}, "m3-review-p018": {"status": "ready", "blocks": [{"text": "**Rumelhart and McClelland modeled past tense as a learned association between present and past sound patterns.** A single trainable network learns across verbs instead of applying a separately specified -ed rule. The model encodes a root's phonology, transforms that representation through modifiable connections, and decodes an output pattern.", "children": ["Regularity is a pattern learned from many examples. Irregular forms are also learned within the same system."]}, {"text": "**One learning mechanism is proposed for both regularities and exceptions.** The challenge is to explain accurate generalization as well as familiar forms.", "children": ["The fixed encoding and decoding stages surround a modifiable pattern associator. Wickelfeatures represent sound patterns, while the trainable connections store the learned mapping."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 18}, "m3-review-p019": {"status": "ready", "blocks": [{"text": "**U-shaped learning describes an initial success, a decline, and later recovery.** A child may correctly say RAN, later produce RUNNED, and eventually return to RAN. The middle error is a **regularization**, because the child applies the common past-tense pattern to an irregular verb.", "children": ["The decline does not necessarily mean that the child has stopped learning. A changing system can generalize more broadly while temporarily disrupting an earlier correct response."]}, {"text": "**Development can involve temporary errors as knowledge changes.** A theory must explain the entire trajectory, not just the final adult response.", "children": ["The vertical dimension is successful performance and the horizontal dimension is development or training. A U shape concerns accuracy over time, not the shape of a word."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 19}, "m3-review-p020": {"status": "ready", "blocks": [{"text": "**The Words and Rules account explains U-shaped learning through changes in the use of rules and lexical exceptions.** Early correct forms can be imitated before a productive rule is available. When the rule is learned, it can be applied too broadly, yielding RUNNED. Later, learned irregulars and the blocking process prevent that regularization.", "children": ["This account treats the developmental stages as involving distinguishable processes rather than only gradual changes in one mapping."]}, {"text": "**Overregularization is interpreted as productive rule use that is not yet sufficiently constrained by exceptions.** Recovery depends on the irregular form winning over the rule output.", "children": ["Blocking means that retrieval of the appropriate irregular prevents the otherwise available regular form. It is a proposed mechanism, not merely another name for correct performance."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 20}, "m3-review-p021": {"status": "ready", "blocks": [{"text": "**Changing the training vocabulary can produce U-shaped learning in one network.** Early training emphasizes frequent irregular verbs, allowing those particular mappings to be learned. As more regular verbs enter training, their common pattern changes the network's responses. That generalization can interfere with previously learned irregulars.", "children": ["With further learning, the network can recover the irregular responses while retaining broad regularity. No new symbolic rule component is inserted at the point of decline."]}, {"text": "**A shift in the distribution of experience can temporarily disrupt familiar responses.** The learning account explains the developmental pattern through changing weights and input.", "children": ["The lower plot contrasts correct irregular responses with regularized alternatives. Their changing strengths illustrate competition during training, rather than the sudden appearance of a separate rule box."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 21}, "m3-review-p022": {"status": "ready", "blocks": [{"text": "**Testing untrained verbs asks whether the network learned transferable structure.** A real English verb can be novel to a model if it was excluded from that model's training set. The test therefore uses the logic of a wug task even when the items are real words to humans.", "children": ["The model can generate many appropriate past-tense features, but feature-level success must be distinguished from producing an entirely correct word."]}, {"text": "**Generalization is defined relative to the learner's experience.** A familiar human word is still a valid novel-model test when it was withheld from training.", "children": ["The summary reports proportions of Wickelfeatures generated correctly. A high proportion of correct features does not imply that the same proportion of whole words was pronounced perfectly."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 22}, "m3-review-p023": {"status": "ready", "blocks": [{"text": "**Some model outputs contain changes that are unlike ordinary human regularizations.** Examples include MADE(D)-like changes to MATE and the unusual outputs MEMBLED for MAIL and TOUREDER for TOUR. The model authors acknowledge that people are unlikely to make some of these errors. They suggest that additional output constraints could reduce bizarre responses.", "children": ["This separates capturing an overall learning pattern from matching the detailed form of human errors."]}, {"text": "**A plausible learning curve is not enough if the model produces implausible words.** Error structure provides another test of the representation and decoding process.", "children": ["The quotation discusses outputs near threshold and a possible cleanup mechanism. That proposed mechanism is an explanation to be tested, not a repair already demonstrated by the quoted result."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 23}, "m3-review-p024": {"status": "ready", "blocks": [{"text": "**Joanisse and Seidenberg propose that phonology supports rule-like generalization while semantics especially supports irregular forms.** The same system links speech input, meaning and speech output. Reliable sound representations support extension from familiar present–past pairs to new forms. Irregular mappings receive additional support from the particular word's semantic representation.", "children": ["The hypothesis concerns different degrees of dependence on shared systems, rather than a separate symbolic rule route for every regular response."]}, {"text": "**The regular–irregular contrast can arise from how phonological and semantic information contribute.** A graded system can produce systematic differences between item types.", "children": ["The diagram connects speech input and semantics through learned mappings to speech output. Its components represent domains of information, not a list of regular and irregular words in separate boxes."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 24}, "m3-review-p025": {"status": "ready", "blocks": [{"text": "**The model aims to explain the dissociation between irregular and nonword past-tense performance.** These tasks differ in how much they depend on learned word-specific information and phonological generalization. A nonword has no familiar item-specific semantic history to support its inflection. A known irregular can require semantic support because its output is not well predicted by the dominant pattern.", "children": ["Manipulating phonological or semantic integrity tests whether these different dependencies can produce opposite impairment profiles."]}, {"text": "**The same architecture should explain both sides of the patient pattern.** Selectivity must arise from the manipulated representations and their contribution to the task.", "children": ["The target is a pattern of performance across item types. Drawing phonology and semantics in a diagram is not enough unless damaging them produces the relevant outcomes."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 25}, "m3-review-p026": {"status": "ready", "blocks": [{"text": "**The patient pattern associated here with Broca's aphasia includes especially poor nonword past-tense production.** These patients have left anterior injury and difficulty producing speech. Regular forms are also vulnerable, while irregular forms are relatively better in the displayed comparison. A novel BLICK must be transformed without relying on a familiar stored past tense.", "children": ["This motivates investigating phonological contributions to the apparent morphological deficit."]}, {"text": "**Difficulty with productive inflection may be connected to sound processing.** The nonword condition is particularly demanding because it relies on generalization.", "children": ["The graph places nonword accuracy below regular and irregular accuracy. The irregular advantage over regulars is smaller than the nonword disadvantage, so these differences should not be treated as equally large."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 26}, "m3-review-p027": {"status": "ready", "blocks": [{"text": "**Other patient groups show a larger problem with irregular past-tense forms.** The material discusses Wernicke's and Alzheimer's patients and anomic patients with inferior or middle temporal injury. Their irregular performance is lower than their regular and nonword performance in the displayed comparison.", "children": ["This creates the other side of the dissociation and motivates examining the information that especially supports known irregular forms."]}, {"text": "**Relatively preserved nonword inflection can coexist with poor irregular inflection.** The theory must explain this reverse pattern as well as phonological impairment.", "children": ["The middle bar is the irregular condition, at roughly 60% correct, compared with higher regular and nonword scores. The diagnostic labels do not make every individual's performance identical."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 27}, "m3-review-p028": {"status": "ready", "blocks": [{"text": "**The classical contrast associates Wernicke's aphasia with fluent but often poorly interpretable speech and Broca's aphasia with effortful, telegraphic speech.** The former can include neologisms, while the latter can omit grammatical particles and show word-order difficulty. This makes a lexical-versus-grammatical interpretation attractive. However, a descriptive syndrome is not itself a demonstration of an isolated processing module.", "children": ["Content words may be relatively preserved in telegraphic speech, while fluent speech can retain sentence-like structure without conveying a clear message."]}, {"text": "**Fluency, grammatical organization and meaningful word selection are distinguishable dimensions.** The two example profiles emphasize different disruptions.", "children": ["The quoted utterances contrast fluent but difficult-to-interpret output with short, effortful content-word sequences. The diagnostic terms summarize patterns rather than guaranteeing identical symptoms in every patient."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 28}, "m3-review-p029": {"status": "ready", "blocks": [{"text": "**Broca's original patients are not necessarily straightforward examples of what is now called Broca's aphasia.** Profound inability to articulate speech can reflect motor-planning impairment rather than a selective grammatical deficit. **Apraxia of speech** concerns planning or coordinating speech movements. That differs from explaining an omission of grammatical structure in otherwise producible speech.", "children": ["The historical label therefore should not substitute for a precise description of the impaired behavior."]}, {"text": "**A familiar syndrome name does not settle which level of processing is affected.** Articulation and grammatical formulation must be distinguished.", "children": ["The case description emphasizes extremely restricted spoken output despite some preserved understanding. It motivates examining speech production at multiple levels rather than locating grammar from the name alone."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 29}, "m3-review-p030": {"status": "ready", "blocks": [{"text": "**A grammar–lexicon distinction makes the classical aphasia contrast theoretically appealing.** A grammatical system combines forms, while lexical knowledge concerns words and their properties. Chomsky's example of a grammatical but semantically unusual sentence shows that syntactic well-formedness cannot be reduced to whether a sentence describes a sensible event.", "children": ["That conceptual distinction does not establish a simple one-to-one mapping from each syndrome to one isolated component."]}, {"text": "**Syntax and meaning can come apart in a judgment without proving a perfectly modular neural organization.** The behavioral and theoretical claims should be kept separate.", "children": ["“Colorless green ideas sleep furiously” contrasts with an order that violates English syntax. The example isolates grammatical organization from familiarity or ordinary plausibility."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 30}, "m3-review-p031": {"status": "ready", "blocks": [{"text": "**The functional level selects word meanings and semantic roles, while the positional level organizes word forms into a grammatical sequence.** Phonological encoding and articulation concern later aspects of producing the utterance. A **lemma** is a representation involved in lexical selection, distinct from simply executing its sound pattern. Positional processing contributes ordering and morphological structure.", "children": ["Combinations such as HOUSEBOAT show that complex-word meaning can be partly compositional. Errors such as “easy enoughly” provide evidence about the organization of morphological operations."]}, {"text": "**Word selection, ordering, sound encoding and articulation are different explanatory levels.** An apparent lexical–grammatical contrast should be related to those operations carefully.", "children": ["The diagram runs from message-level conceptual preparation through functional and positional levels to phonological encoding and speech gestures. Its order represents a processing proposal, not a direct picture of separate brain locations."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 31}, "m3-review-p032": {"status": "ready", "blocks": [{"text": "**Egocentric spatial descriptions use the speaker's position and orientation.** Left, right, in front and behind are familiar examples for nearby objects. Tzeltal commonly uses absolute directions in circumstances where English speakers might use these relative terms.", "children": ["The contrast motivates asking whether habitual language use relates to nonverbal spatial coding, rather than merely comparing two ways of giving spoken directions."]}, {"text": "**A direction can stay fixed when a person turns.** Absolute coding differs from coding an object as being on the viewer's left.", "children": ["The language comparison concerns preferred spatial descriptions. It does not imply that speakers of either language are incapable of learning another frame."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 32}, "m3-review-p033": {"status": "ready", "blocks": [{"text": "**Tzeltal's uphill and downhill terms function as an absolute directional system.** Their historical connection to a slope does not mean that each use simply points to the nearest visible hill. A direction is retained as a stable spatial reference rather than being recalculated from the speaker's current left and right.", "children": ["This allows positions to be described consistently as the speaker changes orientation."]}, {"text": "**A landmark origin and an absolute use are different properties.** A historically landscape-based term can become a stable directional reference.", "children": ["The contrast is with a description that depends entirely on the current viewpoint. The relevant feature is how the reference behaves across changes in location and orientation."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 33}, "m3-review-p034": {"status": "ready", "blocks": [{"text": "**The chips task separates relative from absolute spatial memory by rotating the participant 180 degrees.** A participant sees a configuration, waits, and then chooses its match at a second table. A relative response preserves the arrangement with respect to the person's viewpoint. An absolute response preserves its orientation in the environment, so the two responses diverge after rotation.", "children": ["Dutch speakers predominantly gave relative responses, while Tzeltal speakers gave more absolute responses. The association is consistent with their preferred linguistic frames but does not isolate language from all other experience."]}, {"text": "**The rotation makes two otherwise similar descriptions predict different choices.** The nonverbal response reveals a preferred spatial coding strategy.", "children": ["The north arrow stays fixed while the person changes orientation. Red bars represent relative choices and blue bars absolute choices, showing different response distributions across the two language groups."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 34}, "m3-review-p035": {"status": "ready", "blocks": [{"text": "**Spatial inference can combine relations learned in different displays.** Participants learn the relation between two objects, rotate to another display, and learn a second relation involving a shared object. They then place an object relative to another using the combined information. Relative and absolute coding lead to different placements because the person's orientation has changed.", "children": ["Dutch and Tzeltal response patterns again differ in the direction associated with their preferred spatial frames."]}, {"text": "**The task goes beyond reproducing one remembered arrangement.** It asks whether a frame is used when combining spatial relations to make an inference.", "children": ["The cube appears in both learning displays, linking the cone and cylinder relations. The final placement distinguishes a viewer-relative inference from one preserving environmental direction."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 35}, "m3-review-p036": {"status": "ready", "blocks": [{"text": "**Testing conditions could contribute to the apparent language-group difference.** Li and Gleitman noted that Tzeltal participants had been tested with visible, familiar outdoor landmarks, unlike many laboratory participants. An environment with useful landmarks can encourage landmark-based coding. A windowless laboratory can make viewer-relative descriptions more convenient.", "children": ["Manipulating landmark availability within English speakers tests whether the behavior can change without changing native language."]}, {"text": "**A language comparison can be confounded with a setting comparison.** The environment must be considered before assigning the entire difference to linguistic structure.", "children": ["The critical contrast is access to spatial cues, not simply the label “laboratory.” Windows, outdoor views and familiar surroundings can alter which references are useful."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 36}, "m3-review-p037": {"status": "ready", "blocks": [{"text": "**English speakers' preference for relative coding weakened when external landmarks were available.** They strongly preferred relative responses with the blinds down, but the preference was less pronounced with a street view or outdoors. The manipulation changes the spatial information available while keeping the language group the same.", "children": ["This demonstrates that task context can influence the response. It challenges an explanation in which language alone fixes the chosen frame."]}, {"text": "**Spatial strategy is sensitive to the testing environment.** A within-language change helps reveal a potential confound in a between-language comparison.", "children": ["A reduced relative preference is not necessarily a complete switch to absolute coding. Describe the observed change in preference without exaggerating it into an all-or-none reversal."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 37}, "m3-review-p038": {"status": "ready", "blocks": [{"text": "**Levinson and colleagues argued that the simplified task could make the experimenter's purpose too obvious.** Low memory demands and short time or distance between displays may encourage a deliberate strategy about rotation. Participants who infer what is being tested can alter their response for reasons different from habitual spatial coding.", "children": ["The response therefore focuses on memory load and task transparency, rather than denying that landmarks can ever matter."]}, {"text": "**Changing a task can change the process it measures.** A landmark effect in an easy, transparent task may not settle how people habitually remember spatial relations.", "children": ["The proposed alternative is a demand-characteristic explanation. Participants' interpretation of the experiment may influence the response independently of their normal coding preference."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 38}, "m3-review-p039": {"status": "ready", "blocks": [{"text": "**Categorical perception can be tested by varying a sign feature continuously.** The hand-configuration continuum moves between forms while the observer's identification and discrimination responses are measured. One continuum crosses a phonemic distinction between PLEASE and SORRY. The allophonic comparison varies hand configuration without the same change in sign identity.", "children": ["A sharp identification boundary accompanied by better discrimination near that boundary would indicate category-sensitive perception."]}, {"text": "**The test distinguishes a physical change from a linguistically meaningful category change.** Both continua vary visually, but only one crosses the relevant contrast.", "children": ["The stimulus sequences progress through intermediate hand configurations. Comparing equal-sized changes within and across a linguistic boundary is more informative than comparing only the two endpoints."]}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 39}, "m3-review-p040": {"status": "ready", "blocks": [{"text": "**Deaf signers show a sharper categorical boundary for phonemic than allophonic hand-configuration changes.** In the phonemic condition, identification shifts steeply around stimuli 4–6. Discrimination is also strongest near the phonemic boundary. Comparable physical steps are easier to distinguish when they cross that category boundary.", "children": ["The allophonic identification function is shallower and lacks the same localized discrimination peak. This links the perceptual pattern to linguistic contrast rather than any visible hand change."]}, {"text": "**The combination of a sharp identification shift and a boundary-related discrimination peak supports categorical perception.** Identification alone would provide a less complete test.", "children": ["The top plots show categorization and the lower plots discrimination. Compare the position of the steep change with the discrimination peak in the phonemic column."]}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 40}, "m3-review-p041": {"status": "ready", "blocks": [{"text": "**Signed-language comprehension recruits classical language regions and shows left lateralization, as spoken-language comprehension does.** Inferior frontal and posterior superior temporal regions are part of this overlap. Signing also engages visual and superior parietal regions relevant to its perceptual and spatial demands.", "children": ["The combination suggests both common language organization and modality-related contributions. Similarity does not require identical activation everywhere."]}, {"text": "**Different sensory inputs can engage overlapping language networks.** The additional visual and spatial activity reflects the demands of processing a signed signal.", "children": ["The figure compares deaf signers, hearing signers and hearing audiovisual-speech participants. Hearing signers are particularly useful because signing experience is not restricted to people who are deaf."]}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 41}, "m3-review-p042": {"status": "ready", "blocks": [{"text": "**Signed languages have linguistic form, grammar and language-related neural organization.** Contrastive sign features can produce categorical perception, and comprehension recruits posterior superior temporal language regions. Signing experience is associated with changes in motion lateralization. Deafness is associated with enhanced peripheral attention in the reported comparison.", "children": ["These findings jointly show that linguistic experience and sensory history contribute in different ways."]}, {"text": "**A coherent account must separate shared language organization from sensory adaptations.** Neither “sign is just gesture” nor “modality makes no difference” captures the evidence.", "children": ["The summary combines behavioral category evidence, group comparisons and neural contrasts. Each addresses a different question, so one result should not be used as if it established all the others."]}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 42}, "m3-review-p043": {"status": "ready", "blocks": [{"text": "**The exercise hypothesis proposes that early language use preserves language-learning capacity, while the maturational-state hypothesis allows capacity to decline despite early use.** Both assume an early advantage, but they differ in what early successful experience protects. Later second-language difficulty in people who already acquired a first language is more directly compatible with maturation than with complete preservation through exercise.", "children": ["This does not make early first-language experience unimportant. Early access and age-related change address related but distinct questions."]}, {"text": "**A late L2 learner has already exercised language capacity.** That history is what makes late-L2 outcomes informative for distinguishing the two proposals.", "children": ["The two text panels differ in the condition attached to decline. The exercise account includes preservation through use, while the maturational-state account predicts decline with maturation itself."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 43}, "m3-review-p044": {"status": "ready", "blocks": [{"text": "**Mayberry, Lock and Kazmi compared later language learning after different early-language histories.** Deaf individuals without accessible early language performed worse than those who had acquired an early spoken or signed language. Children first exposed to ASL at ages 9–15 had particular difficulty when it was also their first language. Those who had first learned a spoken language did much better, and the differences persisted.", "children": ["The comparison distinguishes late first-language learning from late acquisition of an additional language."]}, {"text": "**Age of starting ASL is not the same as age of first language access.** Earlier linguistic experience can support learning a new language later.", "children": ["The bars separate no-early-language groups from early spoken or signed language groups. The contrast concerns access to language, not a simple superiority of speech over signing."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 44}, "m3-review-p045": {"status": "ready", "blocks": [{"text": "**Semantic blocking effects must be separated from visual-recognition difficulty.** Objects from one semantic category could resemble one another visually, creating a potential confound in naming. The materials were normed so that same-category items were not more visually similar on average. A separate visual-similarity manipulation also produced a different time course.", "children": ["Visual blocking affected the first block, whereas the semantic pattern of interest developed differently. This weakens a purely visual explanation."]}, {"text": "**A control is informative when it tests the alternative mechanism directly.** Matching appearance and manipulating visual similarity provide complementary evidence.", "children": ["The comparison concerns when interference appears across repetitions. A difference in time course helps distinguish visual recognition from the proposed lexical contribution."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 45}, "m3-review-p046": {"status": "ready", "blocks": [{"text": "**Belke and colleagues presented four objects simultaneously but required their names in sequence.** This tests whether the absence of an effect in another simultaneous-display study depended on presentation format. Displaying all objects at once reduces dependence on a succession of isolated pictures. Serial naming still requires selecting and producing one label after another.", "children": ["Eye tracking provides additional timing information about the processing of each object."]}, {"text": "**Separating display timing from naming order helps locate the source of interference.** Simultaneous visibility does not remove the need for sequential lexical selection.", "children": ["The four pictured animals are visible together. The instruction concerns producing their names in order, rather than choosing only one target from the display."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 46}, "m3-review-p047": {"status": "ready", "blocks": [{"text": "**Eye movements and speech onsets provide different timing measures during serial naming.** Gaze duration records how long the eyes remain on an object, while eye–speech lag concerns the interval between leaving it and beginning its spoken name. A participant can move the eyes toward the next object before articulating the current one. The measures therefore separate overlapping parts of preparation.", "children": ["Different blocking effects on these measures can help constrain the processing stage affected."]}, {"text": "**One total naming time can conceal several processes.** Coordinating eye and speech measures reveals where a condition begins to change performance.", "children": ["The GD boxes represent gaze durations and the lag boxes extend toward articulatory onset. The timeline shows why looking at an object and speaking its name are not the same event."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 47}, "m3-review-p048": {"status": "ready", "blocks": [{"text": "**Semantic blocking increases gaze duration after the first presentation cycle, but not overall speech duration or eye–speech lag.** The measures therefore do not show a uniform slowdown. Speech duration decreases with repetition without a blocking difference. Gaze duration shows the condition difference after the first cycle.", "children": ["The nonsignificant lag difference should not be reported as evidence for a reversed effect. The reported pattern is interpreted as supporting a contribution at lemma selection rather than articulation or phonological encoding."]}, {"text": "**The location of the effect across measures matters more than a general statement that naming is slower.** Its time course and selectivity constrain the proposed mechanism.", "children": ["HOM and HET compare homogeneous and heterogeneous contexts. The three panels correspond to speech duration, gaze duration and lag, so their vertical scales describe different measurements."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 48}, "m3-review-p049": {"status": "ready", "blocks": [{"text": "**McMurray and colleagues tested whether fine phonetic information affects lexical competition.** Participants heard a /b/–/p/ continuum while viewing pictures including BEAR and PEAR, with eye movements recorded. **Voice onset time**, or VOT, varies the timing between release and voicing. It can change how strongly the sound supports /b/ or /p/.", "children": ["A thresholded account would pass a completed categorical decision onward. A cascaded account allows graded information to influence word candidates before uncertainty is fully resolved."]}, {"text": "**The critical test is whether within-category differences influence lexical responses.** A binary final choice alone may hide that information.", "children": ["The visual-world display includes a target, a phonetic competitor and unrelated fillers. Looking at the competitor is informative because its name overlaps with the heard word near the manipulated contrast."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 49}, "m3-review-p050": {"status": "ready", "blocks": [{"text": "**Participants selected the picture that best matched the spoken item.** Their BEAR–PEAR choices produced a typical step-like identification function across VOT. Shorter VOTs favored the /b/ response and longer VOTs the /p/ response. Near the boundary, the preferred category changed rapidly.", "children": ["A categorical-looking final response does not establish that all earlier lexical activation was categorical."]}, {"text": "**A forced choice can end in one category even when processing used graded evidence.** Eye movements provide a separate measure of that processing.", "children": ["The horizontal axis is VOT in milliseconds and the vertical axis is proportion of /p/ responses. The steep transition is around 17.5 ms in the displayed function."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 50}, "m3-review-p051": {"status": "ready", "blocks": [{"text": "**Competitor looks vary with phonetic ambiguity even within a chosen category.** Tokens closer to the /b/–/p/ boundary produce more competition than clear tokens farther from it. A participant can ultimately select BEAR while spending more time looking at PEAR when the sound is close to the boundary.", "children": ["This supports the claim that fine phonetic information remains relevant to lexical activation, rather than disappearing completely after a categorical phoneme decision."]}, {"text": "**Final identification and moment-by-moment competition reveal different aspects of processing.** A sharp choice boundary can coexist with graded lexical uncertainty.", "children": ["The gaze curves group trials by VOT and final response. The effect concerns looks to the unchosen competitor, not merely how often participants click the wrong picture."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 51}, "m3-review-p052": {"status": "ready", "blocks": [{"text": "**Competitor fixation increases as a token approaches the category boundary from either side.** For BEAR responses, more /p/-like VOT increases looks to PEAR. For PEAR responses, more /b/-like VOT increases looks to BEAR. The graph separates early and late observation windows. The gradient remains visible in the later competition measure, supporting continued sensitivity to within-category phonetic detail.", "children": ["The result favors cascaded use of graded evidence over a model that transmits only a completed phoneme label with all within-category detail discarded."]}, {"text": "**The relevant predictor is distance from the boundary, not only which side of it the token occupies.** Similar final choices can still have different lexical-competition profiles.", "children": ["The left and right halves plot different final-response categories and their corresponding competitors. Early is 300–1100 ms and late is 1100–1900 ms, so the line types distinguish time windows rather than two participant groups."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 52}}}, {"id": "original-c-v2", "label": "Original C · Version 2", "scripts": {"m3-reading1-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 1}, "m3-reading1-p002": {"status": "ready", "blocks": [{"text": "**Phonemes are speech-sound categories, not letters.** A writing system represents language, but its symbols do not have to correspond one-to-one with those categories.", "children": ["A letter can contribute to different pronunciations, and a phoneme can be represented by different spellings."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 2}, "m3-reading1-p003": {"status": "ready", "blocks": [{"text": "**Orthographic depth** describes how consistently spelling corresponds to pronunciation. English is relatively deep because many spellings do not transparently specify their sounds.", "children": ["COLONEL and PARADIGM make the problem concrete. Applying common letter–sound patterns can produce a plausible-looking pronunciation that is wrong for the actual word."]}, {"text": "In shallower writing systems, such as Finnish and Korean, spelling–sound correspondences are more predictable. The comparison concerns the writing system, not the intelligence or ability of its readers.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 3}, "m3-reading1-p004": {"status": "ready", "blocks": [{"text": "**Finnish has a shallow orthography.** Letters correspond relatively unambiguously to phonemes, so learning a spelling–sound correspondence helps with many different words.", "children": ["Doubled letters represent a meaningful length distinction. A doubled consonant is geminated, and a doubled vowel is long."]}, {"text": "This regularity helps Finnish children learn decoding quickly. Decoding means generating a pronunciation from a written form, whether or not its meaning is familiar.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 4}, "m3-reading1-p005": {"status": "ready", "blocks": [{"text": "**Pseudoword reading tests decoding.** Because a pseudoword is not a familiar stored word, the child must generalize from learned spelling–sound patterns.", "children": ["The comparison involves Grade 1 children learning different alphabetic writing systems. Children learning many other languages produce plausible pseudoword pronunciations more successfully than English learners."]}, {"text": "English's less predictable correspondences help explain why decoding develops more slowly. This task does not measure the child's entire language ability.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 5}, "m3-reading1-p006": {"status": "ready", "blocks": [{"text": "**Korean writing represents sound structure systematically.** Related phonemes can have related written shapes, so the visual forms themselves reflect aspects of phonological organization.", "children": ["The letters are arranged into syllable blocks with initial, medial and sometimes final positions. Those positions are not three unrelated pictures of whole words."]}, {"text": "The velar consonant forms share the basic angular ㄱ shape. Additional strokes or doubling distinguish related consonants.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 6}, "m3-reading1-p007": {"status": "ready", "blocks": [{"text": "**GLORP, SPLING, JONK, FEESH and QUISP can be pronounced without being familiar words.** Their forms follow enough English spelling patterns for a reader to construct a plausible pronunciation.", "children": ["Success cannot depend on retrieving a stored pronunciation for each particular item. The reader is using knowledge that generalizes across words."]}, {"text": "The demonstration establishes generalization. By itself, it does not decide whether that knowledge consists of categorical rules or learned statistical patterns.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 7}, "m3-reading1-p008": {"status": "ready", "blocks": [{"text": "**Pseudoword decoding is fast and largely automatic.** In the Lupker, Brown and Colombo example, naming pseudowords is only about 5–12% slower than naming low-frequency real words.", "children": ["Participants read the items aloud, and naming time measures how quickly a pronunciation becomes available. The small difference shows that unfamiliarity does not make pronunciation an entirely slow, deliberate process."]}, {"text": "Both rules and statistical generalization might produce efficient decoding. The speed result constrains a theory without selecting one architecture on its own.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 8}, "m3-reading1-p009": {"status": "ready", "blocks": [{"text": "**An unfamiliar spelling can support more than one plausible pronunciation.** VONTH, PHANGE, STREAD and SOUGH contain patterns whose pronunciations are not all uniquely determined in English.", "children": ["A response reflects the spelling–sound patterns available from previously learned words. Different familiar patterns can favor different responses to the same novel form."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 9}, "m3-reading1-p010": {"status": "ready", "blocks": [{"text": "**STREAD can plausibly be pronounced with either /ɛ/ or /i/.** The same written sequence can resemble more than one learned spelling–sound pattern.", "children": ["Testing novel items reveals what a reader has generalized, because the particular word cannot simply have been memorized."]}, {"text": "The challenge for a categorical rule account is to explain why multiple outputs seem acceptable. A statistical account can represent differing support for alternative pronunciations.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 10}, "m3-reading1-p011": {"status": "ready", "blocks": [{"text": "**The regularity effect is the difficulty of reading words whose pronunciation conflicts with common spelling–sound patterns.** PINT, ACHE and CHOIR are examples of words for which straightforward decoding can mislead.", "children": ["A strict regular–irregular division is less clear when a spelling neighborhood contains several pronunciations. ROLL, POLL and TOLL support one pattern, while DOLL differs."]}, {"text": "COOK, TOOK and BOOK likewise contrast with SPOOK. These neighborhoods motivate asking how much support a pronunciation has from similar words.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 11}, "m3-reading1-p012": {"status": "ready", "blocks": [{"text": "**Sublexical information concerns units smaller than a whole word.** Rapid nonword reading and the advantage for typical spelling–sound patterns show that readers use this information.", "children": ["**Lexical information** concerns knowledge of particular words. A complete account must explain how experience with a specific word contributes alongside general spelling patterns."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 12}, "m3-reading1-p013": {"status": "ready", "blocks": [{"text": "**Word knowledge can help identify an ambiguous letter.** In an interactive activation network, visual features activate letters and letters activate candidate words.", "children": ["Activated word candidates send feedback to their constituent letters. A letter supported by a plausible word receives additional activation even when its local visual evidence is unclear."]}, {"text": "Competing candidates do not remain equally active. Their activation changes as the network settles on an interpretation.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 13}, "m3-reading1-p014": {"status": "ready", "blocks": [{"text": "**Feedback carries word-level activation back to letters.** A partially activated known word increases activation of the letters that belong to it.", "children": ["This makes recognition interactive. Information does not flow only from isolated features upward to a finished word."]}, {"text": "The mechanism helps explain why an ambiguous letter can become easier to recognize when it appears in a familiar word context.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 14}, "m3-reading1-p015": {"status": "ready", "blocks": [{"text": "**Lexicality and word frequency reveal effects of word-specific experience.** Real words are generally named faster than pseudowords, and frequently encountered words are named faster than less frequent words.", "children": ["Lexicality compares whether the item is a word. Frequency compares how often a particular word has been encountered."]}, {"text": "The English Lexicon Project data show that the frequency effect occurs across many observations, rather than depending on a few unusually easy examples.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 15}, "m3-reading1-p016": {"status": "ready", "blocks": [{"text": "**Multiple regression tests whether frequency predicts reading time after accounting for other word properties.** Length and sound-related characteristics could otherwise be mistaken for effects of frequency.", "children": ["The analysis uses about 3,000 words read by young and older adults. Frequency still contributes when other predictors are considered."]}, {"text": "This makes a simple length-confound explanation less plausible. It does not turn an observational predictor into an experimentally isolated cause.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 16}, "m3-reading1-p017": {"status": "ready", "blocks": [{"text": "**Frequency and regularity interact.** Low-frequency exception words are slowed much more than low-frequency regular words, whereas high-frequency words show a much smaller regularity difference.", "children": ["Naming latency is the time needed to begin saying the word. Higher values mean slower responses."]}, {"text": "An interaction means the effect of one factor depends on the other. The regularity cost is not a fixed amount added equally to high- and low-frequency words.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 17}, "m3-reading1-p018": {"status": "ready", "blocks": [{"text": "**A dual-route interpretation separates lexical retrieval from sublexical decoding.** The lexical process supplies the learned pronunciation of a particular word, while decoding computes pronunciation from spelling units.", "children": ["For a high-frequency word, lexical information becomes available quickly enough to reduce the influence of the decoding output."]}, {"text": "For a low-frequency exception, the lexical response is less efficient and the regularized decoding output can interfere. Nonwords depend on decoding because they lack a stored whole-word entry.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 18}, "m3-reading1-p019": {"status": "ready", "blocks": [{"text": "**Acquired phonological dyslexia involves disproportionate difficulty reading pseudowords after brain injury.** Familiar words can remain relatively well read even when novel forms are difficult.", "children": ["Cacciopo van Vliet and colleagues compare real-word reading with several nonword tasks. The patients can often recognize and pronounce known words while struggling to generate a plausible pronunciation for an unfamiliar spelling."]}, {"text": "The selective difficulty suggests that familiar-word success and novel-form decoding do not rely on every process to the same degree.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 19}, "m3-reading1-p020": {"status": "ready", "blocks": [{"text": "**Acquired surface dyslexia involves disproportionate difficulty reading irregular words after brain injury.** Errors often regularize the word by applying a more common spelling–sound pattern.", "children": ["DEAF pronounced like “deef” and SHOE pronounced like “show” illustrate regularization. The response is related to the spelling, but it is not the target word's learned pronunciation."]}, {"text": "Relatively good regular-word and nonword reading shows that generating pronunciation from spelling can remain useful despite difficulty with exceptions.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 20}, "m3-reading1-p021": {"status": "ready", "blocks": [{"text": "**A double dissociation compares opposite relative impairments.** Phonological dyslexia particularly affects pseudowords, while surface dyslexia particularly affects exception words.", "children": ["The first pattern shows that unfamiliar decoding can be difficult despite relatively preserved familiar-word reading. The second shows that exception reading can be difficult despite relatively preserved pseudoword reading."]}, {"text": "Together, the patterns are harder to explain by saying that one task is simply harder for everyone.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 21}, "m3-reading1-p022": {"status": "ready", "blocks": [{"text": "**A double dissociation challenges a single fixed difficulty ranking.** If task A were merely harder than task B, damage might consistently hurt A more, but it would not readily explain another patient showing the reverse pattern.", "children": ["The reversal suggests that the tasks depend differently on underlying processes. For reading, pseudowords and exception words place different demands on the system."]}, {"text": "The evidence still requires a theory of what those underlying processes are. It does not uniquely identify a particular set of boxes in a model.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 22}, "m3-reading1-p023": {"status": "ready", "blocks": [{"text": "**A dual-route model attributes phonological dyslexia to damage in grapheme–phoneme conversion and surface dyslexia to damage in lexical processing.** These proposed locations connect the task dissociation to specific mechanisms.", "children": ["Damage to conversion particularly affects nonwords because there is no familiar whole-word pronunciation to retrieve."]}, {"text": "Damage to input or output word representations, called logogens in this account, or their connections makes exceptions vulnerable because general decoding supplies the wrong pronunciation.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 23}, "m3-reading1-p024": {"status": "ready", "blocks": [{"text": "**Patterson's discussion shows why reading errors can complicate a clean lexical–nonlexical division.** Errors attributed to a purely nonlexical route can still show lexical influences.", "children": ["The example “incense” read as “increase” is a real-word response. A simple letter–sound mistake could instead produce a nonword, so the actual response raises a question about whole-word influence."]}, {"text": "Possible responses are to allow a more complicated combination of routes or to revise the supposedly nonlexical process itself. The observation motivates refinement rather than settling the issue alone.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 24}, "m3-reading2-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 1}, "m3-reading2-p002": {"status": "ready", "blocks": [{"text": "**Dual-route models distinguish a lexical route from a sublexical route.** Lexical processing uses knowledge of particular words, while grapheme–phoneme conversion generates pronunciation from spelling units.", "children": ["A model must explain fast pseudoword reading, faster familiar-word reading, frequency effects, regularity effects and their interaction."]}, {"text": "It must also explain why pseudoword and exception-word reading can be differently impaired after brain injury. These observations motivate the architecture but do not uniquely prove it.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 2}, "m3-reading2-p003": {"status": "ready", "blocks": [{"text": "**The Dual Route Cascaded model, or DRC, combines interactive lexical processing with a separate grapheme–phoneme rule system.** The two routes can contribute activation toward a spoken response.", "children": ["The lexical portion includes orthographic and phonological lexicons, representing written and spoken word forms. These representations are distinguished from meanings."]}, {"text": "The implementation described here does not implement semantics. The GPC rule system also has processing assumptions different from those of the interactive lexical network.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 3}, "m3-reading2-p004": {"status": "ready", "blocks": [{"text": "**The DRC's grapheme–phoneme conversion rules operate serially, letter by letter.** Their operation is not adjusted by word frequency and receives no lexical feedback.", "children": ["The GPC and lexical routes do not interact throughout their internal computations. They converge in the phoneme response buffer."]}, {"text": "If the routes favor different phonemes, they can compete at that shared output. An exception word can therefore receive a correct lexical pronunciation and an incompatible regularized pronunciation.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 4}, "m3-reading2-p005": {"status": "ready", "blocks": [{"text": "**GPC rules map written units onto phonemes.** Some rules concern individual letters, while others concern several letters or a particular letter context.", "children": ["A model also needs a way to decide which applicable rule takes priority. A larger-unit rule can supersede rules for its individual letters."]}, {"text": "Context-sensitive rules restrict a pronunciation to specified surrounding letters or positions. This makes the procedure more than a simple lookup of one sound per letter.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 5}, "m3-reading2-p006": {"status": "ready", "blocks": [{"text": "**A categorical rule does not express the strength of the evidence behind it.** The DRC can choose a mapping because it is frequent, yet treat that mapping as a fixed rule during processing.", "children": ["The possible pronunciations of OUGH have more divided statistical support than those of EIGH. A rule can still operate categorically for both spellings."]}, {"text": "A probabilistic account instead allows alternatives to receive different strengths of support. The distinction concerns processing, not whether the model designer ever consulted frequency information.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 6}, "m3-reading2-p007": {"status": "ready", "blocks": [{"text": "**The DRC's simple rules are intended to explain systematic human errors as well as correct reading.** More finely tuned rules might pronounce more exceptions correctly but remove behavior the model is meant to explain.", "children": ["A regularizing route helps account for errors in surface dyslexia and for slow naming of low-frequency exception words."]}, {"text": "The theory therefore claims that people's sublexical computation is constrained, rather than assuming that the best possible spelling algorithm is the correct cognitive model.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 7}, "m3-reading2-p008": {"status": "ready", "blocks": [{"text": "**Informational encapsulation means that a process does not freely use every source of relevant knowledge.** In the dual-route account, GPC conversion proceeds without consulting whole-word meaning or lexical feedback.", "children": ["This resembles a modular parsing proposal in which an early syntactic process follows structural principles without immediately using world knowledge."]}, {"text": "Pseudoword naming exposes the conversion procedure because a familiar lexical entry is unavailable. Regularization errors expose it when conversion favors the wrong pronunciation.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 8}, "m3-reading2-p009": {"status": "ready", "blocks": [{"text": "**The DRC is evaluated against many reading phenomena.** These include frequency, lexicality, regularity, interactions, lexical decision and patterns in acquired dyslexia.", "children": ["Accounting for several effects with one architecture is stronger than fitting a single result. It also requires examining which assumptions stay fixed and which are changed between tasks."]}, {"text": "The model's research strategy places strong weight on human behavioral evidence as a constraint on architecture.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 9}, "m3-reading2-p010": {"status": "ready", "blocks": [{"text": "**Lexical decision requires deciding whether a written item is a word.** The DRC simulation adds decision criteria to the activation produced by its recognition system.", "children": ["A “yes” response can depend on a strongly activated single word or on total activity across the orthographic lexicon. A “no” response occurs if the criteria are not met by a deadline."]}, {"text": "The implementation also changes inhibition and uses time-dependent thresholds. These choices help obtain a fit, but they add assumptions beyond the basic two-route diagram.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 10}, "m3-reading2-p011": {"status": "ready", "blocks": [{"text": "**The DRC routes are modular in several related senses.** They use different processing assumptions, restrict information exchange and accept particular kinds of input.", "children": ["The GPC system takes letters as input and sends phoneme activation toward the response system. This is **domain specificity** in the account."]}, {"text": "The absence of lexical feedback into the GPC system is **informational encapsulation**. Having two pathways alone would not establish those stronger restrictions.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 11}, "m3-reading2-p012": {"status": "ready", "blocks": [{"text": "**PDP models treat reading as learned mappings among orthography, phonology and semantics.** Orthography is spelling, phonology is sound structure, and semantics is meaning.", "children": ["Seidenberg and McClelland trained an associative network to map spelling onto pronunciation. The modeled spelling-to-sound pathway used one learned mapping for different kinds of words."]}, {"text": "Reading skill emerges from learning rather than being specified entirely as a hand-built list of rules and lexical entries.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 12}, "m3-reading2-p013": {"status": "ready", "blocks": [{"text": "**In a PDP account, rules are generalizations learned across words.** Whole-word knowledge is distributed across learned mappings instead of being stored only in a distinct lexical route.", "children": ["The same learning mechanism can capture both patterns shared by many words and information specific to a familiar word."]}, {"text": "The research strategy asks whether domain-general learning can explain reading. This contrasts with choosing separate adult processing components primarily from neuropsychological dissociations.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 13}, "m3-reading2-p014": {"status": "ready", "blocks": [{"text": "**A learned network can produce a frequency-by-regularity interaction without separate frequency and rule mechanisms.** Regular words receive support from patterns shared across many words.", "children": ["An exception conflicts with those patterns, so learning its particular mapping is especially important. Frequent exposure strengthens that word-specific mapping."]}, {"text": "A low-frequency exception has both weak item-specific learning and poor support from the dominant pattern. This combination creates a larger disadvantage than either factor alone.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 14}, "m3-reading2-p015": {"status": "ready", "blocks": [{"text": "**Consistency describes how many similar spellings support a pronunciation.** “Friends” have the relevant spelling pattern and a compatible pronunciation, while “enemies” support a competing pronunciation.", "children": ["LATE and DUST illustrate consistent patterns. GAVE and MINT have many friends but also enemies such as HAVE and PINT."]}, {"text": "DOWN versus KNOWN and POUR versus SOUR illustrate ambiguity. An exception such as PINT has relatively little support compared with its competing neighborhood.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 15}, "m3-reading2-p016": {"status": "ready", "blocks": [{"text": "**A PDP model can pronounce nonwords using the weights learned from real words.** A new spelling activates patterns that overlap with familiar spellings, allowing the network to generalize.", "children": ["No stored entry for the particular nonword is required. The same learned correspondences that support consistent words can support a new combination."]}, {"text": "This is a proposed mechanism for decoding without a separate GPC rule module.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 16}, "m3-reading2-p017": {"status": "ready", "blocks": [{"text": "**Poor nonword performance can challenge either a theoretical proposal or a particular implementation.** The early model's nonword accuracy was weaker than desired.", "children": ["One possibility is that a single associative mechanism cannot explain the task. Another is that the chosen representations fail to capture the similarities needed for generalization."]}, {"text": "Improving the implementation while retaining the theoretical mechanism helps distinguish these possibilities.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 17}, "m3-reading2-p018": {"status": "ready", "blocks": [{"text": "**Generalization depends on how sound similarity is represented.** The early Seidenberg–McClelland model used Wickelfeatures, whose representation of phonology was problematic for nonword reading.", "children": ["Plaut and colleagues improved the phonological representations and obtained better nonword performance. This supports a representational explanation for at least part of the earlier failure."]}, {"text": "Behavioral relations between phonological processing and decoding also make phonology a relevant target for explanation.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 18}, "m3-reading2-p019": {"status": "ready", "blocks": [{"text": "**A network generalizes through similarity.** If its phonological representation poorly captures similarities among words, the learned mapping cannot transfer as effectively to new forms.", "children": ["A familiar word can retain support from its own training history. A nonword lacks that item-specific experience and depends more heavily on generalization."]}, {"text": "This produces a reason for unfamiliar forms to be especially vulnerable to poor representations without requiring a dedicated nonword mechanism.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 19}, "m3-reading2-p020": {"status": "ready", "blocks": [{"text": "**Harm and Seidenberg manipulated noise in phonological representations.** Increasing noise makes the sound representations less reliable while keeping the model's general learning framework.", "children": ["The manipulation produced poorer nonword decoding and relative sparing of word recognition. It also linked the severity of the phonological deficit to the degree of decoding difficulty."]}, {"text": "The model therefore connects a reading pattern to the quality of a more general phonological system.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 20}, "m3-reading2-p021": {"status": "ready", "blocks": [{"text": "**Damaging semantic support in a triangle model can impair exception-word reading especially strongly.** Plaut and colleagues added a simplified semantic contribution and examined what happened when it was lesioned.", "children": ["An exception has weak support from typical spelling–sound regularities. Meaning-related support can help produce its learned pronunciation."]}, {"text": "Reducing that support creates a surface-dyslexia-like pattern without defining a separate exception-word list as the sole explanation.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 21}, "m3-reading2-p022": {"status": "ready", "blocks": [{"text": "**The triangle model's pathways share graded learning assumptions and interact during learning.** Semantic representations are directly involved rather than replaced by a lexicon defined as independent of meaning.", "children": ["Spelling-to-sound learning develops in the presence of meaning-related support. The contribution of one pathway therefore affects what another pathway learns."]}, {"text": "This allows graded impairments. Phonological dyslexics can make some exception errors, and surface dyslexics can make some nonword errors.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 22}, "m3-reading2-p023": {"status": "ready", "blocks": [{"text": "**Woollams and colleagues tested the predicted association between semantic ability and exception-word reading.** Lower semantic scores were associated with poorer low-frequency exception reading in patients with semantic dementia.", "children": ["The model and patient panels show comparable overall relationships, although individual patients vary. This supports an association between meaning and exceptional pronunciation."]}, {"text": "The finding is informative because it links a reading weakness to a broader semantic measure rather than describing only a reading-task dissociation.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 23}, "m3-reading2-p024": {"status": "ready", "blocks": [{"text": "**Some patients have relatively good exception reading despite low semantic scores.** These cases challenge a perfect one-to-one relationship, but an account of graded association does not predict zero variability.", "children": ["Woollams and colleagues interpret such observations in relation to the full distribution rather than treating each outlier as an automatic refutation."]}, {"text": "The scientific issue is whether the unusual cases show a stable separate pattern or arise within a noisy overall association.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 24}, "m3-reading2-p025": {"status": "ready", "blocks": [{"text": "**Longitudinal observations track whether semantic and reading abilities change together within a patient.** Because semantic dementia progresses, repeated testing can reveal a trajectory rather than a single unusual score.", "children": ["In most cases, declining semantic ability accompanies declining exception-word reading. Some initially unusual observations move closer to the broader relation on retesting."]}, {"text": "This strengthens the association while leaving room for variability between individuals.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 25}, "m3-reading2-p026": {"status": "ready", "blocks": [{"text": "**Coltheart and colleagues generated 40,000 model patients with different lexical-route and GPC impairment levels.** For each real patient, they selected the model run that best matched the observed data.", "children": ["This produced an excellent fit to the patient scores. The selection procedure is part of how that fit was achieved."]}, {"text": "The fit should be distinguished from predicting each patient's pattern before choosing among many possible parameter combinations.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 26}, "m3-reading2-p027": {"status": "ready", "blocks": [{"text": "**A better fit can be less informative if it relies on much greater flexibility.** Selecting the best match from many parameter combinations can reproduce a dataset without strongly constraining the underlying explanation.", "children": ["The question is not whether close agreement is bad in itself. It is whether the account predicts the relation with principled assumptions or accommodates each case after seeing the outcome."]}, {"text": "Comparing theories therefore requires attention to both fit and how much freedom produced it.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 27}, "m3-reading2-p028": {"status": "ready", "blocks": [{"text": "**Dual-route and triangle models address many of the same findings.** Both must explain rapid nonword decoding, exception difficulty, the frequency–regularity interaction and acquired reading dissociations.", "children": ["Agreement on the phenomena does not mean agreement on mechanisms. One account emphasizes specialized routes, while the other emphasizes learning across interacting representational systems."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 28}, "m3-reading2-p029": {"status": "ready", "blocks": [{"text": "**DRC attributes nonword decoding and regularity effects to GPC rules, while the triangle account attributes them to statistical learning.** Word-specific exposure strengthens learned mappings in the triangle account and affects lexical processing in DRC.", "children": ["For phonological dyslexia, DRC emphasizes GPC damage and the triangle account emphasizes broader phonological impairment."]}, {"text": "For surface dyslexia, DRC emphasizes lexical-route damage and the triangle account emphasizes semantic impairment.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 29}, "m3-reading2-p030": {"status": "ready", "blocks": [{"text": "**A major contrast is whether the explanation begins with separate reading routes or broader language associations.** Dual-route models use different task impairments to motivate independent processes.", "children": ["The statistical-learning account links phonology to spelling–sound generalization and semantics to words whose pronunciation is poorly supported by that generalization."]}, {"text": "Both dissociations and associations matter. A theory should explain selective weaknesses and the related abilities that vary with them.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 30}, "m3-reading2-p031": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 31}, "m3-morphology-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 1}, "m3-morphology-p002": {"status": "ready", "blocks": [{"text": "**Morphology is generative because speakers can form words they have not memorized individually.** Derivational morphology creates a new lexical form, while inflection marks grammatical information such as plural or past tense.", "children": ["The central question is how a speaker extends a familiar pattern to a new item. English plural and past-tense formation provide tractable examples."]}, {"text": "Generalization can also produce playful or incorrect forms. This shows productive use of patterns, rather than a vocabulary containing only previously heard responses.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 2}, "m3-morphology-p003": {"status": "ready", "blocks": [{"text": "**Berko Gleason's wug test measures morphological generalization to a novel word.** A child learns a new label and then supplies an inflected form that has not been provided.", "children": ["The pictured task introduces one WUG and then asks about two. Producing WUGS applies plural knowledge to a new noun."]}, {"text": "The same logic can test past tense using novel verbs. Success shows productive knowledge, but does not by itself distinguish symbolic rules from statistical generalization.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 3}, "m3-morphology-p004": {"status": "ready", "blocks": [{"text": "**Regular past tense follows the productive -ed pattern.** SHOW becomes SHOWED, BAKE becomes BAKED, and a novel verb such as BLICK can become BLICKED.", "children": ["Irregular pairs such as GO–WENT, TAKE–TOOK and EAT–ATE do not follow that default form. Some irregulars share smaller patterns with other verbs."]}, {"text": "A theory must explain both familiar exceptions and productive extension to novel verbs.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 4}, "m3-morphology-p005": {"status": "ready", "blocks": [{"text": "**The Words and Rules account gives regular and irregular inflection different mechanisms.** A symbolic rule generates a regular past tense, while irregular forms are stored in an associative lexical system.", "children": ["The regular process can apply to a new verb because it does not require an entry for that particular past tense."]}, {"text": "The irregular system stores word-specific information and can be influenced by frequency and similarity. A successful explanation also needs to prevent an available irregular form from being replaced by a regularization.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 5}, "m3-morphology-p006": {"status": "ready", "blocks": [{"text": "**The lexicon and grammar offer different ways to produce a past tense.** Lexical retrieval supplies an irregular form such as HELD, while grammatical combination can produce WALK plus -ed.", "children": ["Pinker and Ullman's diagram associates lexical lookup with declarative memory and grammatical combination with procedural processing."]}, {"text": "Like dual-route reading, the account separates word-specific knowledge from a productive operation. Unlike reading aloud, its task is to transform a stem according to a grammatical feature, rather than convert spelling into sound.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 6}, "m3-morphology-p007": {"status": "ready", "blocks": [{"text": "**The Words and Rules proposal was motivated partly by a theory of grammar.** A categorical symbolic grammar describes productive patterns, but language also contains exceptions.", "children": ["Reading dual-route theories were strongly motivated by neuropsychological dissociations. The morphology proposal also reflects a commitment to keeping the grammatical rule system distinct from exceptional lexical information."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 7}, "m3-morphology-p008": {"status": "ready", "blocks": [{"text": "**An associative lexicon handles information that does not fit a categorical rule.** Its representations are word-specific and sensitive to frequency and phonological similarity.", "children": ["KEEP–KEPT, WEEP–WEPT and LEAP–LEAPT illustrate similarity among irregular forms. An exception can belong to a small family rather than being wholly unrelated to other words."]}, {"text": "Assigning these properties to lexical memory lets the rule system remain categorical and general.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 8}, "m3-morphology-p009": {"status": "ready", "blocks": [{"text": "**Rumelhart and McClelland modeled past tense as a learned association between present and past sound patterns.** A single trainable network learns across verbs instead of applying a separately specified -ed rule.", "children": ["The model encodes a root's phonology, transforms that representation through modifiable connections, and decodes an output pattern."]}, {"text": "Regularity is a pattern learned from many examples. Irregular forms are also learned within the same system.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 9}, "m3-morphology-p010": {"status": "ready", "blocks": [{"text": "**U-shaped learning describes an initial success, a decline, and later recovery.** A child may correctly say RAN, later produce RUNNED, and eventually return to RAN.", "children": ["The middle error is a **regularization**, because the child applies the common past-tense pattern to an irregular verb."]}, {"text": "The decline does not necessarily mean that the child has stopped learning. A changing system can generalize more broadly while temporarily disrupting an earlier correct response.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 10}, "m3-morphology-p011": {"status": "ready", "blocks": [{"text": "**The Words and Rules account explains U-shaped learning through changes in the use of rules and lexical exceptions.** Early correct forms can be imitated before a productive rule is available.", "children": ["When the rule is learned, it can be applied too broadly, yielding RUNNED. Later, learned irregulars and the blocking process prevent that regularization."]}, {"text": "This account treats the developmental stages as involving distinguishable processes rather than only gradual changes in one mapping.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 11}, "m3-morphology-p012": {"status": "ready", "blocks": [{"text": "**Changing the training vocabulary can produce U-shaped learning in one network.** Early training emphasizes frequent irregular verbs, allowing those particular mappings to be learned.", "children": ["As more regular verbs enter training, their common pattern changes the network's responses. That generalization can interfere with previously learned irregulars."]}, {"text": "With further learning, the network can recover the irregular responses while retaining broad regularity. No new symbolic rule component is inserted at the point of decline.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 12}, "m3-morphology-p013": {"status": "ready", "blocks": [{"text": "**Testing untrained verbs asks whether the network learned transferable structure.** A real English verb can be novel to a model if it was excluded from that model's training set.", "children": ["The test therefore uses the logic of a wug task even when the items are real words to humans."]}, {"text": "The model can generate many appropriate past-tense features, but feature-level success must be distinguished from producing an entirely correct word.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 13}, "m3-morphology-p014": {"status": "ready", "blocks": [{"text": "**Some model outputs contain changes that are unlike ordinary human regularizations.** Examples include MADE(D)-like changes to MATE and the unusual outputs MEMBLED for MAIL and TOUREDER for TOUR.", "children": ["The model authors acknowledge that people are unlikely to make some of these errors. They suggest that additional output constraints could reduce bizarre responses."]}, {"text": "This separates capturing an overall learning pattern from matching the detailed form of human errors.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 14}, "m3-morphology-p015": {"status": "ready", "blocks": [{"text": "**Prince and Pinker argued that feature representations can blend distinct alternatives.** A model may activate features belonging to several possible past-tense forms without keeping those candidates separate.", "children": ["For SING, partial support for different sound patterns can overlap. Decoding the combined activation can produce a hybrid rather than selecting a coherent word."]}, {"text": "The criticism targets the representation and its treatment of competing outputs, not merely the presence of learning.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 15}, "m3-morphology-p016": {"status": "ready", "blocks": [{"text": "**Joanisse and Seidenberg propose that phonology supports rule-like generalization while semantics especially supports irregular forms.** The same system links speech input, meaning and speech output.", "children": ["Reliable sound representations support extension from familiar present–past pairs to new forms. Irregular mappings receive additional support from the particular word's semantic representation."]}, {"text": "The hypothesis concerns different degrees of dependence on shared systems, rather than a separate symbolic rule route for every regular response.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 16}, "m3-morphology-p017": {"status": "ready", "blocks": [{"text": "**The model aims to explain the dissociation between irregular and nonword past-tense performance.** These tasks differ in how much they depend on learned word-specific information and phonological generalization.", "children": ["A nonword has no familiar item-specific semantic history to support its inflection. A known irregular can require semantic support because its output is not well predicted by the dominant pattern."]}, {"text": "Manipulating phonological or semantic integrity tests whether these different dependencies can produce opposite impairment profiles.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 17}, "m3-morphology-p018": {"status": "ready", "blocks": [{"text": "**The patient pattern associated here with Broca's aphasia includes especially poor nonword past-tense production.** These patients have left anterior injury and difficulty producing speech.", "children": ["Regular forms are also vulnerable, while irregular forms are relatively better in the displayed comparison. A novel BLICK must be transformed without relying on a familiar stored past tense."]}, {"text": "This motivates investigating phonological contributions to the apparent morphological deficit.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 18}, "m3-morphology-p019": {"status": "ready", "blocks": [{"text": "**Phonological impairment reduces past-tense performance most strongly for nonwords in the model.** Regulars are numerically worse than irregulars, but the largest difference concerns novel forms.", "children": ["The model manipulation weakens sound-based computation. Familiar words retain support unavailable to an untrained nonword."]}, {"text": "The similarity to the patient pattern shows how a selective-looking morphological deficit can arise from a broader phonological impairment.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 19}, "m3-morphology-p020": {"status": "ready", "blocks": [{"text": "**Other patient groups show a larger problem with irregular past-tense forms.** The material discusses Wernicke's and Alzheimer's patients and anomic patients with inferior or middle temporal injury.", "children": ["Their irregular performance is lower than their regular and nonword performance in the displayed comparison."]}, {"text": "This creates the other side of the dissociation and motivates examining the information that especially supports known irregular forms.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 20}, "m3-morphology-p021": {"status": "ready", "blocks": [{"text": "**Semantic impairment particularly disrupts irregular past-tense forms.** When the model loses meaning-related support, irregular accuracy falls below regular and nonword accuracy.", "children": ["Typical phonological patterns still support many regular and novel forms. Nonwords can nevertheless be somewhat worse than regular words because they lack item-specific training."]}, {"text": "This shows how unequal dependence on semantics can produce the reverse of the phonological-damage profile.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 21}, "m3-morphology-p022": {"status": "ready", "blocks": [{"text": "**Phonological controls can change the apparent regular–irregular difference.** Bird and colleagues found that the difference in Broca's patients was reduced when items were adequately matched for phonology.", "children": ["Patterson and colleagues found that irregular impairment in semantic dementia correlated with semantic deficit severity."]}, {"text": "These findings connect morphology to phonological and semantic abilities, making a pure rule-versus-word interpretation less straightforward.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 22}, "m3-morphology-p023": {"status": "ready", "blocks": [{"text": "**Phonological representations support learning the common mapping from present to past.** A degraded representation makes that generalization less reliable, especially for new words.", "children": ["Semantic information supports forms that depart from the dominant -ed pattern. Some irregulars also benefit from smaller phonological families and can be relatively spared."]}, {"text": "Regularity and exception status therefore describe degrees of statistical support rather than perfectly isolated kinds of processing.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 23}, "m3-morphology-p024": {"status": "ready", "blocks": [{"text": "**Specific language impairment, or SLI in the course terminology, involves impaired language development despite relatively typical nonverbal performance.** Difficulties can include morphology and syntax.", "children": ["The profile can also involve phonology, reading, working memory and speech perception. This broader range matters when evaluating a theory that locates the problem only in grammar."]}, {"text": "A relative language difficulty does not by itself identify a single damaged learning mechanism.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 24}, "m3-morphology-p025": {"status": "ready", "blocks": [{"text": "**A rule-deficit account predicts particular difficulty with regular and novel inflections.** If a domain-specific rule-learning mechanism is impaired, irregular forms stored lexically should be relatively less affected.", "children": ["This proposal uses past-tense performance to argue for a mechanism specific to grammatical rules."]}, {"text": "The prediction must be tested against the complete pattern, including irregular performance and broader phonological difficulties.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 25}, "m3-morphology-p026": {"status": "ready", "blocks": [{"text": "**The van der Lely and Ullman comparison shows low past-tense accuracy across all three item types in the SLI group.** Same-age controls perform much better.", "children": ["Nonwords are especially difficult for the SLI group, but regulars and irregulars are also impaired. The results therefore contain a broad deficit as well as unequal condition difficulty."]}, {"text": "An explanation should account for the entire profile rather than reporting only that productive forms are poor.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 26}, "m3-morphology-p027": {"status": "ready", "blocks": [{"text": "**Weakening phonological processing produces impaired learning across forms, with nonwords especially vulnerable.** The severe and weaker impairment settings differ in the degree of difficulty.", "children": ["The intact model performs substantially better. Even intact learning shows different performance across regulars, irregulars and nonwords."]}, {"text": "The comparison tests whether a phonological learning weakness can reproduce important aspects of the behavioral profile without a missing grammatical rule.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 27}, "m3-morphology-p028": {"status": "ready", "blocks": [{"text": "**Phonology contributes to every spoken past-tense response.** Weakening it can therefore reduce performance on regulars, irregulars and nonwords.", "children": ["Nonwords are particularly dependent on generalizing a sound pattern to a new form. Familiar words have additional item-specific learning that can partly support their responses."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 28}, "m3-morphology-p029": {"status": "ready", "blocks": [{"text": "**The associative account learns mappings among phonology and semantics without a separate symbolic past-tense rule or an isolated exception lexicon.** Regular and irregular are useful descriptions of behavior, but only approximate descriptions of the system's internal organization.", "children": ["Irregular performance is associated with semantic processing. Wug-test performance is associated with phonological processing."]}, {"text": "These associations provide tests of the proposed underlying mechanisms, beyond simply assigning different item types to different boxes.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 29}, "m3-morphology-p030": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 30}, "m3-thought-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 1}, "m3-thought-p002": {"status": "ready", "blocks": [{"text": "**Linguistic relativity concerns whether differences in language influence how people organize or use concepts.** The Sapir and Whorf quotations suggest that linguistic categories can shape how experience is interpreted.", "children": ["The strongest reading would make language determine what a person can think. A weaker claim is that habitual language use biases attention, memory or preferred ways of representing a situation."]}, {"text": "These claims require different evidence. A preference associated with language does not establish that alternative thought is impossible.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 2}, "m3-thought-p003": {"status": "ready", "blocks": [{"text": "**Language is embedded in cultural practices and experience.** A difference between language communities may therefore covary with factors other than linguistic structure.", "children": ["Sapir and Whorf should not automatically be assigned the strongest deterministic interpretation of selected quotations."]}, {"text": "A precise study must identify which cognitive process is affected and what alternative explanations the comparison controls.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 3}, "m3-thought-p004": {"status": "ready", "blocks": [{"text": "**A location description needs a frame of reference.** Saying where the ball is requires choosing what counts as left, front or a stable direction.", "children": ["The ball can be located with respect to the viewer, the chair's own orientation or a direction independent of either."]}, {"text": "Different descriptions can identify the same physical position while organizing that position differently.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 4}, "m3-thought-p005": {"status": "ready", "blocks": [{"text": "**An intrinsic frame uses an object's own orientation, a relative frame uses an observer's viewpoint, and an absolute frame uses a stable direction.** These are different ways to specify the same location.", "children": ["“At the chair's front” uses the chair's intrinsic front. “To the left of the chair from my viewpoint” depends on the observer."]}, {"text": "“North of the chair” uses an absolute direction that does not reverse when the observer turns around.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 5}, "m3-thought-p006": {"status": "ready", "blocks": [{"text": "**Egocentric spatial descriptions use the speaker's position and orientation.** Left, right, in front and behind are familiar examples for nearby objects.", "children": ["Tzeltal commonly uses absolute directions in circumstances where English speakers might use these relative terms."]}, {"text": "The contrast motivates asking whether habitual language use relates to nonverbal spatial coding, rather than merely comparing two ways of giving spoken directions.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 6}, "m3-thought-p007": {"status": "ready", "blocks": [{"text": "**Tzeltal's uphill and downhill terms function as an absolute directional system.** Their historical connection to a slope does not mean that each use simply points to the nearest visible hill.", "children": ["A direction is retained as a stable spatial reference rather than being recalculated from the speaker's current left and right."]}, {"text": "This allows positions to be described consistently as the speaker changes orientation.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 7}, "m3-thought-p008": {"status": "ready", "blocks": [{"text": "**A landmark-based direction is tied to a particular environment.** Uptown and downtown organize movement within Manhattan but do not provide a universally usable compass system.", "children": ["A city's conventional map orientation can also differ from magnetic north. Familiar spatial language therefore reflects local practices as well as geometric directions."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 8}, "m3-thought-p009": {"status": "ready", "blocks": [{"text": "**The chips task separates relative from absolute spatial memory by rotating the participant 180 degrees.** A participant sees a configuration, waits, and then chooses its match at a second table.", "children": ["A relative response preserves the arrangement with respect to the person's viewpoint. An absolute response preserves its orientation in the environment, so the two responses diverge after rotation."]}, {"text": "Dutch speakers predominantly gave relative responses, while Tzeltal speakers gave more absolute responses. The association is consistent with their preferred linguistic frames but does not isolate language from all other experience.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 9}, "m3-thought-p010": {"status": "ready", "blocks": [{"text": "**Spatial inference can combine relations learned in different displays.** Participants learn the relation between two objects, rotate to another display, and learn a second relation involving a shared object.", "children": ["They then place an object relative to another using the combined information. Relative and absolute coding lead to different placements because the person's orientation has changed."]}, {"text": "Dutch and Tzeltal response patterns again differ in the direction associated with their preferred spatial frames.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 10}, "m3-thought-p011": {"status": "ready", "blocks": [{"text": "**Testing conditions could contribute to the apparent language-group difference.** Li and Gleitman noted that Tzeltal participants had been tested with visible, familiar outdoor landmarks, unlike many laboratory participants.", "children": ["An environment with useful landmarks can encourage landmark-based coding. A windowless laboratory can make viewer-relative descriptions more convenient."]}, {"text": "Manipulating landmark availability within English speakers tests whether the behavior can change without changing native language.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 11}, "m3-thought-p012": {"status": "ready", "blocks": [{"text": "**English speakers' preference for relative coding weakened when external landmarks were available.** They strongly preferred relative responses with the blinds down, but the preference was less pronounced with a street view or outdoors.", "children": ["The manipulation changes the spatial information available while keeping the language group the same."]}, {"text": "This demonstrates that task context can influence the response. It challenges an explanation in which language alone fixes the chosen frame.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 12}, "m3-thought-p013": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 13}, "m3-thought-p014": {"status": "ready", "blocks": [{"text": "**If language groups are tested under different conditions, their response difference may partly reflect those conditions.** Visible landmarks and familiarity can covary with native language in a cross-community study.", "children": ["A controlled comparison must separate the effect of the environment from any contribution of habitual linguistic coding."]}, {"text": "Showing an environmental effect does not prove that language never matters. It limits what can be inferred from an uncontrolled comparison.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 14}, "m3-thought-p015": {"status": "ready", "blocks": [{"text": "**Levinson and colleagues argued that the simplified task could make the experimenter's purpose too obvious.** Low memory demands and short time or distance between displays may encourage a deliberate strategy about rotation.", "children": ["Participants who infer what is being tested can alter their response for reasons different from habitual spatial coding."]}, {"text": "The response therefore focuses on memory load and task transparency, rather than denying that landmarks can ever matter.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 15}, "m3-thought-p016": {"status": "ready", "blocks": [{"text": "**Levinson and colleagues retested Dutch students with four animals, a longer delay and greater distance between tables.** The extra item and delay increased memory demands, while the distance made the rotation manipulation less conspicuous.", "children": ["Under these conditions, the preference for relative coding remained."]}, {"text": "The result suggests that the environmental effect depends on how the task is arranged, including how much memory and strategic inference it encourages.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 16}, "m3-thought-p017": {"status": "ready", "blocks": [{"text": "**A robust spatial-frame preference under memory demands does not automatically identify a purely spatial representation.** Remembering the task can recruit verbal strategies as well as spatial ones.", "children": ["The relative preference is reported when memory demands are substantial and the experimenter's interest is less obvious."]}, {"text": "That pattern makes it important to ask how the sequence is stored during the delay, not only which direction is chosen at the end.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 17}, "m3-thought-p018": {"status": "ready", "blocks": [{"text": "**Participants might remember the animals as a verbal list such as “lion, tiger, bear.”** Reconstructing that sequence from left to right can produce a relative-looking response.", "children": ["This strategy would connect language to the task through working memory and ordering habits, rather than through an inability to represent absolute space."]}, {"text": "The interpretation changes because the same choice can arise from different internal codes.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 18}, "m3-thought-p019": {"status": "ready", "blocks": [{"text": "**Metaphorical language expresses one kind of experience using terms from another.** Saying that an argument is not “cutting” describes its effectiveness rather than a literal action with a blade.", "children": ["Physical and spatial terms can therefore help express abstract relations. Time is especially useful for studying whether such linguistic habits are associated with nonlinguistic representations."]}, {"text": "The question is empirical. Using a spatial phrase does not by itself prove that every thought about time has the same spatial format.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 19}, "m3-thought-p020": {"status": "ready", "blocks": [{"text": "**English and Mandarin both use horizontal spatial language for time, but Mandarin also frequently uses vertical terms.** Earlier events can be described with an “up” term and later events with a “down” term.", "children": ["The linguistic contrast motivates testing whether speakers differ in the spatial organization they use during temporal tasks."]}, {"text": "The existence of the expressions is the starting observation. A behavioral task is needed to investigate whether the contrast extends beyond words.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 20}, "m3-thought-p021": {"status": "ready", "blocks": [{"text": "**Boroditsky's priming task tests whether spatial processing influences subsequent time judgments.** Participants first process horizontal or vertical relations, then respond to temporal earlier–later questions.", "children": ["English speakers respond faster after horizontal than vertical primes, while Mandarin speakers show the opposite pattern in the displayed comparison."]}, {"text": "Training English speakers on vertical metaphors changes the pattern toward a vertical-prime advantage. This suggests sensitivity to experience, rather than an unchangeable division between language groups.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 21}, "m3-thought-p022": {"status": "ready", "blocks": [{"text": "**Reading and writing habits can also organize sequences spatially.** Differences attributed to temporal metaphors may covary with whether text is commonly read left-to-right, right-to-left or vertically.", "children": ["Casasanto and Bottini use differences in text orientation and arrangement preferences to motivate this alternative."]}, {"text": "The point is to identify another source of spatial experience, not to assume that a writing-system label perfectly predicts every individual's habits.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 22}, "m3-thought-p023": {"status": "ready", "blocks": [{"text": "**Boroditsky and colleagues excluded Chinese readers who reported top-to-bottom reading.** This tests whether the vertical temporal effect can be explained entirely by that reported reading experience.", "children": ["English speakers show an advantage for a left-is-earlier horizontal mapping. Mandarin speakers also show an advantage for a top-is-earlier vertical mapping in the displayed comparison."]}, {"text": "Retaining a vertical effect under this restriction weakens that particular reading-direction explanation, without proving that every possible experiential confound is removed.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 23}, "m3-thought-p024": {"status": "ready", "blocks": [{"text": "**Participants classify events as past or future using colored buttons.** The color-to-category mapping is reversed across blocks, so the past response is sometimes on the left and sometimes on the right.", "children": ["With standard text reading, responses are faster when past maps left and future maps right."]}, {"text": "Because the response concerns time rather than an explicit judgment of spatial direction, the compatibility effect reveals an implicit spatial association in this task.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 24}, "m3-thought-p025": {"status": "ready", "blocks": [{"text": "**Mirror reading tests whether short-term reading experience can alter spatial associations with time.** Participants read reversed text and perform the past–future button task.", "children": ["By the second mirror-reading block, the compatibility effect reverses. Responses are faster when earlier maps right and later maps left."]}, {"text": "The result supports a contribution of reading-direction experience and shows that the association can change over a short period.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 25}, "m3-thought-p026": {"status": "ready", "blocks": [{"text": "**Claims about a language's vocabulary are not automatically evidence for cognitive limits.** Pullum's discussion criticizes how an account of different word roots became an exaggerated story about language and thought.", "children": ["Languages can express distinctions through separate roots, derived words or phrases. Counting one of these forms without considering the others can misrepresent expressive capacity."]}, {"text": "A reliable claim requires accurate linguistic description and an appropriate behavioral test, rather than repetition of a striking anecdote.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 26}, "m3-thought-p027": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 27}, "m3-modalities-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 1}, "m3-modalities-p002": {"status": "ready", "blocks": [{"text": "**A signed language is a natural language, while Braille is a writing system.** Signed languages have their own linguistic structure. Braille allows a language to be read through touch.", "children": ["The distinction matters because changing the modality of a language is not the same as changing how a written language is accessed."]}, {"text": "Both cases reveal how sensory experience shapes the organization of systems involved in language and reading.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 2}, "m3-modalities-p003": {"status": "ready", "blocks": [{"text": "**Signed languages use a visual modality and manual and bodily articulators.** The hands, face and upper body contribute to a coordinated linguistic signal.", "children": ["Space can carry linguistic relations. Some signs are iconic, meaning that aspects of their form resemble aspects of their meaning."]}, {"text": "Iconicity is easy to overestimate when a familiar translation is supplied. A visible resemblance does not eliminate the need to learn a language's forms and structure.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 3}, "m3-modalities-p004": {"status": "ready", "blocks": [{"text": "**Fluent signing coordinates hands, facial expression, gaze and upper-body movement.** The linguistic signal is distributed across these visible articulators rather than produced by one hand movement at a time.", "children": ["Like speech, a fluent stream is continuous enough that word boundaries are not always obvious to a learner."]}, {"text": "Eye contact and movement timing are therefore relevant to perceiving the interaction, alongside the form of individual signs.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 4}, "m3-modalities-p005": {"status": "ready", "blocks": [{"text": "**Signed-language phonology includes contrastive hand configuration, location and movement.** Changing one of these features can distinguish signs, just as changing a speech feature can distinguish spoken words.", "children": ["The PLEASE–SORRY and ONION–APPLE examples demonstrate that closely related visible forms can have different linguistic identities."]}, {"text": "Phonology therefore concerns the organization of contrastive form, not only acoustic sound.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 5}, "m3-modalities-p006": {"status": "ready", "blocks": [{"text": "**Categorical perception can be tested by varying a sign feature continuously.** The hand-configuration continuum moves between forms while the observer's identification and discrimination responses are measured.", "children": ["One continuum crosses a phonemic distinction between PLEASE and SORRY. The allophonic comparison varies hand configuration without the same change in sign identity."]}, {"text": "A sharp identification boundary accompanied by better discrimination near that boundary would indicate category-sensitive perception.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 6}, "m3-modalities-p007": {"status": "ready", "blocks": [{"text": "**Deaf signers show a sharper categorical boundary for phonemic than allophonic hand-configuration changes.** In the phonemic condition, identification shifts steeply around stimuli 4–6.", "children": ["Discrimination is also strongest near the phonemic boundary. Comparable physical steps are easier to distinguish when they cross that category boundary."]}, {"text": "The allophonic identification function is shallower and lacks the same localized discrimination peak. This links the perceptual pattern to linguistic contrast rather than any visible hand change.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 7}, "m3-modalities-p008": {"status": "ready", "blocks": [{"text": "**Signed languages can use positions in signing space to represent relationships.** A classifier sign made at a particular location can indicate the relative position of an object.", "children": ["Understanding a sentence can require retaining where entities were introduced and how subsequent signs relate to those locations."]}, {"text": "Spatial processing therefore contributes to linguistic comprehension, rather than functioning only as background vision.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 8}, "m3-modalities-p009": {"status": "ready", "blocks": [{"text": "**Signed-language comprehension recruits classical language regions and shows left lateralization, as spoken-language comprehension does.** Inferior frontal and posterior superior temporal regions are part of this overlap.", "children": ["Signing also engages visual and superior parietal regions relevant to its perceptual and spatial demands."]}, {"text": "The combination suggests both common language organization and modality-related contributions. Similarity does not require identical activation everywhere.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 9}, "m3-modalities-p010": {"status": "ready", "blocks": [{"text": "**Bavelier and colleagues compared hearing controls, deaf signers and hearing signers on visual attention.** Participants monitored dots for brief changes in luminance or velocity, with attention directed centrally or peripherally.", "children": ["Deaf participants showed an advantage when attention was directed to the periphery."]}, {"text": "Including hearing signers helps separate experience with signing from lack of auditory input. If all signers had the same advantage, signing alone would be a stronger explanation.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 10}, "m3-modalities-p011": {"status": "ready", "blocks": [{"text": "**Signing experience and deafness show different associations with visual processing.** Both deaf and hearing signers show a leftward shift in motion-processing lateralization relative to hearing nonsigners.", "children": ["Enhanced peripheral attention is found in deaf individuals, not hearing signers. Signing experience alone therefore does not explain that enhancement."]}, {"text": "The proposed interpretations involve links between motion and language systems for signing, and reduced reliance on auditory peripheral cues in deafness.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 11}, "m3-modalities-p012": {"status": "ready", "blocks": [{"text": "**Comparing sign comprehension with another organized gesture system helps control visible movement demands.** Tic-tac uses sophisticated hand gestures to communicate horse-racing odds.", "children": ["Both tasks involve meaningful, sequenced hand movements. A difference between them is more informative about linguistic processing than a comparison between signing and no movement."]}, {"text": "The control is not identical to a natural language, which is precisely why the remaining difference is of interest.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 12}, "m3-modalities-p013": {"status": "ready", "blocks": [{"text": "**Sign language produces stronger activity around posterior superior temporal language regions than tic-tac gestures.** This supports a distinction between processing organized hand movements and processing a natural language.", "children": ["The comparison reduces a simple explanation based only on the presence of hands moving through space."]}, {"text": "The frontal activation shown is superior to classic Broca's area, so it should not be casually relabeled as a precise Broca's effect.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 13}, "m3-modalities-p014": {"status": "ready", "blocks": [{"text": "**Signed languages have linguistic form, grammar and language-related neural organization.** Contrastive sign features can produce categorical perception, and comprehension recruits posterior superior temporal language regions.", "children": ["Signing experience is associated with changes in motion lateralization. Deafness is associated with enhanced peripheral attention in the reported comparison."]}, {"text": "These findings jointly show that linguistic experience and sensory history contribute in different ways.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 14}, "m3-modalities-p015": {"status": "ready", "blocks": [{"text": "**Comprehending a signed spatial description can require a perspective transformation.** A room can be described from the speaker's perspective or the addressee's perspective.", "children": ["The figure's caption reports better comprehension for descriptions from the speaker's perspective despite the mental transformation that this requires."]}, {"text": "This illustrates that the most linguistically natural representation is not necessarily the one that eliminates every spatial transformation.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 15}, "m3-modalities-p016": {"status": "ready", "blocks": [{"text": "**Braille represents written language through tactilely distinguishable symbols.** It is a way to read a language, rather than a separate natural language with its own grammar.", "children": ["The symbols are optimized for touch. Fingers acquire letters sequentially, creating perceptual demands that differ from viewing printed text."]}, {"text": "The comparison asks how reading networks operate when the input arrives through touch instead of vision.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 16}, "m3-modalities-p017": {"status": "ready", "blocks": [{"text": "**Braille reading activates visual cortex in blind individuals, with more extensive recruitment after earlier sight loss.** Early- and late-blind groups therefore provide a comparison of developmental sensory history.", "children": ["Early-blind participants show stronger involvement of regions associated with visual word processing than late-blind participants."]}, {"text": "This indicates that a region's usual sensory label does not completely determine the information it can help process.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 17}, "m3-modalities-p018": {"status": "ready", "blocks": [{"text": "**Merabet and colleagues tested rapid plasticity by blindfolding sighted adults for five days while training Braille.** A comparison group received training without the same continuous removal of visual input.", "children": ["The blindfolded group learned more quickly. This suggests that eliminating competing visual input can affect tactile learning over a short timescale."]}, {"text": "Because the participants were sighted adults, the experiment tests a different question from lifelong or early blindness.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 18}, "m3-modalities-p019": {"status": "ready", "blocks": [{"text": "**Visual-cortex responses to Braille developed during blindfolding and reversed after the blindfold was removed on Day 6.** The time course shows that the change was rapid and reversible.", "children": ["Removing visual input can allow tactile-related activity to become more evident. Restoring vision changes that balance again."]}, {"text": "This pattern is consistent with unmasking existing inputs rather than requiring the creation of an entirely new pathway over a few days.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 19}, "m3-modalities-p020": {"status": "ready", "blocks": [{"text": "**Disrupting visual cortex with TMS impaired Braille discrimination in the blindfolded group.** This goes beyond showing that the region becomes active during touch.", "children": ["On Day 5, the blindfolded group's error rate rises under 1 Hz TMS relative to its baseline and sham conditions. The nonblindfolded group does not show the same selective disruption."]}, {"text": "The effect is no longer present in the same way after blindfold removal. The result supports a temporary functional contribution of visual cortex to tactile performance.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 20}, "m3-modalities-p021": {"status": "ready", "blocks": [{"text": "**Language-related organization is resilient across sensory modalities while remaining shaped by experience.** Signed language recruits classical language regions, and Braille engages networks associated with text processing.", "children": ["Competition among available inputs offers a way to understand reorganization. When an input is absent or reduced, other information can make a larger contribution."]}, {"text": "The evidence does not imply that all regions are interchangeable. It shows both stable functional relationships and experience-sensitive recruitment.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 21}, "m3-review-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/review.txt", "source": "review", "page": 1}, "m3-review-p002": {"status": "ready", "blocks": [{"text": "**Orthographic depth** describes how consistently spelling corresponds to pronunciation. English is relatively deep because many spellings do not transparently specify their sounds.", "children": ["COLONEL and PARADIGM make the problem concrete. Applying common letter–sound patterns can produce a plausible-looking pronunciation that is wrong for the actual word."]}, {"text": "In shallower writing systems, such as Finnish and Korean, spelling–sound correspondences are more predictable. The comparison concerns the writing system, not the intelligence or ability of its readers.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 2}, "m3-review-p003": {"status": "ready", "blocks": [{"text": "**Finnish has a shallow orthography.** Letters correspond relatively unambiguously to phonemes, so learning a spelling–sound correspondence helps with many different words.", "children": ["Doubled letters represent a meaningful length distinction. A doubled consonant is geminated, and a doubled vowel is long."]}, {"text": "This regularity helps Finnish children learn decoding quickly. Decoding means generating a pronunciation from a written form, whether or not its meaning is familiar.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 3}, "m3-review-p004": {"status": "ready", "blocks": [{"text": "**Pseudoword reading tests decoding.** Because a pseudoword is not a familiar stored word, the child must generalize from learned spelling–sound patterns.", "children": ["The comparison involves Grade 1 children learning different alphabetic writing systems. Children learning many other languages produce plausible pseudoword pronunciations more successfully than English learners."]}, {"text": "English's less predictable correspondences help explain why decoding develops more slowly. This task does not measure the child's entire language ability.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 4}, "m3-review-p005": {"status": "ready", "blocks": [{"text": "**Korean writing represents sound structure systematically.** Related phonemes can have related written shapes, so the visual forms themselves reflect aspects of phonological organization.", "children": ["The letters are arranged into syllable blocks with initial, medial and sometimes final positions. Those positions are not three unrelated pictures of whole words."]}, {"text": "The velar consonant forms share the basic angular ㄱ shape. Additional strokes or doubling distinguish related consonants.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 5}, "m3-review-p006": {"status": "ready", "blocks": [{"text": "**Frequency and regularity interact.** Low-frequency exception words are slowed much more than low-frequency regular words, whereas high-frequency words show a much smaller regularity difference.", "children": ["Naming latency is the time needed to begin saying the word. Higher values mean slower responses."]}, {"text": "An interaction means the effect of one factor depends on the other. The regularity cost is not a fixed amount added equally to high- and low-frequency words.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 6}, "m3-review-p007": {"status": "ready", "blocks": [{"text": "**A dual-route interpretation separates lexical retrieval from sublexical decoding.** The lexical process supplies the learned pronunciation of a particular word, while decoding computes pronunciation from spelling units.", "children": ["For a high-frequency word, lexical information becomes available quickly enough to reduce the influence of the decoding output."]}, {"text": "For a low-frequency exception, the lexical response is less efficient and the regularized decoding output can interfere. Nonwords depend on decoding because they lack a stored whole-word entry.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 7}, "m3-review-p008": {"status": "ready", "blocks": [{"text": "**In a PDP account, rules are generalizations learned across words.** Whole-word knowledge is distributed across learned mappings instead of being stored only in a distinct lexical route.", "children": ["The same learning mechanism can capture both patterns shared by many words and information specific to a familiar word."]}, {"text": "The research strategy asks whether domain-general learning can explain reading. This contrasts with choosing separate adult processing components primarily from neuropsychological dissociations.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 8}, "m3-review-p009": {"status": "ready", "blocks": [{"text": "**A learned network can produce a frequency-by-regularity interaction without separate frequency and rule mechanisms.** Regular words receive support from patterns shared across many words.", "children": ["An exception conflicts with those patterns, so learning its particular mapping is especially important. Frequent exposure strengthens that word-specific mapping."]}, {"text": "A low-frequency exception has both weak item-specific learning and poor support from the dominant pattern. This combination creates a larger disadvantage than either factor alone.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 9}, "m3-review-p010": {"status": "ready", "blocks": [{"text": "**A PDP model can pronounce nonwords using the weights learned from real words.** A new spelling activates patterns that overlap with familiar spellings, allowing the network to generalize.", "children": ["No stored entry for the particular nonword is required. The same learned correspondences that support consistent words can support a new combination."]}, {"text": "This is a proposed mechanism for decoding without a separate GPC rule module.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 10}, "m3-review-p011": {"status": "ready", "blocks": [{"text": "**Poor nonword performance can challenge either a theoretical proposal or a particular implementation.** The early model's nonword accuracy was weaker than desired.", "children": ["One possibility is that a single associative mechanism cannot explain the task. Another is that the chosen representations fail to capture the similarities needed for generalization."]}, {"text": "Improving the implementation while retaining the theoretical mechanism helps distinguish these possibilities.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 11}, "m3-review-p012": {"status": "ready", "blocks": [{"text": "**Generalization depends on how sound similarity is represented.** The early Seidenberg–McClelland model used Wickelfeatures, whose representation of phonology was problematic for nonword reading.", "children": ["Plaut and colleagues improved the phonological representations and obtained better nonword performance. This supports a representational explanation for at least part of the earlier failure."]}, {"text": "Behavioral relations between phonological processing and decoding also make phonology a relevant target for explanation.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 12}, "m3-review-p013": {"status": "ready", "blocks": [{"text": "**A network generalizes through similarity.** If its phonological representation poorly captures similarities among words, the learned mapping cannot transfer as effectively to new forms.", "children": ["A familiar word can retain support from its own training history. A nonword lacks that item-specific experience and depends more heavily on generalization."]}, {"text": "This produces a reason for unfamiliar forms to be especially vulnerable to poor representations without requiring a dedicated nonword mechanism.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 13}, "m3-review-p014": {"status": "ready", "blocks": [{"text": "**Harm and Seidenberg manipulated noise in phonological representations.** Increasing noise makes the sound representations less reliable while keeping the model's general learning framework.", "children": ["The manipulation produced poorer nonword decoding and relative sparing of word recognition. It also linked the severity of the phonological deficit to the degree of decoding difficulty."]}, {"text": "The model therefore connects a reading pattern to the quality of a more general phonological system.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 14}, "m3-review-p015": {"status": "ready", "blocks": [{"text": "**The lexicon and grammar offer different ways to produce a past tense.** Lexical retrieval supplies an irregular form such as HELD, while grammatical combination can produce WALK plus -ed.", "children": ["Pinker and Ullman's diagram associates lexical lookup with declarative memory and grammatical combination with procedural processing."]}, {"text": "Like dual-route reading, the account separates word-specific knowledge from a productive operation. Unlike reading aloud, its task is to transform a stem according to a grammatical feature, rather than convert spelling into sound.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 15}, "m3-review-p016": {"status": "ready", "blocks": [{"text": "**The Words and Rules proposal was motivated partly by a theory of grammar.** A categorical symbolic grammar describes productive patterns, but language also contains exceptions.", "children": ["Reading dual-route theories were strongly motivated by neuropsychological dissociations. The morphology proposal also reflects a commitment to keeping the grammatical rule system distinct from exceptional lexical information."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 16}, "m3-review-p017": {"status": "ready", "blocks": [{"text": "**An associative lexicon handles information that does not fit a categorical rule.** Its representations are word-specific and sensitive to frequency and phonological similarity.", "children": ["KEEP–KEPT, WEEP–WEPT and LEAP–LEAPT illustrate similarity among irregular forms. An exception can belong to a small family rather than being wholly unrelated to other words."]}, {"text": "Assigning these properties to lexical memory lets the rule system remain categorical and general.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 17}, "m3-review-p018": {"status": "ready", "blocks": [{"text": "**Rumelhart and McClelland modeled past tense as a learned association between present and past sound patterns.** A single trainable network learns across verbs instead of applying a separately specified -ed rule.", "children": ["The model encodes a root's phonology, transforms that representation through modifiable connections, and decodes an output pattern."]}, {"text": "Regularity is a pattern learned from many examples. Irregular forms are also learned within the same system.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 18}, "m3-review-p019": {"status": "ready", "blocks": [{"text": "**U-shaped learning describes an initial success, a decline, and later recovery.** A child may correctly say RAN, later produce RUNNED, and eventually return to RAN.", "children": ["The middle error is a **regularization**, because the child applies the common past-tense pattern to an irregular verb."]}, {"text": "The decline does not necessarily mean that the child has stopped learning. A changing system can generalize more broadly while temporarily disrupting an earlier correct response.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 19}, "m3-review-p020": {"status": "ready", "blocks": [{"text": "**The Words and Rules account explains U-shaped learning through changes in the use of rules and lexical exceptions.** Early correct forms can be imitated before a productive rule is available.", "children": ["When the rule is learned, it can be applied too broadly, yielding RUNNED. Later, learned irregulars and the blocking process prevent that regularization."]}, {"text": "This account treats the developmental stages as involving distinguishable processes rather than only gradual changes in one mapping.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 20}, "m3-review-p021": {"status": "ready", "blocks": [{"text": "**Changing the training vocabulary can produce U-shaped learning in one network.** Early training emphasizes frequent irregular verbs, allowing those particular mappings to be learned.", "children": ["As more regular verbs enter training, their common pattern changes the network's responses. That generalization can interfere with previously learned irregulars."]}, {"text": "With further learning, the network can recover the irregular responses while retaining broad regularity. No new symbolic rule component is inserted at the point of decline.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 21}, "m3-review-p022": {"status": "ready", "blocks": [{"text": "**Testing untrained verbs asks whether the network learned transferable structure.** A real English verb can be novel to a model if it was excluded from that model's training set.", "children": ["The test therefore uses the logic of a wug task even when the items are real words to humans."]}, {"text": "The model can generate many appropriate past-tense features, but feature-level success must be distinguished from producing an entirely correct word.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 22}, "m3-review-p023": {"status": "ready", "blocks": [{"text": "**Some model outputs contain changes that are unlike ordinary human regularizations.** Examples include MADE(D)-like changes to MATE and the unusual outputs MEMBLED for MAIL and TOUREDER for TOUR.", "children": ["The model authors acknowledge that people are unlikely to make some of these errors. They suggest that additional output constraints could reduce bizarre responses."]}, {"text": "This separates capturing an overall learning pattern from matching the detailed form of human errors.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 23}, "m3-review-p024": {"status": "ready", "blocks": [{"text": "**Joanisse and Seidenberg propose that phonology supports rule-like generalization while semantics especially supports irregular forms.** The same system links speech input, meaning and speech output.", "children": ["Reliable sound representations support extension from familiar present–past pairs to new forms. Irregular mappings receive additional support from the particular word's semantic representation."]}, {"text": "The hypothesis concerns different degrees of dependence on shared systems, rather than a separate symbolic rule route for every regular response.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 24}, "m3-review-p025": {"status": "ready", "blocks": [{"text": "**The model aims to explain the dissociation between irregular and nonword past-tense performance.** These tasks differ in how much they depend on learned word-specific information and phonological generalization.", "children": ["A nonword has no familiar item-specific semantic history to support its inflection. A known irregular can require semantic support because its output is not well predicted by the dominant pattern."]}, {"text": "Manipulating phonological or semantic integrity tests whether these different dependencies can produce opposite impairment profiles.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 25}, "m3-review-p026": {"status": "ready", "blocks": [{"text": "**The patient pattern associated here with Broca's aphasia includes especially poor nonword past-tense production.** These patients have left anterior injury and difficulty producing speech.", "children": ["Regular forms are also vulnerable, while irregular forms are relatively better in the displayed comparison. A novel BLICK must be transformed without relying on a familiar stored past tense."]}, {"text": "This motivates investigating phonological contributions to the apparent morphological deficit.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 26}, "m3-review-p027": {"status": "ready", "blocks": [{"text": "**Other patient groups show a larger problem with irregular past-tense forms.** The material discusses Wernicke's and Alzheimer's patients and anomic patients with inferior or middle temporal injury.", "children": ["Their irregular performance is lower than their regular and nonword performance in the displayed comparison."]}, {"text": "This creates the other side of the dissociation and motivates examining the information that especially supports known irregular forms.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 27}, "m3-review-p028": {"status": "ready", "blocks": [{"text": "**The classical contrast associates Wernicke's aphasia with fluent but often poorly interpretable speech and Broca's aphasia with effortful, telegraphic speech.** The former can include neologisms, while the latter can omit grammatical particles and show word-order difficulty.", "children": ["This makes a lexical-versus-grammatical interpretation attractive. However, a descriptive syndrome is not itself a demonstration of an isolated processing module."]}, {"text": "Content words may be relatively preserved in telegraphic speech, while fluent speech can retain sentence-like structure without conveying a clear message.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 28}, "m3-review-p029": {"status": "ready", "blocks": [{"text": "**Broca's original patients are not necessarily straightforward examples of what is now called Broca's aphasia.** Profound inability to articulate speech can reflect motor-planning impairment rather than a selective grammatical deficit.", "children": ["**Apraxia of speech** concerns planning or coordinating speech movements. That differs from explaining an omission of grammatical structure in otherwise producible speech."]}, {"text": "The historical label therefore should not substitute for a precise description of the impaired behavior.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 29}, "m3-review-p030": {"status": "ready", "blocks": [{"text": "**A grammar–lexicon distinction makes the classical aphasia contrast theoretically appealing.** A grammatical system combines forms, while lexical knowledge concerns words and their properties.", "children": ["Chomsky's example of a grammatical but semantically unusual sentence shows that syntactic well-formedness cannot be reduced to whether a sentence describes a sensible event."]}, {"text": "That conceptual distinction does not establish a simple one-to-one mapping from each syndrome to one isolated component.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 30}, "m3-review-p031": {"status": "ready", "blocks": [{"text": "**The functional level selects word meanings and semantic roles, while the positional level organizes word forms into a grammatical sequence.** Phonological encoding and articulation concern later aspects of producing the utterance.", "children": ["A **lemma** is a representation involved in lexical selection, distinct from simply executing its sound pattern. Positional processing contributes ordering and morphological structure."]}, {"text": "Combinations such as HOUSEBOAT show that complex-word meaning can be partly compositional. Errors such as “easy enoughly” provide evidence about the organization of morphological operations.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 31}, "m3-review-p032": {"status": "ready", "blocks": [{"text": "**Egocentric spatial descriptions use the speaker's position and orientation.** Left, right, in front and behind are familiar examples for nearby objects.", "children": ["Tzeltal commonly uses absolute directions in circumstances where English speakers might use these relative terms."]}, {"text": "The contrast motivates asking whether habitual language use relates to nonverbal spatial coding, rather than merely comparing two ways of giving spoken directions.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 32}, "m3-review-p033": {"status": "ready", "blocks": [{"text": "**Tzeltal's uphill and downhill terms function as an absolute directional system.** Their historical connection to a slope does not mean that each use simply points to the nearest visible hill.", "children": ["A direction is retained as a stable spatial reference rather than being recalculated from the speaker's current left and right."]}, {"text": "This allows positions to be described consistently as the speaker changes orientation.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 33}, "m3-review-p034": {"status": "ready", "blocks": [{"text": "**The chips task separates relative from absolute spatial memory by rotating the participant 180 degrees.** A participant sees a configuration, waits, and then chooses its match at a second table.", "children": ["A relative response preserves the arrangement with respect to the person's viewpoint. An absolute response preserves its orientation in the environment, so the two responses diverge after rotation."]}, {"text": "Dutch speakers predominantly gave relative responses, while Tzeltal speakers gave more absolute responses. The association is consistent with their preferred linguistic frames but does not isolate language from all other experience.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 34}, "m3-review-p035": {"status": "ready", "blocks": [{"text": "**Spatial inference can combine relations learned in different displays.** Participants learn the relation between two objects, rotate to another display, and learn a second relation involving a shared object.", "children": ["They then place an object relative to another using the combined information. Relative and absolute coding lead to different placements because the person's orientation has changed."]}, {"text": "Dutch and Tzeltal response patterns again differ in the direction associated with their preferred spatial frames.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 35}, "m3-review-p036": {"status": "ready", "blocks": [{"text": "**Testing conditions could contribute to the apparent language-group difference.** Li and Gleitman noted that Tzeltal participants had been tested with visible, familiar outdoor landmarks, unlike many laboratory participants.", "children": ["An environment with useful landmarks can encourage landmark-based coding. A windowless laboratory can make viewer-relative descriptions more convenient."]}, {"text": "Manipulating landmark availability within English speakers tests whether the behavior can change without changing native language.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 36}, "m3-review-p037": {"status": "ready", "blocks": [{"text": "**English speakers' preference for relative coding weakened when external landmarks were available.** They strongly preferred relative responses with the blinds down, but the preference was less pronounced with a street view or outdoors.", "children": ["The manipulation changes the spatial information available while keeping the language group the same."]}, {"text": "This demonstrates that task context can influence the response. It challenges an explanation in which language alone fixes the chosen frame.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 37}, "m3-review-p038": {"status": "ready", "blocks": [{"text": "**Levinson and colleagues argued that the simplified task could make the experimenter's purpose too obvious.** Low memory demands and short time or distance between displays may encourage a deliberate strategy about rotation.", "children": ["Participants who infer what is being tested can alter their response for reasons different from habitual spatial coding."]}, {"text": "The response therefore focuses on memory load and task transparency, rather than denying that landmarks can ever matter.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 38}, "m3-review-p039": {"status": "ready", "blocks": [{"text": "**Categorical perception can be tested by varying a sign feature continuously.** The hand-configuration continuum moves between forms while the observer's identification and discrimination responses are measured.", "children": ["One continuum crosses a phonemic distinction between PLEASE and SORRY. The allophonic comparison varies hand configuration without the same change in sign identity."]}, {"text": "A sharp identification boundary accompanied by better discrimination near that boundary would indicate category-sensitive perception.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 39}, "m3-review-p040": {"status": "ready", "blocks": [{"text": "**Deaf signers show a sharper categorical boundary for phonemic than allophonic hand-configuration changes.** In the phonemic condition, identification shifts steeply around stimuli 4–6.", "children": ["Discrimination is also strongest near the phonemic boundary. Comparable physical steps are easier to distinguish when they cross that category boundary."]}, {"text": "The allophonic identification function is shallower and lacks the same localized discrimination peak. This links the perceptual pattern to linguistic contrast rather than any visible hand change.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 40}, "m3-review-p041": {"status": "ready", "blocks": [{"text": "**Signed-language comprehension recruits classical language regions and shows left lateralization, as spoken-language comprehension does.** Inferior frontal and posterior superior temporal regions are part of this overlap.", "children": ["Signing also engages visual and superior parietal regions relevant to its perceptual and spatial demands."]}, {"text": "The combination suggests both common language organization and modality-related contributions. Similarity does not require identical activation everywhere.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 41}, "m3-review-p042": {"status": "ready", "blocks": [{"text": "**Signed languages have linguistic form, grammar and language-related neural organization.** Contrastive sign features can produce categorical perception, and comprehension recruits posterior superior temporal language regions.", "children": ["Signing experience is associated with changes in motion lateralization. Deafness is associated with enhanced peripheral attention in the reported comparison."]}, {"text": "These findings jointly show that linguistic experience and sensory history contribute in different ways.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 42}, "m3-review-p043": {"status": "ready", "blocks": [{"text": "**The exercise hypothesis proposes that early language use preserves language-learning capacity, while the maturational-state hypothesis allows capacity to decline despite early use.** Both assume an early advantage, but they differ in what early successful experience protects.", "children": ["Later second-language difficulty in people who already acquired a first language is more directly compatible with maturation than with complete preservation through exercise."]}, {"text": "This does not make early first-language experience unimportant. Early access and age-related change address related but distinct questions.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 43}, "m3-review-p044": {"status": "ready", "blocks": [{"text": "**Mayberry, Lock and Kazmi compared later language learning after different early-language histories.** Deaf individuals without accessible early language performed worse than those who had acquired an early spoken or signed language.", "children": ["Children first exposed to ASL at ages 9–15 had particular difficulty when it was also their first language. Those who had first learned a spoken language did much better, and the differences persisted."]}, {"text": "The comparison distinguishes late first-language learning from late acquisition of an additional language.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 44}, "m3-review-p045": {"status": "ready", "blocks": [{"text": "**Semantic blocking effects must be separated from visual-recognition difficulty.** Objects from one semantic category could resemble one another visually, creating a potential confound in naming.", "children": ["The materials were normed so that same-category items were not more visually similar on average. A separate visual-similarity manipulation also produced a different time course."]}, {"text": "Visual blocking affected the first block, whereas the semantic pattern of interest developed differently. This weakens a purely visual explanation.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 45}, "m3-review-p046": {"status": "ready", "blocks": [{"text": "**Belke and colleagues presented four objects simultaneously but required their names in sequence.** This tests whether the absence of an effect in another simultaneous-display study depended on presentation format.", "children": ["Displaying all objects at once reduces dependence on a succession of isolated pictures. Serial naming still requires selecting and producing one label after another."]}, {"text": "Eye tracking provides additional timing information about the processing of each object.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 46}, "m3-review-p047": {"status": "ready", "blocks": [{"text": "**Eye movements and speech onsets provide different timing measures during serial naming.** Gaze duration records how long the eyes remain on an object, while eye–speech lag concerns the interval between leaving it and beginning its spoken name.", "children": ["A participant can move the eyes toward the next object before articulating the current one. The measures therefore separate overlapping parts of preparation."]}, {"text": "Different blocking effects on these measures can help constrain the processing stage affected.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 47}, "m3-review-p048": {"status": "ready", "blocks": [{"text": "**Semantic blocking increases gaze duration after the first presentation cycle, but not overall speech duration or eye–speech lag.** The measures therefore do not show a uniform slowdown.", "children": ["Speech duration decreases with repetition without a blocking difference. Gaze duration shows the condition difference after the first cycle."]}, {"text": "The nonsignificant lag difference should not be reported as evidence for a reversed effect. The reported pattern is interpreted as supporting a contribution at lemma selection rather than articulation or phonological encoding.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 48}, "m3-review-p049": {"status": "ready", "blocks": [{"text": "**McMurray and colleagues tested whether fine phonetic information affects lexical competition.** Participants heard a /b/–/p/ continuum while viewing pictures including BEAR and PEAR, with eye movements recorded.", "children": ["**Voice onset time**, or VOT, varies the timing between release and voicing. It can change how strongly the sound supports /b/ or /p/."]}, {"text": "A thresholded account would pass a completed categorical decision onward. A cascaded account allows graded information to influence word candidates before uncertainty is fully resolved.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 49}, "m3-review-p050": {"status": "ready", "blocks": [{"text": "**Participants selected the picture that best matched the spoken item.** Their BEAR–PEAR choices produced a typical step-like identification function across VOT.", "children": ["Shorter VOTs favored the /b/ response and longer VOTs the /p/ response. Near the boundary, the preferred category changed rapidly."]}, {"text": "A categorical-looking final response does not establish that all earlier lexical activation was categorical.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 50}, "m3-review-p051": {"status": "ready", "blocks": [{"text": "**Competitor looks vary with phonetic ambiguity even within a chosen category.** Tokens closer to the /b/–/p/ boundary produce more competition than clear tokens farther from it.", "children": ["A participant can ultimately select BEAR while spending more time looking at PEAR when the sound is close to the boundary."]}, {"text": "This supports the claim that fine phonetic information remains relevant to lexical activation, rather than disappearing completely after a categorical phoneme decision.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 51}, "m3-review-p052": {"status": "ready", "blocks": [{"text": "**Competitor fixation increases as a token approaches the category boundary from either side.** For BEAR responses, more /p/-like VOT increases looks to PEAR. For PEAR responses, more /b/-like VOT increases looks to BEAR.", "children": ["The graph separates early and late observation windows. The gradient remains visible in the later competition measure, supporting continued sensitivity to within-category phonetic detail."]}, {"text": "The result favors cascaded use of graded evidence over a model that transmits only a completed phoneme label with all within-category detail discarded.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 52}}}, {"id": "d-v2", "label": "D · Version 2", "scripts": {"m3-reading1-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 1}, "m3-reading1-p002": {"status": "ready", "blocks": [{"text": "**Keep spoken categories separate from written symbols.** Identifying a letter is not the same task as identifying a phoneme.", "children": []}, {"text": "A letter can contribute to different pronunciations, and a phoneme can be represented by different spellings.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 2}, "m3-reading1-p003": {"status": "ready", "blocks": [{"text": "**An unfamiliar spelling cannot always be decoded correctly from its letters alone.** Deep orthographies create more exceptions that readers must learn through experience.", "children": []}, {"text": "COLONEL and PARADIGM make the problem concrete. Applying common letter–sound patterns can produce a plausible-looking pronunciation that is wrong for the actual word.", "children": ["In shallower writing systems, such as Finnish and Korean, spelling–sound correspondences are more predictable. The comparison concerns the writing system, not the intelligence or ability of its readers."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 3}, "m3-reading1-p004": {"status": "ready", "blocks": [{"text": "**Consistent correspondences make decoding easier to generalize.** Finnish readers can apply what they learn about letters to unfamiliar written forms.", "children": []}, {"text": "Doubled letters represent a meaningful length distinction. A doubled consonant is geminated, and a doubled vowel is long.", "children": ["This regularity helps Finnish children learn decoding quickly. Decoding means generating a pronunciation from a written form, whether or not its meaning is familiar."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 4}, "m3-reading1-p005": {"status": "ready", "blocks": [{"text": "**A made-up word separates decoding from remembering a familiar word.** The lower English performance is consistent with greater orthographic depth.", "children": []}, {"text": "The comparison involves Grade 1 children learning different alphabetic writing systems. Children learning many other languages produce plausible pseudoword pronunciations more successfully than English learners.", "children": ["English's less predictable correspondences help explain why decoding develops more slowly. This task does not measure the child's entire language ability."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 5}, "m3-reading1-p006": {"status": "ready", "blocks": [{"text": "**The organization of Hangul supports more than consistent pronunciation.** Similar sound categories can also be visibly related in their written symbols.", "children": []}, {"text": "The letters are arranged into syllable blocks with initial, medial and sometimes final positions. Those positions are not three unrelated pictures of whole words.", "children": ["The velar consonant forms share the basic angular ㄱ shape. Additional strokes or doubling distinguish related consonants."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 6}, "m3-reading1-p007": {"status": "ready", "blocks": [{"text": "**Reading a novel letter sequence reveals knowledge beyond memorized words.** Familiar spelling patterns support pronunciation of new combinations.", "children": []}, {"text": "Success cannot depend on retrieving a stored pronunciation for each particular item. The reader is using knowledge that generalizes across words.", "children": ["The demonstration establishes generalization. By itself, it does not decide whether that knowledge consists of categorical rules or learned statistical patterns."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 7}, "m3-reading1-p008": {"status": "ready", "blocks": [{"text": "**Fast nonword naming is evidence that decoding is a normal part of skilled reading.** It does not by itself prove that a separate rule system performs the task.", "children": []}, {"text": "Participants read the items aloud, and naming time measures how quickly a pronunciation becomes available. The small difference shows that unfamiliarity does not make pronunciation an entirely slow, deliberate process.", "children": ["Both rules and statistical generalization might produce efficient decoding. The speed result constrains a theory without selecting one architecture on its own."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 8}, "m3-reading1-p009": {"status": "ready", "blocks": [{"text": "**Generalization can be graded rather than all-or-none.** Ambiguous pseudowords reveal competing pronunciation possibilities.", "children": []}, {"text": "A response reflects the spelling–sound patterns available from previously learned words. Different familiar patterns can favor different responses to the same novel form.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 9}, "m3-reading1-p010": {"status": "ready", "blocks": [{"text": "**Accepting both /strɛd/ and /strid/ is information about the knowledge being generalized.** A model must explain the alternatives, not merely choose one output and ignore the other.", "children": []}, {"text": "Testing novel items reveals what a reader has generalized, because the particular word cannot simply have been memorized.", "children": ["The challenge for a categorical rule account is to explain why multiple outputs seem acceptable. A statistical account can represent differing support for alternative pronunciations."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 10}, "m3-reading1-p011": {"status": "ready", "blocks": [{"text": "**A word's difficulty depends partly on how its spelling neighbors are pronounced.** The issue is not simply whether the reader knows the letters.", "children": []}, {"text": "A strict regular–irregular division is less clear when a spelling neighborhood contains several pronunciations. ROLL, POLL and TOLL support one pattern, while DOLL differs.", "children": ["COOK, TOOK and BOOK likewise contrast with SPOOK. These neighborhoods motivate asking how much support a pronunciation has from similar words."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 11}, "m3-reading1-p012": {"status": "ready", "blocks": [{"text": "**General decoding explains part of reading, but familiar-word knowledge also needs an account.** The two sources of information are conceptually distinguishable even before deciding how they are implemented.", "children": []}, {"text": "**Lexical information** concerns knowledge of particular words. A complete account must explain how experience with a specific word contributes alongside general spelling patterns.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 12}, "m3-reading1-p013": {"status": "ready", "blocks": [{"text": "**Letter recognition can depend on the word surrounding the letter.** Feedback supplies a mechanism by which whole-word knowledge influences perception.", "children": []}, {"text": "Activated word candidates send feedback to their constituent letters. A letter supported by a plausible word receives additional activation even when its local visual evidence is unclear.", "children": ["Competing candidates do not remain equally active. Their activation changes as the network settles on an interpretation."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 13}, "m3-reading1-p014": {"status": "ready", "blocks": [{"text": "**Recognizing a word and recognizing its letters can support one another.** Top-down feedback is the word-to-letter part of that interaction.", "children": []}, {"text": "This makes recognition interactive. Information does not flow only from isolated features upward to a finished word.", "children": ["The mechanism helps explain why an ambiguous letter can become easier to recognize when it appears in a familiar word context."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 14}, "m3-reading1-p015": {"status": "ready", "blocks": [{"text": "**Familiarity with a particular word contributes to reading speed.** Knowing general spelling patterns does not remove the benefit of repeated encounters with that word.", "children": []}, {"text": "Lexicality compares whether the item is a word. Frequency compares how often a particular word has been encountered.", "children": ["The English Lexicon Project data show that the frequency effect occurs across many observations, rather than depending on a few unusually easy examples."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 15}, "m3-reading1-p016": {"status": "ready", "blocks": [{"text": "**The frequency effect is not adequately explained by saying that frequent words are merely shorter.** Its contribution survives statistical control of other properties.", "children": []}, {"text": "The analysis uses about 3,000 words read by young and older adults. Frequency still contributes when other predictors are considered.", "children": ["This makes a simple length-confound explanation less plausible. It does not turn an observational predictor into an experimentally isolated cause."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 16}, "m3-reading1-p017": {"status": "ready", "blocks": [{"text": "**Experience matters especially when pronunciation conflicts with the usual spelling pattern.** Frequent exposure reduces the disadvantage of exception words.", "children": []}, {"text": "Naming latency is the time needed to begin saying the word. Higher values mean slower responses.", "children": ["An interaction means the effect of one factor depends on the other. The regularity cost is not a fixed amount added equally to high- and low-frequency words."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 17}, "m3-reading1-p018": {"status": "ready", "blocks": [{"text": "**Two routes can explain why regularity matters most for unfamiliar words.** Fast lexical processing protects familiar exceptions from competing sublexical output.", "children": []}, {"text": "For a high-frequency word, lexical information becomes available quickly enough to reduce the influence of the decoding output.", "children": ["For a low-frequency exception, the lexical response is less efficient and the regularized decoding output can interfere. Nonwords depend on decoding because they lack a stored whole-word entry."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 18}, "m3-reading1-p019": {"status": "ready", "blocks": [{"text": "**Preserved word reading does not guarantee preserved decoding.** A patient can draw on learned word information while performing poorly on novel letter sequences.", "children": []}, {"text": "Cacciopo van Vliet and colleagues compare real-word reading with several nonword tasks. The patients can often recognize and pronounce known words while struggling to generate a plausible pronunciation for an unfamiliar spelling.", "children": ["The selective difficulty suggests that familiar-word success and novel-form decoding do not rely on every process to the same degree."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 19}, "m3-reading1-p020": {"status": "ready", "blocks": [{"text": "**Surface dyslexia exposes the cost of relying on typical correspondences when a word is exceptional.** The errors are systematic rather than arbitrary failures to see the letters.", "children": []}, {"text": "DEAF pronounced like “deef” and SHOE pronounced like “show” illustrate regularization. The response is related to the spelling, but it is not the target word's learned pronunciation.", "children": ["Relatively good regular-word and nonword reading shows that generating pronunciation from spelling can remain useful despite difficulty with exceptions."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 20}, "m3-reading1-p021": {"status": "ready", "blocks": [{"text": "**Opposite patient patterns support separable contributions to reading.** They are stronger evidence than a single group doing worse on one difficult task.", "children": []}, {"text": "The first pattern shows that unfamiliar decoding can be difficult despite relatively preserved familiar-word reading. The second shows that exception reading can be difficult despite relatively preserved pseudoword reading.", "children": ["Together, the patterns are harder to explain by saying that one task is simply harder for everyone."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 21}, "m3-reading1-p022": {"status": "ready", "blocks": [{"text": "**The strength of a double dissociation comes from the reversal across cases.** The interpretation must explain both directions of impairment.", "children": []}, {"text": "The reversal suggests that the tasks depend differently on underlying processes. For reading, pseudowords and exception words place different demands on the system.", "children": ["The evidence still requires a theory of what those underlying processes are. It does not uniquely identify a particular set of boxes in a model."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 22}, "m3-reading1-p023": {"status": "ready", "blocks": [{"text": "**The model turns an observed dissociation into a claim about damaged processing components.** Each proposed lesion must produce the corresponding pattern of spared and impaired performance.", "children": []}, {"text": "Damage to conversion particularly affects nonwords because there is no familiar whole-word pronunciation to retrieve.", "children": ["Damage to input or output word representations, called logogens in this account, or their connections makes exceptions vulnerable because general decoding supplies the wrong pronunciation."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 23}, "m3-reading1-p024": {"status": "ready", "blocks": [{"text": "**A patient's error type matters as well as overall accuracy.** Lexical-looking errors challenge the idea that the remaining reading process is wholly independent of word knowledge.", "children": []}, {"text": "The example “incense” read as “increase” is a real-word response. A simple letter–sound mistake could instead produce a nonword, so the actual response raises a question about whole-word influence.", "children": ["Possible responses are to allow a more complicated combination of routes or to revise the supposedly nonlexical process itself. The observation motivates refinement rather than settling the issue alone."]}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 24}, "m3-reading2-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 1}, "m3-reading2-p002": {"status": "ready", "blocks": [{"text": "**The two-route proposal connects several reading findings to a common processing account.** Its success depends on explaining the full pattern, not only nonword reading.", "children": []}, {"text": "A model must explain fast pseudoword reading, faster familiar-word reading, frequency effects, regularity effects and their interaction.", "children": ["It must also explain why pseudoword and exception-word reading can be differently impaired after brain injury. These observations motivate the architecture but do not uniquely prove it."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 2}, "m3-reading2-p003": {"status": "ready", "blocks": [{"text": "**The DRC does not treat every connection as the same kind of computation.** Word-form activation and rule-based conversion are separate mechanisms.", "children": []}, {"text": "The lexical portion includes orthographic and phonological lexicons, representing written and spoken word forms. These representations are distinguished from meanings.", "children": ["The implementation described here does not implement semantics. The GPC rule system also has processing assumptions different from those of the interactive lexical network."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 3}, "m3-reading2-p004": {"status": "ready", "blocks": [{"text": "**Encapsulation does not mean that the routes never affect the same response.** They remain separate internally but meet at the phoneme output.", "children": []}, {"text": "The GPC and lexical routes do not interact throughout their internal computations. They converge in the phoneme response buffer.", "children": ["If the routes favor different phonemes, they can compete at that shared output. An exception word can therefore receive a correct lexical pronunciation and an incompatible regularized pronunciation."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 4}, "m3-reading2-p005": {"status": "ready", "blocks": [{"text": "**A rule list is incomplete without a procedure for resolving overlapping rules.** Both the mapping and its conditions of application matter.", "children": []}, {"text": "A model also needs a way to decide which applicable rule takes priority. A larger-unit rule can supersede rules for its individual letters.", "children": ["Context-sensitive rules restrict a pronunciation to specified surrounding letters or positions. This makes the procedure more than a simple lookup of one sound per letter."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 5}, "m3-reading2-p006": {"status": "ready", "blocks": [{"text": "**Using statistics to select a rule differs from representing graded statistics while reading.** The two approaches can make different predictions for ambiguous spellings.", "children": []}, {"text": "The possible pronunciations of OUGH have more divided statistical support than those of EIGH. A rule can still operate categorically for both spellings.", "children": ["A probabilistic account instead allows alternatives to receive different strengths of support. The distinction concerns processing, not whether the model designer ever consulted frequency information."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 6}, "m3-reading2-p007": {"status": "ready", "blocks": [{"text": "**A cognitively useful model should reproduce the relevant failures.** Maximizing pronunciation accuracy is not the only goal.", "children": []}, {"text": "A regularizing route helps account for errors in surface dyslexia and for slow naming of low-frequency exception words.", "children": ["The theory therefore claims that people's sublexical computation is constrained, rather than assuming that the best possible spelling algorithm is the correct cognitive model."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 7}, "m3-reading2-p008": {"status": "ready", "blocks": [{"text": "**A modular account predicts restricted access to information.** The GPC route may produce an inappropriate response even when another part of the system has word-specific knowledge.", "children": []}, {"text": "This resembles a modular parsing proposal in which an early syntactic process follows structural principles without immediately using world knowledge.", "children": ["Pseudoword naming exposes the conversion procedure because a familiar lexical entry is unavailable. Regularization errors expose it when conversion favors the wrong pronunciation."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 8}, "m3-reading2-p009": {"status": "ready", "blocks": [{"text": "**A broad list of successful simulations is informative, but the conditions of each success also matter.** Model evaluation includes both coverage and the assumptions used to obtain it.", "children": []}, {"text": "Accounting for several effects with one architecture is stronger than fitting a single result. It also requires examining which assumptions stay fixed and which are changed between tasks.", "children": ["The model's research strategy places strong weight on human behavioral evidence as a constraint on architecture."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 9}, "m3-reading2-p010": {"status": "ready", "blocks": [{"text": "**Fitting lexical decision requires an account of the decision itself.** Recognition activity does not automatically specify when to say yes or no.", "children": []}, {"text": "A “yes” response can depend on a strongly activated single word or on total activity across the orthographic lexicon. A “no” response occurs if the criteria are not met by a deadline.", "children": ["The implementation also changes inhibition and uses time-dependent thresholds. These choices help obtain a fit, but they add assumptions beyond the basic two-route diagram."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 10}, "m3-reading2-p011": {"status": "ready", "blocks": [{"text": "**Modularity is a claim about how components operate and communicate.** It is more specific than drawing two arrows in a model.", "children": []}, {"text": "The GPC system takes letters as input and sends phoneme activation toward the response system. This is **domain specificity** in the account.", "children": ["The absence of lexical feedback into the GPC system is **informational encapsulation**. Having two pathways alone would not establish those stronger restrictions."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 11}, "m3-reading2-p012": {"status": "ready", "blocks": [{"text": "**An emergentist account asks how experience creates useful reading behavior.** Regularity can arise from learning across words rather than from a separate rule mechanism.", "children": []}, {"text": "Seidenberg and McClelland trained an associative network to map spelling onto pronunciation. The modeled spelling-to-sound pathway used one learned mapping for different kinds of words.", "children": ["Reading skill emerges from learning rather than being specified entirely as a hand-built list of rules and lexical entries."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 12}, "m3-reading2-p013": {"status": "ready", "blocks": [{"text": "**Word-specific knowledge and generalization can coexist in the same learned system.** They do not have to be implemented as a dictionary and a separate symbolic rule list.", "children": []}, {"text": "The same learning mechanism can capture both patterns shared by many words and information specific to a familiar word.", "children": ["The research strategy asks whether domain-general learning can explain reading. This contrasts with choosing separate adult processing components primarily from neuropsychological dissociations."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 13}, "m3-reading2-p014": {"status": "ready", "blocks": [{"text": "**Consistency supplies support from other words, while frequency strengthens experience with the particular word.** Their joint influence explains why infrequent exceptions are especially difficult.", "children": []}, {"text": "An exception conflicts with those patterns, so learning its particular mapping is especially important. Frequent exposure strengthens that word-specific mapping.", "children": ["A low-frequency exception has both weak item-specific learning and poor support from the dominant pattern. This combination creates a larger disadvantage than either factor alone."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 14}, "m3-reading2-p015": {"status": "ready", "blocks": [{"text": "**Spelling–sound support varies in degree.** A statistical description captures differences that a simple regular-versus-irregular label can hide.", "children": []}, {"text": "LATE and DUST illustrate consistent patterns. GAVE and MINT have many friends but also enemies such as HAVE and PINT.", "children": ["DOWN versus KNOWN and POUR versus SOUR illustrate ambiguity. An exception such as PINT has relatively little support compared with its competing neighborhood."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 15}, "m3-reading2-p016": {"status": "ready", "blocks": [{"text": "**Novel pronunciation can result from applying learned statistical structure.** Nonword reading therefore does not automatically establish a separate symbolic route.", "children": []}, {"text": "No stored entry for the particular nonword is required. The same learned correspondences that support consistent words can support a new combination.", "children": ["This is a proposed mechanism for decoding without a separate GPC rule module."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 16}, "m3-reading2-p017": {"status": "ready", "blocks": [{"text": "**A failed simulation does not identify its own cause.** The failure must be traced to the architecture, learning assumptions, representations or other implementation choices.", "children": []}, {"text": "One possibility is that a single associative mechanism cannot explain the task. Another is that the chosen representations fail to capture the similarities needed for generalization.", "children": ["Improving the implementation while retaining the theoretical mechanism helps distinguish these possibilities."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 17}, "m3-reading2-p018": {"status": "ready", "blocks": [{"text": "**Changing the representation can improve decoding without adding a symbolic rule system.** That distinction matters when evaluating the original theoretical claim.", "children": []}, {"text": "Plaut and colleagues improved the phonological representations and obtained better nonword performance. This supports a representational explanation for at least part of the earlier failure.", "children": ["Behavioral relations between phonological processing and decoding also make phonology a relevant target for explanation."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 18}, "m3-reading2-p019": {"status": "ready", "blocks": [{"text": "**The same representational weakness can have unequal effects on words and nonwords.** Familiarity can partly compensate where new-item generalization cannot.", "children": []}, {"text": "A familiar word can retain support from its own training history. A nonword lacks that item-specific experience and depends more heavily on generalization.", "children": ["This produces a reason for unfamiliar forms to be especially vulnerable to poor representations without requiring a dedicated nonword mechanism."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 19}, "m3-reading2-p020": {"status": "ready", "blocks": [{"text": "**A selective-looking reading deficit can emerge from degraded shared representations.** Nonwords are especially dependent on reliable generalization.", "children": []}, {"text": "The manipulation produced poorer nonword decoding and relative sparing of word recognition. It also linked the severity of the phonological deficit to the degree of decoding difficulty.", "children": ["The model therefore connects a reading pattern to the quality of a more general phonological system."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 20}, "m3-reading2-p021": {"status": "ready", "blocks": [{"text": "**The model links exception reading to semantic processing.** A reading dissociation can reflect unequal dependence on broader language systems.", "children": []}, {"text": "An exception has weak support from typical spelling–sound regularities. Meaning-related support can help produce its learned pronunciation.", "children": ["Reducing that support creates a surface-dyslexia-like pattern without defining a separate exception-word list as the sole explanation."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 21}, "m3-reading2-p022": {"status": "ready", "blocks": [{"text": "**Multiple pathways do not necessarily imply modular routes.** Their learning rules, information types and interactions distinguish the accounts.", "children": []}, {"text": "Spelling-to-sound learning develops in the presence of meaning-related support. The contribution of one pathway therefore affects what another pathway learns.", "children": ["This allows graded impairments. Phonological dyslexics can make some exception errors, and surface dyslexics can make some nonword errors."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 22}, "m3-reading2-p023": {"status": "ready", "blocks": [{"text": "**The triangle account predicts that exception reading should vary with semantic ability.** The patient data broadly follow that relationship.", "children": []}, {"text": "The model and patient panels show comparable overall relationships, although individual patients vary. This supports an association between meaning and exceptional pronunciation.", "children": ["The finding is informative because it links a reading weakness to a broader semantic measure rather than describing only a reading-task dissociation."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 23}, "m3-reading2-p024": {"status": "ready", "blocks": [{"text": "**An outlier and a clean dissociation are not automatically the same thing.** The strength and reliability of the apparent exception matter.", "children": []}, {"text": "Woollams and colleagues interpret such observations in relation to the full distribution rather than treating each outlier as an automatic refutation.", "children": ["The scientific issue is whether the unusual cases show a stable separate pattern or arise within a noisy overall association."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 24}, "m3-reading2-p025": {"status": "ready", "blocks": [{"text": "**Repeated observations help test whether an apparent dissociation persists.** A one-time exceptional score is less compelling if the patient's later trajectory follows the general relation.", "children": []}, {"text": "In most cases, declining semantic ability accompanies declining exception-word reading. Some initially unusual observations move closer to the broader relation on retesting.", "children": ["This strengthens the association while leaving room for variability between individuals."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 25}, "m3-reading2-p026": {"status": "ready", "blocks": [{"text": "**A flexible model can closely reproduce observed data.** Evaluating the explanation also requires asking how the matching simulation was selected.", "children": []}, {"text": "This produced an excellent fit to the patient scores. The selection procedure is part of how that fit was achieved.", "children": ["The fit should be distinguished from predicting each patient's pattern before choosing among many possible parameter combinations."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 26}, "m3-reading2-p027": {"status": "ready", "blocks": [{"text": "**Goodness of fit is only one part of model evaluation.** A model should explain why the pattern occurs, not only contain a setting that resembles it.", "children": []}, {"text": "The question is not whether close agreement is bad in itself. It is whether the account predicts the relation with principled assumptions or accommodates each case after seeing the outcome.", "children": ["Comparing theories therefore requires attention to both fit and how much freedom produced it."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 27}, "m3-reading2-p028": {"status": "ready", "blocks": [{"text": "**The models compete over explanation, not over whether these basic reading patterns exist.** Shared behavioral success makes their differing assumptions especially important.", "children": []}, {"text": "Agreement on the phenomena does not mean agreement on mechanisms. One account emphasizes specialized routes, while the other emphasizes learning across interacting representational systems.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 28}, "m3-reading2-p029": {"status": "ready", "blocks": [{"text": "**The same task pattern receives a different mechanistic explanation in each model.** Keep the observed phenomenon separate from the proposed locus of impairment.", "children": []}, {"text": "For phonological dyslexia, DRC emphasizes GPC damage and the triangle account emphasizes broader phonological impairment.", "children": ["For surface dyslexia, DRC emphasizes lexical-route damage and the triangle account emphasizes semantic impairment."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 29}, "m3-reading2-p030": {"status": "ready", "blocks": [{"text": "**Phonological and semantic measures can help identify what lies behind a reading dissociation.** They extend the evidence beyond the reading scores alone.", "children": []}, {"text": "The statistical-learning account links phonology to spelling–sound generalization and semantics to words whose pronunciation is poorly supported by that generalization.", "children": ["Both dissociations and associations matter. A theory should explain selective weaknesses and the related abilities that vary with them."]}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 30}, "m3-reading2-p031": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 31}, "m3-morphology-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 1}, "m3-morphology-p002": {"status": "ready", "blocks": [{"text": "**Productive word formation goes beyond retrieving a stored list.** The theoretical issue is whether that productivity requires symbolic rules or can emerge from learning.", "children": []}, {"text": "The central question is how a speaker extends a familiar pattern to a new item. English plural and past-tense formation provide tractable examples.", "children": ["Generalization can also produce playful or incorrect forms. This shows productive use of patterns, rather than a vocabulary containing only previously heard responses."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 2}, "m3-morphology-p003": {"status": "ready", "blocks": [{"text": "**A novel item prevents success from being explained as retrieval of that item's memorized inflection.** The child must extend a learned pattern.", "children": []}, {"text": "The pictured task introduces one WUG and then asks about two. Producing WUGS applies plural knowledge to a new noun.", "children": ["The same logic can test past tense using novel verbs. Success shows productive knowledge, but does not by itself distinguish symbolic rules from statistical generalization."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 3}, "m3-morphology-p004": {"status": "ready", "blocks": [{"text": "**Past-tense knowledge includes generalization and item-specific variation.** The contrast creates a test for different theories of morphology.", "children": []}, {"text": "Irregular pairs such as GO–WENT, TAKE–TOOK and EAT–ATE do not follow that default form. Some irregulars share smaller patterns with other verbs.", "children": ["A theory must explain both familiar exceptions and productive extension to novel verbs."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 4}, "m3-morphology-p005": {"status": "ready", "blocks": [{"text": "**In this account, productive rule application and remembered exceptions are separate kinds of knowledge.** That is stronger than simply observing that regular and irregular forms look different.", "children": []}, {"text": "The regular process can apply to a new verb because it does not require an entry for that particular past tense.", "children": ["The irregular system stores word-specific information and can be influenced by frequency and similarity. A successful explanation also needs to prevent an available irregular form from being replaced by a regularization."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 5}, "m3-morphology-p006": {"status": "ready", "blocks": [{"text": "**Similar-looking architectures can solve different computational problems.** Keep morphological inflection separate from grapheme–phoneme conversion.", "children": []}, {"text": "Pinker and Ullman's diagram associates lexical lookup with declarative memory and grammatical combination with procedural processing.", "children": ["Like dual-route reading, the account separates word-specific knowledge from a productive operation. Unlike reading aloud, its task is to transform a stem according to a grammatical feature, rather than convert spelling into sound."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 6}, "m3-morphology-p007": {"status": "ready", "blocks": [{"text": "**The motivation for an architecture matters when evaluating its evidence.** Similar diagrams do not mean that the theories were derived from the same observations.", "children": []}, {"text": "Reading dual-route theories were strongly motivated by neuropsychological dissociations. The morphology proposal also reflects a commitment to keeping the grammatical rule system distinct from exceptional lexical information.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 7}, "m3-morphology-p008": {"status": "ready", "blocks": [{"text": "**Separating exceptions protects a simple rule, but creates a second mechanism that must also be explained.** The associative system carries graded and item-specific influences.", "children": []}, {"text": "KEEP–KEPT, WEEP–WEPT and LEAP–LEAPT illustrate similarity among irregular forms. An exception can belong to a small family rather than being wholly unrelated to other words.", "children": ["Assigning these properties to lexical memory lets the rule system remain categorical and general."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 8}, "m3-morphology-p009": {"status": "ready", "blocks": [{"text": "**One learning mechanism is proposed for both regularities and exceptions.** The challenge is to explain accurate generalization as well as familiar forms.", "children": []}, {"text": "The model encodes a root's phonology, transforms that representation through modifiable connections, and decodes an output pattern.", "children": ["Regularity is a pattern learned from many examples. Irregular forms are also learned within the same system."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 9}, "m3-morphology-p010": {"status": "ready", "blocks": [{"text": "**Development can involve temporary errors as knowledge changes.** A theory must explain the entire trajectory, not just the final adult response.", "children": []}, {"text": "The middle error is a **regularization**, because the child applies the common past-tense pattern to an irregular verb.", "children": ["The decline does not necessarily mean that the child has stopped learning. A changing system can generalize more broadly while temporarily disrupting an earlier correct response."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 10}, "m3-morphology-p011": {"status": "ready", "blocks": [{"text": "**Overregularization is interpreted as productive rule use that is not yet sufficiently constrained by exceptions.** Recovery depends on the irregular form winning over the rule output.", "children": []}, {"text": "When the rule is learned, it can be applied too broadly, yielding RUNNED. Later, learned irregulars and the blocking process prevent that regularization.", "children": ["This account treats the developmental stages as involving distinguishable processes rather than only gradual changes in one mapping."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 11}, "m3-morphology-p012": {"status": "ready", "blocks": [{"text": "**A shift in the distribution of experience can temporarily disrupt familiar responses.** The learning account explains the developmental pattern through changing weights and input.", "children": []}, {"text": "As more regular verbs enter training, their common pattern changes the network's responses. That generalization can interfere with previously learned irregulars.", "children": ["With further learning, the network can recover the irregular responses while retaining broad regularity. No new symbolic rule component is inserted at the point of decline."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 12}, "m3-morphology-p013": {"status": "ready", "blocks": [{"text": "**Generalization is defined relative to the learner's experience.** A familiar human word is still a valid novel-model test when it was withheld from training.", "children": []}, {"text": "The test therefore uses the logic of a wug task even when the items are real words to humans.", "children": ["The model can generate many appropriate past-tense features, but feature-level success must be distinguished from producing an entirely correct word."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 13}, "m3-morphology-p014": {"status": "ready", "blocks": [{"text": "**A plausible learning curve is not enough if the model produces implausible words.** Error structure provides another test of the representation and decoding process.", "children": []}, {"text": "The model authors acknowledge that people are unlikely to make some of these errors. They suggest that additional output constraints could reduce bizarre responses.", "children": ["This separates capturing an overall learning pattern from matching the detailed form of human errors."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 14}, "m3-morphology-p015": {"status": "ready", "blocks": [{"text": "**Combining evidence for alternatives is different from blending the alternatives into a new malformed output.** A model must preserve the distinctions needed to produce a coherent response.", "children": []}, {"text": "For SING, partial support for different sound patterns can overlap. Decoding the combined activation can produce a hybrid rather than selecting a coherent word.", "children": ["The criticism targets the representation and its treatment of competing outputs, not merely the presence of learning."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 15}, "m3-morphology-p016": {"status": "ready", "blocks": [{"text": "**The regular–irregular contrast can arise from how phonological and semantic information contribute.** A graded system can produce systematic differences between item types.", "children": []}, {"text": "Reliable sound representations support extension from familiar present–past pairs to new forms. Irregular mappings receive additional support from the particular word's semantic representation.", "children": ["The hypothesis concerns different degrees of dependence on shared systems, rather than a separate symbolic rule route for every regular response."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 16}, "m3-morphology-p017": {"status": "ready", "blocks": [{"text": "**The same architecture should explain both sides of the patient pattern.** Selectivity must arise from the manipulated representations and their contribution to the task.", "children": []}, {"text": "A nonword has no familiar item-specific semantic history to support its inflection. A known irregular can require semantic support because its output is not well predicted by the dominant pattern.", "children": ["Manipulating phonological or semantic integrity tests whether these different dependencies can produce opposite impairment profiles."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 17}, "m3-morphology-p018": {"status": "ready", "blocks": [{"text": "**Difficulty with productive inflection may be connected to sound processing.** The nonword condition is particularly demanding because it relies on generalization.", "children": []}, {"text": "Regular forms are also vulnerable, while irregular forms are relatively better in the displayed comparison. A novel BLICK must be transformed without relying on a familiar stored past tense.", "children": ["This motivates investigating phonological contributions to the apparent morphological deficit."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 18}, "m3-morphology-p019": {"status": "ready", "blocks": [{"text": "**Damaging phonology can imitate a failure of productive morphology without removing a symbolic rule.** The mechanism being tested is the quality of sound representations.", "children": []}, {"text": "The model manipulation weakens sound-based computation. Familiar words retain support unavailable to an untrained nonword.", "children": ["The similarity to the patient pattern shows how a selective-looking morphological deficit can arise from a broader phonological impairment."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 19}, "m3-morphology-p020": {"status": "ready", "blocks": [{"text": "**Relatively preserved nonword inflection can coexist with poor irregular inflection.** The theory must explain this reverse pattern as well as phonological impairment.", "children": []}, {"text": "Their irregular performance is lower than their regular and nonword performance in the displayed comparison.", "children": ["This creates the other side of the dissociation and motivates examining the information that especially supports known irregular forms."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 20}, "m3-morphology-p021": {"status": "ready", "blocks": [{"text": "**Irregular vulnerability is predicted from its greater dependence on semantic support.** The model does not have to delete an isolated exception list to produce that pattern.", "children": []}, {"text": "Typical phonological patterns still support many regular and novel forms. Nonwords can nevertheless be somewhat worse than regular words because they lack item-specific training.", "children": ["This shows how unequal dependence on semantics can produce the reverse of the phonological-damage profile."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 21}, "m3-morphology-p022": {"status": "ready", "blocks": [{"text": "**A task dissociation should be checked for differences in the demands of its items.** Related abilities can explain why one condition is more vulnerable.", "children": []}, {"text": "Patterson and colleagues found that irregular impairment in semantic dementia correlated with semantic deficit severity.", "children": ["These findings connect morphology to phonological and semantic abilities, making a pure rule-versus-word interpretation less straightforward."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 22}, "m3-morphology-p023": {"status": "ready", "blocks": [{"text": "**Different forms draw on the same systems to different degrees.** General patterns and word-specific support can jointly determine an output.", "children": []}, {"text": "Semantic information supports forms that depart from the dominant -ed pattern. Some irregulars also benefit from smaller phonological families and can be relatively spared.", "children": ["Regularity and exception status therefore describe degrees of statistical support rather than perfectly isolated kinds of processing."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 23}, "m3-morphology-p024": {"status": "ready", "blocks": [{"text": "**The diagnostic description and the causal explanation are separate.** A grammatical difficulty can coexist with weaknesses in other processes that support language.", "children": []}, {"text": "The profile can also involve phonology, reading, working memory and speech perception. This broader range matters when evaluating a theory that locates the problem only in grammar.", "children": ["A relative language difficulty does not by itself identify a single damaged learning mechanism."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 24}, "m3-morphology-p025": {"status": "ready", "blocks": [{"text": "**The crucial issue is whether the deficit is selective enough to support the proposed rule mechanism.** Merely finding poor past tense does not establish its cause.", "children": []}, {"text": "This proposal uses past-tense performance to argue for a mechanism specific to grammatical rules.", "children": ["The prediction must be tested against the complete pattern, including irregular performance and broader phonological difficulties."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 25}, "m3-morphology-p026": {"status": "ready", "blocks": [{"text": "**The observed pattern is broader than a simple intact-irregulars versus damaged-rules contrast.** Novel forms are most vulnerable, while familiar forms are not unaffected.", "children": []}, {"text": "Nonwords are especially difficult for the SLI group, but regulars and irregulars are also impaired. The results therefore contain a broad deficit as well as unequal condition difficulty.", "children": ["An explanation should account for the entire profile rather than reporting only that productive forms are poor."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 26}, "m3-morphology-p027": {"status": "ready", "blocks": [{"text": "**A graded phonological manipulation creates graded developmental impairment.** Novel generalization is most fragile because it cannot rely on a word's own training history.", "children": []}, {"text": "The intact model performs substantially better. Even intact learning shows different performance across regulars, irregulars and nonwords.", "children": ["The comparison tests whether a phonological learning weakness can reproduce important aspects of the behavioral profile without a missing grammatical rule."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 27}, "m3-morphology-p028": {"status": "ready", "blocks": [{"text": "**An especially large nonword deficit does not imply that other forms avoid phonology.** It reflects different degrees of dependence on generalization.", "children": []}, {"text": "Nonwords are particularly dependent on generalizing a sound pattern to a new form. Familiar words have additional item-specific learning that can partly support their responses.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 28}, "m3-morphology-p029": {"status": "ready", "blocks": [{"text": "**Past-tense behavior can be explained through learned structure and unequal support from shared representations.** The proposal must still explain developmental, patient and generalization data together.", "children": []}, {"text": "Irregular performance is associated with semantic processing. Wug-test performance is associated with phonological processing.", "children": ["These associations provide tests of the proposed underlying mechanisms, beyond simply assigning different item types to different boxes."]}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 29}, "m3-morphology-p030": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 30}, "m3-thought-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 1}, "m3-thought-p002": {"status": "ready", "blocks": [{"text": "**Influencing thought is different from completely determining thought.** Keep that distinction explicit when interpreting a language-group difference.", "children": []}, {"text": "The strongest reading would make language determine what a person can think. A weaker claim is that habitual language use biases attention, memory or preferred ways of representing a situation.", "children": ["These claims require different evidence. A preference associated with language does not establish that alternative thought is impossible."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 2}, "m3-thought-p003": {"status": "ready", "blocks": [{"text": "**Testing linguistic relativity requires a narrower claim than saying that every language creates a completely separate world.** Space and time provide specific domains in which to test representational preferences.", "children": []}, {"text": "Sapir and Whorf should not automatically be assigned the strongest deterministic interpretation of selected quotations.", "children": ["A precise study must identify which cognitive process is affected and what alternative explanations the comparison controls."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 3}, "m3-thought-p004": {"status": "ready", "blocks": [{"text": "**The object does not have to move for its verbal description to change.** Changing the reference frame changes the relation being described.", "children": []}, {"text": "The ball can be located with respect to the viewer, the chair's own orientation or a direction independent of either.", "children": ["Different descriptions can identify the same physical position while organizing that position differently."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 4}, "m3-thought-p005": {"status": "ready", "blocks": [{"text": "**Ask what fixes the direction in each description.** The object's orientation, the observer's body and a stable external direction are not interchangeable.", "children": []}, {"text": "“At the chair's front” uses the chair's intrinsic front. “To the left of the chair from my viewpoint” depends on the observer.", "children": ["“North of the chair” uses an absolute direction that does not reverse when the observer turns around."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 5}, "m3-thought-p006": {"status": "ready", "blocks": [{"text": "**A direction can stay fixed when a person turns.** Absolute coding differs from coding an object as being on the viewer's left.", "children": []}, {"text": "Tzeltal commonly uses absolute directions in circumstances where English speakers might use these relative terms.", "children": ["The contrast motivates asking whether habitual language use relates to nonverbal spatial coding, rather than merely comparing two ways of giving spoken directions."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 6}, "m3-thought-p007": {"status": "ready", "blocks": [{"text": "**A landmark origin and an absolute use are different properties.** A historically landscape-based term can become a stable directional reference.", "children": []}, {"text": "A direction is retained as a stable spatial reference rather than being recalculated from the speaker's current left and right.", "children": ["This allows positions to be described consistently as the speaker changes orientation."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 7}, "m3-thought-p008": {"status": "ready", "blocks": [{"text": "**A stable local convention is not automatically an absolute frame that transfers everywhere.** Its usefulness depends on the landmark system being available.", "children": []}, {"text": "A city's conventional map orientation can also differ from magnetic north. Familiar spatial language therefore reflects local practices as well as geometric directions.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 8}, "m3-thought-p009": {"status": "ready", "blocks": [{"text": "**The rotation makes two otherwise similar descriptions predict different choices.** The nonverbal response reveals a preferred spatial coding strategy.", "children": []}, {"text": "A relative response preserves the arrangement with respect to the person's viewpoint. An absolute response preserves its orientation in the environment, so the two responses diverge after rotation.", "children": ["Dutch speakers predominantly gave relative responses, while Tzeltal speakers gave more absolute responses. The association is consistent with their preferred linguistic frames but does not isolate language from all other experience."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 9}, "m3-thought-p010": {"status": "ready", "blocks": [{"text": "**The task goes beyond reproducing one remembered arrangement.** It asks whether a frame is used when combining spatial relations to make an inference.", "children": []}, {"text": "They then place an object relative to another using the combined information. Relative and absolute coding lead to different placements because the person's orientation has changed.", "children": ["Dutch and Tzeltal response patterns again differ in the direction associated with their preferred spatial frames."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 10}, "m3-thought-p011": {"status": "ready", "blocks": [{"text": "**A language comparison can be confounded with a setting comparison.** The environment must be considered before assigning the entire difference to linguistic structure.", "children": []}, {"text": "An environment with useful landmarks can encourage landmark-based coding. A windowless laboratory can make viewer-relative descriptions more convenient.", "children": ["Manipulating landmark availability within English speakers tests whether the behavior can change without changing native language."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 11}, "m3-thought-p012": {"status": "ready", "blocks": [{"text": "**Spatial strategy is sensitive to the testing environment.** A within-language change helps reveal a potential confound in a between-language comparison.", "children": []}, {"text": "The manipulation changes the spatial information available while keeping the language group the same.", "children": ["This demonstrates that task context can influence the response. It challenges an explanation in which language alone fixes the chosen frame."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 12}, "m3-thought-p013": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 13}, "m3-thought-p014": {"status": "ready", "blocks": [{"text": "**The relevant question is what the study actually isolates.** A language-group effect can be real while its causal interpretation remains unsettled.", "children": []}, {"text": "A controlled comparison must separate the effect of the environment from any contribution of habitual linguistic coding.", "children": ["Showing an environmental effect does not prove that language never matters. It limits what can be inferred from an uncontrolled comparison."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 14}, "m3-thought-p015": {"status": "ready", "blocks": [{"text": "**Changing a task can change the process it measures.** A landmark effect in an easy, transparent task may not settle how people habitually remember spatial relations.", "children": []}, {"text": "Participants who infer what is being tested can alter their response for reasons different from habitual spatial coding.", "children": ["The response therefore focuses on memory load and task transparency, rather than denying that landmarks can ever matter."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 15}, "m3-thought-p016": {"status": "ready", "blocks": [{"text": "**A relative preference can persist despite changes in the environment when the memory task is more demanding.** This narrows the conditions under which the landmark alternative explains behavior.", "children": []}, {"text": "Under these conditions, the preference for relative coding remained.", "children": ["The result suggests that the environmental effect depends on how the task is arranged, including how much memory and strategic inference it encourages."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 16}, "m3-thought-p017": {"status": "ready", "blocks": [{"text": "**The involvement of memory creates another mechanism to examine.** A task can be nonverbal in its response while still allowing verbal recoding internally.", "children": []}, {"text": "The relative preference is reported when memory demands are substantial and the experimenter's interest is less obvious.", "children": ["That pattern makes it important to ask how the sequence is stored during the delay, not only which direction is chosen at the end."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 17}, "m3-thought-p018": {"status": "ready", "blocks": [{"text": "**A nonverbal task does not guarantee nonverbal processing.** Verbal recoding is a concrete alternative mechanism for the spatial-memory result.", "children": []}, {"text": "This strategy would connect language to the task through working memory and ordering habits, rather than through an inability to represent absolute space.", "children": ["The interpretation changes because the same choice can arise from different internal codes."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 18}, "m3-thought-p019": {"status": "ready", "blocks": [{"text": "**An expression can be meaningful without being literal.** The study of time asks whether familiar spatial expressions also relate to cognitive processing.", "children": []}, {"text": "Physical and spatial terms can therefore help express abstract relations. Time is especially useful for studying whether such linguistic habits are associated with nonlinguistic representations.", "children": ["The question is empirical. Using a spatial phrase does not by itself prove that every thought about time has the same spatial format."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 19}, "m3-thought-p020": {"status": "ready", "blocks": [{"text": "**Habitual ways of talking about time can suggest testable predictions about processing.** Mandarin's vertical terms make a vertical temporal organization a relevant possibility.", "children": []}, {"text": "The linguistic contrast motivates testing whether speakers differ in the spatial organization they use during temporal tasks.", "children": ["The existence of the expressions is the starting observation. A behavioral task is needed to investigate whether the contrast extends beyond words."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 20}, "m3-thought-p021": {"status": "ready", "blocks": [{"text": "**The prime changes what representation is active before the temporal judgment.** Response-time differences reveal compatibility between the prime and the later task.", "children": []}, {"text": "English speakers respond faster after horizontal than vertical primes, while Mandarin speakers show the opposite pattern in the displayed comparison.", "children": ["Training English speakers on vertical metaphors changes the pattern toward a vertical-prime advantage. This suggests sensitivity to experience, rather than an unchangeable division between language groups."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 21}, "m3-thought-p022": {"status": "ready", "blocks": [{"text": "**Language-group differences can bundle linguistic and literacy experiences together.** Reading direction therefore needs to be measured or controlled.", "children": []}, {"text": "Casasanto and Bottini use differences in text orientation and arrangement preferences to motivate this alternative.", "children": ["The point is to identify another source of spatial experience, not to assume that a writing-system label perfectly predicts every individual's habits."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 22}, "m3-thought-p023": {"status": "ready", "blocks": [{"text": "**A targeted control tests a specific alternative explanation.** Its conclusion should be limited to the experience that was actually controlled.", "children": []}, {"text": "English speakers show an advantage for a left-is-earlier horizontal mapping. Mandarin speakers also show an advantage for a top-is-earlier vertical mapping in the displayed comparison.", "children": ["Retaining a vertical effect under this restriction weakens that particular reading-direction explanation, without proving that every possible experiential confound is removed."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 23}, "m3-thought-p024": {"status": "ready", "blocks": [{"text": "**Changing which side corresponds to past allows a direct test of spatial–temporal compatibility.** Color alone cannot explain the pattern because the mappings are counterbalanced.", "children": []}, {"text": "With standard text reading, responses are faster when past maps left and future maps right.", "children": ["Because the response concerns time rather than an explicit judgment of spatial direction, the compatibility effect reveals an implicit spatial association in this task."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 24}, "m3-thought-p025": {"status": "ready", "blocks": [{"text": "**A flexible temporal mapping is difficult to explain as a fixed consequence of native-language grammar alone.** Recent perceptual and reading experience contributes to performance.", "children": []}, {"text": "By the second mirror-reading block, the compatibility effect reverses. Responses are faster when earlier maps right and later maps left.", "children": ["The result supports a contribution of reading-direction experience and shows that the association can change over a short period."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 25}, "m3-thought-p026": {"status": "ready", "blocks": [{"text": "**Different lexical packaging does not show that one group cannot understand another group's distinctions.** The linguistic facts and the cognitive inference both need scrutiny.", "children": []}, {"text": "Languages can express distinctions through separate roots, derived words or phrases. Counting one of these forms without considering the others can misrepresent expressive capacity.", "children": ["A reliable claim requires accurate linguistic description and an appropriate behavioral test, rather than repetition of a striking anecdote."]}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 26}, "m3-thought-p027": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 27}, "m3-modalities-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 1}, "m3-modalities-p002": {"status": "ready", "blocks": [{"text": "**Do not treat Braille as a signed language or signing as a tactile alphabet.** They provide different tests of language and neural plasticity.", "children": []}, {"text": "The distinction matters because changing the modality of a language is not the same as changing how a written language is accessed.", "children": ["Both cases reveal how sensory experience shapes the organization of systems involved in language and reading."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 2}, "m3-modalities-p003": {"status": "ready", "blocks": [{"text": "**Changing the articulators does not remove linguistic organization.** Signed languages remain structured systems rather than collections of transparent gestures.", "children": []}, {"text": "Space can carry linguistic relations. Some signs are iconic, meaning that aspects of their form resemble aspects of their meaning.", "children": ["Iconicity is easy to overestimate when a familiar translation is supplied. A visible resemblance does not eliminate the need to learn a language's forms and structure."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 3}, "m3-modalities-p004": {"status": "ready", "blocks": [{"text": "**The unit of analysis is coordinated language production, not an isolated hand pose.** Fluency depends on how the articulators work together.", "children": []}, {"text": "Like speech, a fluent stream is continuous enough that word boundaries are not always obvious to a learner.", "children": ["Eye contact and movement timing are therefore relevant to perceiving the interaction, alongside the form of individual signs."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 4}, "m3-modalities-p005": {"status": "ready", "blocks": [{"text": "**A feature is linguistically contrastive when changing it changes the sign identity.** Visual similarity alone does not determine whether two forms belong to the same category.", "children": []}, {"text": "The PLEASE–SORRY and ONION–APPLE examples demonstrate that closely related visible forms can have different linguistic identities.", "children": ["Phonology therefore concerns the organization of contrastive form, not only acoustic sound."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 5}, "m3-modalities-p006": {"status": "ready", "blocks": [{"text": "**The test distinguishes a physical change from a linguistically meaningful category change.** Both continua vary visually, but only one crosses the relevant contrast.", "children": []}, {"text": "One continuum crosses a phonemic distinction between PLEASE and SORRY. The allophonic comparison varies hand configuration without the same change in sign identity.", "children": ["A sharp identification boundary accompanied by better discrimination near that boundary would indicate category-sensitive perception."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 6}, "m3-modalities-p007": {"status": "ready", "blocks": [{"text": "**The combination of a sharp identification shift and a boundary-related discrimination peak supports categorical perception.** Identification alone would provide a less complete test.", "children": []}, {"text": "Discrimination is also strongest near the phonemic boundary. Comparable physical steps are easier to distinguish when they cross that category boundary.", "children": ["The allophonic identification function is shallower and lacks the same localized discrimination peak. This links the perceptual pattern to linguistic contrast rather than any visible hand change."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 7}, "m3-modalities-p008": {"status": "ready", "blocks": [{"text": "**Where a sign is made can be part of the sentence's meaning.** The listener must track linguistic relations across space as well as over time.", "children": []}, {"text": "Understanding a sentence can require retaining where entities were introduced and how subsequent signs relate to those locations.", "children": ["Spatial processing therefore contributes to linguistic comprehension, rather than functioning only as background vision."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 8}, "m3-modalities-p009": {"status": "ready", "blocks": [{"text": "**Different sensory inputs can engage overlapping language networks.** The additional visual and spatial activity reflects the demands of processing a signed signal.", "children": []}, {"text": "Signing also engages visual and superior parietal regions relevant to its perceptual and spatial demands.", "children": ["The combination suggests both common language organization and modality-related contributions. Similarity does not require identical activation everywhere."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 9}, "m3-modalities-p010": {"status": "ready", "blocks": [{"text": "**The comparison groups are essential to the causal question.** A deaf-versus-hearing contrast alone would bundle deafness and signing experience together.", "children": []}, {"text": "Deaf participants showed an advantage when attention was directed to the periphery.", "children": ["Including hearing signers helps separate experience with signing from lack of auditory input. If all signers had the same advantage, signing alone would be a stronger explanation."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 10}, "m3-modalities-p011": {"status": "ready", "blocks": [{"text": "**Do not combine lateralization and peripheral attention into one undifferentiated advantage.** They track different aspects of experience.", "children": []}, {"text": "Enhanced peripheral attention is found in deaf individuals, not hearing signers. Signing experience alone therefore does not explain that enhancement.", "children": ["The proposed interpretations involve links between motion and language systems for signing, and reduced reliance on auditory peripheral cues in deafness."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 11}, "m3-modalities-p012": {"status": "ready", "blocks": [{"text": "**A useful control shares some demands while differing in the process being tested.** Tic-tac helps separate language comprehension from hand-motion processing.", "children": []}, {"text": "Both tasks involve meaningful, sequenced hand movements. A difference between them is more informative about linguistic processing than a comparison between signing and no movement.", "children": ["The control is not identical to a natural language, which is precisely why the remaining difference is of interest."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 12}, "m3-modalities-p013": {"status": "ready", "blocks": [{"text": "**Shared visual movement does not explain the entire neural response to signed language.** The temporal-region difference is the central language-related result.", "children": []}, {"text": "The comparison reduces a simple explanation based only on the presence of hands moving through space.", "children": ["The frontal activation shown is superior to classic Broca's area, so it should not be casually relabeled as a precise Broca's effect."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 13}, "m3-modalities-p014": {"status": "ready", "blocks": [{"text": "**A coherent account must separate shared language organization from sensory adaptations.** Neither “sign is just gesture” nor “modality makes no difference” captures the evidence.", "children": []}, {"text": "Signing experience is associated with changes in motion lateralization. Deafness is associated with enhanced peripheral attention in the reported comparison.", "children": ["These findings jointly show that linguistic experience and sensory history contribute in different ways."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 14}, "m3-modalities-p015": {"status": "ready", "blocks": [{"text": "**Spatial comprehension depends on conventions as well as geometric convenience.** The observer may transform a speaker-centered description rather than prefer an already reversed one.", "children": []}, {"text": "The figure's caption reports better comprehension for descriptions from the speaker's perspective despite the mental transformation that this requires.", "children": ["This illustrates that the most linguistically natural representation is not necessarily the one that eliminates every spatial transformation."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 15}, "m3-modalities-p016": {"status": "ready", "blocks": [{"text": "**The linguistic task can remain reading while the sensory input changes.** This makes Braille useful for studying cross-modal organization.", "children": []}, {"text": "The symbols are optimized for touch. Fingers acquire letters sequentially, creating perceptual demands that differ from viewing printed text.", "children": ["The comparison asks how reading networks operate when the input arrives through touch instead of vision."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 16}, "m3-modalities-p017": {"status": "ready", "blocks": [{"text": "**The timing of sensory experience relates to later functional organization.** Visual cortex can participate in tactile reading even when the stimulus is not visual.", "children": []}, {"text": "Early-blind participants show stronger involvement of regions associated with visual word processing than late-blind participants.", "children": ["This indicates that a region's usual sensory label does not completely determine the information it can help process."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 17}, "m3-modalities-p018": {"status": "ready", "blocks": [{"text": "**Cross-modal changes do not have to be limited to early development.** A short-term manipulation can reveal latent contributions to tactile processing.", "children": []}, {"text": "The blindfolded group learned more quickly. This suggests that eliminating competing visual input can affect tactile learning over a short timescale.", "children": ["Because the participants were sighted adults, the experiment tests a different question from lifelong or early blindness."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 18}, "m3-modalities-p019": {"status": "ready", "blocks": [{"text": "**Reversibility helps constrain the mechanism.** A rapid response that disappears after vision returns suggests a change in functional contribution or competition.", "children": []}, {"text": "Removing visual input can allow tactile-related activity to become more evident. Restoring vision changes that balance again.", "children": ["This pattern is consistent with unmasking existing inputs rather than requiring the creation of an entirely new pathway over a few days."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 19}, "m3-modalities-p020": {"status": "ready", "blocks": [{"text": "**Activation and necessity are different kinds of evidence.** Interfering with a region and changing behavior provides stronger evidence that its activity contributes to the task.", "children": []}, {"text": "On Day 5, the blindfolded group's error rate rises under 1 Hz TMS relative to its baseline and sham conditions. The nonblindfolded group does not show the same selective disruption.", "children": ["The effect is no longer present in the same way after blindfold removal. The result supports a temporary functional contribution of visual cortex to tactile performance."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 20}, "m3-modalities-p021": {"status": "ready", "blocks": [{"text": "**A brain region's contribution reflects development and competition as well as its usual sensory input.** Common language functions can coexist with modality-specific adaptations.", "children": []}, {"text": "Competition among available inputs offers a way to understand reorganization. When an input is absent or reduced, other information can make a larger contribution.", "children": ["The evidence does not imply that all regions are interchangeable. It shows both stable functional relationships and experience-sensitive recruitment."]}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 21}, "m3-review-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/review.txt", "source": "review", "page": 1}, "m3-review-p002": {"status": "ready", "blocks": [{"text": "**An unfamiliar spelling cannot always be decoded correctly from its letters alone.** Deep orthographies create more exceptions that readers must learn through experience.", "children": []}, {"text": "COLONEL and PARADIGM make the problem concrete. Applying common letter–sound patterns can produce a plausible-looking pronunciation that is wrong for the actual word.", "children": ["In shallower writing systems, such as Finnish and Korean, spelling–sound correspondences are more predictable. The comparison concerns the writing system, not the intelligence or ability of its readers."]}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 2}, "m3-review-p003": {"status": "ready", "blocks": [{"text": "**Consistent correspondences make decoding easier to generalize.** Finnish readers can apply what they learn about letters to unfamiliar written forms.", "children": []}, {"text": "Doubled letters represent a meaningful length distinction. A doubled consonant is geminated, and a doubled vowel is long.", "children": ["This regularity helps Finnish children learn decoding quickly. Decoding means generating a pronunciation from a written form, whether or not its meaning is familiar."]}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 3}, "m3-review-p004": {"status": "ready", "blocks": [{"text": "**A made-up word separates decoding from remembering a familiar word.** The lower English performance is consistent with greater orthographic depth.", "children": []}, {"text": "The comparison involves Grade 1 children learning different alphabetic writing systems. Children learning many other languages produce plausible pseudoword pronunciations more successfully than English learners.", "children": ["English's less predictable correspondences help explain why decoding develops more slowly. This task does not measure the child's entire language ability."]}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 4}, "m3-review-p005": {"status": "ready", "blocks": [{"text": "**The organization of Hangul supports more than consistent pronunciation.** Similar sound categories can also be visibly related in their written symbols.", "children": []}, {"text": "The letters are arranged into syllable blocks with initial, medial and sometimes final positions. Those positions are not three unrelated pictures of whole words.", "children": ["The velar consonant forms share the basic angular ㄱ shape. Additional strokes or doubling distinguish related consonants."]}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 5}, "m3-review-p006": {"status": "ready", "blocks": [{"text": "**Experience matters especially when pronunciation conflicts with the usual spelling pattern.** Frequent exposure reduces the disadvantage of exception words.", "children": []}, {"text": "Naming latency is the time needed to begin saying the word. Higher values mean slower responses.", "children": ["An interaction means the effect of one factor depends on the other. The regularity cost is not a fixed amount added equally to high- and low-frequency words."]}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 6}, "m3-review-p007": {"status": "ready", "blocks": [{"text": "**Two routes can explain why regularity matters most for unfamiliar words.** Fast lexical processing protects familiar exceptions from competing sublexical output.", "children": []}, {"text": "For a high-frequency word, lexical information becomes available quickly enough to reduce the influence of the decoding output.", "children": ["For a low-frequency exception, the lexical response is less efficient and the regularized decoding output can interfere. Nonwords depend on decoding because they lack a stored whole-word entry."]}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 7}, "m3-review-p008": {"status": "ready", "blocks": [{"text": "**Word-specific knowledge and generalization can coexist in the same learned system.** They do not have to be implemented as a dictionary and a separate symbolic rule list.", "children": []}, {"text": "The same learning mechanism can capture both patterns shared by many words and information specific to a familiar word.", "children": ["The research strategy asks whether domain-general learning can explain reading. This contrasts with choosing separate adult processing components primarily from neuropsychological dissociations."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 8}, "m3-review-p009": {"status": "ready", "blocks": [{"text": "**Consistency supplies support from other words, while frequency strengthens experience with the particular word.** Their joint influence explains why infrequent exceptions are especially difficult.", "children": []}, {"text": "An exception conflicts with those patterns, so learning its particular mapping is especially important. Frequent exposure strengthens that word-specific mapping.", "children": ["A low-frequency exception has both weak item-specific learning and poor support from the dominant pattern. This combination creates a larger disadvantage than either factor alone."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 9}, "m3-review-p010": {"status": "ready", "blocks": [{"text": "**Novel pronunciation can result from applying learned statistical structure.** Nonword reading therefore does not automatically establish a separate symbolic route.", "children": []}, {"text": "No stored entry for the particular nonword is required. The same learned correspondences that support consistent words can support a new combination.", "children": ["This is a proposed mechanism for decoding without a separate GPC rule module."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 10}, "m3-review-p011": {"status": "ready", "blocks": [{"text": "**A failed simulation does not identify its own cause.** The failure must be traced to the architecture, learning assumptions, representations or other implementation choices.", "children": []}, {"text": "One possibility is that a single associative mechanism cannot explain the task. Another is that the chosen representations fail to capture the similarities needed for generalization.", "children": ["Improving the implementation while retaining the theoretical mechanism helps distinguish these possibilities."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 11}, "m3-review-p012": {"status": "ready", "blocks": [{"text": "**Changing the representation can improve decoding without adding a symbolic rule system.** That distinction matters when evaluating the original theoretical claim.", "children": []}, {"text": "Plaut and colleagues improved the phonological representations and obtained better nonword performance. This supports a representational explanation for at least part of the earlier failure.", "children": ["Behavioral relations between phonological processing and decoding also make phonology a relevant target for explanation."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 12}, "m3-review-p013": {"status": "ready", "blocks": [{"text": "**The same representational weakness can have unequal effects on words and nonwords.** Familiarity can partly compensate where new-item generalization cannot.", "children": []}, {"text": "A familiar word can retain support from its own training history. A nonword lacks that item-specific experience and depends more heavily on generalization.", "children": ["This produces a reason for unfamiliar forms to be especially vulnerable to poor representations without requiring a dedicated nonword mechanism."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 13}, "m3-review-p014": {"status": "ready", "blocks": [{"text": "**A selective-looking reading deficit can emerge from degraded shared representations.** Nonwords are especially dependent on reliable generalization.", "children": []}, {"text": "The manipulation produced poorer nonword decoding and relative sparing of word recognition. It also linked the severity of the phonological deficit to the degree of decoding difficulty.", "children": ["The model therefore connects a reading pattern to the quality of a more general phonological system."]}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 14}, "m3-review-p015": {"status": "ready", "blocks": [{"text": "**Similar-looking architectures can solve different computational problems.** Keep morphological inflection separate from grapheme–phoneme conversion.", "children": []}, {"text": "Pinker and Ullman's diagram associates lexical lookup with declarative memory and grammatical combination with procedural processing.", "children": ["Like dual-route reading, the account separates word-specific knowledge from a productive operation. Unlike reading aloud, its task is to transform a stem according to a grammatical feature, rather than convert spelling into sound."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 15}, "m3-review-p016": {"status": "ready", "blocks": [{"text": "**The motivation for an architecture matters when evaluating its evidence.** Similar diagrams do not mean that the theories were derived from the same observations.", "children": []}, {"text": "Reading dual-route theories were strongly motivated by neuropsychological dissociations. The morphology proposal also reflects a commitment to keeping the grammatical rule system distinct from exceptional lexical information.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 16}, "m3-review-p017": {"status": "ready", "blocks": [{"text": "**Separating exceptions protects a simple rule, but creates a second mechanism that must also be explained.** The associative system carries graded and item-specific influences.", "children": []}, {"text": "KEEP–KEPT, WEEP–WEPT and LEAP–LEAPT illustrate similarity among irregular forms. An exception can belong to a small family rather than being wholly unrelated to other words.", "children": ["Assigning these properties to lexical memory lets the rule system remain categorical and general."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 17}, "m3-review-p018": {"status": "ready", "blocks": [{"text": "**One learning mechanism is proposed for both regularities and exceptions.** The challenge is to explain accurate generalization as well as familiar forms.", "children": []}, {"text": "The model encodes a root's phonology, transforms that representation through modifiable connections, and decodes an output pattern.", "children": ["Regularity is a pattern learned from many examples. Irregular forms are also learned within the same system."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 18}, "m3-review-p019": {"status": "ready", "blocks": [{"text": "**Development can involve temporary errors as knowledge changes.** A theory must explain the entire trajectory, not just the final adult response.", "children": []}, {"text": "The middle error is a **regularization**, because the child applies the common past-tense pattern to an irregular verb.", "children": ["The decline does not necessarily mean that the child has stopped learning. A changing system can generalize more broadly while temporarily disrupting an earlier correct response."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 19}, "m3-review-p020": {"status": "ready", "blocks": [{"text": "**Overregularization is interpreted as productive rule use that is not yet sufficiently constrained by exceptions.** Recovery depends on the irregular form winning over the rule output.", "children": []}, {"text": "When the rule is learned, it can be applied too broadly, yielding RUNNED. Later, learned irregulars and the blocking process prevent that regularization.", "children": ["This account treats the developmental stages as involving distinguishable processes rather than only gradual changes in one mapping."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 20}, "m3-review-p021": {"status": "ready", "blocks": [{"text": "**A shift in the distribution of experience can temporarily disrupt familiar responses.** The learning account explains the developmental pattern through changing weights and input.", "children": []}, {"text": "As more regular verbs enter training, their common pattern changes the network's responses. That generalization can interfere with previously learned irregulars.", "children": ["With further learning, the network can recover the irregular responses while retaining broad regularity. No new symbolic rule component is inserted at the point of decline."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 21}, "m3-review-p022": {"status": "ready", "blocks": [{"text": "**Generalization is defined relative to the learner's experience.** A familiar human word is still a valid novel-model test when it was withheld from training.", "children": []}, {"text": "The test therefore uses the logic of a wug task even when the items are real words to humans.", "children": ["The model can generate many appropriate past-tense features, but feature-level success must be distinguished from producing an entirely correct word."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 22}, "m3-review-p023": {"status": "ready", "blocks": [{"text": "**A plausible learning curve is not enough if the model produces implausible words.** Error structure provides another test of the representation and decoding process.", "children": []}, {"text": "The model authors acknowledge that people are unlikely to make some of these errors. They suggest that additional output constraints could reduce bizarre responses.", "children": ["This separates capturing an overall learning pattern from matching the detailed form of human errors."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 23}, "m3-review-p024": {"status": "ready", "blocks": [{"text": "**The regular–irregular contrast can arise from how phonological and semantic information contribute.** A graded system can produce systematic differences between item types.", "children": []}, {"text": "Reliable sound representations support extension from familiar present–past pairs to new forms. Irregular mappings receive additional support from the particular word's semantic representation.", "children": ["The hypothesis concerns different degrees of dependence on shared systems, rather than a separate symbolic rule route for every regular response."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 24}, "m3-review-p025": {"status": "ready", "blocks": [{"text": "**The same architecture should explain both sides of the patient pattern.** Selectivity must arise from the manipulated representations and their contribution to the task.", "children": []}, {"text": "A nonword has no familiar item-specific semantic history to support its inflection. A known irregular can require semantic support because its output is not well predicted by the dominant pattern.", "children": ["Manipulating phonological or semantic integrity tests whether these different dependencies can produce opposite impairment profiles."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 25}, "m3-review-p026": {"status": "ready", "blocks": [{"text": "**Difficulty with productive inflection may be connected to sound processing.** The nonword condition is particularly demanding because it relies on generalization.", "children": []}, {"text": "Regular forms are also vulnerable, while irregular forms are relatively better in the displayed comparison. A novel BLICK must be transformed without relying on a familiar stored past tense.", "children": ["This motivates investigating phonological contributions to the apparent morphological deficit."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 26}, "m3-review-p027": {"status": "ready", "blocks": [{"text": "**Relatively preserved nonword inflection can coexist with poor irregular inflection.** The theory must explain this reverse pattern as well as phonological impairment.", "children": []}, {"text": "Their irregular performance is lower than their regular and nonword performance in the displayed comparison.", "children": ["This creates the other side of the dissociation and motivates examining the information that especially supports known irregular forms."]}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 27}, "m3-review-p028": {"status": "ready", "blocks": [{"text": "**Fluency, grammatical organization and meaningful word selection are distinguishable dimensions.** The two example profiles emphasize different disruptions.", "children": []}, {"text": "This makes a lexical-versus-grammatical interpretation attractive. However, a descriptive syndrome is not itself a demonstration of an isolated processing module.", "children": ["Content words may be relatively preserved in telegraphic speech, while fluent speech can retain sentence-like structure without conveying a clear message."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 28}, "m3-review-p029": {"status": "ready", "blocks": [{"text": "**A familiar syndrome name does not settle which level of processing is affected.** Articulation and grammatical formulation must be distinguished.", "children": []}, {"text": "**Apraxia of speech** concerns planning or coordinating speech movements. That differs from explaining an omission of grammatical structure in otherwise producible speech.", "children": ["The historical label therefore should not substitute for a precise description of the impaired behavior."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 29}, "m3-review-p030": {"status": "ready", "blocks": [{"text": "**Syntax and meaning can come apart in a judgment without proving a perfectly modular neural organization.** The behavioral and theoretical claims should be kept separate.", "children": []}, {"text": "Chomsky's example of a grammatical but semantically unusual sentence shows that syntactic well-formedness cannot be reduced to whether a sentence describes a sensible event.", "children": ["That conceptual distinction does not establish a simple one-to-one mapping from each syndrome to one isolated component."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 30}, "m3-review-p031": {"status": "ready", "blocks": [{"text": "**Word selection, ordering, sound encoding and articulation are different explanatory levels.** An apparent lexical–grammatical contrast should be related to those operations carefully.", "children": []}, {"text": "A **lemma** is a representation involved in lexical selection, distinct from simply executing its sound pattern. Positional processing contributes ordering and morphological structure.", "children": ["Combinations such as HOUSEBOAT show that complex-word meaning can be partly compositional. Errors such as “easy enoughly” provide evidence about the organization of morphological operations."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 31}, "m3-review-p032": {"status": "ready", "blocks": [{"text": "**A direction can stay fixed when a person turns.** Absolute coding differs from coding an object as being on the viewer's left.", "children": []}, {"text": "Tzeltal commonly uses absolute directions in circumstances where English speakers might use these relative terms.", "children": ["The contrast motivates asking whether habitual language use relates to nonverbal spatial coding, rather than merely comparing two ways of giving spoken directions."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 32}, "m3-review-p033": {"status": "ready", "blocks": [{"text": "**A landmark origin and an absolute use are different properties.** A historically landscape-based term can become a stable directional reference.", "children": []}, {"text": "A direction is retained as a stable spatial reference rather than being recalculated from the speaker's current left and right.", "children": ["This allows positions to be described consistently as the speaker changes orientation."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 33}, "m3-review-p034": {"status": "ready", "blocks": [{"text": "**The rotation makes two otherwise similar descriptions predict different choices.** The nonverbal response reveals a preferred spatial coding strategy.", "children": []}, {"text": "A relative response preserves the arrangement with respect to the person's viewpoint. An absolute response preserves its orientation in the environment, so the two responses diverge after rotation.", "children": ["Dutch speakers predominantly gave relative responses, while Tzeltal speakers gave more absolute responses. The association is consistent with their preferred linguistic frames but does not isolate language from all other experience."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 34}, "m3-review-p035": {"status": "ready", "blocks": [{"text": "**The task goes beyond reproducing one remembered arrangement.** It asks whether a frame is used when combining spatial relations to make an inference.", "children": []}, {"text": "They then place an object relative to another using the combined information. Relative and absolute coding lead to different placements because the person's orientation has changed.", "children": ["Dutch and Tzeltal response patterns again differ in the direction associated with their preferred spatial frames."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 35}, "m3-review-p036": {"status": "ready", "blocks": [{"text": "**A language comparison can be confounded with a setting comparison.** The environment must be considered before assigning the entire difference to linguistic structure.", "children": []}, {"text": "An environment with useful landmarks can encourage landmark-based coding. A windowless laboratory can make viewer-relative descriptions more convenient.", "children": ["Manipulating landmark availability within English speakers tests whether the behavior can change without changing native language."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 36}, "m3-review-p037": {"status": "ready", "blocks": [{"text": "**Spatial strategy is sensitive to the testing environment.** A within-language change helps reveal a potential confound in a between-language comparison.", "children": []}, {"text": "The manipulation changes the spatial information available while keeping the language group the same.", "children": ["This demonstrates that task context can influence the response. It challenges an explanation in which language alone fixes the chosen frame."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 37}, "m3-review-p038": {"status": "ready", "blocks": [{"text": "**Changing a task can change the process it measures.** A landmark effect in an easy, transparent task may not settle how people habitually remember spatial relations.", "children": []}, {"text": "Participants who infer what is being tested can alter their response for reasons different from habitual spatial coding.", "children": ["The response therefore focuses on memory load and task transparency, rather than denying that landmarks can ever matter."]}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 38}, "m3-review-p039": {"status": "ready", "blocks": [{"text": "**The test distinguishes a physical change from a linguistically meaningful category change.** Both continua vary visually, but only one crosses the relevant contrast.", "children": []}, {"text": "One continuum crosses a phonemic distinction between PLEASE and SORRY. The allophonic comparison varies hand configuration without the same change in sign identity.", "children": ["A sharp identification boundary accompanied by better discrimination near that boundary would indicate category-sensitive perception."]}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 39}, "m3-review-p040": {"status": "ready", "blocks": [{"text": "**The combination of a sharp identification shift and a boundary-related discrimination peak supports categorical perception.** Identification alone would provide a less complete test.", "children": []}, {"text": "Discrimination is also strongest near the phonemic boundary. Comparable physical steps are easier to distinguish when they cross that category boundary.", "children": ["The allophonic identification function is shallower and lacks the same localized discrimination peak. This links the perceptual pattern to linguistic contrast rather than any visible hand change."]}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 40}, "m3-review-p041": {"status": "ready", "blocks": [{"text": "**Different sensory inputs can engage overlapping language networks.** The additional visual and spatial activity reflects the demands of processing a signed signal.", "children": []}, {"text": "Signing also engages visual and superior parietal regions relevant to its perceptual and spatial demands.", "children": ["The combination suggests both common language organization and modality-related contributions. Similarity does not require identical activation everywhere."]}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 41}, "m3-review-p042": {"status": "ready", "blocks": [{"text": "**A coherent account must separate shared language organization from sensory adaptations.** Neither “sign is just gesture” nor “modality makes no difference” captures the evidence.", "children": []}, {"text": "Signing experience is associated with changes in motion lateralization. Deafness is associated with enhanced peripheral attention in the reported comparison.", "children": ["These findings jointly show that linguistic experience and sensory history contribute in different ways."]}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 42}, "m3-review-p043": {"status": "ready", "blocks": [{"text": "**A late L2 learner has already exercised language capacity.** That history is what makes late-L2 outcomes informative for distinguishing the two proposals.", "children": []}, {"text": "Later second-language difficulty in people who already acquired a first language is more directly compatible with maturation than with complete preservation through exercise.", "children": ["This does not make early first-language experience unimportant. Early access and age-related change address related but distinct questions."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 43}, "m3-review-p044": {"status": "ready", "blocks": [{"text": "**Age of starting ASL is not the same as age of first language access.** Earlier linguistic experience can support learning a new language later.", "children": []}, {"text": "Children first exposed to ASL at ages 9–15 had particular difficulty when it was also their first language. Those who had first learned a spoken language did much better, and the differences persisted.", "children": ["The comparison distinguishes late first-language learning from late acquisition of an additional language."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 44}, "m3-review-p045": {"status": "ready", "blocks": [{"text": "**A control is informative when it tests the alternative mechanism directly.** Matching appearance and manipulating visual similarity provide complementary evidence.", "children": []}, {"text": "The materials were normed so that same-category items were not more visually similar on average. A separate visual-similarity manipulation also produced a different time course.", "children": ["Visual blocking affected the first block, whereas the semantic pattern of interest developed differently. This weakens a purely visual explanation."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 45}, "m3-review-p046": {"status": "ready", "blocks": [{"text": "**Separating display timing from naming order helps locate the source of interference.** Simultaneous visibility does not remove the need for sequential lexical selection.", "children": []}, {"text": "Displaying all objects at once reduces dependence on a succession of isolated pictures. Serial naming still requires selecting and producing one label after another.", "children": ["Eye tracking provides additional timing information about the processing of each object."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 46}, "m3-review-p047": {"status": "ready", "blocks": [{"text": "**One total naming time can conceal several processes.** Coordinating eye and speech measures reveals where a condition begins to change performance.", "children": []}, {"text": "A participant can move the eyes toward the next object before articulating the current one. The measures therefore separate overlapping parts of preparation.", "children": ["Different blocking effects on these measures can help constrain the processing stage affected."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 47}, "m3-review-p048": {"status": "ready", "blocks": [{"text": "**The location of the effect across measures matters more than a general statement that naming is slower.** Its time course and selectivity constrain the proposed mechanism.", "children": []}, {"text": "Speech duration decreases with repetition without a blocking difference. Gaze duration shows the condition difference after the first cycle.", "children": ["The nonsignificant lag difference should not be reported as evidence for a reversed effect. The reported pattern is interpreted as supporting a contribution at lemma selection rather than articulation or phonological encoding."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 48}, "m3-review-p049": {"status": "ready", "blocks": [{"text": "**The critical test is whether within-category differences influence lexical responses.** A binary final choice alone may hide that information.", "children": []}, {"text": "**Voice onset time**, or VOT, varies the timing between release and voicing. It can change how strongly the sound supports /b/ or /p/.", "children": ["A thresholded account would pass a completed categorical decision onward. A cascaded account allows graded information to influence word candidates before uncertainty is fully resolved."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 49}, "m3-review-p050": {"status": "ready", "blocks": [{"text": "**A forced choice can end in one category even when processing used graded evidence.** Eye movements provide a separate measure of that processing.", "children": []}, {"text": "Shorter VOTs favored the /b/ response and longer VOTs the /p/ response. Near the boundary, the preferred category changed rapidly.", "children": ["A categorical-looking final response does not establish that all earlier lexical activation was categorical."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 50}, "m3-review-p051": {"status": "ready", "blocks": [{"text": "**Final identification and moment-by-moment competition reveal different aspects of processing.** A sharp choice boundary can coexist with graded lexical uncertainty.", "children": []}, {"text": "A participant can ultimately select BEAR while spending more time looking at PEAR when the sound is close to the boundary.", "children": ["This supports the claim that fine phonetic information remains relevant to lexical activation, rather than disappearing completely after a categorical phoneme decision."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 51}, "m3-review-p052": {"status": "ready", "blocks": [{"text": "**The relevant predictor is distance from the boundary, not only which side of it the token occupies.** Similar final choices can still have different lexical-competition profiles.", "children": []}, {"text": "The graph separates early and late observation windows. The gradient remains visible in the later competition measure, supporting continued sensitivity to within-category phonetic detail.", "children": ["The result favors cascaded use of graded evidence over a model that transmits only a completed phoneme label with all within-category detail discarded."]}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 52}}}, {"id": "original-c-v3", "label": "Original C · Version 3", "scripts": {"m3-reading1-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 1}, "m3-reading1-p002": {"status": "ready", "blocks": [{"text": "**Phonemes are speech-sound categories, not letters.** A writing system represents language, but its symbols do not have to correspond one-to-one with those categories.", "children": ["A letter can contribute to different pronunciations, and a phoneme can be represented by different spellings."]}, {"text": "The question concerns the relation between sound and writing, rather than how many letters a word contains.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 2}, "m3-reading1-p003": {"status": "ready", "blocks": [{"text": "**Orthographic depth** describes how consistently spelling corresponds to pronunciation. English is relatively deep because many spellings do not transparently specify their sounds.", "children": ["COLONEL and PARADIGM make the problem concrete. Applying common letter–sound patterns can produce a plausible-looking pronunciation that is wrong for the actual word."]}, {"text": "In shallower writing systems, such as Finnish and Korean, spelling–sound correspondences are more predictable. The comparison concerns the writing system, not the intelligence or ability of its readers.", "children": []}, {"text": "The English examples contrast ordinary expectations from the letters with the word's learned pronunciation. A deep script is less predictable, not completely random.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 3}, "m3-reading1-p004": {"status": "ready", "blocks": [{"text": "**Finnish has a shallow orthography.** Letters correspond relatively unambiguously to phonemes, so learning a spelling–sound correspondence helps with many different words.", "children": ["Doubled letters represent a meaningful length distinction. A doubled consonant is geminated, and a doubled vowel is long."]}, {"text": "This regularity helps Finnish children learn decoding quickly. Decoding means generating a pronunciation from a written form, whether or not its meaning is familiar.", "children": []}, {"text": "The linked Finnish lesson is a source demonstration. Its sound is not embedded in the PDF, so the written claims establish the correspondence and length distinctions without supplying a recovered recording.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 4}, "m3-reading1-p005": {"status": "ready", "blocks": [{"text": "**Pseudoword reading tests decoding.** Because a pseudoword is not a familiar stored word, the child must generalize from learned spelling–sound patterns.", "children": ["The comparison involves Grade 1 children learning different alphabetic writing systems. Children learning many other languages produce plausible pseudoword pronunciations more successfully than English learners."]}, {"text": "English's less predictable correspondences help explain why decoding develops more slowly. This task does not measure the child's entire language ability.", "children": []}, {"text": "Compare accuracy across languages for the same type of task. The important outcome is the relative difficulty of English pseudoword decoding, not a claim that English children cannot decode.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 5}, "m3-reading1-p006": {"status": "ready", "blocks": [{"text": "**Korean writing represents sound structure systematically.** Related phonemes can have related written shapes, so the visual forms themselves reflect aspects of phonological organization.", "children": ["The letters are arranged into syllable blocks with initial, medial and sometimes final positions. Those positions are not three unrelated pictures of whole words."]}, {"text": "The velar consonant forms share the basic angular ㄱ shape. Additional strokes or doubling distinguish related consonants.", "children": []}, {"text": "The diagrams label initial, medial and final positions. The g, kk and k examples share a shape family, illustrating how a place-of-articulation relation can be reflected in the script.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 6}, "m3-reading1-p007": {"status": "ready", "blocks": [{"text": "**GLORP, SPLING, JONK, FEESH and QUISP can be pronounced without being familiar words.** Their forms follow enough English spelling patterns for a reader to construct a plausible pronunciation.", "children": ["Success cannot depend on retrieving a stored pronunciation for each particular item. The reader is using knowledge that generalizes across words."]}, {"text": "The demonstration establishes generalization. By itself, it does not decide whether that knowledge consists of categorical rules or learned statistical patterns.", "children": []}, {"text": "The items are instructional stimuli. Their role is to test decoding, not vocabulary knowledge or knowledge of a definition.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 7}, "m3-reading1-p008": {"status": "ready", "blocks": [{"text": "**Pseudoword decoding is fast and largely automatic.** In the Lupker, Brown and Colombo example, naming pseudowords is only about 5–12% slower than naming low-frequency real words.", "children": ["Participants read the items aloud, and naming time measures how quickly a pronunciation becomes available. The small difference shows that unfamiliarity does not make pronunciation an entirely slow, deliberate process."]}, {"text": "Both rules and statistical generalization might produce efficient decoding. The speed result constrains a theory without selecting one architecture on its own.", "children": []}, {"text": "Compare pseudowords with low-frequency words rather than treating every real word as an equally familiar baseline. A percentage slowdown describes relative naming time, not an error rate.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 8}, "m3-reading1-p009": {"status": "ready", "blocks": [{"text": "**An unfamiliar spelling can support more than one plausible pronunciation.** VONTH, PHANGE, STREAD and SOUGH contain patterns whose pronunciations are not all uniquely determined in English.", "children": ["A response reflects the spelling–sound patterns available from previously learned words. Different familiar patterns can favor different responses to the same novel form."]}, {"text": "These items probe how readers resolve uncertainty in spelling-to-sound mappings. There is no requirement that every unfamiliar form have one universally agreed pronunciation.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 9}, "m3-reading1-p010": {"status": "ready", "blocks": [{"text": "**STREAD can plausibly be pronounced with either /ɛ/ or /i/.** The same written sequence can resemble more than one learned spelling–sound pattern.", "children": ["Testing novel items reveals what a reader has generalized, because the particular word cannot simply have been memorized."]}, {"text": "The challenge for a categorical rule account is to explain why multiple outputs seem acceptable. A statistical account can represent differing support for alternative pronunciations.", "children": []}, {"text": "The contrast changes the vowel while keeping the rest of STREAD constant. This isolates ambiguity in the spelling–sound relation.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 10}, "m3-reading1-p011": {"status": "ready", "blocks": [{"text": "**The regularity effect is the difficulty of reading words whose pronunciation conflicts with common spelling–sound patterns.** PINT, ACHE and CHOIR are examples of words for which straightforward decoding can mislead.", "children": ["A strict regular–irregular division is less clear when a spelling neighborhood contains several pronunciations. ROLL, POLL and TOLL support one pattern, while DOLL differs."]}, {"text": "COOK, TOOK and BOOK likewise contrast with SPOOK. These neighborhoods motivate asking how much support a pronunciation has from similar words.", "children": []}, {"text": "A neighborhood is a set of words sharing relevant spelling patterns. The comparison concerns their pronunciations, not similarities in their meanings.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 11}, "m3-reading1-p012": {"status": "ready", "blocks": [{"text": "**Sublexical information concerns units smaller than a whole word.** Rapid nonword reading and the advantage for typical spelling–sound patterns show that readers use this information.", "children": ["**Lexical information** concerns knowledge of particular words. A complete account must explain how experience with a specific word contributes alongside general spelling patterns."]}, {"text": "Nonwords test generalization, while differences among familiar words can reveal word-specific knowledge. These are evidence types, not proof that two independent modules must exist.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 12}, "m3-reading1-p013": {"status": "ready", "blocks": [{"text": "**Word knowledge can help identify an ambiguous letter.** In an interactive activation network, visual features activate letters and letters activate candidate words.", "children": ["Activated word candidates send feedback to their constituent letters. A letter supported by a plausible word receives additional activation even when its local visual evidence is unclear."]}, {"text": "Competing candidates do not remain equally active. Their activation changes as the network settles on an interpretation.", "children": []}, {"text": "The network links features, letters and words. The letter-output graph shows one candidate increasing while competing candidates remain low, illustrating a developing preference rather than instantaneous recognition.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 13}, "m3-reading1-p014": {"status": "ready", "blocks": [{"text": "**Feedback carries word-level activation back to letters.** A partially activated known word increases activation of the letters that belong to it.", "children": ["This makes recognition interactive. Information does not flow only from isolated features upward to a finished word."]}, {"text": "The mechanism helps explain why an ambiguous letter can become easier to recognize when it appears in a familiar word context.", "children": []}, {"text": "The direction of a connection matters. Letter-to-word activation provides evidence for a candidate, while word-to-letter feedback supports the candidate's components.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 14}, "m3-reading1-p015": {"status": "ready", "blocks": [{"text": "**Lexicality and word frequency reveal effects of word-specific experience.** Real words are generally named faster than pseudowords, and frequently encountered words are named faster than less frequent words.", "children": ["Lexicality compares whether the item is a word. Frequency compares how often a particular word has been encountered."]}, {"text": "The English Lexicon Project data show that the frequency effect occurs across many observations, rather than depending on a few unusually easy examples.", "children": []}, {"text": "A frequency effect is a relation between prior exposure and naming performance. It is not the claim that all high-frequency words have the same length or pronunciation pattern.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 15}, "m3-reading1-p016": {"status": "ready", "blocks": [{"text": "**Multiple regression tests whether frequency predicts reading time after accounting for other word properties.** Length and sound-related characteristics could otherwise be mistaken for effects of frequency.", "children": ["The analysis uses about 3,000 words read by young and older adults. Frequency still contributes when other predictors are considered."]}, {"text": "This makes a simple length-confound explanation less plausible. It does not turn an observational predictor into an experimentally isolated cause.", "children": []}, {"text": "The highlighted objective- and subjective-frequency coefficients are negative. Higher frequency is associated with shorter reaction times, with separate columns for lexical decision and naming in the two age groups.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 16}, "m3-reading1-p017": {"status": "ready", "blocks": [{"text": "**Frequency and regularity interact.** Low-frequency exception words are slowed much more than low-frequency regular words, whereas high-frequency words show a much smaller regularity difference.", "children": ["Naming latency is the time needed to begin saying the word. Higher values mean slower responses."]}, {"text": "An interaction means the effect of one factor depends on the other. The regularity cost is not a fixed amount added equally to high- and low-frequency words.", "children": []}, {"text": "The lines are close at high frequency and separate at low frequency. Exception words rise to roughly 580 ms, while regular words rise only to roughly 555 ms in this figure.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 17}, "m3-reading1-p018": {"status": "ready", "blocks": [{"text": "**A dual-route interpretation separates lexical retrieval from sublexical decoding.** The lexical process supplies the learned pronunciation of a particular word, while decoding computes pronunciation from spelling units.", "children": ["For a high-frequency word, lexical information becomes available quickly enough to reduce the influence of the decoding output."]}, {"text": "For a low-frequency exception, the lexical response is less efficient and the regularized decoding output can interfere. Nonwords depend on decoding because they lack a stored whole-word entry.", "children": []}, {"text": "This is an interpretation of the interaction, not the interaction itself. Other architectures must be evaluated against the same observed pattern.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 18}, "m3-reading1-p019": {"status": "ready", "blocks": [{"text": "**Acquired phonological dyslexia involves disproportionate difficulty reading pseudowords after brain injury.** Familiar words can remain relatively well read even when novel forms are difficult.", "children": ["Cacciopo van Vliet and colleagues compare real-word reading with several nonword tasks. The patients can often recognize and pronounce known words while struggling to generate a plausible pronunciation for an unfamiliar spelling."]}, {"text": "The selective difficulty suggests that familiar-word success and novel-form decoding do not rely on every process to the same degree.", "children": []}, {"text": "The real-word table contains many high accuracy values, while several nonword lists have much lower scores. The deficit is relative, not a claim that every nonword response is wrong.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 19}, "m3-reading1-p020": {"status": "ready", "blocks": [{"text": "**Acquired surface dyslexia involves disproportionate difficulty reading irregular words after brain injury.** Errors often regularize the word by applying a more common spelling–sound pattern.", "children": ["DEAF pronounced like “deef” and SHOE pronounced like “show” illustrate regularization. The response is related to the spelling, but it is not the target word's learned pronunciation."]}, {"text": "Relatively good regular-word and nonword reading shows that generating pronunciation from spelling can remain useful despite difficulty with exceptions.", "children": []}, {"text": "HFR and LFR refer to high- and low-frequency regular words. HFE and LFE refer to exceptions. The highlighted exception columns are lower, especially for low-frequency exceptions.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 20}, "m3-reading1-p021": {"status": "ready", "blocks": [{"text": "**A double dissociation compares opposite relative impairments.** Phonological dyslexia particularly affects pseudowords, while surface dyslexia particularly affects exception words.", "children": ["The first pattern shows that unfamiliar decoding can be difficult despite relatively preserved familiar-word reading. The second shows that exception reading can be difficult despite relatively preserved pseudoword reading."]}, {"text": "Together, the patterns are harder to explain by saying that one task is simply harder for everyone.", "children": []}, {"text": "“Relatively spared” does not mean perfect. The inference concerns the difference between task profiles, not an absence of every error in the better-performing condition.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 21}, "m3-reading1-p022": {"status": "ready", "blocks": [{"text": "**A double dissociation challenges a single fixed difficulty ranking.** If task A were merely harder than task B, damage might consistently hurt A more, but it would not readily explain another patient showing the reverse pattern.", "children": ["The reversal suggests that the tasks depend differently on underlying processes. For reading, pseudowords and exception words place different demands on the system."]}, {"text": "The evidence still requires a theory of what those underlying processes are. It does not uniquely identify a particular set of boxes in a model.", "children": []}, {"text": "Compare the relative task costs within each patient or group, then compare those profiles. Two low scores without an opposite pattern are not a double dissociation.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 22}, "m3-reading1-p023": {"status": "ready", "blocks": [{"text": "**A dual-route model attributes phonological dyslexia to damage in grapheme–phoneme conversion and surface dyslexia to damage in lexical processing.** These proposed locations connect the task dissociation to specific mechanisms.", "children": ["Damage to conversion particularly affects nonwords because there is no familiar whole-word pronunciation to retrieve."]}, {"text": "Damage to input or output word representations, called logogens in this account, or their connections makes exceptions vulnerable because general decoding supplies the wrong pronunciation.", "children": []}, {"text": "The lexical and conversion paths are theoretical components. Their labels should not be confused with a direct anatomical map of two single brain regions.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 23}, "m3-reading1-p024": {"status": "ready", "blocks": [{"text": "**Patterson's discussion shows why reading errors can complicate a clean lexical–nonlexical division.** Errors attributed to a purely nonlexical route can still show lexical influences.", "children": ["The example “incense” read as “increase” is a real-word response. A simple letter–sound mistake could instead produce a nonword, so the actual response raises a question about whole-word influence."]}, {"text": "Possible responses are to allow a more complicated combination of routes or to revise the supposedly nonlexical process itself. The observation motivates refinement rather than settling the issue alone.", "children": []}, {"text": "The highlighted passage presents two alternatives for interpreting lexical influence in surface dyslexia. It does not simply declare that the patient evidence is irrelevant.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "reading1", "page": 24}, "m3-reading2-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 1}, "m3-reading2-p002": {"status": "ready", "blocks": [{"text": "**Dual-route models distinguish a lexical route from a sublexical route.** Lexical processing uses knowledge of particular words, while grapheme–phoneme conversion generates pronunciation from spelling units.", "children": ["A model must explain fast pseudoword reading, faster familiar-word reading, frequency effects, regularity effects and their interaction."]}, {"text": "It must also explain why pseudoword and exception-word reading can be differently impaired after brain injury. These observations motivate the architecture but do not uniquely prove it.", "children": []}, {"text": "A grapheme is a written unit associated with a sound. The route labels specify kinds of information used during reading.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 2}, "m3-reading2-p003": {"status": "ready", "blocks": [{"text": "**The Dual Route Cascaded model, or DRC, combines interactive lexical processing with a separate grapheme–phoneme rule system.** The two routes can contribute activation toward a spoken response.", "children": ["The lexical portion includes orthographic and phonological lexicons, representing written and spoken word forms. These representations are distinguished from meanings."]}, {"text": "The implementation described here does not implement semantics. The GPC rule system also has processing assumptions different from those of the interactive lexical network.", "children": []}, {"text": "The circled part of the diagram corresponds to interactive activation. The separate GPC path joins the output system rather than becoming another interactive lexical layer.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 3}, "m3-reading2-p004": {"status": "ready", "blocks": [{"text": "**The DRC's grapheme–phoneme conversion rules operate serially, letter by letter.** Their operation is not adjusted by word frequency and receives no lexical feedback.", "children": ["The GPC and lexical routes do not interact throughout their internal computations. They converge in the phoneme response buffer."]}, {"text": "If the routes favor different phonemes, they can compete at that shared output. An exception word can therefore receive a correct lexical pronunciation and an incompatible regularized pronunciation.", "children": []}, {"text": "Follow the route to the response buffer. Shared output units explain how competing pronunciations can influence naming even without feedback into the GPC rules.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 4}, "m3-reading2-p005": {"status": "ready", "blocks": [{"text": "**GPC rules map written units onto phonemes.** Some rules concern individual letters, while others concern several letters or a particular letter context.", "children": ["A model also needs a way to decide which applicable rule takes priority. A larger-unit rule can supersede rules for its individual letters."]}, {"text": "Context-sensitive rules restrict a pronunciation to specified surrounding letters or positions. This makes the procedure more than a simple lookup of one sound per letter.", "children": []}, {"text": "The table distinguishes multiletter rules from context-sensitive rules. Position labels specify whether a mapping applies at the beginning, middle, end or all positions.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 5}, "m3-reading2-p006": {"status": "ready", "blocks": [{"text": "**A categorical rule does not express the strength of the evidence behind it.** The DRC can choose a mapping because it is frequent, yet treat that mapping as a fixed rule during processing.", "children": ["The possible pronunciations of OUGH have more divided statistical support than those of EIGH. A rule can still operate categorically for both spellings."]}, {"text": "A probabilistic account instead allows alternatives to receive different strengths of support. The distinction concerns processing, not whether the model designer ever consulted frequency information.", "children": []}, {"text": "The table distributes pronunciation frequencies across alternatives. A spread across many rows indicates greater uncertainty than a distribution concentrated on one pronunciation.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 6}, "m3-reading2-p007": {"status": "ready", "blocks": [{"text": "**The DRC's simple rules are intended to explain systematic human errors as well as correct reading.** More finely tuned rules might pronounce more exceptions correctly but remove behavior the model is meant to explain.", "children": ["A regularizing route helps account for errors in surface dyslexia and for slow naming of low-frequency exception words."]}, {"text": "The theory therefore claims that people's sublexical computation is constrained, rather than assuming that the best possible spelling algorithm is the correct cognitive model.", "children": []}, {"text": "The crucial test is whether the same processing assumptions produce the observed pattern of success, interference and regularization, rather than an isolated incorrect response.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 7}, "m3-reading2-p008": {"status": "ready", "blocks": [{"text": "**Informational encapsulation means that a process does not freely use every source of relevant knowledge.** In the dual-route account, GPC conversion proceeds without consulting whole-word meaning or lexical feedback.", "children": ["This resembles a modular parsing proposal in which an early syntactic process follows structural principles without immediately using world knowledge."]}, {"text": "Pseudoword naming exposes the conversion procedure because a familiar lexical entry is unavailable. Regularization errors expose it when conversion favors the wrong pronunciation.", "children": []}, {"text": "The comparison with parsing concerns processing restrictions. It does not mean that syntactic parsing and letter–sound conversion use the same representations.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 8}, "m3-reading2-p009": {"status": "ready", "blocks": [{"text": "**The DRC is evaluated against many reading phenomena.** These include frequency, lexicality, regularity, interactions, lexical decision and patterns in acquired dyslexia.", "children": ["Accounting for several effects with one architecture is stronger than fitting a single result. It also requires examining which assumptions stay fixed and which are changed between tasks."]}, {"text": "The model's research strategy places strong weight on human behavioral evidence as a constraint on architecture.", "children": []}, {"text": "The listed effects span reading aloud, lexical decision and patient performance. These are related but distinct tasks, so a task-specific adjustment must be identified as such.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 9}, "m3-reading2-p010": {"status": "ready", "blocks": [{"text": "**Lexical decision requires deciding whether a written item is a word.** The DRC simulation adds decision criteria to the activation produced by its recognition system.", "children": ["A “yes” response can depend on a strongly activated single word or on total activity across the orthographic lexicon. A “no” response occurs if the criteria are not met by a deadline."]}, {"text": "The implementation also changes inhibition and uses time-dependent thresholds. These choices help obtain a fit, but they add assumptions beyond the basic two-route diagram.", "children": []}, {"text": "The thresholds and cycle deadlines implement response rules. Their conceptual role is more important here than memorizing each numerical cutoff.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 10}, "m3-reading2-p011": {"status": "ready", "blocks": [{"text": "**The DRC routes are modular in several related senses.** They use different processing assumptions, restrict information exchange and accept particular kinds of input.", "children": ["The GPC system takes letters as input and sends phoneme activation toward the response system. This is **domain specificity** in the account."]}, {"text": "The absence of lexical feedback into the GPC system is **informational encapsulation**. Having two pathways alone would not establish those stronger restrictions.", "children": []}, {"text": "Distinguish the restrictions on inputs, the rules of computation and the restrictions on communication. These are separate properties of the proposed architecture.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 11}, "m3-reading2-p012": {"status": "ready", "blocks": [{"text": "**PDP models treat reading as learned mappings among orthography, phonology and semantics.** Orthography is spelling, phonology is sound structure, and semantics is meaning.", "children": ["Seidenberg and McClelland trained an associative network to map spelling onto pronunciation. The modeled spelling-to-sound pathway used one learned mapping for different kinds of words."]}, {"text": "Reading skill emerges from learning rather than being specified entirely as a hand-built list of rules and lexical entries.", "children": []}, {"text": "The triangle's labels identify representational domains. A connection between domains represents a learned mapping, not an additional stored dictionary for every item.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 12}, "m3-reading2-p013": {"status": "ready", "blocks": [{"text": "**In a PDP account, rules are generalizations learned across words.** Whole-word knowledge is distributed across learned mappings instead of being stored only in a distinct lexical route.", "children": ["The same learning mechanism can capture both patterns shared by many words and information specific to a familiar word."]}, {"text": "The research strategy asks whether domain-general learning can explain reading. This contrasts with choosing separate adult processing components primarily from neuropsychological dissociations.", "children": []}, {"text": "“Distributed” refers to how knowledge is represented across the network. It does not mean that the model has no memory of individual words.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 13}, "m3-reading2-p014": {"status": "ready", "blocks": [{"text": "**A learned network can produce a frequency-by-regularity interaction without separate frequency and rule mechanisms.** Regular words receive support from patterns shared across many words.", "children": ["An exception conflicts with those patterns, so learning its particular mapping is especially important. Frequent exposure strengthens that word-specific mapping."]}, {"text": "A low-frequency exception has both weak item-specific learning and poor support from the dominant pattern. This combination creates a larger disadvantage than either factor alone.", "children": []}, {"text": "The interaction is shared evidence that both architectures must explain. Producing it does not by itself establish whether the implementation contains symbolic rules.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 14}, "m3-reading2-p015": {"status": "ready", "blocks": [{"text": "**Consistency describes how many similar spellings support a pronunciation.** “Friends” have the relevant spelling pattern and a compatible pronunciation, while “enemies” support a competing pronunciation.", "children": ["LATE and DUST illustrate consistent patterns. GAVE and MINT have many friends but also enemies such as HAVE and PINT."]}, {"text": "DOWN versus KNOWN and POUR versus SOUR illustrate ambiguity. An exception such as PINT has relatively little support compared with its competing neighborhood.", "children": []}, {"text": "Friend and enemy are labels for pronunciation relations among similar spellings. They do not refer to semantic relationships between the words.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 15}, "m3-reading2-p016": {"status": "ready", "blocks": [{"text": "**A PDP model can pronounce nonwords using the weights learned from real words.** A new spelling activates patterns that overlap with familiar spellings, allowing the network to generalize.", "children": ["No stored entry for the particular nonword is required. The same learned correspondences that support consistent words can support a new combination."]}, {"text": "This is a proposed mechanism for decoding without a separate GPC rule module.", "children": []}, {"text": "The relevant comparison is whether one learned mapping can handle both familiar words and new items. The claim must still be checked against the model's actual performance.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 16}, "m3-reading2-p017": {"status": "ready", "blocks": [{"text": "**Poor nonword performance can challenge either a theoretical proposal or a particular implementation.** The early model's nonword accuracy was weaker than desired.", "children": ["One possibility is that a single associative mechanism cannot explain the task. Another is that the chosen representations fail to capture the similarities needed for generalization."]}, {"text": "Improving the implementation while retaining the theoretical mechanism helps distinguish these possibilities.", "children": []}, {"text": "The important question is what changes when the model is repaired. A representational improvement is a different theoretical move from adding a separate nonword route.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 17}, "m3-reading2-p018": {"status": "ready", "blocks": [{"text": "**Generalization depends on how sound similarity is represented.** The early Seidenberg–McClelland model used Wickelfeatures, whose representation of phonology was problematic for nonword reading.", "children": ["Plaut and colleagues improved the phonological representations and obtained better nonword performance. This supports a representational explanation for at least part of the earlier failure."]}, {"text": "Behavioral relations between phonological processing and decoding also make phonology a relevant target for explanation.", "children": []}, {"text": "The comparison concerns models with different representations. Better performance after that change is evidence about implementation, not proof that every associative model will succeed.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 18}, "m3-reading2-p019": {"status": "ready", "blocks": [{"text": "**A network generalizes through similarity.** If its phonological representation poorly captures similarities among words, the learned mapping cannot transfer as effectively to new forms.", "children": ["A familiar word can retain support from its own training history. A nonword lacks that item-specific experience and depends more heavily on generalization."]}, {"text": "This produces a reason for unfamiliar forms to be especially vulnerable to poor representations without requiring a dedicated nonword mechanism.", "children": []}, {"text": "Distinguish a weaker shared representation from damage to a separate route. Both can create a task difference, but they locate the explanation differently.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 19}, "m3-reading2-p020": {"status": "ready", "blocks": [{"text": "**Harm and Seidenberg manipulated noise in phonological representations.** Increasing noise makes the sound representations less reliable while keeping the model's general learning framework.", "children": ["The manipulation produced poorer nonword decoding and relative sparing of word recognition. It also linked the severity of the phonological deficit to the degree of decoding difficulty."]}, {"text": "The model therefore connects a reading pattern to the quality of a more general phonological system.", "children": []}, {"text": "Noise is the manipulated model property. Word and nonword performance are outcomes, so the simulation tests a directional mechanistic proposal rather than merely observing a correlation.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 20}, "m3-reading2-p021": {"status": "ready", "blocks": [{"text": "**Damaging semantic support in a triangle model can impair exception-word reading especially strongly.** Plaut and colleagues added a simplified semantic contribution and examined what happened when it was lesioned.", "children": ["An exception has weak support from typical spelling–sound regularities. Meaning-related support can help produce its learned pronunciation."]}, {"text": "Reducing that support creates a surface-dyslexia-like pattern without defining a separate exception-word list as the sole explanation.", "children": []}, {"text": "“Lesion” here means a controlled change to the computational model. It is distinct from directly observing where a particular patient's brain injury occurred.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 21}, "m3-reading2-p022": {"status": "ready", "blocks": [{"text": "**The triangle model's pathways share graded learning assumptions and interact during learning.** Semantic representations are directly involved rather than replaced by a lexicon defined as independent of meaning.", "children": ["Spelling-to-sound learning develops in the presence of meaning-related support. The contribution of one pathway therefore affects what another pathway learns."]}, {"text": "This allows graded impairments. Phonological dyslexics can make some exception errors, and surface dyslexics can make some nonword errors.", "children": []}, {"text": "O denotes orthography, P phonology and S semantics. O-to-P and S-to-P mappings use the same general probabilistic assumptions, unlike DRC's distinct GPC and lexical procedures.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 22}, "m3-reading2-p023": {"status": "ready", "blocks": [{"text": "**Woollams and colleagues tested the predicted association between semantic ability and exception-word reading.** Lower semantic scores were associated with poorer low-frequency exception reading in patients with semantic dementia.", "children": ["The model and patient panels show comparable overall relationships, although individual patients vary. This supports an association between meaning and exceptional pronunciation."]}, {"text": "The finding is informative because it links a reading weakness to a broader semantic measure rather than describing only a reading-task dissociation.", "children": []}, {"text": "The semantic score decreases from left to right on the patient plot. The downward slope therefore means that poorer semantics goes with poorer reading, not that better semantics harms reading.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 23}, "m3-reading2-p024": {"status": "ready", "blocks": [{"text": "**Some patients have relatively good exception reading despite low semantic scores.** These cases challenge a perfect one-to-one relationship, but an account of graded association does not predict zero variability.", "children": ["Woollams and colleagues interpret such observations in relation to the full distribution rather than treating each outlier as an automatic refutation."]}, {"text": "The scientific issue is whether the unusual cases show a stable separate pattern or arise within a noisy overall association.", "children": []}, {"text": "Points above the horizontal reference line and left of the specified vertical boundary are singled out as unusual. Evaluate their location relative to the broader patient cloud and repeated measurements.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 24}, "m3-reading2-p025": {"status": "ready", "blocks": [{"text": "**Longitudinal observations track whether semantic and reading abilities change together within a patient.** Because semantic dementia progresses, repeated testing can reveal a trajectory rather than a single unusual score.", "children": ["In most cases, declining semantic ability accompanies declining exception-word reading. Some initially unusual observations move closer to the broader relation on retesting."]}, {"text": "This strengthens the association while leaving room for variability between individuals.", "children": []}, {"text": "Lines connect observations from the same person. Movement toward lower semantic scores and lower reading accuracy shows coupled decline rather than a comparison of unrelated people only.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 25}, "m3-reading2-p026": {"status": "ready", "blocks": [{"text": "**Coltheart and colleagues generated 40,000 model patients with different lexical-route and GPC impairment levels.** For each real patient, they selected the model run that best matched the observed data.", "children": ["This produced an excellent fit to the patient scores. The selection procedure is part of how that fit was achieved."]}, {"text": "The fit should be distinguished from predicting each patient's pattern before choosing among many possible parameter combinations.", "children": []}, {"text": "The plotted patient and model lines lie close together. That visual agreement describes goodness of fit, while the large search over simulated patients describes flexibility.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 26}, "m3-reading2-p027": {"status": "ready", "blocks": [{"text": "**A better fit can be less informative if it relies on much greater flexibility.** Selecting the best match from many parameter combinations can reproduce a dataset without strongly constraining the underlying explanation.", "children": ["The question is not whether close agreement is bad in itself. It is whether the account predicts the relation with principled assumptions or accommodates each case after seeing the outcome."]}, {"text": "Comparing theories therefore requires attention to both fit and how much freedom produced it.", "children": []}, {"text": "The contrast is between constrained prediction and flexible post hoc matching. It does not justify rejecting a model merely because its numerical fit is strong.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 27}, "m3-reading2-p028": {"status": "ready", "blocks": [{"text": "**Dual-route and triangle models address many of the same findings.** Both must explain rapid nonword decoding, exception difficulty, the frequency–regularity interaction and acquired reading dissociations.", "children": ["Agreement on the phenomena does not mean agreement on mechanisms. One account emphasizes specialized routes, while the other emphasizes learning across interacting representational systems."]}, {"text": "A useful comparison holds the phenomenon constant and asks what each model changes or computes to produce it.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 28}, "m3-reading2-p029": {"status": "ready", "blocks": [{"text": "**DRC attributes nonword decoding and regularity effects to GPC rules, while the triangle account attributes them to statistical learning.** Word-specific exposure strengthens learned mappings in the triangle account and affects lexical processing in DRC.", "children": ["For phonological dyslexia, DRC emphasizes GPC damage and the triangle account emphasizes broader phonological impairment."]}, {"text": "For surface dyslexia, DRC emphasizes lexical-route damage and the triangle account emphasizes semantic impairment.", "children": []}, {"text": "Read each table row across the two model columns. The row identifies the finding, while the columns specify competing explanations rather than two names for identical components.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 29}, "m3-reading2-p030": {"status": "ready", "blocks": [{"text": "**A major contrast is whether the explanation begins with separate reading routes or broader language associations.** Dual-route models use different task impairments to motivate independent processes.", "children": ["The statistical-learning account links phonology to spelling–sound generalization and semantics to words whose pronunciation is poorly supported by that generalization."]}, {"text": "Both dissociations and associations matter. A theory should explain selective weaknesses and the related abilities that vary with them.", "children": []}, {"text": "The table's dyslexia rows contrast GPC versus phonological damage and lexical-route versus semantic damage. These are the key theoretical alternatives, not just different diagnostic labels.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 30}, "m3-reading2-p031": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/reading2.txt", "source": "reading2", "page": 31}, "m3-morphology-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 1}, "m3-morphology-p002": {"status": "ready", "blocks": [{"text": "**Morphology is generative because speakers can form words they have not memorized individually.** Derivational morphology creates a new lexical form, while inflection marks grammatical information such as plural or past tense.", "children": ["The central question is how a speaker extends a familiar pattern to a new item. English plural and past-tense formation provide tractable examples."]}, {"text": "Generalization can also produce playful or incorrect forms. This shows productive use of patterns, rather than a vocabulary containing only previously heard responses.", "children": []}, {"text": "The playful “crew” and “crode” examples extend irregular-sounding patterns to CRY. They demonstrate creative generalization, not correct standard English past-tense forms.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 2}, "m3-morphology-p003": {"status": "ready", "blocks": [{"text": "**Berko Gleason's wug test measures morphological generalization to a novel word.** A child learns a new label and then supplies an inflected form that has not been provided.", "children": ["The pictured task introduces one WUG and then asks about two. Producing WUGS applies plural knowledge to a new noun."]}, {"text": "The same logic can test past tense using novel verbs. Success shows productive knowledge, but does not by itself distinguish symbolic rules from statistical generalization.", "children": []}, {"text": "The drawing depicts plural formation, even though the accompanying discussion also mentions past tense. Keep the displayed plural task separate from the broader application of the method.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 3}, "m3-morphology-p004": {"status": "ready", "blocks": [{"text": "**Regular past tense follows the productive -ed pattern.** SHOW becomes SHOWED, BAKE becomes BAKED, and a novel verb such as BLICK can become BLICKED.", "children": ["Irregular pairs such as GO–WENT, TAKE–TOOK and EAT–ATE do not follow that default form. Some irregulars share smaller patterns with other verbs."]}, {"text": "A theory must explain both familiar exceptions and productive extension to novel verbs.", "children": []}, {"text": "Compare regular real verbs with regularized nonwords, then with learned irregular pairs. The nonwords test extension, while the irregulars test successful handling of exceptions.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 4}, "m3-morphology-p005": {"status": "ready", "blocks": [{"text": "**The Words and Rules account gives regular and irregular inflection different mechanisms.** A symbolic rule generates a regular past tense, while irregular forms are stored in an associative lexical system.", "children": ["The regular process can apply to a new verb because it does not require an entry for that particular past tense."]}, {"text": "The irregular system stores word-specific information and can be influenced by frequency and similarity. A successful explanation also needs to prevent an available irregular form from being replaced by a regularization.", "children": []}, {"text": "“Add -ed” summarizes the symbolic operation. The associative system is not proposed as another copy of the same rule.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 5}, "m3-morphology-p006": {"status": "ready", "blocks": [{"text": "**The lexicon and grammar offer different ways to produce a past tense.** Lexical retrieval supplies an irregular form such as HELD, while grammatical combination can produce WALK plus -ed.", "children": ["Pinker and Ullman's diagram associates lexical lookup with declarative memory and grammatical combination with procedural processing."]}, {"text": "Like dual-route reading, the account separates word-specific knowledge from a productive operation. Unlike reading aloud, its task is to transform a stem according to a grammatical feature, rather than convert spelling into sound.", "children": []}, {"text": "The input includes a stem and a past-tense feature. The diagram distinguishes lexical association from combination, and its blocking connection prevents a retrieved irregular from competing unchecked with a regular form.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 6}, "m3-morphology-p007": {"status": "ready", "blocks": [{"text": "**The Words and Rules proposal was motivated partly by a theory of grammar.** A categorical symbolic grammar describes productive patterns, but language also contains exceptions.", "children": ["Reading dual-route theories were strongly motivated by neuropsychological dissociations. The morphology proposal also reflects a commitment to keeping the grammatical rule system distinct from exceptional lexical information."]}, {"text": "The contrast is between a dissociation-driven reading account and a grammatical argument for separating productive rules from exceptions.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 7}, "m3-morphology-p008": {"status": "ready", "blocks": [{"text": "**An associative lexicon handles information that does not fit a categorical rule.** Its representations are word-specific and sensitive to frequency and phonological similarity.", "children": ["KEEP–KEPT, WEEP–WEPT and LEAP–LEAPT illustrate similarity among irregular forms. An exception can belong to a small family rather than being wholly unrelated to other words."]}, {"text": "Assigning these properties to lexical memory lets the rule system remain categorical and general.", "children": []}, {"text": "The shared sound pattern in the listed verbs motivates associative similarity. It is not evidence that every irregular verb uses exactly the same transformation.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 8}, "m3-morphology-p009": {"status": "ready", "blocks": [{"text": "**Rumelhart and McClelland modeled past tense as a learned association between present and past sound patterns.** A single trainable network learns across verbs instead of applying a separately specified -ed rule.", "children": ["The model encodes a root's phonology, transforms that representation through modifiable connections, and decodes an output pattern."]}, {"text": "Regularity is a pattern learned from many examples. Irregular forms are also learned within the same system.", "children": []}, {"text": "The fixed encoding and decoding stages surround a modifiable pattern associator. Wickelfeatures represent sound patterns, while the trainable connections store the learned mapping.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 9}, "m3-morphology-p010": {"status": "ready", "blocks": [{"text": "**U-shaped learning describes an initial success, a decline, and later recovery.** A child may correctly say RAN, later produce RUNNED, and eventually return to RAN.", "children": ["The middle error is a **regularization**, because the child applies the common past-tense pattern to an irregular verb."]}, {"text": "The decline does not necessarily mean that the child has stopped learning. A changing system can generalize more broadly while temporarily disrupting an earlier correct response.", "children": []}, {"text": "The vertical dimension is successful performance and the horizontal dimension is development or training. A U shape concerns accuracy over time, not the shape of a word.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 10}, "m3-morphology-p011": {"status": "ready", "blocks": [{"text": "**The Words and Rules account explains U-shaped learning through changes in the use of rules and lexical exceptions.** Early correct forms can be imitated before a productive rule is available.", "children": ["When the rule is learned, it can be applied too broadly, yielding RUNNED. Later, learned irregulars and the blocking process prevent that regularization."]}, {"text": "This account treats the developmental stages as involving distinguishable processes rather than only gradual changes in one mapping.", "children": []}, {"text": "Blocking means that retrieval of the appropriate irregular prevents the otherwise available regular form. It is a proposed mechanism, not merely another name for correct performance.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 11}, "m3-morphology-p012": {"status": "ready", "blocks": [{"text": "**Changing the training vocabulary can produce U-shaped learning in one network.** Early training emphasizes frequent irregular verbs, allowing those particular mappings to be learned.", "children": ["As more regular verbs enter training, their common pattern changes the network's responses. That generalization can interfere with previously learned irregulars."]}, {"text": "With further learning, the network can recover the irregular responses while retaining broad regularity. No new symbolic rule component is inserted at the point of decline.", "children": []}, {"text": "The lower plot contrasts correct irregular responses with regularized alternatives. Their changing strengths illustrate competition during training, rather than the sudden appearance of a separate rule box.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 12}, "m3-morphology-p013": {"status": "ready", "blocks": [{"text": "**Testing untrained verbs asks whether the network learned transferable structure.** A real English verb can be novel to a model if it was excluded from that model's training set.", "children": ["The test therefore uses the logic of a wug task even when the items are real words to humans."]}, {"text": "The model can generate many appropriate past-tense features, but feature-level success must be distinguished from producing an entirely correct word.", "children": []}, {"text": "The summary reports proportions of Wickelfeatures generated correctly. A high proportion of correct features does not imply that the same proportion of whole words was pronounced perfectly.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 13}, "m3-morphology-p014": {"status": "ready", "blocks": [{"text": "**Some model outputs contain changes that are unlike ordinary human regularizations.** Examples include MADE(D)-like changes to MATE and the unusual outputs MEMBLED for MAIL and TOUREDER for TOUR.", "children": ["The model authors acknowledge that people are unlikely to make some of these errors. They suggest that additional output constraints could reduce bizarre responses."]}, {"text": "This separates capturing an overall learning pattern from matching the detailed form of human errors.", "children": []}, {"text": "The quotation discusses outputs near threshold and a possible cleanup mechanism. That proposed mechanism is an explanation to be tested, not a repair already demonstrated by the quoted result.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 14}, "m3-morphology-p015": {"status": "ready", "blocks": [{"text": "**Prince and Pinker argued that feature representations can blend distinct alternatives.** A model may activate features belonging to several possible past-tense forms without keeping those candidates separate.", "children": ["For SING, partial support for different sound patterns can overlap. Decoding the combined activation can produce a hybrid rather than selecting a coherent word."]}, {"text": "The criticism targets the representation and its treatment of competing outputs, not merely the presence of learning.", "children": []}, {"text": "The highlighted MEMBLED example makes the criticism concrete. It is presented as an unwanted hybrid, not as a normal past tense that children commonly produce.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 15}, "m3-morphology-p016": {"status": "ready", "blocks": [{"text": "**Joanisse and Seidenberg propose that phonology supports rule-like generalization while semantics especially supports irregular forms.** The same system links speech input, meaning and speech output.", "children": ["Reliable sound representations support extension from familiar present–past pairs to new forms. Irregular mappings receive additional support from the particular word's semantic representation."]}, {"text": "The hypothesis concerns different degrees of dependence on shared systems, rather than a separate symbolic rule route for every regular response.", "children": []}, {"text": "The diagram connects speech input and semantics through learned mappings to speech output. Its components represent domains of information, not a list of regular and irregular words in separate boxes.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 16}, "m3-morphology-p017": {"status": "ready", "blocks": [{"text": "**The model aims to explain the dissociation between irregular and nonword past-tense performance.** These tasks differ in how much they depend on learned word-specific information and phonological generalization.", "children": ["A nonword has no familiar item-specific semantic history to support its inflection. A known irregular can require semantic support because its output is not well predicted by the dominant pattern."]}, {"text": "Manipulating phonological or semantic integrity tests whether these different dependencies can produce opposite impairment profiles.", "children": []}, {"text": "The target is a pattern of performance across item types. Drawing phonology and semantics in a diagram is not enough unless damaging them produces the relevant outcomes.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 17}, "m3-morphology-p018": {"status": "ready", "blocks": [{"text": "**The patient pattern associated here with Broca's aphasia includes especially poor nonword past-tense production.** These patients have left anterior injury and difficulty producing speech.", "children": ["Regular forms are also vulnerable, while irregular forms are relatively better in the displayed comparison. A novel BLICK must be transformed without relying on a familiar stored past tense."]}, {"text": "This motivates investigating phonological contributions to the apparent morphological deficit.", "children": []}, {"text": "The graph places nonword accuracy below regular and irregular accuracy. The irregular advantage over regulars is smaller than the nonword disadvantage, so these differences should not be treated as equally large.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 18}, "m3-morphology-p019": {"status": "ready", "blocks": [{"text": "**Phonological impairment reduces past-tense performance most strongly for nonwords in the model.** Regulars are numerically worse than irregulars, but the largest difference concerns novel forms.", "children": ["The model manipulation weakens sound-based computation. Familiar words retain support unavailable to an untrained nonword."]}, {"text": "The similarity to the patient pattern shows how a selective-looking morphological deficit can arise from a broader phonological impairment.", "children": []}, {"text": "Model and patient bars are paired within regular, irregular and nonword conditions. Compare the profile across conditions rather than expecting exact equality of every bar.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 19}, "m3-morphology-p020": {"status": "ready", "blocks": [{"text": "**Other patient groups show a larger problem with irregular past-tense forms.** The material discusses Wernicke's and Alzheimer's patients and anomic patients with inferior or middle temporal injury.", "children": ["Their irregular performance is lower than their regular and nonword performance in the displayed comparison."]}, {"text": "This creates the other side of the dissociation and motivates examining the information that especially supports known irregular forms.", "children": []}, {"text": "The middle bar is the irregular condition, at roughly 60% correct, compared with higher regular and nonword scores. The diagnostic labels do not make every individual's performance identical.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 20}, "m3-morphology-p021": {"status": "ready", "blocks": [{"text": "**Semantic impairment particularly disrupts irregular past-tense forms.** When the model loses meaning-related support, irregular accuracy falls below regular and nonword accuracy.", "children": ["Typical phonological patterns still support many regular and novel forms. Nonwords can nevertheless be somewhat worse than regular words because they lack item-specific training."]}, {"text": "This shows how unequal dependence on semantics can produce the reverse of the phonological-damage profile.", "children": []}, {"text": "The irregular bars are the lowest for both the model and the comparison patients. The figure compares profiles, not a claim that model lesions reproduce every aspect of Alzheimer's disease.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 21}, "m3-morphology-p022": {"status": "ready", "blocks": [{"text": "**Phonological controls can change the apparent regular–irregular difference.** Bird and colleagues found that the difference in Broca's patients was reduced when items were adequately matched for phonology.", "children": ["Patterson and colleagues found that irregular impairment in semantic dementia correlated with semantic deficit severity."]}, {"text": "These findings connect morphology to phonological and semantic abilities, making a pure rule-versus-word interpretation less straightforward.", "children": []}, {"text": "Matching phonology addresses a potential confound in the regular–irregular comparison. Correlating semantic severity with irregular performance tests an association predicted by the alternative account.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 22}, "m3-morphology-p023": {"status": "ready", "blocks": [{"text": "**Phonological representations support learning the common mapping from present to past.** A degraded representation makes that generalization less reliable, especially for new words.", "children": ["Semantic information supports forms that depart from the dominant -ed pattern. Some irregulars also benefit from smaller phonological families and can be relatively spared."]}, {"text": "Regularity and exception status therefore describe degrees of statistical support rather than perfectly isolated kinds of processing.", "children": []}, {"text": "The comparison with triangle reading concerns the division of support between phonology and semantics. Spelling-to-sound reading and present-to-past inflection remain different tasks.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 23}, "m3-morphology-p024": {"status": "ready", "blocks": [{"text": "**Specific language impairment, or SLI in the course terminology, involves impaired language development despite relatively typical nonverbal performance.** Difficulties can include morphology and syntax.", "children": ["The profile can also involve phonology, reading, working memory and speech perception. This broader range matters when evaluating a theory that locates the problem only in grammar."]}, {"text": "A relative language difficulty does not by itself identify a single damaged learning mechanism.", "children": []}, {"text": "The list extends beyond grammatical categories. Those additional domains are relevant evidence, not automatically irrelevant symptoms because the condition is called language impairment.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 24}, "m3-morphology-p025": {"status": "ready", "blocks": [{"text": "**A rule-deficit account predicts particular difficulty with regular and novel inflections.** If a domain-specific rule-learning mechanism is impaired, irregular forms stored lexically should be relatively less affected.", "children": ["This proposal uses past-tense performance to argue for a mechanism specific to grammatical rules."]}, {"text": "The prediction must be tested against the complete pattern, including irregular performance and broader phonological difficulties.", "children": []}, {"text": "Regular real words, irregular real words and nonwords are separate conditions. A theory should state how each condition is expected to change.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 25}, "m3-morphology-p026": {"status": "ready", "blocks": [{"text": "**The van der Lely and Ullman comparison shows low past-tense accuracy across all three item types in the SLI group.** Same-age controls perform much better.", "children": ["Nonwords are especially difficult for the SLI group, but regulars and irregulars are also impaired. The results therefore contain a broad deficit as well as unequal condition difficulty."]}, {"text": "An explanation should account for the entire profile rather than reporting only that productive forms are poor.", "children": []}, {"text": "The SLI bars are approximately 20% for regulars, somewhat lower for irregulars and below 10% for nonwords. The controls' bars are much higher in all three categories.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 26}, "m3-morphology-p027": {"status": "ready", "blocks": [{"text": "**Weakening phonological processing produces impaired learning across forms, with nonwords especially vulnerable.** The severe and weaker impairment settings differ in the degree of difficulty.", "children": ["The intact model performs substantially better. Even intact learning shows different performance across regulars, irregulars and nonwords."]}, {"text": "The comparison tests whether a phonological learning weakness can reproduce important aspects of the behavioral profile without a missing grammatical rule.", "children": []}, {"text": "Compare severe phonology, weaker phonology and intact settings. The bars report percent correct, and the intact model is shown at two training points, so training amount and impairment should not be conflated.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 27}, "m3-morphology-p028": {"status": "ready", "blocks": [{"text": "**Phonology contributes to every spoken past-tense response.** Weakening it can therefore reduce performance on regulars, irregulars and nonwords.", "children": ["Nonwords are particularly dependent on generalizing a sound pattern to a new form. Familiar words have additional item-specific learning that can partly support their responses."]}, {"text": "The pattern to explain is broad impairment with a disproportionate nonword cost. A theory that predicts only one affected category misses part of that pattern.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 28}, "m3-morphology-p029": {"status": "ready", "blocks": [{"text": "**The associative account learns mappings among phonology and semantics without a separate symbolic past-tense rule or an isolated exception lexicon.** Regular and irregular are useful descriptions of behavior, but only approximate descriptions of the system's internal organization.", "children": ["Irregular performance is associated with semantic processing. Wug-test performance is associated with phonological processing."]}, {"text": "These associations provide tests of the proposed underlying mechanisms, beyond simply assigning different item types to different boxes.", "children": []}, {"text": "The contrast with Words and Rules concerns representation and computation, not whether the English language contains recognizable regular and irregular patterns.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 29}, "m3-morphology-p030": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/morphology.txt", "source": "morphology", "page": 30}, "m3-thought-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 1}, "m3-thought-p002": {"status": "ready", "blocks": [{"text": "**Linguistic relativity concerns whether differences in language influence how people organize or use concepts.** The Sapir and Whorf quotations suggest that linguistic categories can shape how experience is interpreted.", "children": ["The strongest reading would make language determine what a person can think. A weaker claim is that habitual language use biases attention, memory or preferred ways of representing a situation."]}, {"text": "These claims require different evidence. A preference associated with language does not establish that alternative thought is impossible.", "children": []}, {"text": "The quotations express broad theoretical ideas. They are not experimental demonstrations that two speakers are unable to understand the same physical event.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 2}, "m3-thought-p003": {"status": "ready", "blocks": [{"text": "**Language is embedded in cultural practices and experience.** A difference between language communities may therefore covary with factors other than linguistic structure.", "children": ["Sapir and Whorf should not automatically be assigned the strongest deterministic interpretation of selected quotations."]}, {"text": "A precise study must identify which cognitive process is affected and what alternative explanations the comparison controls.", "children": []}, {"text": "Historical framing explains why language and culture were often discussed together. It also highlights the need to distinguish their contributions in an experiment.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 3}, "m3-thought-p004": {"status": "ready", "blocks": [{"text": "**A location description needs a frame of reference.** Saying where the ball is requires choosing what counts as left, front or a stable direction.", "children": ["The ball can be located with respect to the viewer, the chair's own orientation or a direction independent of either."]}, {"text": "Different descriptions can identify the same physical position while organizing that position differently.", "children": []}, {"text": "The chair and ball are the meaningful stimuli. The question is which reference determines the ball's location, not a judgment about the objects' appearance.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 4}, "m3-thought-p005": {"status": "ready", "blocks": [{"text": "**An intrinsic frame uses an object's own orientation, a relative frame uses an observer's viewpoint, and an absolute frame uses a stable direction.** These are different ways to specify the same location.", "children": ["“At the chair's front” uses the chair's intrinsic front. “To the left of the chair from my viewpoint” depends on the observer."]}, {"text": "“North of the chair” uses an absolute direction that does not reverse when the observer turns around.", "children": []}, {"text": "The ball–chair example holds the scene constant while changing the reference. Rotating the observer changes relative left and right but does not change north.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 5}, "m3-thought-p006": {"status": "ready", "blocks": [{"text": "**Egocentric spatial descriptions use the speaker's position and orientation.** Left, right, in front and behind are familiar examples for nearby objects.", "children": ["Tzeltal commonly uses absolute directions in circumstances where English speakers might use these relative terms."]}, {"text": "The contrast motivates asking whether habitual language use relates to nonverbal spatial coding, rather than merely comparing two ways of giving spoken directions.", "children": []}, {"text": "The language comparison concerns preferred spatial descriptions. It does not imply that speakers of either language are incapable of learning another frame.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 6}, "m3-thought-p007": {"status": "ready", "blocks": [{"text": "**Tzeltal's uphill and downhill terms function as an absolute directional system.** Their historical connection to a slope does not mean that each use simply points to the nearest visible hill.", "children": ["A direction is retained as a stable spatial reference rather than being recalculated from the speaker's current left and right."]}, {"text": "This allows positions to be described consistently as the speaker changes orientation.", "children": []}, {"text": "The contrast is with a description that depends entirely on the current viewpoint. The relevant feature is how the reference behaves across changes in location and orientation.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 7}, "m3-thought-p008": {"status": "ready", "blocks": [{"text": "**A landmark-based direction is tied to a particular environment.** Uptown and downtown organize movement within Manhattan but do not provide a universally usable compass system.", "children": ["A city's conventional map orientation can also differ from magnetic north. Familiar spatial language therefore reflects local practices as well as geometric directions."]}, {"text": "The Manhattan example distinguishes local orientation from cardinal direction. It is a contrast about reference systems rather than an experiment demonstrating linguistic causation.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 8}, "m3-thought-p009": {"status": "ready", "blocks": [{"text": "**The chips task separates relative from absolute spatial memory by rotating the participant 180 degrees.** A participant sees a configuration, waits, and then chooses its match at a second table.", "children": ["A relative response preserves the arrangement with respect to the person's viewpoint. An absolute response preserves its orientation in the environment, so the two responses diverge after rotation."]}, {"text": "Dutch speakers predominantly gave relative responses, while Tzeltal speakers gave more absolute responses. The association is consistent with their preferred linguistic frames but does not isolate language from all other experience.", "children": []}, {"text": "The north arrow stays fixed while the person changes orientation. Red bars represent relative choices and blue bars absolute choices, showing different response distributions across the two language groups.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 9}, "m3-thought-p010": {"status": "ready", "blocks": [{"text": "**Spatial inference can combine relations learned in different displays.** Participants learn the relation between two objects, rotate to another display, and learn a second relation involving a shared object.", "children": ["They then place an object relative to another using the combined information. Relative and absolute coding lead to different placements because the person's orientation has changed."]}, {"text": "Dutch and Tzeltal response patterns again differ in the direction associated with their preferred spatial frames.", "children": []}, {"text": "The cube appears in both learning displays, linking the cone and cylinder relations. The final placement distinguishes a viewer-relative inference from one preserving environmental direction.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 10}, "m3-thought-p011": {"status": "ready", "blocks": [{"text": "**Testing conditions could contribute to the apparent language-group difference.** Li and Gleitman noted that Tzeltal participants had been tested with visible, familiar outdoor landmarks, unlike many laboratory participants.", "children": ["An environment with useful landmarks can encourage landmark-based coding. A windowless laboratory can make viewer-relative descriptions more convenient."]}, {"text": "Manipulating landmark availability within English speakers tests whether the behavior can change without changing native language.", "children": []}, {"text": "The critical contrast is access to spatial cues, not simply the label “laboratory.” Windows, outdoor views and familiar surroundings can alter which references are useful.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 11}, "m3-thought-p012": {"status": "ready", "blocks": [{"text": "**English speakers' preference for relative coding weakened when external landmarks were available.** They strongly preferred relative responses with the blinds down, but the preference was less pronounced with a street view or outdoors.", "children": ["The manipulation changes the spatial information available while keeping the language group the same."]}, {"text": "This demonstrates that task context can influence the response. It challenges an explanation in which language alone fixes the chosen frame.", "children": []}, {"text": "A reduced relative preference is not necessarily a complete switch to absolute coding. Describe the observed change in preference without exaggerating it into an all-or-none reversal.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 12}, "m3-thought-p013": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 13}, "m3-thought-p014": {"status": "ready", "blocks": [{"text": "**If language groups are tested under different conditions, their response difference may partly reflect those conditions.** Visible landmarks and familiarity can covary with native language in a cross-community study.", "children": ["A controlled comparison must separate the effect of the environment from any contribution of habitual linguistic coding."]}, {"text": "Showing an environmental effect does not prove that language never matters. It limits what can be inferred from an uncontrolled comparison.", "children": []}, {"text": "A confound is a factor that changes with the variable of interest and offers another explanation for the result. It is not merely any feature present in the experiment.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 14}, "m3-thought-p015": {"status": "ready", "blocks": [{"text": "**Levinson and colleagues argued that the simplified task could make the experimenter's purpose too obvious.** Low memory demands and short time or distance between displays may encourage a deliberate strategy about rotation.", "children": ["Participants who infer what is being tested can alter their response for reasons different from habitual spatial coding."]}, {"text": "The response therefore focuses on memory load and task transparency, rather than denying that landmarks can ever matter.", "children": []}, {"text": "The proposed alternative is a demand-characteristic explanation. Participants' interpretation of the experiment may influence the response independently of their normal coding preference.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 15}, "m3-thought-p016": {"status": "ready", "blocks": [{"text": "**Levinson and colleagues retested Dutch students with four animals, a longer delay and greater distance between tables.** The extra item and delay increased memory demands, while the distance made the rotation manipulation less conspicuous.", "children": ["Under these conditions, the preference for relative coding remained."]}, {"text": "The result suggests that the environmental effect depends on how the task is arranged, including how much memory and strategic inference it encourages.", "children": []}, {"text": "Each procedural change has a purpose. More animals and a longer delay tax memory, while separation of the tables reduces the salience of the rotation.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 16}, "m3-thought-p017": {"status": "ready", "blocks": [{"text": "**A robust spatial-frame preference under memory demands does not automatically identify a purely spatial representation.** Remembering the task can recruit verbal strategies as well as spatial ones.", "children": ["The relative preference is reported when memory demands are substantial and the experimenter's interest is less obvious."]}, {"text": "That pattern makes it important to ask how the sequence is stored during the delay, not only which direction is chosen at the end.", "children": []}, {"text": "The two conditions concern memory load and task transparency. They specify when the effect is robust, rather than proving that all other explanations have been eliminated.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 17}, "m3-thought-p018": {"status": "ready", "blocks": [{"text": "**Participants might remember the animals as a verbal list such as “lion, tiger, bear.”** Reconstructing that sequence from left to right can produce a relative-looking response.", "children": ["This strategy would connect language to the task through working memory and ordering habits, rather than through an inability to represent absolute space."]}, {"text": "The interpretation changes because the same choice can arise from different internal codes.", "children": []}, {"text": "The proposed list preserves order but does not explicitly preserve compass direction. Translating that order into a left-to-right display can mimic a spatial-frame preference.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 18}, "m3-thought-p019": {"status": "ready", "blocks": [{"text": "**Metaphorical language expresses one kind of experience using terms from another.** Saying that an argument is not “cutting” describes its effectiveness rather than a literal action with a blade.", "children": ["Physical and spatial terms can therefore help express abstract relations. Time is especially useful for studying whether such linguistic habits are associated with nonlinguistic representations."]}, {"text": "The question is empirical. Using a spatial phrase does not by itself prove that every thought about time has the same spatial format.", "children": []}, {"text": "The lyric is an example of metaphorical expression. It is not experimental evidence for a particular direction of causation between language and thought.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 19}, "m3-thought-p020": {"status": "ready", "blocks": [{"text": "**English and Mandarin both use horizontal spatial language for time, but Mandarin also frequently uses vertical terms.** Earlier events can be described with an “up” term and later events with a “down” term.", "children": ["The linguistic contrast motivates testing whether speakers differ in the spatial organization they use during temporal tasks."]}, {"text": "The existence of the expressions is the starting observation. A behavioral task is needed to investigate whether the contrast extends beyond words.", "children": []}, {"text": "The examples contrast spatial and temporal uses of the same terms. “Up” in an expression for an earlier month is a temporal use, not a claim that the month occupies a physical location.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 20}, "m3-thought-p021": {"status": "ready", "blocks": [{"text": "**Boroditsky's priming task tests whether spatial processing influences subsequent time judgments.** Participants first process horizontal or vertical relations, then respond to temporal earlier–later questions.", "children": ["English speakers respond faster after horizontal than vertical primes, while Mandarin speakers show the opposite pattern in the displayed comparison."]}, {"text": "Training English speakers on vertical metaphors changes the pattern toward a vertical-prime advantage. This suggests sensitivity to experience, rather than an unchangeable division between language groups.", "children": []}, {"text": "The vertical axis is reaction time, so a lower bar means faster processing. Compare horizontal and vertical bars within each group rather than interpreting the tallest bar as the best performance.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 21}, "m3-thought-p022": {"status": "ready", "blocks": [{"text": "**Reading and writing habits can also organize sequences spatially.** Differences attributed to temporal metaphors may covary with whether text is commonly read left-to-right, right-to-left or vertically.", "children": ["Casasanto and Bottini use differences in text orientation and arrangement preferences to motivate this alternative."]}, {"text": "The point is to identify another source of spatial experience, not to assume that a writing-system label perfectly predicts every individual's habits.", "children": []}, {"text": "The diagrams distinguish starting side and line direction. The table shows several arrangement patterns within the sampled groups, making individual experience relevant.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 22}, "m3-thought-p023": {"status": "ready", "blocks": [{"text": "**Boroditsky and colleagues excluded Chinese readers who reported top-to-bottom reading.** This tests whether the vertical temporal effect can be explained entirely by that reported reading experience.", "children": ["English speakers show an advantage for a left-is-earlier horizontal mapping. Mandarin speakers also show an advantage for a top-is-earlier vertical mapping in the displayed comparison."]}, {"text": "Retaining a vertical effect under this restriction weakens that particular reading-direction explanation, without proving that every possible experiential confound is removed.", "children": []}, {"text": "White bars are canonical mappings and black bars noncanonical mappings. For vertical trials, canonical means top-is-earlier. Lower reaction times indicate a mapping advantage.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 23}, "m3-thought-p024": {"status": "ready", "blocks": [{"text": "**Participants classify events as past or future using colored buttons.** The color-to-category mapping is reversed across blocks, so the past response is sometimes on the left and sometimes on the right.", "children": ["With standard text reading, responses are faster when past maps left and future maps right."]}, {"text": "Because the response concerns time rather than an explicit judgment of spatial direction, the compatibility effect reveals an implicit spatial association in this task.", "children": []}, {"text": "The lower black bars represent the left-to-right temporal mapping. The effect concerns response time across mappings, not a change in which events count as past or future.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 24}, "m3-thought-p025": {"status": "ready", "blocks": [{"text": "**Mirror reading tests whether short-term reading experience can alter spatial associations with time.** Participants read reversed text and perform the past–future button task.", "children": ["By the second mirror-reading block, the compatibility effect reverses. Responses are faster when earlier maps right and later maps left."]}, {"text": "The result supports a contribution of reading-direction experience and shows that the association can change over a short period.", "children": []}, {"text": "The first block retains the usual advantage, while the second favors the opposite mapping. Compare the two colors within each block before comparing overall reaction times between blocks.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 25}, "m3-thought-p026": {"status": "ready", "blocks": [{"text": "**Claims about a language's vocabulary are not automatically evidence for cognitive limits.** Pullum's discussion criticizes how an account of different word roots became an exaggerated story about language and thought.", "children": ["Languages can express distinctions through separate roots, derived words or phrases. Counting one of these forms without considering the others can misrepresent expressive capacity."]}, {"text": "A reliable claim requires accurate linguistic description and an appropriate behavioral test, rather than repetition of a striking anecdote.", "children": []}, {"text": "The excerpt distinguishes roots from derivationally related forms and phrases. That distinction is central to why simple vocabulary counts can be misleading.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 26}, "m3-thought-p027": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/thought.txt", "source": "thought", "page": 27}, "m3-modalities-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 1}, "m3-modalities-p002": {"status": "ready", "blocks": [{"text": "**A signed language is a natural language, while Braille is a writing system.** Signed languages have their own linguistic structure. Braille allows a language to be read through touch.", "children": ["The distinction matters because changing the modality of a language is not the same as changing how a written language is accessed."]}, {"text": "Both cases reveal how sensory experience shapes the organization of systems involved in language and reading.", "children": []}, {"text": "The shared theme is modality, but the linguistic status of the two cases differs. A comparison should preserve that distinction before discussing their brain responses.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 2}, "m3-modalities-p003": {"status": "ready", "blocks": [{"text": "**Signed languages use a visual modality and manual and bodily articulators.** The hands, face and upper body contribute to a coordinated linguistic signal.", "children": ["Space can carry linguistic relations. Some signs are iconic, meaning that aspects of their form resemble aspects of their meaning."]}, {"text": "Iconicity is easy to overestimate when a familiar translation is supplied. A visible resemblance does not eliminate the need to learn a language's forms and structure.", "children": []}, {"text": "The pictured signs include actions, objects and less directly depictable concepts. A gloss names the translation but does not make every feature of a sign self-explanatory.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 3}, "m3-modalities-p004": {"status": "ready", "blocks": [{"text": "**Fluent signing coordinates hands, facial expression, gaze and upper-body movement.** The linguistic signal is distributed across these visible articulators rather than produced by one hand movement at a time.", "children": ["Like speech, a fluent stream is continuous enough that word boundaries are not always obvious to a learner."]}, {"text": "Eye contact and movement timing are therefore relevant to perceiving the interaction, alongside the form of individual signs.", "children": []}, {"text": "The linked demonstration invites attention to coordination and segmentation. The original video link is retained separately from the static slide.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 4}, "m3-modalities-p005": {"status": "ready", "blocks": [{"text": "**Signed-language phonology includes contrastive hand configuration, location and movement.** Changing one of these features can distinguish signs, just as changing a speech feature can distinguish spoken words.", "children": ["The PLEASE–SORRY and ONION–APPLE examples demonstrate that closely related visible forms can have different linguistic identities."]}, {"text": "Phonology therefore concerns the organization of contrastive form, not only acoustic sound.", "children": []}, {"text": "The paired images hold some properties similar while contrasting others. Handshape, where the gesture is made and how it moves are separate dimensions to inspect.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 5}, "m3-modalities-p006": {"status": "ready", "blocks": [{"text": "**Categorical perception can be tested by varying a sign feature continuously.** The hand-configuration continuum moves between forms while the observer's identification and discrimination responses are measured.", "children": ["One continuum crosses a phonemic distinction between PLEASE and SORRY. The allophonic comparison varies hand configuration without the same change in sign identity."]}, {"text": "A sharp identification boundary accompanied by better discrimination near that boundary would indicate category-sensitive perception.", "children": []}, {"text": "The stimulus sequences progress through intermediate hand configurations. Comparing equal-sized changes within and across a linguistic boundary is more informative than comparing only the two endpoints.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 6}, "m3-modalities-p007": {"status": "ready", "blocks": [{"text": "**Deaf signers show a sharper categorical boundary for phonemic than allophonic hand-configuration changes.** In the phonemic condition, identification shifts steeply around stimuli 4–6.", "children": ["Discrimination is also strongest near the phonemic boundary. Comparable physical steps are easier to distinguish when they cross that category boundary."]}, {"text": "The allophonic identification function is shallower and lacks the same localized discrimination peak. This links the perceptual pattern to linguistic contrast rather than any visible hand change.", "children": []}, {"text": "The top plots show categorization and the lower plots discrimination. Compare the position of the steep change with the discrimination peak in the phonemic column.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 7}, "m3-modalities-p008": {"status": "ready", "blocks": [{"text": "**Signed languages can use positions in signing space to represent relationships.** A classifier sign made at a particular location can indicate the relative position of an object.", "children": ["Understanding a sentence can require retaining where entities were introduced and how subsequent signs relate to those locations."]}, {"text": "Spatial processing therefore contributes to linguistic comprehension, rather than functioning only as background vision.", "children": []}, {"text": "The classifier example uses relative placement to express a relation between objects. The signing location is instructional information, not a decorative feature of the display.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 8}, "m3-modalities-p009": {"status": "ready", "blocks": [{"text": "**Signed-language comprehension recruits classical language regions and shows left lateralization, as spoken-language comprehension does.** Inferior frontal and posterior superior temporal regions are part of this overlap.", "children": ["Signing also engages visual and superior parietal regions relevant to its perceptual and spatial demands."]}, {"text": "The combination suggests both common language organization and modality-related contributions. Similarity does not require identical activation everywhere.", "children": []}, {"text": "The figure compares deaf signers, hearing signers and hearing audiovisual-speech participants. Hearing signers are particularly useful because signing experience is not restricted to people who are deaf.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 9}, "m3-modalities-p010": {"status": "ready", "blocks": [{"text": "**Bavelier and colleagues compared hearing controls, deaf signers and hearing signers on visual attention.** Participants monitored dots for brief changes in luminance or velocity, with attention directed centrally or peripherally.", "children": ["Deaf participants showed an advantage when attention was directed to the periphery."]}, {"text": "Including hearing signers helps separate experience with signing from lack of auditory input. If all signers had the same advantage, signing alone would be a stronger explanation.", "children": []}, {"text": "The display distinguishes center and peripheral monitoring. Luminance concerns brightness and velocity concerns motion, so the task measures attention to brief visual changes rather than sign comprehension itself.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 10}, "m3-modalities-p011": {"status": "ready", "blocks": [{"text": "**Signing experience and deafness show different associations with visual processing.** Both deaf and hearing signers show a leftward shift in motion-processing lateralization relative to hearing nonsigners.", "children": ["Enhanced peripheral attention is found in deaf individuals, not hearing signers. Signing experience alone therefore does not explain that enhancement."]}, {"text": "The proposed interpretations involve links between motion and language systems for signing, and reduced reliance on auditory peripheral cues in deafness.", "children": []}, {"text": "The upper comparison concerns hemispheric bias in motion-related areas. The lower comparison concerns center-versus-periphery attention. The sign and size of a bar must be read using its own axis.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 11}, "m3-modalities-p012": {"status": "ready", "blocks": [{"text": "**Comparing sign comprehension with another organized gesture system helps control visible movement demands.** Tic-tac uses sophisticated hand gestures to communicate horse-racing odds.", "children": ["Both tasks involve meaningful, sequenced hand movements. A difference between them is more informative about linguistic processing than a comparison between signing and no movement."]}, {"text": "The control is not identical to a natural language, which is precisely why the remaining difference is of interest.", "children": []}, {"text": "The original demonstration link concerns the control gesture system. The comparison does not assume that every meaningful gesture is a natural language.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 12}, "m3-modalities-p013": {"status": "ready", "blocks": [{"text": "**Sign language produces stronger activity around posterior superior temporal language regions than tic-tac gestures.** This supports a distinction between processing organized hand movements and processing a natural language.", "children": ["The comparison reduces a simple explanation based only on the presence of hands moving through space."]}, {"text": "The frontal activation shown is superior to classic Broca's area, so it should not be casually relabeled as a precise Broca's effect.", "children": []}, {"text": "The highlighted posterior temporal activation is near Wernicke's region. The figure supports a regional comparison, not the claim that one highlighted spot is solely responsible for all signing.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 13}, "m3-modalities-p014": {"status": "ready", "blocks": [{"text": "**Signed languages have linguistic form, grammar and language-related neural organization.** Contrastive sign features can produce categorical perception, and comprehension recruits posterior superior temporal language regions.", "children": ["Signing experience is associated with changes in motion lateralization. Deafness is associated with enhanced peripheral attention in the reported comparison."]}, {"text": "These findings jointly show that linguistic experience and sensory history contribute in different ways.", "children": []}, {"text": "The summary combines behavioral category evidence, group comparisons and neural contrasts. Each addresses a different question, so one result should not be used as if it established all the others.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 14}, "m3-modalities-p015": {"status": "ready", "blocks": [{"text": "**Comprehending a signed spatial description can require a perspective transformation.** A room can be described from the speaker's perspective or the addressee's perspective.", "children": ["The figure's caption reports better comprehension for descriptions from the speaker's perspective despite the mental transformation that this requires."]}, {"text": "This illustrates that the most linguistically natural representation is not necessarily the one that eliminates every spatial transformation.", "children": []}, {"text": "The two signing sequences describe the same table location in the room diagram. The difference is whose perspective organizes the description, not a change in the table's actual location.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 15}, "m3-modalities-p016": {"status": "ready", "blocks": [{"text": "**Braille represents written language through tactilely distinguishable symbols.** It is a way to read a language, rather than a separate natural language with its own grammar.", "children": ["The symbols are optimized for touch. Fingers acquire letters sequentially, creating perceptual demands that differ from viewing printed text."]}, {"text": "The comparison asks how reading networks operate when the input arrives through touch instead of vision.", "children": []}, {"text": "Sequential tactile sampling is a processing constraint. It does not imply that Braille readers must consciously name every individual dot before understanding a word.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 16}, "m3-modalities-p017": {"status": "ready", "blocks": [{"text": "**Braille reading activates visual cortex in blind individuals, with more extensive recruitment after earlier sight loss.** Early- and late-blind groups therefore provide a comparison of developmental sensory history.", "children": ["Early-blind participants show stronger involvement of regions associated with visual word processing than late-blind participants."]}, {"text": "This indicates that a region's usual sensory label does not completely determine the information it can help process.", "children": []}, {"text": "The early-blind examples are on the left and late-blind examples on the right. Compare the extent of activation rather than assuming that every displayed colored voxel has the same function.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 17}, "m3-modalities-p018": {"status": "ready", "blocks": [{"text": "**Merabet and colleagues tested rapid plasticity by blindfolding sighted adults for five days while training Braille.** A comparison group received training without the same continuous removal of visual input.", "children": ["The blindfolded group learned more quickly. This suggests that eliminating competing visual input can affect tactile learning over a short timescale."]}, {"text": "Because the participants were sighted adults, the experiment tests a different question from lifelong or early blindness.", "children": []}, {"text": "The procedure includes baseline testing, training, repeated imaging and blindfold removal. The group comparison distinguishes training effects from the additional effect of continuous blindfolding.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 18}, "m3-modalities-p019": {"status": "ready", "blocks": [{"text": "**Visual-cortex responses to Braille developed during blindfolding and reversed after the blindfold was removed on Day 6.** The time course shows that the change was rapid and reversible.", "children": ["Removing visual input can allow tactile-related activity to become more evident. Restoring vision changes that balance again."]}, {"text": "This pattern is consistent with unmasking existing inputs rather than requiring the creation of an entirely new pathway over a few days.", "children": []}, {"text": "The images and signal plot compare Days 1, 3, 5 and 6. Day 6 is specifically the post-blindfold condition, not simply another day under unchanged deprivation.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 19}, "m3-modalities-p020": {"status": "ready", "blocks": [{"text": "**Disrupting visual cortex with TMS impaired Braille discrimination in the blindfolded group.** This goes beyond showing that the region becomes active during touch.", "children": ["On Day 5, the blindfolded group's error rate rises under 1 Hz TMS relative to its baseline and sham conditions. The nonblindfolded group does not show the same selective disruption."]}, {"text": "The effect is no longer present in the same way after blindfold removal. The result supports a temporary functional contribution of visual cortex to tactile performance.", "children": []}, {"text": "The solid symbols identify blindfolded participants. The vertical axis is error rate, so the upward TMS change means worse performance, not improved reading.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 20}, "m3-modalities-p021": {"status": "ready", "blocks": [{"text": "**Language-related organization is resilient across sensory modalities while remaining shaped by experience.** Signed language recruits classical language regions, and Braille engages networks associated with text processing.", "children": ["Competition among available inputs offers a way to understand reorganization. When an input is absent or reduced, other information can make a larger contribution."]}, {"text": "The evidence does not imply that all regions are interchangeable. It shows both stable functional relationships and experience-sensitive recruitment.", "children": []}, {"text": "Distinguish the language-network overlap from the visual-attention and tactile-recruitment findings. They support a related account of plasticity through different experimental comparisons.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "modalities", "page": 21}, "m3-review-p001": {"status": "noninstructional", "blocks": [], "authorFile": "authoring/content/review.txt", "source": "review", "page": 1}, "m3-review-p002": {"status": "ready", "blocks": [{"text": "**Orthographic depth** describes how consistently spelling corresponds to pronunciation. English is relatively deep because many spellings do not transparently specify their sounds.", "children": ["COLONEL and PARADIGM make the problem concrete. Applying common letter–sound patterns can produce a plausible-looking pronunciation that is wrong for the actual word."]}, {"text": "In shallower writing systems, such as Finnish and Korean, spelling–sound correspondences are more predictable. The comparison concerns the writing system, not the intelligence or ability of its readers.", "children": []}, {"text": "The English examples contrast ordinary expectations from the letters with the word's learned pronunciation. A deep script is less predictable, not completely random.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 2}, "m3-review-p003": {"status": "ready", "blocks": [{"text": "**Finnish has a shallow orthography.** Letters correspond relatively unambiguously to phonemes, so learning a spelling–sound correspondence helps with many different words.", "children": ["Doubled letters represent a meaningful length distinction. A doubled consonant is geminated, and a doubled vowel is long."]}, {"text": "This regularity helps Finnish children learn decoding quickly. Decoding means generating a pronunciation from a written form, whether or not its meaning is familiar.", "children": []}, {"text": "The linked Finnish lesson is a source demonstration. Its sound is not embedded in the PDF, so the written claims establish the correspondence and length distinctions without supplying a recovered recording.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 3}, "m3-review-p004": {"status": "ready", "blocks": [{"text": "**Pseudoword reading tests decoding.** Because a pseudoword is not a familiar stored word, the child must generalize from learned spelling–sound patterns.", "children": ["The comparison involves Grade 1 children learning different alphabetic writing systems. Children learning many other languages produce plausible pseudoword pronunciations more successfully than English learners."]}, {"text": "English's less predictable correspondences help explain why decoding develops more slowly. This task does not measure the child's entire language ability.", "children": []}, {"text": "Compare accuracy across languages for the same type of task. The important outcome is the relative difficulty of English pseudoword decoding, not a claim that English children cannot decode.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 4}, "m3-review-p005": {"status": "ready", "blocks": [{"text": "**Korean writing represents sound structure systematically.** Related phonemes can have related written shapes, so the visual forms themselves reflect aspects of phonological organization.", "children": ["The letters are arranged into syllable blocks with initial, medial and sometimes final positions. Those positions are not three unrelated pictures of whole words."]}, {"text": "The velar consonant forms share the basic angular ㄱ shape. Additional strokes or doubling distinguish related consonants.", "children": []}, {"text": "The diagrams label initial, medial and final positions. The g, kk and k examples share a shape family, illustrating how a place-of-articulation relation can be reflected in the script.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 5}, "m3-review-p006": {"status": "ready", "blocks": [{"text": "**Frequency and regularity interact.** Low-frequency exception words are slowed much more than low-frequency regular words, whereas high-frequency words show a much smaller regularity difference.", "children": ["Naming latency is the time needed to begin saying the word. Higher values mean slower responses."]}, {"text": "An interaction means the effect of one factor depends on the other. The regularity cost is not a fixed amount added equally to high- and low-frequency words.", "children": []}, {"text": "The lines are close at high frequency and separate at low frequency. Exception words rise to roughly 580 ms, while regular words rise only to roughly 555 ms in this figure.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 6}, "m3-review-p007": {"status": "ready", "blocks": [{"text": "**A dual-route interpretation separates lexical retrieval from sublexical decoding.** The lexical process supplies the learned pronunciation of a particular word, while decoding computes pronunciation from spelling units.", "children": ["For a high-frequency word, lexical information becomes available quickly enough to reduce the influence of the decoding output."]}, {"text": "For a low-frequency exception, the lexical response is less efficient and the regularized decoding output can interfere. Nonwords depend on decoding because they lack a stored whole-word entry.", "children": []}, {"text": "This is an interpretation of the interaction, not the interaction itself. Other architectures must be evaluated against the same observed pattern.", "children": []}], "authorFile": "authoring/content/reading1.txt", "source": "review", "page": 7}, "m3-review-p008": {"status": "ready", "blocks": [{"text": "**In a PDP account, rules are generalizations learned across words.** Whole-word knowledge is distributed across learned mappings instead of being stored only in a distinct lexical route.", "children": ["The same learning mechanism can capture both patterns shared by many words and information specific to a familiar word."]}, {"text": "The research strategy asks whether domain-general learning can explain reading. This contrasts with choosing separate adult processing components primarily from neuropsychological dissociations.", "children": []}, {"text": "“Distributed” refers to how knowledge is represented across the network. It does not mean that the model has no memory of individual words.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 8}, "m3-review-p009": {"status": "ready", "blocks": [{"text": "**A learned network can produce a frequency-by-regularity interaction without separate frequency and rule mechanisms.** Regular words receive support from patterns shared across many words.", "children": ["An exception conflicts with those patterns, so learning its particular mapping is especially important. Frequent exposure strengthens that word-specific mapping."]}, {"text": "A low-frequency exception has both weak item-specific learning and poor support from the dominant pattern. This combination creates a larger disadvantage than either factor alone.", "children": []}, {"text": "The interaction is shared evidence that both architectures must explain. Producing it does not by itself establish whether the implementation contains symbolic rules.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 9}, "m3-review-p010": {"status": "ready", "blocks": [{"text": "**A PDP model can pronounce nonwords using the weights learned from real words.** A new spelling activates patterns that overlap with familiar spellings, allowing the network to generalize.", "children": ["No stored entry for the particular nonword is required. The same learned correspondences that support consistent words can support a new combination."]}, {"text": "This is a proposed mechanism for decoding without a separate GPC rule module.", "children": []}, {"text": "The relevant comparison is whether one learned mapping can handle both familiar words and new items. The claim must still be checked against the model's actual performance.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 10}, "m3-review-p011": {"status": "ready", "blocks": [{"text": "**Poor nonword performance can challenge either a theoretical proposal or a particular implementation.** The early model's nonword accuracy was weaker than desired.", "children": ["One possibility is that a single associative mechanism cannot explain the task. Another is that the chosen representations fail to capture the similarities needed for generalization."]}, {"text": "Improving the implementation while retaining the theoretical mechanism helps distinguish these possibilities.", "children": []}, {"text": "The important question is what changes when the model is repaired. A representational improvement is a different theoretical move from adding a separate nonword route.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 11}, "m3-review-p012": {"status": "ready", "blocks": [{"text": "**Generalization depends on how sound similarity is represented.** The early Seidenberg–McClelland model used Wickelfeatures, whose representation of phonology was problematic for nonword reading.", "children": ["Plaut and colleagues improved the phonological representations and obtained better nonword performance. This supports a representational explanation for at least part of the earlier failure."]}, {"text": "Behavioral relations between phonological processing and decoding also make phonology a relevant target for explanation.", "children": []}, {"text": "The comparison concerns models with different representations. Better performance after that change is evidence about implementation, not proof that every associative model will succeed.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 12}, "m3-review-p013": {"status": "ready", "blocks": [{"text": "**A network generalizes through similarity.** If its phonological representation poorly captures similarities among words, the learned mapping cannot transfer as effectively to new forms.", "children": ["A familiar word can retain support from its own training history. A nonword lacks that item-specific experience and depends more heavily on generalization."]}, {"text": "This produces a reason for unfamiliar forms to be especially vulnerable to poor representations without requiring a dedicated nonword mechanism.", "children": []}, {"text": "Distinguish a weaker shared representation from damage to a separate route. Both can create a task difference, but they locate the explanation differently.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 13}, "m3-review-p014": {"status": "ready", "blocks": [{"text": "**Harm and Seidenberg manipulated noise in phonological representations.** Increasing noise makes the sound representations less reliable while keeping the model's general learning framework.", "children": ["The manipulation produced poorer nonword decoding and relative sparing of word recognition. It also linked the severity of the phonological deficit to the degree of decoding difficulty."]}, {"text": "The model therefore connects a reading pattern to the quality of a more general phonological system.", "children": []}, {"text": "Noise is the manipulated model property. Word and nonword performance are outcomes, so the simulation tests a directional mechanistic proposal rather than merely observing a correlation.", "children": []}], "authorFile": "authoring/content/reading2.txt", "source": "review", "page": 14}, "m3-review-p015": {"status": "ready", "blocks": [{"text": "**The lexicon and grammar offer different ways to produce a past tense.** Lexical retrieval supplies an irregular form such as HELD, while grammatical combination can produce WALK plus -ed.", "children": ["Pinker and Ullman's diagram associates lexical lookup with declarative memory and grammatical combination with procedural processing."]}, {"text": "Like dual-route reading, the account separates word-specific knowledge from a productive operation. Unlike reading aloud, its task is to transform a stem according to a grammatical feature, rather than convert spelling into sound.", "children": []}, {"text": "The input includes a stem and a past-tense feature. The diagram distinguishes lexical association from combination, and its blocking connection prevents a retrieved irregular from competing unchecked with a regular form.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 15}, "m3-review-p016": {"status": "ready", "blocks": [{"text": "**The Words and Rules proposal was motivated partly by a theory of grammar.** A categorical symbolic grammar describes productive patterns, but language also contains exceptions.", "children": ["Reading dual-route theories were strongly motivated by neuropsychological dissociations. The morphology proposal also reflects a commitment to keeping the grammatical rule system distinct from exceptional lexical information."]}, {"text": "The contrast is between a dissociation-driven reading account and a grammatical argument for separating productive rules from exceptions.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 16}, "m3-review-p017": {"status": "ready", "blocks": [{"text": "**An associative lexicon handles information that does not fit a categorical rule.** Its representations are word-specific and sensitive to frequency and phonological similarity.", "children": ["KEEP–KEPT, WEEP–WEPT and LEAP–LEAPT illustrate similarity among irregular forms. An exception can belong to a small family rather than being wholly unrelated to other words."]}, {"text": "Assigning these properties to lexical memory lets the rule system remain categorical and general.", "children": []}, {"text": "The shared sound pattern in the listed verbs motivates associative similarity. It is not evidence that every irregular verb uses exactly the same transformation.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 17}, "m3-review-p018": {"status": "ready", "blocks": [{"text": "**Rumelhart and McClelland modeled past tense as a learned association between present and past sound patterns.** A single trainable network learns across verbs instead of applying a separately specified -ed rule.", "children": ["The model encodes a root's phonology, transforms that representation through modifiable connections, and decodes an output pattern."]}, {"text": "Regularity is a pattern learned from many examples. Irregular forms are also learned within the same system.", "children": []}, {"text": "The fixed encoding and decoding stages surround a modifiable pattern associator. Wickelfeatures represent sound patterns, while the trainable connections store the learned mapping.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 18}, "m3-review-p019": {"status": "ready", "blocks": [{"text": "**U-shaped learning describes an initial success, a decline, and later recovery.** A child may correctly say RAN, later produce RUNNED, and eventually return to RAN.", "children": ["The middle error is a **regularization**, because the child applies the common past-tense pattern to an irregular verb."]}, {"text": "The decline does not necessarily mean that the child has stopped learning. A changing system can generalize more broadly while temporarily disrupting an earlier correct response.", "children": []}, {"text": "The vertical dimension is successful performance and the horizontal dimension is development or training. A U shape concerns accuracy over time, not the shape of a word.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 19}, "m3-review-p020": {"status": "ready", "blocks": [{"text": "**The Words and Rules account explains U-shaped learning through changes in the use of rules and lexical exceptions.** Early correct forms can be imitated before a productive rule is available.", "children": ["When the rule is learned, it can be applied too broadly, yielding RUNNED. Later, learned irregulars and the blocking process prevent that regularization."]}, {"text": "This account treats the developmental stages as involving distinguishable processes rather than only gradual changes in one mapping.", "children": []}, {"text": "Blocking means that retrieval of the appropriate irregular prevents the otherwise available regular form. It is a proposed mechanism, not merely another name for correct performance.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 20}, "m3-review-p021": {"status": "ready", "blocks": [{"text": "**Changing the training vocabulary can produce U-shaped learning in one network.** Early training emphasizes frequent irregular verbs, allowing those particular mappings to be learned.", "children": ["As more regular verbs enter training, their common pattern changes the network's responses. That generalization can interfere with previously learned irregulars."]}, {"text": "With further learning, the network can recover the irregular responses while retaining broad regularity. No new symbolic rule component is inserted at the point of decline.", "children": []}, {"text": "The lower plot contrasts correct irregular responses with regularized alternatives. Their changing strengths illustrate competition during training, rather than the sudden appearance of a separate rule box.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 21}, "m3-review-p022": {"status": "ready", "blocks": [{"text": "**Testing untrained verbs asks whether the network learned transferable structure.** A real English verb can be novel to a model if it was excluded from that model's training set.", "children": ["The test therefore uses the logic of a wug task even when the items are real words to humans."]}, {"text": "The model can generate many appropriate past-tense features, but feature-level success must be distinguished from producing an entirely correct word.", "children": []}, {"text": "The summary reports proportions of Wickelfeatures generated correctly. A high proportion of correct features does not imply that the same proportion of whole words was pronounced perfectly.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 22}, "m3-review-p023": {"status": "ready", "blocks": [{"text": "**Some model outputs contain changes that are unlike ordinary human regularizations.** Examples include MADE(D)-like changes to MATE and the unusual outputs MEMBLED for MAIL and TOUREDER for TOUR.", "children": ["The model authors acknowledge that people are unlikely to make some of these errors. They suggest that additional output constraints could reduce bizarre responses."]}, {"text": "This separates capturing an overall learning pattern from matching the detailed form of human errors.", "children": []}, {"text": "The quotation discusses outputs near threshold and a possible cleanup mechanism. That proposed mechanism is an explanation to be tested, not a repair already demonstrated by the quoted result.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 23}, "m3-review-p024": {"status": "ready", "blocks": [{"text": "**Joanisse and Seidenberg propose that phonology supports rule-like generalization while semantics especially supports irregular forms.** The same system links speech input, meaning and speech output.", "children": ["Reliable sound representations support extension from familiar present–past pairs to new forms. Irregular mappings receive additional support from the particular word's semantic representation."]}, {"text": "The hypothesis concerns different degrees of dependence on shared systems, rather than a separate symbolic rule route for every regular response.", "children": []}, {"text": "The diagram connects speech input and semantics through learned mappings to speech output. Its components represent domains of information, not a list of regular and irregular words in separate boxes.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 24}, "m3-review-p025": {"status": "ready", "blocks": [{"text": "**The model aims to explain the dissociation between irregular and nonword past-tense performance.** These tasks differ in how much they depend on learned word-specific information and phonological generalization.", "children": ["A nonword has no familiar item-specific semantic history to support its inflection. A known irregular can require semantic support because its output is not well predicted by the dominant pattern."]}, {"text": "Manipulating phonological or semantic integrity tests whether these different dependencies can produce opposite impairment profiles.", "children": []}, {"text": "The target is a pattern of performance across item types. Drawing phonology and semantics in a diagram is not enough unless damaging them produces the relevant outcomes.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 25}, "m3-review-p026": {"status": "ready", "blocks": [{"text": "**The patient pattern associated here with Broca's aphasia includes especially poor nonword past-tense production.** These patients have left anterior injury and difficulty producing speech.", "children": ["Regular forms are also vulnerable, while irregular forms are relatively better in the displayed comparison. A novel BLICK must be transformed without relying on a familiar stored past tense."]}, {"text": "This motivates investigating phonological contributions to the apparent morphological deficit.", "children": []}, {"text": "The graph places nonword accuracy below regular and irregular accuracy. The irregular advantage over regulars is smaller than the nonword disadvantage, so these differences should not be treated as equally large.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 26}, "m3-review-p027": {"status": "ready", "blocks": [{"text": "**Other patient groups show a larger problem with irregular past-tense forms.** The material discusses Wernicke's and Alzheimer's patients and anomic patients with inferior or middle temporal injury.", "children": ["Their irregular performance is lower than their regular and nonword performance in the displayed comparison."]}, {"text": "This creates the other side of the dissociation and motivates examining the information that especially supports known irregular forms.", "children": []}, {"text": "The middle bar is the irregular condition, at roughly 60% correct, compared with higher regular and nonword scores. The diagnostic labels do not make every individual's performance identical.", "children": []}], "authorFile": "authoring/content/morphology.txt", "source": "review", "page": 27}, "m3-review-p028": {"status": "ready", "blocks": [{"text": "**The classical contrast associates Wernicke's aphasia with fluent but often poorly interpretable speech and Broca's aphasia with effortful, telegraphic speech.** The former can include neologisms, while the latter can omit grammatical particles and show word-order difficulty.", "children": ["This makes a lexical-versus-grammatical interpretation attractive. However, a descriptive syndrome is not itself a demonstration of an isolated processing module."]}, {"text": "Content words may be relatively preserved in telegraphic speech, while fluent speech can retain sentence-like structure without conveying a clear message.", "children": []}, {"text": "The quoted utterances contrast fluent but difficult-to-interpret output with short, effortful content-word sequences. The diagnostic terms summarize patterns rather than guaranteeing identical symptoms in every patient.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 28}, "m3-review-p029": {"status": "ready", "blocks": [{"text": "**Broca's original patients are not necessarily straightforward examples of what is now called Broca's aphasia.** Profound inability to articulate speech can reflect motor-planning impairment rather than a selective grammatical deficit.", "children": ["**Apraxia of speech** concerns planning or coordinating speech movements. That differs from explaining an omission of grammatical structure in otherwise producible speech."]}, {"text": "The historical label therefore should not substitute for a precise description of the impaired behavior.", "children": []}, {"text": "The case description emphasizes extremely restricted spoken output despite some preserved understanding. It motivates examining speech production at multiple levels rather than locating grammar from the name alone.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 29}, "m3-review-p030": {"status": "ready", "blocks": [{"text": "**A grammar–lexicon distinction makes the classical aphasia contrast theoretically appealing.** A grammatical system combines forms, while lexical knowledge concerns words and their properties.", "children": ["Chomsky's example of a grammatical but semantically unusual sentence shows that syntactic well-formedness cannot be reduced to whether a sentence describes a sensible event."]}, {"text": "That conceptual distinction does not establish a simple one-to-one mapping from each syndrome to one isolated component.", "children": []}, {"text": "“Colorless green ideas sleep furiously” contrasts with an order that violates English syntax. The example isolates grammatical organization from familiarity or ordinary plausibility.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 30}, "m3-review-p031": {"status": "ready", "blocks": [{"text": "**The functional level selects word meanings and semantic roles, while the positional level organizes word forms into a grammatical sequence.** Phonological encoding and articulation concern later aspects of producing the utterance.", "children": ["A **lemma** is a representation involved in lexical selection, distinct from simply executing its sound pattern. Positional processing contributes ordering and morphological structure."]}, {"text": "Combinations such as HOUSEBOAT show that complex-word meaning can be partly compositional. Errors such as “easy enoughly” provide evidence about the organization of morphological operations.", "children": []}, {"text": "The diagram runs from message-level conceptual preparation through functional and positional levels to phonological encoding and speech gestures. Its order represents a processing proposal, not a direct picture of separate brain locations.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 31}, "m3-review-p032": {"status": "ready", "blocks": [{"text": "**Egocentric spatial descriptions use the speaker's position and orientation.** Left, right, in front and behind are familiar examples for nearby objects.", "children": ["Tzeltal commonly uses absolute directions in circumstances where English speakers might use these relative terms."]}, {"text": "The contrast motivates asking whether habitual language use relates to nonverbal spatial coding, rather than merely comparing two ways of giving spoken directions.", "children": []}, {"text": "The language comparison concerns preferred spatial descriptions. It does not imply that speakers of either language are incapable of learning another frame.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 32}, "m3-review-p033": {"status": "ready", "blocks": [{"text": "**Tzeltal's uphill and downhill terms function as an absolute directional system.** Their historical connection to a slope does not mean that each use simply points to the nearest visible hill.", "children": ["A direction is retained as a stable spatial reference rather than being recalculated from the speaker's current left and right."]}, {"text": "This allows positions to be described consistently as the speaker changes orientation.", "children": []}, {"text": "The contrast is with a description that depends entirely on the current viewpoint. The relevant feature is how the reference behaves across changes in location and orientation.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 33}, "m3-review-p034": {"status": "ready", "blocks": [{"text": "**The chips task separates relative from absolute spatial memory by rotating the participant 180 degrees.** A participant sees a configuration, waits, and then chooses its match at a second table.", "children": ["A relative response preserves the arrangement with respect to the person's viewpoint. An absolute response preserves its orientation in the environment, so the two responses diverge after rotation."]}, {"text": "Dutch speakers predominantly gave relative responses, while Tzeltal speakers gave more absolute responses. The association is consistent with their preferred linguistic frames but does not isolate language from all other experience.", "children": []}, {"text": "The north arrow stays fixed while the person changes orientation. Red bars represent relative choices and blue bars absolute choices, showing different response distributions across the two language groups.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 34}, "m3-review-p035": {"status": "ready", "blocks": [{"text": "**Spatial inference can combine relations learned in different displays.** Participants learn the relation between two objects, rotate to another display, and learn a second relation involving a shared object.", "children": ["They then place an object relative to another using the combined information. Relative and absolute coding lead to different placements because the person's orientation has changed."]}, {"text": "Dutch and Tzeltal response patterns again differ in the direction associated with their preferred spatial frames.", "children": []}, {"text": "The cube appears in both learning displays, linking the cone and cylinder relations. The final placement distinguishes a viewer-relative inference from one preserving environmental direction.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 35}, "m3-review-p036": {"status": "ready", "blocks": [{"text": "**Testing conditions could contribute to the apparent language-group difference.** Li and Gleitman noted that Tzeltal participants had been tested with visible, familiar outdoor landmarks, unlike many laboratory participants.", "children": ["An environment with useful landmarks can encourage landmark-based coding. A windowless laboratory can make viewer-relative descriptions more convenient."]}, {"text": "Manipulating landmark availability within English speakers tests whether the behavior can change without changing native language.", "children": []}, {"text": "The critical contrast is access to spatial cues, not simply the label “laboratory.” Windows, outdoor views and familiar surroundings can alter which references are useful.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 36}, "m3-review-p037": {"status": "ready", "blocks": [{"text": "**English speakers' preference for relative coding weakened when external landmarks were available.** They strongly preferred relative responses with the blinds down, but the preference was less pronounced with a street view or outdoors.", "children": ["The manipulation changes the spatial information available while keeping the language group the same."]}, {"text": "This demonstrates that task context can influence the response. It challenges an explanation in which language alone fixes the chosen frame.", "children": []}, {"text": "A reduced relative preference is not necessarily a complete switch to absolute coding. Describe the observed change in preference without exaggerating it into an all-or-none reversal.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 37}, "m3-review-p038": {"status": "ready", "blocks": [{"text": "**Levinson and colleagues argued that the simplified task could make the experimenter's purpose too obvious.** Low memory demands and short time or distance between displays may encourage a deliberate strategy about rotation.", "children": ["Participants who infer what is being tested can alter their response for reasons different from habitual spatial coding."]}, {"text": "The response therefore focuses on memory load and task transparency, rather than denying that landmarks can ever matter.", "children": []}, {"text": "The proposed alternative is a demand-characteristic explanation. Participants' interpretation of the experiment may influence the response independently of their normal coding preference.", "children": []}], "authorFile": "authoring/content/thought.txt", "source": "review", "page": 38}, "m3-review-p039": {"status": "ready", "blocks": [{"text": "**Categorical perception can be tested by varying a sign feature continuously.** The hand-configuration continuum moves between forms while the observer's identification and discrimination responses are measured.", "children": ["One continuum crosses a phonemic distinction between PLEASE and SORRY. The allophonic comparison varies hand configuration without the same change in sign identity."]}, {"text": "A sharp identification boundary accompanied by better discrimination near that boundary would indicate category-sensitive perception.", "children": []}, {"text": "The stimulus sequences progress through intermediate hand configurations. Comparing equal-sized changes within and across a linguistic boundary is more informative than comparing only the two endpoints.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 39}, "m3-review-p040": {"status": "ready", "blocks": [{"text": "**Deaf signers show a sharper categorical boundary for phonemic than allophonic hand-configuration changes.** In the phonemic condition, identification shifts steeply around stimuli 4–6.", "children": ["Discrimination is also strongest near the phonemic boundary. Comparable physical steps are easier to distinguish when they cross that category boundary."]}, {"text": "The allophonic identification function is shallower and lacks the same localized discrimination peak. This links the perceptual pattern to linguistic contrast rather than any visible hand change.", "children": []}, {"text": "The top plots show categorization and the lower plots discrimination. Compare the position of the steep change with the discrimination peak in the phonemic column.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 40}, "m3-review-p041": {"status": "ready", "blocks": [{"text": "**Signed-language comprehension recruits classical language regions and shows left lateralization, as spoken-language comprehension does.** Inferior frontal and posterior superior temporal regions are part of this overlap.", "children": ["Signing also engages visual and superior parietal regions relevant to its perceptual and spatial demands."]}, {"text": "The combination suggests both common language organization and modality-related contributions. Similarity does not require identical activation everywhere.", "children": []}, {"text": "The figure compares deaf signers, hearing signers and hearing audiovisual-speech participants. Hearing signers are particularly useful because signing experience is not restricted to people who are deaf.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 41}, "m3-review-p042": {"status": "ready", "blocks": [{"text": "**Signed languages have linguistic form, grammar and language-related neural organization.** Contrastive sign features can produce categorical perception, and comprehension recruits posterior superior temporal language regions.", "children": ["Signing experience is associated with changes in motion lateralization. Deafness is associated with enhanced peripheral attention in the reported comparison."]}, {"text": "These findings jointly show that linguistic experience and sensory history contribute in different ways.", "children": []}, {"text": "The summary combines behavioral category evidence, group comparisons and neural contrasts. Each addresses a different question, so one result should not be used as if it established all the others.", "children": []}], "authorFile": "authoring/content/modalities.txt", "source": "review", "page": 42}, "m3-review-p043": {"status": "ready", "blocks": [{"text": "**The exercise hypothesis proposes that early language use preserves language-learning capacity, while the maturational-state hypothesis allows capacity to decline despite early use.** Both assume an early advantage, but they differ in what early successful experience protects.", "children": ["Later second-language difficulty in people who already acquired a first language is more directly compatible with maturation than with complete preservation through exercise."]}, {"text": "This does not make early first-language experience unimportant. Early access and age-related change address related but distinct questions.", "children": []}, {"text": "The two text panels differ in the condition attached to decline. The exercise account includes preservation through use, while the maturational-state account predicts decline with maturation itself.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 43}, "m3-review-p044": {"status": "ready", "blocks": [{"text": "**Mayberry, Lock and Kazmi compared later language learning after different early-language histories.** Deaf individuals without accessible early language performed worse than those who had acquired an early spoken or signed language.", "children": ["Children first exposed to ASL at ages 9–15 had particular difficulty when it was also their first language. Those who had first learned a spoken language did much better, and the differences persisted."]}, {"text": "The comparison distinguishes late first-language learning from late acquisition of an additional language.", "children": []}, {"text": "The bars separate no-early-language groups from early spoken or signed language groups. The contrast concerns access to language, not a simple superiority of speech over signing.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 44}, "m3-review-p045": {"status": "ready", "blocks": [{"text": "**Semantic blocking effects must be separated from visual-recognition difficulty.** Objects from one semantic category could resemble one another visually, creating a potential confound in naming.", "children": ["The materials were normed so that same-category items were not more visually similar on average. A separate visual-similarity manipulation also produced a different time course."]}, {"text": "Visual blocking affected the first block, whereas the semantic pattern of interest developed differently. This weakens a purely visual explanation.", "children": []}, {"text": "The comparison concerns when interference appears across repetitions. A difference in time course helps distinguish visual recognition from the proposed lexical contribution.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 45}, "m3-review-p046": {"status": "ready", "blocks": [{"text": "**Belke and colleagues presented four objects simultaneously but required their names in sequence.** This tests whether the absence of an effect in another simultaneous-display study depended on presentation format.", "children": ["Displaying all objects at once reduces dependence on a succession of isolated pictures. Serial naming still requires selecting and producing one label after another."]}, {"text": "Eye tracking provides additional timing information about the processing of each object.", "children": []}, {"text": "The four pictured animals are visible together. The instruction concerns producing their names in order, rather than choosing only one target from the display.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 46}, "m3-review-p047": {"status": "ready", "blocks": [{"text": "**Eye movements and speech onsets provide different timing measures during serial naming.** Gaze duration records how long the eyes remain on an object, while eye–speech lag concerns the interval between leaving it and beginning its spoken name.", "children": ["A participant can move the eyes toward the next object before articulating the current one. The measures therefore separate overlapping parts of preparation."]}, {"text": "Different blocking effects on these measures can help constrain the processing stage affected.", "children": []}, {"text": "The GD boxes represent gaze durations and the lag boxes extend toward articulatory onset. The timeline shows why looking at an object and speaking its name are not the same event.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 47}, "m3-review-p048": {"status": "ready", "blocks": [{"text": "**Semantic blocking increases gaze duration after the first presentation cycle, but not overall speech duration or eye–speech lag.** The measures therefore do not show a uniform slowdown.", "children": ["Speech duration decreases with repetition without a blocking difference. Gaze duration shows the condition difference after the first cycle."]}, {"text": "The nonsignificant lag difference should not be reported as evidence for a reversed effect. The reported pattern is interpreted as supporting a contribution at lemma selection rather than articulation or phonological encoding.", "children": []}, {"text": "HOM and HET compare homogeneous and heterogeneous contexts. The three panels correspond to speech duration, gaze duration and lag, so their vertical scales describe different measurements.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 48}, "m3-review-p049": {"status": "ready", "blocks": [{"text": "**McMurray and colleagues tested whether fine phonetic information affects lexical competition.** Participants heard a /b/–/p/ continuum while viewing pictures including BEAR and PEAR, with eye movements recorded.", "children": ["**Voice onset time**, or VOT, varies the timing between release and voicing. It can change how strongly the sound supports /b/ or /p/."]}, {"text": "A thresholded account would pass a completed categorical decision onward. A cascaded account allows graded information to influence word candidates before uncertainty is fully resolved.", "children": []}, {"text": "The visual-world display includes a target, a phonetic competitor and unrelated fillers. Looking at the competitor is informative because its name overlaps with the heard word near the manipulated contrast.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 49}, "m3-review-p050": {"status": "ready", "blocks": [{"text": "**Participants selected the picture that best matched the spoken item.** Their BEAR–PEAR choices produced a typical step-like identification function across VOT.", "children": ["Shorter VOTs favored the /b/ response and longer VOTs the /p/ response. Near the boundary, the preferred category changed rapidly."]}, {"text": "A categorical-looking final response does not establish that all earlier lexical activation was categorical.", "children": []}, {"text": "The horizontal axis is VOT in milliseconds and the vertical axis is proportion of /p/ responses. The steep transition is around 17.5 ms in the displayed function.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 50}, "m3-review-p051": {"status": "ready", "blocks": [{"text": "**Competitor looks vary with phonetic ambiguity even within a chosen category.** Tokens closer to the /b/–/p/ boundary produce more competition than clear tokens farther from it.", "children": ["A participant can ultimately select BEAR while spending more time looking at PEAR when the sound is close to the boundary."]}, {"text": "This supports the claim that fine phonetic information remains relevant to lexical activation, rather than disappearing completely after a categorical phoneme decision.", "children": []}, {"text": "The gaze curves group trials by VOT and final response. The effect concerns looks to the unchosen competitor, not merely how often participants click the wrong picture.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 51}, "m3-review-p052": {"status": "ready", "blocks": [{"text": "**Competitor fixation increases as a token approaches the category boundary from either side.** For BEAR responses, more /p/-like VOT increases looks to PEAR. For PEAR responses, more /b/-like VOT increases looks to BEAR.", "children": ["The graph separates early and late observation windows. The gradient remains visible in the later competition measure, supporting continued sensitivity to within-category phonetic detail."]}, {"text": "The result favors cascaded use of graded evidence over a model that transmits only a completed phoneme label with all within-category detail discarded.", "children": []}, {"text": "The left and right halves plot different final-response categories and their corresponding competitors. Early is 300–1100 ms and late is 1100–1900 ms, so the line types distinguish time windows rather than two participant groups.", "children": []}], "authorFile": "authoring/content/review.txt", "source": "review", "page": 52}}}], "questions": [{"id": "m3-q001", "module": "reading1", "section": "m3-reading1-p003", "kind": "Apply and explain", "stem": "A learner pronounces COLONEL by applying common letter–sound correspondences and gets the familiar word wrong. What does this illustrate?", "choices": ["A deep orthography can make general decoding conflict with a word's learned pronunciation.", "A phoneme is defined by whichever letter appears in its spelling.", "A shallow orthography prevents the pronunciation of unfamiliar words.", "A lexical entry is unnecessary whenever the letters are familiar."], "correct": 0, "why": "The letters support a plausible decoding that conflicts with the exception word. Orthographic depth concerns the predictability of spelling–sound mappings."}, {"id": "m3-q002", "module": "reading1", "section": "m3-reading1-p005", "kind": "Apply and explain", "stem": "Why are pseudowords useful when comparing children's decoding across writing systems?", "choices": ["They require generalization beyond a stored pronunciation for that particular word.", "They remove the need to know the writing system's spelling patterns.", "They measure word meaning while holding pronunciation constant.", "They guarantee that all language groups face identical task difficulty."], "correct": 0, "why": "A novel item cannot be read by retrieving its own familiar lexical entry. Performance therefore reveals how learned spelling–sound knowledge generalizes."}, {"id": "m3-q003", "module": "reading1", "section": "m3-reading1-p010", "kind": "Apply and explain", "stem": "Readers accept both /strɛd/ and /strid/ for STREAD. What must a model explain?", "choices": ["How competing spelling–sound patterns can support more than one plausible response.", "Why every novel spelling retrieves two previously memorized lexical entries.", "Why phonological representations are irrelevant to unfamiliar words.", "How semantic context forces one pronunciation on all trials."], "correct": 0, "why": "The ambiguity reflects multiple learned pronunciation patterns. It challenges a simple account that assumes each spelling pattern has only one acceptable categorical output."}, {"id": "m3-q004", "module": "reading1", "section": "m3-reading1-p014", "kind": "Apply and explain", "stem": "Which connection implements top-down support in the Interactive Activation Model?", "choices": ["An activated word increases activation of its constituent letters.", "A visual stroke activates a compatible letter feature.", "A spoken response is executed by the articulators.", "An unfamiliar word is assigned a dictionary meaning."], "correct": 0, "why": "Word-to-letter feedback allows whole-word context to help resolve ambiguous letter information. Bottom-up feature activation is a different direction of information flow."}, {"id": "m3-q005", "module": "reading1", "section": "m3-reading1-p016", "kind": "Apply and explain", "stem": "Why analyze frequency alongside length and other properties in multiple regression?", "choices": ["To test whether frequency predicts reaction time beyond those correlated properties.", "To make frequency experimentally randomized for every word.", "To eliminate all individual differences between readers.", "To convert a continuous response time into a categorical diagnosis."], "correct": 0, "why": "Statistical control addresses the proposed confound that frequency merely stands in for properties such as length. It does not turn the observational dataset into a randomized experiment."}, {"id": "m3-q006", "module": "reading1", "section": "m3-reading1-p017", "kind": "Apply and explain", "stem": "Which pattern demonstrates a frequency-by-regularity interaction?", "choices": ["The regularity cost is larger for low-frequency than high-frequency words.", "Exception words are slower by the same amount at both frequency levels.", "All high-frequency words have the same reaction time.", "Regularity changes accuracy but never changes naming time."], "correct": 0, "why": "An interaction means the effect of one factor depends on the other. A constant regularity cost would be an additive effect instead."}, {"id": "m3-q007", "module": "reading1", "section": "m3-reading1-p018", "kind": "Apply and explain", "stem": "Under the dual-route interpretation, why are high-frequency exceptions less disrupted by decoding?", "choices": ["Fast lexical processing supplies the learned pronunciation before competing decoding has much influence.", "Frequent exposure converts every irregular spelling into a categorical GPC rule.", "The reader no longer processes any letters in familiar words.", "The sublexical route gains direct access to the word's meaning."], "correct": 0, "why": "The explanation attributes the reduced interference to efficient word-specific processing. It does not change the GPC system into a semantic or exception-retrieval system."}, {"id": "m3-q008", "module": "reading1", "section": "m3-reading1-p019", "kind": "Apply and explain", "stem": "A patient reads familiar words well but struggles especially with pseudowords after injury. Which pattern is this?", "choices": ["Acquired phonological dyslexia.", "Acquired surface dyslexia.", "A pure semantic-memory advantage.", "A developmental effect established before injury."], "correct": 0, "why": "The defining relative weakness is novel-form decoding after brain injury. Surface dyslexia instead especially affects exception-word pronunciation."}, {"id": "m3-q009", "module": "reading1", "section": "m3-reading1-p020", "kind": "Apply and explain", "stem": "Which error best illustrates regularization in surface dyslexia?", "choices": ["Pronouncing SHOE like SHOW.", "Failing to name every visible letter.", "Substituting a word with a similar meaning.", "Correctly pronouncing an unfamiliar pseudoword."], "correct": 0, "why": "The response follows a plausible spelling pattern but misses the actual word's exceptional pronunciation. That systematic error differs from a semantic substitution."}, {"id": "m3-q010", "module": "reading1", "section": "m3-reading1-p021", "kind": "Apply and explain", "stem": "What is the strongest conclusion supported by opposite pseudoword and exception-word impairments?", "choices": ["The tasks depend differently on underlying processes, which competing models must explain.", "The evidence uniquely proves every detail of the DRC architecture.", "The relatively spared task must be completely normal in every patient.", "One task is simply harder for all readers under all conditions."], "correct": 0, "why": "A double dissociation challenges a single fixed difficulty ranking. It supports separable contributions without uniquely identifying their implementation."}, {"id": "m3-q011", "module": "reading2", "section": "m3-reading2-p004", "kind": "Apply and explain", "stem": "Where do the DRC's lexical and GPC outputs directly converge?", "choices": ["The phoneme response buffer.", "The semantic representation of the target.", "The rule system's frequency-learning component.", "The visual features before letter identification."], "correct": 0, "why": "The routes have separate internal processing assumptions but activate a shared output system, where incompatible pronunciations can compete."}, {"id": "m3-q012", "module": "reading2", "section": "m3-reading2-p006", "kind": "Apply and explain", "stem": "A GPC mapping is selected because it is common but then applies categorically. What distinction matters?", "choices": ["Statistics used to choose a rule are different from graded statistical influence during processing.", "Any use of frequency makes a model identical to a triangle model.", "Categorical processing requires that the designer never inspect words.", "A fixed rule must be equally accurate for every spelling neighborhood."], "correct": 0, "why": "The DRC can use typical correspondences without representing degrees of confidence among pronunciation alternatives during the conversion itself."}, {"id": "m3-q013", "module": "reading2", "section": "m3-reading2-p011", "kind": "Apply and explain", "stem": "Which claim is specifically about informational encapsulation?", "choices": ["The GPC procedure does not receive lexical feedback while it computes.", "The model contains more than one labeled component.", "The response buffer contains phoneme units.", "The input to reading is a written stimulus."], "correct": 0, "why": "Encapsulation restricts access to information. Multiple components, domain-specific inputs and particular representations are related but distinct properties."}, {"id": "m3-q014", "module": "reading2", "section": "m3-reading2-p014", "kind": "Apply and explain", "stem": "Why can a triangle model show a larger cost for low-frequency exceptions?", "choices": ["They have weak item-specific learning and conflict with patterns learned across other words.", "It gives each exception a separate symbolic rule that runs more slowly.", "It disables the phonological system whenever word frequency is low.", "It stores no information about familiar irregular spellings."], "correct": 0, "why": "Frequency strengthens learning for the item, while consistency provides support from other items. Their combination can produce the interaction without separate rule and frequency mechanisms."}, {"id": "m3-q015", "module": "reading2", "section": "m3-reading2-p017", "kind": "Apply and explain", "stem": "Nonword performance improves after replacing poor phonological representations. What does this establish most directly?", "choices": ["Part of the initial failure depended on the implementation's representation of sound similarity.", "A separate symbolic nonword route has been proven necessary.", "All possible associative reading theories are now confirmed.", "The original model's low accuracy was not a genuine problem."], "correct": 0, "why": "Changing representations while retaining the general learning approach helps distinguish a representational weakness from a failure of the whole theoretical proposal."}, {"id": "m3-q016", "module": "reading2", "section": "m3-reading2-p020", "kind": "Apply and explain", "stem": "What did the phonological-noise simulation manipulate and what was the key outcome?", "choices": ["It degraded phonological representations and disproportionately impaired nonword decoding.", "It removed semantics and improved exception reading.", "It increased word frequency and eliminated all reading errors.", "It changed the alphabet and measured participants' visual attention."], "correct": 0, "why": "Nonwords rely heavily on generalization through sound representations, so degraded phonology can hurt them more than familiar words without a dedicated nonword mechanism."}, {"id": "m3-q017", "module": "reading2", "section": "m3-reading2-p022", "kind": "Apply and explain", "stem": "Why is the triangle model not simply the DRC with renamed routes?", "choices": ["Its pathways share graded learning assumptions and interact during learning, with semantics directly involved.", "It contains only one arrow and no distinction between spelling and sound.", "It cannot represent information specific to a familiar word.", "It assumes that all patients perform perfectly on their spared task."], "correct": 0, "why": "The important differences concern learning, representation and interaction, not just the number of pathways in the diagram."}, {"id": "m3-q018", "module": "reading2", "section": "m3-reading2-p025", "kind": "Apply and explain", "stem": "Why are repeated observations in semantic dementia informative?", "choices": ["They test whether semantic and exception-reading abilities decline together within a person.", "They guarantee that all initial outliers must be measurement errors.", "They remove the need to measure semantic knowledge.", "They directly identify a single brain region for irregular words."], "correct": 0, "why": "Longitudinal trajectories help determine whether an apparent dissociation persists and whether the broader association holds during change."}, {"id": "m3-q019", "module": "reading2", "section": "m3-reading2-p026", "kind": "Apply and explain", "stem": "What limits the inference from selecting each patient's best match among 40,000 model runs?", "choices": ["A close fit obtained through extensive parameter selection is less constrained than a prospective prediction.", "The model's outputs cannot be compared numerically with patient scores.", "A good numerical fit is automatically evidence against the model.", "A simulation cannot model any condition involving brain damage."], "correct": 0, "why": "The issue is how much flexibility produced the agreement. Fit remains relevant, but selecting among many possibilities adds explanatory freedom."}, {"id": "m3-q020", "module": "reading2", "section": "m3-reading2-p030", "kind": "Apply and explain", "stem": "Which evidence particularly supports the triangle account's proposed underlying associations?", "choices": ["Nonword ability tracks phonology and exception-word ability tracks semantics.", "Pseudowords and exception words have different spellings.", "Every patient has exactly one damaged reading score.", "Frequency never affects any pronunciation in the model."], "correct": 0, "why": "The account predicts links to broader phonological and semantic abilities, extending the evidence beyond a reading-task dissociation alone."}, {"id": "m3-q021", "module": "morphology", "section": "m3-morphology-p003", "kind": "Apply and explain", "stem": "Why does producing WUGS support productive morphological knowledge?", "choices": ["The child applies plural knowledge to a form whose plural was not supplied.", "The child retrieves a frequently heard dictionary entry for WUGS.", "The drawing proves that children use a symbolic rule rather than learned patterns.", "The response tests the visual recognition of a familiar animal species."], "correct": 0, "why": "The novel item rules out simple retrieval of that particular learned plural. Both symbolic and statistical theories still need to explain the generalization."}, {"id": "m3-q022", "module": "morphology", "section": "m3-morphology-p005", "kind": "Apply and explain", "stem": "What does Words and Rules propose for regular and irregular past tense?", "choices": ["A productive symbolic operation for regulars and associative lexical knowledge for irregulars.", "A separate phoneme-identification system for each verb.", "The same categorical rule with no stored exceptional information.", "A distinction only in articulation, with identical prior processing."], "correct": 0, "why": "The theoretical separation concerns representation and computation. It is stronger than the descriptive observation that regular and irregular forms look different."}, {"id": "m3-q023", "module": "morphology", "section": "m3-morphology-p010", "kind": "Apply and explain", "stem": "Which sequence illustrates U-shaped learning?", "choices": ["RAN, then RUNNED, then RAN.", "RUNNED, then RUNNED, then RAN.", "RAN, then RAN, then RAN.", "RAN, then RAN, then RUNNED permanently."], "correct": 0, "why": "The sequence contains initial success, overregularization and later recovery. A simple monotonic improvement is not U-shaped."}, {"id": "m3-q024", "module": "morphology", "section": "m3-morphology-p012", "kind": "Apply and explain", "stem": "How does the associative model account for an intermediate rise in regularizations?", "choices": ["Expansion of regular verbs in training changes learned mappings and interferes with some early irregulars.", "A new symbolic rule box is inserted after the initial training stage.", "The model deletes every irregular verb from the training set permanently.", "The output system becomes independent of all prior learning."], "correct": 0, "why": "Changing the distribution of input reorganizes the network. U-shaped performance can arise without adding a separate rule mechanism at the point of decline."}, {"id": "m3-q025", "module": "morphology", "section": "m3-morphology-p013", "kind": "Apply and explain", "stem": "Why can a real verb be used in a model's generalization test?", "choices": ["It can be absent from that model's training set even if familiar to humans.", "Every real verb is automatically a pseudoword.", "The model is assumed to know the full English vocabulary before training.", "Only visually unfamiliar spellings can test morphological generalization."], "correct": 0, "why": "Novelty is relative to the learner's experience. Withholding a real verb lets the test examine transfer rather than recall of its trained response."}, {"id": "m3-q026", "module": "morphology", "section": "m3-morphology-p015", "kind": "Apply and explain", "stem": "What was the central concern about outputs such as MEMBLED for MAIL?", "choices": ["Overlapping feature patterns can blend alternatives into a malformed output.", "The model correctly discovered a common English irregular form.", "The model used too many independent symbolic grammar rules.", "Human children never generalize beyond memorized past tenses."], "correct": 0, "why": "The criticism concerns preserving coherent candidate forms when multiple patterns are active. Overall learning success does not excuse implausible error structures."}, {"id": "m3-q027", "module": "morphology", "section": "m3-morphology-p019", "kind": "Apply and explain", "stem": "Which pattern follows phonological damage in the Joanisse–Seidenberg account?", "choices": ["Nonword past tense is especially impaired, with familiar forms relatively better.", "Only irregular forms are impaired while all nonwords remain perfect.", "All item categories improve through added semantic support.", "Past-tense computation becomes independent of phonology."], "correct": 0, "why": "Novel forms depend heavily on phonological generalization. Familiar words can draw on item-specific learning, producing unequal effects of shared-system damage."}, {"id": "m3-q028", "module": "morphology", "section": "m3-morphology-p021", "kind": "Apply and explain", "stem": "Why does semantic impairment particularly affect irregular past tense?", "choices": ["Irregular mappings depend more on item-specific semantic support because general phonological patterns are less sufficient.", "Irregular words have no phonological representation at all.", "The manipulation explicitly deletes every irregular from a separate dictionary.", "Nonwords have stronger stored meanings than familiar verbs."], "correct": 0, "why": "The account attributes selective vulnerability to unequal dependence on semantic support, rather than assuming a dedicated exception store is removed."}, {"id": "m3-q029", "module": "morphology", "section": "m3-morphology-p022", "kind": "Apply and explain", "stem": "Why match regular and irregular items for phonological properties?", "choices": ["To test whether the apparent morphological difference partly reflects unequal sound-processing demands.", "To make the words equally frequent in every language.", "To remove semantics from the patients' language system.", "To ensure that all regular verbs become phonologically identical."], "correct": 0, "why": "A reduced difference after matching weakens a purely regular-versus-irregular mechanism explanation and highlights a potential phonological confound."}, {"id": "m3-q030", "module": "morphology", "section": "m3-morphology-p026", "kind": "Apply and explain", "stem": "What does the displayed SLI behavioral profile require an explanation to cover?", "choices": ["Poor performance across forms, with nonwords especially impaired.", "Normal irregular accuracy and no impairment outside regulars.", "An advantage for novel forms over all familiar forms.", "Perfect regular performance but an isolated semantic deficit."], "correct": 0, "why": "The graph shows broad impairment rather than fully spared irregulars. A rule-deficit account must be tested against the whole profile, not only the nonword cost."}, {"id": "m3-q031", "module": "thought", "section": "m3-thought-p005", "kind": "Apply and explain", "stem": "A person turns around but the ball remains north of the chair. Which frame stays fixed?", "choices": ["An absolute frame.", "A viewer-relative left–right frame.", "A frame defined only by the observer's gaze.", "A frame that treats every direction as interchangeable."], "correct": 0, "why": "Absolute directions do not reverse with the observer's orientation. Relative left and right can change when the person turns."}, {"id": "m3-q032", "module": "thought", "section": "m3-thought-p009", "kind": "Apply and explain", "stem": "Why rotate participants in the chips task?", "choices": ["To make preserving viewer-relative orientation and preserving environmental orientation predict different choices.", "To prevent participants from seeing any response options.", "To test whether they know the names of the objects.", "To guarantee that any language-group difference is caused by grammar."], "correct": 0, "why": "Rotation separates the predictions of two frames. It makes response choice diagnostic of preferred coding, but does not eliminate all group-level confounds."}, {"id": "m3-q033", "module": "thought", "section": "m3-thought-p012", "kind": "Apply and explain", "stem": "What does a change in English speakers' spatial choices when blinds are raised show?", "choices": ["The available environment can influence frame preference within one language group.", "Native language never influences cognition in any task.", "English speakers lack the capacity for relative coding.", "The linguistic categories of English changed during the experiment."], "correct": 0, "why": "The manipulation supports a contextual contribution and identifies a potential confound. It does not establish that language is irrelevant everywhere."}, {"id": "m3-q034", "module": "thought", "section": "m3-thought-p016", "kind": "Apply and explain", "stem": "Why add an animal, extend the delay and separate the tables more in the Dutch study?", "choices": ["To increase memory demands and reduce transparency of the rotation manipulation.", "To eliminate memory and make the expected answer obvious.", "To teach participants new absolute-direction vocabulary.", "To change the study into a test of color discrimination."], "correct": 0, "why": "The modifications address the concern that an easy, transparent task encourages strategic responses. The relative preference remained under the revised conditions."}, {"id": "m3-q035", "module": "thought", "section": "m3-thought-p018", "kind": "Apply and explain", "stem": "Why does remembering “lion, tiger, bear” complicate interpretation of a spatial-memory task?", "choices": ["A verbal sequence reconstructed left-to-right can produce a relative-looking answer.", "It proves that participants cannot form any spatial representation.", "It makes the task independent of working memory.", "It guarantees that all absolute responses must be errors."], "correct": 0, "why": "The same response can arise from verbal recoding rather than a purely spatial memory format. Nonverbal response options do not prevent internal language use."}, {"id": "m3-q036", "module": "thought", "section": "m3-thought-p021", "kind": "Apply and explain", "stem": "What is manipulated in the spatial-priming experiment before temporal judgments?", "choices": ["Whether the preceding spatial task uses horizontal or vertical relations.", "Whether the participant's native language is changed by random assignment.", "Whether an event objectively happened in the past or future.", "Whether participants have ever learned to read."], "correct": 0, "why": "The prime temporarily activates a spatial relation. Different reaction-time effects on the temporal task test compatibility with the subsequent processing."}, {"id": "m3-q037", "module": "thought", "section": "m3-thought-p022", "kind": "Apply and explain", "stem": "Why consider writing direction when interpreting language-group differences about time?", "choices": ["Literacy experience can organize sequences spatially and covary with language group.", "Writing direction is identical for every reader of every language.", "Temporal metaphors cannot occur in spoken language.", "A reading habit directly determines which events occurred first."], "correct": 0, "why": "Reading direction offers an alternative source of spatial experience. It must be separated from the proposed effect of habitual temporal language."}, {"id": "m3-q038", "module": "thought", "section": "m3-thought-p023", "kind": "Apply and explain", "stem": "What does excluding readers who report top-to-bottom reading address?", "choices": ["A specific explanation based on that reported vertical-reading experience.", "Every possible cultural and experiential confound simultaneously.", "Whether Mandarin has any vertical temporal expressions.", "Whether the participants can understand earlier–later relations."], "correct": 0, "why": "A targeted exclusion weakens a particular alternative when the effect persists. Its scope should not be inflated into proof that no other confound exists."}, {"id": "m3-q039", "module": "thought", "section": "m3-thought-p025", "kind": "Apply and explain", "stem": "Why is the mirror-reading result important?", "choices": ["A short-term change in reading experience can reverse spatial–temporal compatibility.", "It shows that native-language grammar permanently changes within minutes.", "It proves that all past–future judgments require conscious spatial imagery.", "It shows that participants no longer distinguish past from future."], "correct": 0, "why": "The response mapping changes after reversed reading experience. That supports flexible experiential contributions rather than a wholly fixed native-language explanation."}, {"id": "m3-q040", "module": "thought", "section": "m3-thought-p002", "kind": "Apply and explain", "stem": "A group difference shows a preferred coding strategy. Which conclusion goes beyond that evidence?", "choices": ["The speakers are incapable of thinking using any alternative code.", "The groups differ in response distributions on the task.", "Habitual experience is a possible contributor to the difference.", "Alternative explanations should be considered before inferring causality."], "correct": 0, "why": "A preference is not an inability. Strong linguistic determinism requires more than a difference in how frequently groups choose one response."}, {"id": "m3-q041", "module": "modalities", "section": "m3-modalities-p002", "kind": "Apply and explain", "stem": "Which distinction between signing and Braille is correct?", "choices": ["Signed languages are natural languages, while Braille is a tactile writing system.", "Braille is a signed language with its own independent grammar.", "Signing is only a visual spelling system for spoken words.", "Both are nonlinguistic gestures without structured representations."], "correct": 0, "why": "Their linguistic status differs even though both inform questions about modality and plasticity. A change in reading input is not the same as a different natural language."}, {"id": "m3-q042", "module": "modalities", "section": "m3-modalities-p007", "kind": "Apply and explain", "stem": "Which joint result supports categorical perception for a sign contrast?", "choices": ["A steep identification boundary and enhanced discrimination near that boundary.", "Identical discrimination at every point with no identification change.", "Better recognition of only the first and last pictures regardless of category.", "A category label supplied after every trial without a discrimination measure."], "correct": 0, "why": "The alignment of identification and discrimination relates perceptual sensitivity to a linguistic boundary, rather than merely documenting a physical continuum."}, {"id": "m3-q043", "module": "modalities", "section": "m3-modalities-p010", "kind": "Apply and explain", "stem": "Why include hearing signers in the attention experiment?", "choices": ["To distinguish effects associated with signing experience from effects associated with deafness.", "To ensure every participant has the same auditory history.", "To remove all visual experience from the hearing comparison.", "To replace the need for a hearing nonsigning control group."], "correct": 0, "why": "Hearing signers share signing experience with deaf signers while differing in auditory status. This helps separate two factors otherwise confounded."}, {"id": "m3-q044", "module": "modalities", "section": "m3-modalities-p011", "kind": "Apply and explain", "stem": "Which reported pattern separates signing experience from deafness?", "choices": ["Both signer groups show a lateralization change, but enhanced peripheral attention is specific to deaf participants.", "Only hearing signers show any change in motion processing.", "Every group has identical lateralization and peripheral attention.", "All signers show the same peripheral advantage regardless of hearing."], "correct": 0, "why": "The two outcomes track different experiences. Treating them as a single general visual advantage would miss the key comparison."}, {"id": "m3-q045", "module": "modalities", "section": "m3-modalities-p012", "kind": "Apply and explain", "stem": "Why compare sign comprehension with tic-tac gestures?", "choices": ["To control some organized hand-movement demands while contrasting linguistic status.", "To compare signing with a stimulus containing no movement.", "To prove that tic-tac has the same grammar as a natural language.", "To remove all meaningful information from the control condition."], "correct": 0, "why": "The control shares visible, sequenced gestures. A remaining difference is more informative than comparing signing only with no activity."}, {"id": "m3-q046", "module": "modalities", "section": "m3-modalities-p013", "kind": "Apply and explain", "stem": "Which finding is central to the sign-versus-tic-tac neural comparison?", "choices": ["Stronger posterior temporal language-region activity for sign language.", "Complete absence of visual processing during signing.", "Exclusive activation of one precisely identified Broca's point.", "Equal activity in every region for the two gesture systems."], "correct": 0, "why": "The posterior temporal contrast supports a linguistic contribution beyond organized hand movement. The frontal activation should not simply be relabeled as classic Broca's area."}, {"id": "m3-q047", "module": "modalities", "section": "m3-modalities-p017", "kind": "Apply and explain", "stem": "What does the early- versus late-blind comparison suggest?", "choices": ["The timing of visual loss relates to the extent of visual-cortex recruitment for Braille.", "Visual cortex can only respond to visual stimuli.", "Late-blind readers cannot learn any tactile symbols.", "The study randomly assigned people to lifelong blindness."], "correct": 0, "why": "The reported association concerns developmental sensory history. It does not make the between-group comparison a randomized manipulation of blindness onset."}, {"id": "m3-q048", "module": "modalities", "section": "m3-modalities-p018", "kind": "Apply and explain", "stem": "What additional manipulation distinguishes the Merabet blindfolded group from controls?", "choices": ["Continuous removal of visual input during a five-day period with Braille training.", "Training in a completely different natural language.", "Permanent destruction of visual cortex.", "A test requiring only recognition of printed letters."], "correct": 0, "why": "Both training and sensory competition matter. The blindfold manipulation tests what changes when vision is temporarily unavailable in sighted adults."}, {"id": "m3-q049", "module": "modalities", "section": "m3-modalities-p019", "kind": "Apply and explain", "stem": "Why is reversal after blindfold removal mechanistically informative?", "choices": ["It is consistent with rapid functional unmasking and changing competition among existing inputs.", "It requires that a new permanent brain region formed during training.", "It demonstrates that no learning occurred during blindfolding.", "It proves tactile processing is unrelated to visual-cortex activity."], "correct": 0, "why": "The rapid, reversible time course constrains explanations and fits altered contributions of available inputs better than assuming permanent new organization alone."}, {"id": "m3-q050", "module": "modalities", "section": "m3-modalities-p020", "kind": "Apply and explain", "stem": "What does the TMS result add beyond brain activation during Braille?", "choices": ["Disrupting the recruited region changes tactile performance in the blindfolded group.", "It proves that activation always means a region is necessary for every task.", "It shows that the nonblindfolded group cannot read Braille at baseline.", "It replaces the need for behavioral comparisons or control stimulation."], "correct": 0, "why": "Interference provides evidence for functional contribution. The group-specific impairment is stronger evidence than correlated activation alone."}, {"id": "m3-q051", "module": "review", "section": "m3-review-p029", "kind": "Apply and explain", "stem": "Why distinguish apraxia of speech from a grammatical deficit in a historical patient?", "choices": ["Inability to produce speech can reflect motor planning rather than isolated loss of grammar.", "All speech disorders are identical whenever spoken output is low.", "A syndrome name directly identifies the damaged computational stage.", "Preserved understanding guarantees completely normal articulation."], "correct": 0, "why": "Precise behavioral description matters. A historical label does not establish whether the main difficulty concerns movement planning, word selection or grammar."}, {"id": "m3-q052", "module": "review", "section": "m3-review-p031", "kind": "Apply and explain", "stem": "Which pairing matches the speech-production distinctions in the review?", "choices": ["Functional processing concerns word meanings and roles, while positional processing organizes forms grammatically.", "Functional processing articulates sounds, while positional processing recognizes visual objects.", "Both levels are defined solely by the duration of eye fixations.", "Positional processing selects only the conceptual topic before words are chosen."], "correct": 0, "why": "The model distinguishes lexical-semantic preparation from grammatical ordering and form construction, with phonological encoding and articulation treated separately."}, {"id": "m3-q053", "module": "review", "section": "m3-review-p043", "kind": "Apply and explain", "stem": "Why does late-L2 difficulty after normal early L1 favor maturation over complete preservation by exercise?", "choices": ["The person already exercised language capacity early, yet later learning can still decline.", "The person never had access to any first language.", "Both hypotheses require that early language experience have no effect.", "The comparison directly proves a single irreversible cutoff for every learner."], "correct": 0, "why": "The exercise account's strong preservation prediction differs from maturation despite early use. This does not eliminate the importance of early accessible language."}, {"id": "m3-q054", "module": "review", "section": "m3-review-p044", "kind": "Apply and explain", "stem": "What is confounded if two people have the same ASL starting age but only one had an early spoken language?", "choices": ["Age of learning ASL is matched, but prior first-language access is not.", "Both people necessarily began learning their first language at the same age.", "Their hearing histories and educational experiences are guaranteed identical.", "The later ASL learner cannot have any earlier linguistic knowledge."], "correct": 0, "why": "The distinction between late L1 and late L2 is central. Early language experience can support later learning even when the new language's onset age is similar."}, {"id": "m3-q055", "module": "review", "section": "m3-review-p045", "kind": "Apply and explain", "stem": "Why is the first-cycle visual-blocking effect useful as a control?", "choices": ["Its different time course weakens a purely visual explanation of the semantic-blocking pattern.", "It shows that visually similar objects are always semantically unrelated.", "It guarantees that every reaction-time difference is grammatical.", "It eliminates the need to match visual similarity in the main materials."], "correct": 0, "why": "A control that produces a different temporal signature helps distinguish candidate processing mechanisms. Visual norming provides additional evidence."}, {"id": "m3-q056", "module": "review", "section": "m3-review-p046", "kind": "Apply and explain", "stem": "What does simultaneous presentation with serial naming separate?", "choices": ["Visibility of the object set from the sequential demands of producing names.", "Lexical selection from all possible conceptual processing.", "The need for speech from the need to see any object.", "The participant's age from the age of first language exposure."], "correct": 0, "why": "All objects can be present together while their names are produced one at a time. This tests whether presentation format alone explains the discrepancy between studies."}, {"id": "m3-q057", "module": "review", "section": "m3-review-p048", "kind": "Apply and explain", "stem": "Which measure shows the semantic-blocking effect after the first cycle?", "choices": ["Gaze duration.", "Overall speech duration.", "A statistically reliable reversed effect on lag.", "The number of letters in each object's label."], "correct": 0, "why": "The selective gaze-duration effect is interpreted in relation to lemma selection. Speech duration and lag do not show the same significant blocking pattern."}, {"id": "m3-q058", "module": "review", "section": "m3-review-p050", "kind": "Apply and explain", "stem": "Why does a step-like BEAR–PEAR choice function not prove strictly categorical lexical processing?", "choices": ["A final binary choice can conceal graded competition earlier in processing.", "The choice task contains no manipulation of phonetic evidence.", "Participants cannot look at pictures while making a choice.", "Every step-like graph necessarily indicates random responding."], "correct": 0, "why": "Eye movements can reveal varying activation of an unchosen competitor even when the final response selects one category."}, {"id": "m3-q059", "module": "review", "section": "m3-review-p051", "kind": "Apply and explain", "stem": "What supports graded transmission of phonetic information to lexical candidates?", "choices": ["More competitor looks for tokens nearer the boundary within a final-response category.", "Exactly equal competitor looks for all VOTs assigned the same response.", "Eliminating every incorrect final choice from the task.", "Only measuring whether participants recognize the unrelated filler pictures."], "correct": 0, "why": "Within-category variation in competitor activation shows that fine phonetic detail remains relevant beyond a simple final category label."}, {"id": "m3-q060", "module": "review", "section": "m3-review-p052", "kind": "Apply and explain", "stem": "How should the two halves of the competitor-fixation graph be read?", "choices": ["Each half groups a different final response and plots looks to its competing picture.", "The two halves are unrelated tasks using different participant populations.", "Both halves plot only looks to the selected target.", "The line types distinguish blind and sighted groups."], "correct": 0, "why": "BEAR responses are paired with PEAR looks and PEAR responses with BEAR looks. Early and late lines distinguish observation windows."}], "guide": [{"title": "Orthographic depth and generalization", "module": "reading1", "sections": ["m3-reading1-p003", "m3-reading1-p004", "m3-reading1-p005", "m3-reading1-p006", "m3-reading1-p008", "m3-reading1-p010"]}, {"title": "Lexical influences and frequency × regularity", "module": "reading1", "sections": ["m3-reading1-p013", "m3-reading1-p014", "m3-reading1-p016", "m3-reading1-p017", "m3-reading1-p018"]}, {"title": "Dyslexia and double dissociations", "module": "reading1", "sections": ["m3-reading1-p019", "m3-reading1-p020", "m3-reading1-p021", "m3-reading1-p023", "m3-reading1-p024"]}, {"title": "DRC processing and modularity", "module": "reading2", "sections": ["m3-reading2-p003", "m3-reading2-p004", "m3-reading2-p006", "m3-reading2-p010", "m3-reading2-p011"]}, {"title": "Statistical learning and phonological representations", "module": "reading2", "sections": ["m3-reading2-p013", "m3-reading2-p014", "m3-reading2-p015", "m3-reading2-p016", "m3-reading2-p018", "m3-reading2-p019", "m3-reading2-p020"]}, {"title": "Semantics and model evaluation", "module": "reading2", "sections": ["m3-reading2-p021", "m3-reading2-p022", "m3-reading2-p023", "m3-reading2-p025", "m3-reading2-p026", "m3-reading2-p027", "m3-reading2-p029", "m3-reading2-p030"]}, {"title": "Morphological generalization and development", "module": "morphology", "sections": ["m3-morphology-p003", "m3-morphology-p005", "m3-morphology-p006", "m3-morphology-p010", "m3-morphology-p011", "m3-morphology-p012", "m3-morphology-p014", "m3-morphology-p015"]}, {"title": "Phonology, semantics and impairment", "module": "morphology", "sections": ["m3-morphology-p016", "m3-morphology-p018", "m3-morphology-p019", "m3-morphology-p020", "m3-morphology-p021", "m3-morphology-p022", "m3-morphology-p023", "m3-morphology-p026", "m3-morphology-p027", "m3-morphology-p029"]}, {"title": "Spatial frames and competing explanations", "module": "thought", "sections": ["m3-thought-p005", "m3-thought-p007", "m3-thought-p009", "m3-thought-p010", "m3-thought-p011", "m3-thought-p012", "m3-thought-p014", "m3-thought-p015", "m3-thought-p016", "m3-thought-p018"]}, {"title": "Temporal metaphors and reading experience", "module": "thought", "sections": ["m3-thought-p020", "m3-thought-p021", "m3-thought-p022", "m3-thought-p023", "m3-thought-p024", "m3-thought-p025"]}, {"title": "Sign phonology and language networks", "module": "modalities", "sections": ["m3-modalities-p002", "m3-modalities-p005", "m3-modalities-p006", "m3-modalities-p007", "m3-modalities-p008", "m3-modalities-p009", "m3-modalities-p012", "m3-modalities-p013", "m3-modalities-p015"]}, {"title": "Deafness, signing and visual attention", "module": "modalities", "sections": ["m3-modalities-p010", "m3-modalities-p011", "m3-modalities-p014"]}, {"title": "Braille and cross-modal plasticity", "module": "modalities", "sections": ["m3-modalities-p016", "m3-modalities-p017", "m3-modalities-p018", "m3-modalities-p019", "m3-modalities-p020", "m3-modalities-p021"]}, {"title": "Review connections · aphasia and production", "module": "review", "sections": ["m3-review-p028", "m3-review-p029", "m3-review-p030", "m3-review-p031"]}, {"title": "Review connections · early language access", "module": "review", "sections": ["m3-review-p043", "m3-review-p044"]}, {"title": "Review connections · lexical selection", "module": "review", "sections": ["m3-review-p045", "m3-review-p046", "m3-review-p047", "m3-review-p048"]}, {"title": "Review connections · graded speech perception", "module": "review", "sections": ["m3-review-p049", "m3-review-p050", "m3-review-p051", "m3-review-p052"]}], "experiments": [{"title": "Pseudoword reading across orthographies", "module": "reading1", "sections": ["m3-reading1-p004", "m3-reading1-p005", "m3-reading1-p006", "m3-reading1-p007", "m3-reading1-p008", "m3-reading1-p009", "m3-reading1-p010"]}, {"title": "Frequency, regularity and the interaction", "module": "reading1", "sections": ["m3-reading1-p015", "m3-reading1-p016", "m3-reading1-p017", "m3-reading1-p018"]}, {"title": "Acquired dyslexia · two patient patterns", "module": "reading1", "sections": ["m3-reading1-p019", "m3-reading1-p020", "m3-reading1-p021", "m3-reading1-p022", "m3-reading1-p023", "m3-reading1-p024"]}, {"title": "Phonological representations and model generalization", "module": "reading2", "sections": ["m3-reading2-p016", "m3-reading2-p017", "m3-reading2-p018", "m3-reading2-p019", "m3-reading2-p020"]}, {"title": "Semantic dementia and competing model fits", "module": "reading2", "sections": ["m3-reading2-p021", "m3-reading2-p022", "m3-reading2-p023", "m3-reading2-p024", "m3-reading2-p025", "m3-reading2-p026", "m3-reading2-p027"]}, {"title": "Wug testing and U-shaped learning", "module": "morphology", "sections": ["m3-morphology-p003", "m3-morphology-p010", "m3-morphology-p011", "m3-morphology-p012", "m3-morphology-p013", "m3-morphology-p014", "m3-morphology-p015"]}, {"title": "Phonological and semantic model lesions", "module": "morphology", "sections": ["m3-morphology-p016", "m3-morphology-p017", "m3-morphology-p018", "m3-morphology-p019", "m3-morphology-p020", "m3-morphology-p021", "m3-morphology-p022", "m3-morphology-p023"]}, {"title": "SLI · behavioral and model comparisons", "module": "morphology", "sections": ["m3-morphology-p024", "m3-morphology-p025", "m3-morphology-p026", "m3-morphology-p027", "m3-morphology-p028"]}, {"title": "Rotated spatial-memory and inference tasks", "module": "thought", "sections": ["m3-thought-p005", "m3-thought-p006", "m3-thought-p007", "m3-thought-p009", "m3-thought-p010"]}, {"title": "Landmarks, memory load and task demands", "module": "thought", "sections": ["m3-thought-p011", "m3-thought-p012", "m3-thought-p014", "m3-thought-p015", "m3-thought-p016", "m3-thought-p017", "m3-thought-p018"]}, {"title": "Spatial priming and temporal judgments", "module": "thought", "sections": ["m3-thought-p020", "m3-thought-p021", "m3-thought-p022", "m3-thought-p023"]}, {"title": "Reading direction and temporal button mappings", "module": "thought", "sections": ["m3-thought-p024", "m3-thought-p025"]}, {"title": "Categorical perception of sign", "module": "modalities", "sections": ["m3-modalities-p005", "m3-modalities-p006", "m3-modalities-p007"]}, {"title": "Deafness versus signing experience", "module": "modalities", "sections": ["m3-modalities-p009", "m3-modalities-p010", "m3-modalities-p011"]}, {"title": "Sign versus tic-tac gesture control", "module": "modalities", "sections": ["m3-modalities-p012", "m3-modalities-p013"]}, {"title": "Braille, blindfolding and TMS", "module": "modalities", "sections": ["m3-modalities-p016", "m3-modalities-p017", "m3-modalities-p018", "m3-modalities-p019", "m3-modalities-p020"]}, {"title": "Early language access · Mayberry and colleagues", "module": "review", "sections": ["m3-review-p043", "m3-review-p044"]}, {"title": "Semantic blocking, gaze and speech timing", "module": "review", "sections": ["m3-review-p045", "m3-review-p046", "m3-review-p047", "m3-review-p048"]}, {"title": "VOT and graded lexical competition", "module": "review", "sections": ["m3-review-p049", "m3-review-p050", "m3-review-p051", "m3-review-p052"]}], "written": [{"id": "m3-written-01", "module": "reading1", "section": "m3-reading1-p017", "prompt": "Explain the frequency-by-regularity interaction and give both the dual-route and statistical-learning interpretations.", "answer": ["The cost of exception status is much larger for low-frequency words than high-frequency words. This is an interaction because the effect of one factor depends on the other.", "A dual-route account emphasizes fast lexical retrieval for familiar exceptions and greater interference from decoding for less familiar exceptions.", "A statistical-learning account combines support from shared spelling–sound patterns with learning of the individual word. Low-frequency exceptions are weak on both sources of support."]}, {"id": "m3-written-02", "module": "reading1", "section": "m3-reading1-p021", "prompt": "Explain what a double dissociation adds beyond one selective deficit, and why it does not uniquely prove DRC.", "answer": ["One deficit can reflect a task being harder overall. Opposite relative impairments challenge a single fixed ranking of task difficulty.", "Phonological dyslexia particularly affects nonwords, while surface dyslexia particularly affects exceptions.", "Different models can explain the reversal through different underlying dependencies. The observation constrains the architecture without specifying every component."]}, {"id": "m3-written-03", "module": "reading2", "section": "m3-reading2-p020", "prompt": "Describe the phonological-noise manipulation and explain why nonwords are particularly vulnerable.", "answer": ["The model manipulates the reliability of phonological representations and measures reading outcomes.", "Nonwords rely on generalization across learned patterns, which depends on an appropriate representation of similarity.", "Familiar words retain item-specific training support, so a shared impairment can produce unequal task effects."]}, {"id": "m3-written-04", "module": "reading2", "section": "m3-reading2-p026", "prompt": "Compare an association predicted by the triangle account with a best-fitting DRC simulation of the same patients.", "answer": ["The triangle account links semantic ability to exception reading and predicts a broad relationship between them.", "The DRC simulation varied lexical and GPC integrity across 40,000 runs and selected a match for each patient.", "Close fit matters, but so do flexibility, parameter selection and whether the relationship was constrained in advance."]}, {"id": "m3-written-05", "module": "morphology", "section": "m3-morphology-p012", "prompt": "Explain how Words and Rules and an associative model can both account for U-shaped learning.", "answer": ["Words and Rules attributes initial success, regularization and recovery to imitation, productive rule use and later exception learning with blocking.", "The associative model changes as training expands from frequent irregulars to more regular verbs. Newly learned regularities can interfere with earlier responses.", "Both must explain the developmental curve, but they propose different mechanisms. The curve alone does not select one."]}, {"id": "m3-written-06", "module": "morphology", "section": "m3-morphology-p022", "prompt": "Explain why phonological controls and semantic correlations matter for interpreting a past-tense dissociation.", "answer": ["Regular and irregular items may differ in phonological demands, so an apparent morphological effect may be partly confounded.", "Reducing that difference after matching supports a phonological contribution.", "An association between semantic impairment and irregular difficulty supports unequal dependence on semantic processing rather than only a separate rule-versus-exception interpretation."]}, {"id": "m3-written-07", "module": "thought", "section": "m3-thought-p009", "prompt": "Describe the rotated spatial task, the group result and two alternative explanations that the later studies address.", "answer": ["Rotation makes preserving a viewer-relative arrangement diverge from preserving an absolute environmental orientation.", "Dutch participants more often give relative responses, while Tzeltal participants more often give absolute responses.", "Landmark availability can differ between settings. Memory load and task transparency can also alter strategy, and verbal recoding provides a further possible mechanism."]}, {"id": "m3-written-08", "module": "thought", "section": "m3-thought-p025", "prompt": "Explain the mirror-reading experiment and what its reversal does and does not establish.", "answer": ["Participants classify temporal events using buttons whose past–future mapping can agree or disagree with a left-to-right timeline.", "After mirror reading, the later block favors the opposite temporal mapping.", "This supports a short-term contribution of reading experience. It does not establish that language never influences temporal thought or that grammar changed during the experiment."]}, {"id": "m3-written-09", "module": "modalities", "section": "m3-modalities-p011", "prompt": "Use the three participant groups to separate signing-related lateralization from peripheral attention.", "answer": ["Compare hearing nonsigners, hearing signers and deaf signers.", "Both signing groups show a leftward motion-processing shift, consistent with an association with signing experience.", "The peripheral-attention enhancement is specific to deaf participants, so signing alone is insufficient to explain that outcome."]}, {"id": "m3-written-10", "module": "modalities", "section": "m3-modalities-p020", "prompt": "Explain how blindfolding, reversal and TMS provide complementary evidence about cross-modal plasticity.", "answer": ["Five days of blindfolding during Braille training permits rapid tactile-related visual-cortex recruitment.", "The response reverses after vision returns, constraining the timescale and suggesting unmasking or changed competition.", "TMS disrupts tactile performance selectively in the blindfolded group, adding evidence for functional contribution beyond correlated activation."]}, {"id": "m3-written-11", "module": "review", "section": "m3-review-p048", "prompt": "Distinguish speech duration, gaze duration and eye–speech lag, then interpret the blocking pattern.", "answer": ["Speech duration concerns execution, gaze duration records time looking at an object, and lag concerns the interval from leaving it to spoken onset.", "Only gaze duration shows the reported blocking effect after the first cycle.", "The course interpretation links the selective pattern to lemma selection. The nonsignificant reverse-looking lag difference is not evidence for a reversed effect."]}, {"id": "m3-written-12", "module": "review", "section": "m3-review-p052", "prompt": "Explain why a step-like phoneme choice function can coexist with graded lexical competition.", "answer": ["The final mouse response selects one category and can therefore show a steep boundary.", "Eye movements reveal more activation of the competitor for tokens nearer the boundary even within a final-response category.", "That within-category gradient supports transmission of fine phonetic evidence to lexical candidates rather than discarding it completely after a thresholded label."]}], "testAllocation": {"reading1": 10, "reading2": 10, "morphology": 10, "thought": 10, "modalities": 10, "review": 10}, "coverage": {"sourcePages": 185, "lecturePages": 133, "reviewPages": 52, "instructionalPages": 175, "questions": 60, "guideTopics": 17, "experimentGroups": 19, "writtenPrompts": 12, "reviewMappings": {"2": "m3-reading1-p003", "3": "m3-reading1-p004", "4": "m3-reading1-p005", "5": "m3-reading1-p006", "6": "m3-reading1-p017", "7": "m3-reading1-p018", "8": "m3-reading2-p013", "9": "m3-reading2-p014", "10": "m3-reading2-p016", "11": "m3-reading2-p017", "12": "m3-reading2-p018", "13": "m3-reading2-p019", "14": "m3-reading2-p020", "15": "m3-morphology-p006", "16": "m3-morphology-p007", "17": "m3-morphology-p008", "18": "m3-morphology-p009", "19": "m3-morphology-p010", "20": "m3-morphology-p011", "21": "m3-morphology-p012", "22": "m3-morphology-p013", "23": "m3-morphology-p014", "24": "m3-morphology-p016", "25": "m3-morphology-p017", "26": "m3-morphology-p018", "27": "m3-morphology-p020", "32": "m3-thought-p006", "33": "m3-thought-p007", "34": "m3-thought-p009", "35": "m3-thought-p010", "36": "m3-thought-p011", "37": "m3-thought-p012", "38": "m3-thought-p015", "39": "m3-modalities-p006", "40": "m3-modalities-p007", "41": "m3-modalities-p009", "42": "m3-modalities-p014"}, "editionWords": {"psyc20": 20049, "original-c-v2": 11714, "d-v2": 10950, "original-c-v3": 16164}}};
